  function clearChapter101TutorialOverlay() {
    document.querySelectorAll('.shooting-ch101-tutorial-overlay').forEach(el => el.remove());
    const root = document.getElementById(ROOT_ID);
    if (root) root.classList.remove('ch101-ult-prompt');
    if (state) {
      state.ch101TutorialPaused = false;
      state.ch101TutorialOverlayActive = false;
    }
  }

  function showChapter101TutorialPages(cues, onComplete) {
    if (!state || !isChapter101TutorialStage()) {
      if (typeof onComplete === 'function') onComplete();
      return;
    }

    ensureChapter101TutorialStyle();
    clearChapter101TutorialOverlay();

    const root = document.getElementById(ROOT_ID);
    if (!root) {
      if (typeof onComplete === 'function') onComplete();
      return;
    }

    const pages = (Array.isArray(cues) ? cues : [cues])
      .map(cue => getChapter101TutorialCombatEntry(cue))
      .filter(Boolean);
    if (!pages.length) {
      if (typeof onComplete === 'function') onComplete();
      return;
    }

    state.ch101TutorialPaused = true;
    state.ch101TutorialOverlayActive = true;

    const overlay = document.createElement('div');
    overlay.className = 'shooting-ch101-tutorial-overlay';
    overlay.innerHTML = `
      <div class="shooting-ch101-tutorial-card">
        <img class="shooting-ch101-tutorial-portrait" src="images/chara_03_panel.webp" alt="" draggable="false">
        <div class="shooting-ch101-tutorial-speaker"></div>
        <div class="shooting-ch101-tutorial-text"></div>
        <div class="shooting-ch101-tutorial-tap">TAP TO CONTINUE</div>
      </div>`;
    root.appendChild(overlay);

    let pageIndex = 0;
    let barrierVisualRunning = false;
    const card = overlay.querySelector('.shooting-ch101-tutorial-card');
    const speakerEl = overlay.querySelector('.shooting-ch101-tutorial-speaker');
    const textEl = overlay.querySelector('.shooting-ch101-tutorial-text');

    const renderPage = () => {
      const page = pages[pageIndex];
      const speaker = String(page.speaker || '');
      card.classList.toggle('no-speaker', !speaker);
      speakerEl.textContent = speaker;
      textEl.textContent = String(page.text || '');
    };

    const finish = () => {
      overlay.classList.remove('show');
      setTimeout(() => {
        overlay.remove();
        if (!state) return;
        state.ch101TutorialPaused = false;
        state.ch101TutorialOverlayActive = false;
        prevTs = performance.now();
        if (typeof onComplete === 'function') onComplete();
      }, 160);
    };

    overlay.addEventListener('pointerup', event => {
      event.preventDefault();
      event.stopPropagation();
      pageIndex += 1;
      if (pageIndex >= pages.length) {
        finish();
        return;
      }
      renderPage();
    }, { passive:false });

    renderPage();
    requestAnimationFrame(() => overlay.classList.add('show'));
  }

  function setChapter101TutorialGauge(fraction) {
    if (!state || !isChapter101TutorialStage()) return;
    const c = getCurrentCharacter();
    const member = getActiveMember();
    if (!c || !member) return;
    const need = Math.max(1, Number(c.burstNeed || 1));
    const value = Math.max(0, Math.min(need, need * Number(fraction || 0)));
    member.burst = value;
    member.ultReadyNotified = value >= need;
    renderHud();
    if (value >= need) showShootingUltFullChargeNotice();
  }

  function spawnChapter101TutorialWave(count) {
    if (!state || !isChapter101TutorialStage()) return;
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;

    const total = Math.max(1, Number(count || 1));
    const enemyIds = selectedStage && Array.isArray(selectedStage.enemyIds) ? selectedStage.enemyIds : [];
    const enemyId = enemyIds[0];
    const def = getShootingEnemy(enemyId);
    if (!def || !def.implemented) return;

    const now = performance.now();
    const xs = total === 5
      ? [.13,.31,.50,.69,.87]
      : total === 2
        ? [.35,.65]
        : [.50];

    for (let i = 0; i < total; i++) {
      const enemy = createNormalEnemy(def, now + i * 8);
      if (!enemy) continue;
      enemy.x = arena.clientWidth * xs[Math.min(i, xs.length - 1)];
      enemy.baseX = enemy.x;
      enemy.y = Math.max(92, arena.clientHeight * (.16 + (i % 2) * .07));
      enemy.baseY = enemy.y;
      positionUnit(enemy.el, enemy.x, enemy.y);
      positionMiniEnemyHp(enemy);
      state.normalEnemies.push(enemy);
      state.normalSpawned += 1;
    }
    state.normalLastSpawnAt = now;
  }

  function startChapter101TutorialBattle() {
    if (!state || !isChapter101TutorialStage()) return;
    state.ch101TutorialPhase = 'intro';
    state.ch101TutorialPaused = true;
    state.normalSpawned = 0;
    state.normalDefeated = 0;
    setChapter101TutorialGauge(0);

    setTimeout(() => {
      if (!state || state.ended || !isChapter101TutorialStage()) return;
      showChapter101TutorialPages(['intro_aura','intro_help'], () => {
        if (!state || state.ended) return;
        state.ch101TutorialPhase = 'wave1';
        spawnChapter101TutorialWave(1);
      });
    }, 260);
  }

  function handleChapter101TutorialEnemyDefeat() {
    if (!state || !isChapter101TutorialStage()) return;

    if (state.ch101TutorialPhase === 'wave1' && state.normalDefeated === 1) {
      state.ch101TutorialPhase = 'between1';
      state.ch101TutorialPaused = true;
      setChapter101TutorialGauge(1 / 3);
      setTimeout(() => {
        if (!state || state.ended) return;
        showChapter101TutorialPages(['after_first'], () => {
          if (!state || state.ended) return;
          state.ch101TutorialPhase = 'wave2';
          spawnChapter101TutorialWave(2);
        });
      }, 320);
      return;
    }

    if (state.ch101TutorialPhase === 'wave2' && state.normalDefeated === 3) {
      state.ch101TutorialPhase = 'ult_prompt';
      state.ch101TutorialPaused = true;
      setChapter101TutorialGauge(1);
      clearProjectiles();
      setTimeout(() => {
        if (!state || state.ended) return;
        spawnChapter101TutorialWave(5);
        showChapter101TutorialPages(['ult_1','ult_2','ult_3','ult_help'], () => {
          if (!state || state.ended) return;
          state.ch101TutorialPhase = 'ult_ready';
          const root = document.getElementById(ROOT_ID);
          if (root) root.classList.add('ch101-ult-prompt');
        });
      }, 360);
    }
  }

  function defeatChapter101TutorialUltWave() {
    if (!state || !isChapter101TutorialStage()) return;
    const now = performance.now();
    const targets = (state.normalEnemies || []).filter(enemy => enemy && enemy.hp > 0);
    targets.forEach(enemy => {
      damageNormalEnemy(enemy, Math.max(999999, Number(enemy.hpMax || 1) * 50), now, true, 'weak');
    });
  }


  function isChapter403FireWallStage() {
    return !!(selectedStage && isSelectedBaseStage(SHOOTING_STAGE_ID.CH04_03));
  }

  function getChapter403CombatEntries() {
    try {
      const data = window.ZERAPHIA_STORY_SCENARIO && window.ZERAPHIA_STORY_SCENARIO.shooting_ch04_03;
      return data && Array.isArray(data.combat) ? data.combat.filter(Boolean) : [];
    } catch (_) { return []; }
  }

  function getChapter403Portrait(speaker) {
    const map = {
      'エリ': 'images/chara_01_panel.webp', 'アウラ': 'images/chara_03_panel.webp',
      'ジグ': 'images/chara_05_panel.webp', 'アルノ': 'images/chara_20_panel.webp',
      'ミモザ': 'images/chara_28_panel.webp', 'レオナクロス': 'images/chara_39_panel.webp',
      'リュネ': 'images/chara_25_panel.webp',
    };
    return map[String(speaker || '')] || '';
  }

  function beginChapter403StoryPause() {
    if (!state || !isChapter403FireWallStage()) return;
    if (!state.ch403StoryPaused) state.ch403StoryPauseStartedAt = performance.now();
    state.ch403StoryPaused = true;
    state.phaseTransition = true;
    state.playerShotLockUntil = Math.max(Number(state.playerShotLockUntil || 0), performance.now() + 120000);
  }

  function endChapter403StoryPause() {
    if (!state || !isChapter403FireWallStage()) return;
    const started = Number(state.ch403StoryPauseStartedAt || 0);
    if (started > 0 && Number(state.startedAt || 0) > 0) state.startedAt += Math.max(0, performance.now() - started);
    state.ch403StoryPauseStartedAt = 0;
    state.ch403StoryPaused = false;
    state.phaseTransition = false;
    state.playerShotLockUntil = 0;
    prevTs = performance.now();
  }

  function breakChapter403FireBarriers() {
    if (!state || !isChapter403FireWallStage()) return;
    state.ch403BarrierBroken = true;
    (state.normalEnemies || []).forEach(enemy => {
      if (!enemy) return;
      if (enemy.weaknessBarrierEl) {
        enemy.weaknessBarrierEl.classList.add('hit');
        const shield = enemy.weaknessBarrierEl;
        setTimeout(() => { if (shield && shield.isConnected) shield.remove(); }, 180);
        enemy.weaknessBarrierEl = null;
      }
      if (enemy.el) enemy.el.classList.remove('has-weakness-barrier');
    });
  }

  function showChapter403EncounterSequence(onComplete, firstOnly = false) {
    if (!state || !isChapter403FireWallStage()) { if (typeof onComplete === 'function') onComplete(); return; }
    ensureChapter101TutorialStyle();
    const root = document.getElementById(ROOT_ID);
    if (!root) { if (typeof onComplete === 'function') onComplete(); return; }
    root.querySelectorAll('.shooting-ch403-encounter-overlay').forEach(el => el.remove());
    const allPages = getChapter403CombatEntries();
    const pages = firstOnly ? allPages.slice(0, 2) : allPages.slice(2);
    if (!pages.length) { if (typeof onComplete === 'function') onComplete(); return; }
    const overlay = document.createElement('div');
    overlay.className = 'shooting-ch101-tutorial-overlay shooting-ch403-encounter-overlay';
    overlay.innerHTML = `<div class="shooting-ch101-tutorial-card"><img class="shooting-ch101-tutorial-portrait" src="" alt="" draggable="false"><div class="shooting-ch101-tutorial-speaker"></div><div class="shooting-ch101-tutorial-text"></div><div class="shooting-ch101-tutorial-tap">TAP TO CONTINUE</div></div>`;
    root.appendChild(overlay);
    let pageIndex = 0;
    let barrierVisualRunning = false;
    const card = overlay.querySelector('.shooting-ch101-tutorial-card');
    const portrait = overlay.querySelector('.shooting-ch101-tutorial-portrait');
    const speakerEl = overlay.querySelector('.shooting-ch101-tutorial-speaker');
    const textEl = overlay.querySelector('.shooting-ch101-tutorial-text');
    const renderPage = () => {
      const page = pages[pageIndex] || {};
      const speaker = String(page.speaker || '');
      const portraitSrc = getChapter403Portrait(speaker);
      card.classList.toggle('no-speaker', !speaker);
      speakerEl.textContent = speaker;
      textEl.textContent = String(page.text || '');
      if (!firstOnly && String(page.cue || '') === 'barrier_break' && !state.ch403BarrierBroken) {
        barrierVisualRunning = true;
        // Keep the battlefield visible while the blue flash fades and shields shatter.
        overlay.style.visibility = 'hidden';
        triggerChapter403BarrierBreakVisual(root, () => {
          barrierVisualRunning = false;
          if (overlay.isConnected) overlay.style.visibility = '';
        });
      }
      if (portraitSrc) { portrait.src = portraitSrc; portrait.style.display = ''; }
      else { portrait.removeAttribute('src'); portrait.style.display = 'none'; }
    };
    const finish = () => { overlay.classList.remove('show'); setTimeout(() => { overlay.remove(); if (typeof onComplete === 'function') onComplete(); }, 160); };
    overlay.addEventListener('pointerup', event => {
      event.preventDefault(); event.stopPropagation();
      if (barrierVisualRunning) return;
      pageIndex += 1;
      if (pageIndex >= pages.length) { finish(); return; }
      renderPage();
    }, { passive:false });
    renderPage(); requestAnimationFrame(() => overlay.classList.add('show'));
  }

  function triggerChapter403BarrierBreakVisual(root, onComplete) {
    if (!state || state.ch403BarrierBroken) {
      if (typeof onComplete === 'function') onComplete();
      return;
    }
    // 0.0s: blue flash; 0.6s: flash recedes; 0.9s: live enemy shields break;
    // 1.3s: reveal the barrier_break narration. Combat stays paused throughout.
    const encounterState = state;
    // A short, expanding center-origin burst, not a flat cyan screen tint.
    if (!document.getElementById('shooting-ch403-bloom-style-v2')) {
      const style = document.createElement('style');
      style.id = 'shooting-ch403-bloom-style-v2';
      style.textContent = `
        .shooting-ch403-blue-flash {
          position:absolute;inset:0;z-index:265;pointer-events:none;
          overflow:hidden;isolation:isolate;
        }
        .shooting-ch403-blue-flash::before {
          content:"";position:absolute;left:50%;top:50%;
          width:180vmax;height:180vmax;border-radius:50%;
          background:radial-gradient(circle,
            rgba(255,255,255,1) 0%,
            rgba(245,254,255,.98) 9%,
            rgba(194,240,255,.78) 21%,
            rgba(105,204,244,.30) 37%,
            rgba(105,204,244,0) 58%);
          transform:translate(-50%,-50%) scale(.015);
          opacity:0;
          animation:shootingCh403Bloom 720ms cubic-bezier(.12,.74,.18,1) both;
        }
        .shooting-ch403-blue-flash::after {
          content:"";position:absolute;left:50%;top:50%;
          width:22vmin;height:22vmin;border-radius:50%;
          background:radial-gradient(circle,
            rgba(255,255,255,1) 0%,rgba(247,255,255,.94) 15%,
            rgba(166,229,255,.52) 43%,transparent 73%);
          transform:translate(-50%,-50%) scale(.25);
          opacity:0;
          animation:shootingCh403Core 520ms ease-out both;
        }
        @keyframes shootingCh403Bloom {
          0%{opacity:0;transform:translate(-50%,-50%) scale(.015)}
          12%{opacity:1}
          39%{opacity:1;transform:translate(-50%,-50%) scale(.7)}
          70%{opacity:.54;transform:translate(-50%,-50%) scale(1.25)}
          100%{opacity:0;transform:translate(-50%,-50%) scale(1.65)}
        }
        @keyframes shootingCh403Core {
          0%{opacity:0;transform:translate(-50%,-50%) scale(.25)}
          18%{opacity:1;transform:translate(-50%,-50%) scale(1.5)}
          45%{opacity:.9;transform:translate(-50%,-50%) scale(3.8)}
          100%{opacity:0;transform:translate(-50%,-50%) scale(6)}
        }
      `;
      document.head.appendChild(style);
    }
    const flash = document.createElement('div');
    flash.className = 'shooting-ch403-blue-flash';
    root.appendChild(flash);
    setTimeout(() => {
      if (state === encounterState && !state.ended && isChapter403FireWallStage()) {
        breakChapter403FireBarriers();
      }
    }, 900);
    setTimeout(() => {
      flash.remove();
      if (typeof onComplete === 'function') onComplete();
    }, 1300);
  }

  function showChapter403ResumeCountdown(onComplete) {
    const countdown = document.getElementById('shooting-countdown');
    const span = countdown && countdown.querySelector('span');
    if (!countdown || !span) { if (typeof onComplete === 'function') onComplete(); return; }
    // Reuse the ordinary battle READY / 3 / 2 / 1 / START presentation,
    // without restarting the stage, resetting enemy positions, or the timer.
    const sequence = [
      {text:'ARE YOU READY', phase:'ready-phase', hold:1250},
      {text:'3', phase:'number-phase', hold:850},
      {text:'2', phase:'number-phase', hold:850},
      {text:'1', phase:'number-phase', hold:850},
      {text:'START', phase:'start-phase', hold:1050}
    ];
    let index = 0;
    countdown.classList.remove('chapter4-rule-phase','chapter4-rule-first','ready-phase','number-phase','start-phase');
    span.textContent = '';
    countdown.classList.add('show');
    countdown.setAttribute('aria-hidden','false');
    const step = () => {
      if (!state || state.ended || !isChapter403FireWallStage()) {
        countdown.classList.remove('show','ready-phase','number-phase','start-phase');
        countdown.setAttribute('aria-hidden','true');
        return;
      }
      if (index >= sequence.length) {
        countdown.classList.remove('show','ready-phase','number-phase','start-phase');
        countdown.setAttribute('aria-hidden','true');
        if (typeof onComplete === 'function') onComplete();
        return;
      }
      const current = sequence[index++];
      countdown.classList.remove('ready-phase','number-phase','start-phase');
      countdown.classList.add(current.phase);
      span.textContent = current.text;
      span.classList.remove('pop','ready-pop','start-pop');
      span.style.removeProperty('animation');
      span.style.removeProperty('opacity');
      span.style.removeProperty('transform');
      span.style.removeProperty('filter');
      void span.offsetWidth;
      span.classList.add(current.phase === 'ready-phase' ? 'ready-pop' : current.phase === 'start-phase' ? 'start-pop' : 'pop');
      setTimeout(step, current.hold);
    };
    step();
  }

  function triggerChapter403EncounterSequence() {
    if (!state || !isChapter403FireWallStage() || state.ch403EncounterTriggered || state.ended) return;
    const phase = Number(state.ch403Phase || 0);
    if (phase >= 2) return;
    state.ch403EncounterTriggered = true;
    beginChapter403StoryPause();
    clearProjectiles();
    setTimeout(() => {
      if (!state || state.ended || !isChapter403FireWallStage()) return;
      showChapter403EncounterSequence(() => {
        if (!state || state.ended || !isChapter403FireWallStage()) return;
        state.ch403Phase = phase + 1;
        state.ch403ImmuneHits = 0;
        state.ch403PhaseElapsedMs = 0;
        state.ch403PhaseStartedAt = performance.now();
        if (phase === 0) {
          state.ch403EncounterTriggered = false;
          endChapter403StoryPause();
        } else {
          // Barrier already broke visibly on the barrier_break story cue.
          showChapter403ResumeCountdown(() => endChapter403StoryPause());
        }
      }, phase === 0);
    }, 180);
  }


  function isChapter104BossStage() {
    return !!(selectedStage && isSelectedBaseStage(SHOOTING_STAGE_ID.CH01_04));
  }

  function getChapter104CombatEntry(cue) {
    try {
      const data = window.ZERAPHIA_STORY_SCENARIO && window.ZERAPHIA_STORY_SCENARIO.shooting_ch01_04;
      const list = data && Array.isArray(data.combat) ? data.combat : [];
      return list.find(entry => entry && entry.cue === cue) || null;
    } catch (_) {
      return null;
    }
  }

  function getChapter104Portrait(speaker) {
    const map = {
      'エリ': 'images/chara_01_panel.webp',
      'アウラ': 'images/chara_03_panel.webp',
      'ジグ': 'images/chara_05_panel.webp',
      'アルノ': 'images/chara_20_panel.webp',
    };
    return map[String(speaker || '')] || '';
  }

  function beginChapter104StoryPause() {
    if (!state || !isChapter104BossStage()) return;
    if (!state.ch104StoryPaused) {
      state.ch104StoryPauseStartedAt = performance.now();
    }
    state.ch104StoryPaused = true;
    state.ch104PauseHudAt = 0;
    state.phaseTransition = true;
    removeBossDangerWarning();
    state.bossDangerExecuteAt = 0;
    deferBossAttackResume(performance.now() + 120000);
  }

  function endChapter104StoryPause() {
    if (!state || !isChapter104BossStage()) return;
    const started = Number(state.ch104StoryPauseStartedAt || 0);
    if (started > 0 && Number(state.startedAt || 0) > 0) {
      state.startedAt += Math.max(0, performance.now() - started);
    }
    state.ch104StoryPauseStartedAt = 0;
    state.ch104StoryPaused = false;
    state.ch104PauseHudAt = 0;
    state.phaseTransition = false;
    prevTs = performance.now();
  }

  function registerChapter104BarrierContact(characterId) {
    if (!state || !isChapter104BossStage() || state.ch104RescueTriggered) return;
    const id = Number(characterId || 0);
    const eriId = Number(CHARACTER_ID.ERI || 1);
    const jigId = Number(CHARACTER_ID.JIG || 5);

    state.ch104BarrierContactHits = Math.max(0, Number(state.ch104BarrierContactHits || 0)) + 1;

    if (state.ch104ForcedBattlePhase === 'eri' && id === eriId) {
      state.ch104EriBarrierContactHits = Math.min(80, Math.max(0, Number(state.ch104EriBarrierContactHits || 0)) + 1);
    } else if (state.ch104ForcedBattlePhase === 'jig' && id === jigId) {
      state.ch104JigBarrierContactHits = Math.min(80, Math.max(0, Number(state.ch104JigBarrierContactHits || 0)) + 1);
    }
  }

  // Resolve both modern explicit scene filenames and legacy location labels.
  function getChapter104SceneBackground(entry) {
    const location = String(entry && entry.location || '').trim();
    if (/^[a-zA-Z0-9_-]+\.(?:webp|png|jpe?g)$/i.test(location)) {
      return 'images/' + location;
    }
    if (location.includes('大型レムナント・アルノ登場')) return 'images/scene_aruno_help.webp';
    if (location.includes('大型レムナント・戦闘')) return 'images/scene_eri_jig_battle.webp';
    if (location.includes('大型レムナント・登場')) return 'images/scene_remnant_01_battle.webp';
    return '';
  }

  function showChapter104BattleDialogue(cues, onComplete) {
    if (!state || !isChapter104BossStage()) {
      if (typeof onComplete === 'function') onComplete();
      return;
    }

    ensureChapter101TutorialStyle();
    const root = document.getElementById(ROOT_ID);
    if (!root) {
      if (typeof onComplete === 'function') onComplete();
      return;
    }

    root.querySelectorAll('.shooting-ch104-battle-dialogue-overlay').forEach(el => el.remove());
    const pages = (Array.isArray(cues) ? cues : [cues])
      .map(cue => getChapter104CombatEntry(cue))
      .filter(Boolean);
    if (!pages.length) {
      if (typeof onComplete === 'function') onComplete();
      return;
    }

    const overlay = document.createElement('div');
    overlay.className = 'shooting-ch101-tutorial-overlay shooting-ch104-battle-dialogue-overlay';
    overlay.innerHTML = `
      <div class="shooting-ch101-tutorial-card">
        <img class="shooting-ch101-tutorial-portrait" src="" alt="" draggable="false">
        <div class="shooting-ch101-tutorial-speaker"></div>
        <div class="shooting-ch101-tutorial-text"></div>
        <div class="shooting-ch101-tutorial-tap">TAP TO CONTINUE</div>
      </div>`;
    root.appendChild(overlay);

    let pageIndex = 0;
    const card = overlay.querySelector('.shooting-ch101-tutorial-card');
    const portrait = overlay.querySelector('.shooting-ch101-tutorial-portrait');
    const speakerEl = overlay.querySelector('.shooting-ch101-tutorial-speaker');
    const textEl = overlay.querySelector('.shooting-ch101-tutorial-text');

    const renderPage = () => {
      const page = pages[pageIndex];
      const speaker = String(page.speaker || '');
      const portraitSrc = getChapter104Portrait(speaker);
      card.classList.toggle('no-speaker', !speaker);
      speakerEl.textContent = speaker;
      textEl.textContent = String(page.text || '');
      const sceneBg = getChapter104SceneBackground(page);
      overlay.style.backgroundImage = sceneBg ? `url("${sceneBg}")` : 'none';
      if (portraitSrc) {
        portrait.src = portraitSrc;
        portrait.style.display = '';
      } else {
        portrait.removeAttribute('src');
        portrait.style.display = 'none';
      }
    };

    const finish = () => {
      overlay.classList.remove('show');
      setTimeout(() => {
        overlay.remove();
        if (typeof onComplete === 'function') onComplete();
      }, 160);
    };

    overlay.addEventListener('pointerup', event => {
      event.preventDefault();
      event.stopPropagation();
      pageIndex += 1;
      if (pageIndex >= pages.length) {
        finish();
        return;
      }
      renderPage();
    }, { passive:false });

    renderPage();
    requestAnimationFrame(() => overlay.classList.add('show'));
  }

  function getChapter104RescueBackground(entry) {
    return getChapter104SceneBackground(entry) || 'images/scene_outside_tower.webp';
  }

  function showChapter104RescuePages(cues, onComplete, options = {}) {
    if (!state || !isChapter104BossStage()) {
      if (typeof onComplete === 'function') onComplete();
      return;
    }

    ensureChapter101TutorialStyle();

    const root = document.getElementById(ROOT_ID);
    if (!root) {
      if (typeof onComplete === 'function') onComplete();
      return;
    }

    document.querySelectorAll('.shooting-ch104-rescue-overlay').forEach(el => el.remove());

    const pages = (Array.isArray(cues) ? cues : [cues])
      .map(cue => getChapter104CombatEntry(cue))
      .filter(Boolean);

    if (!pages.length) {
      if (typeof onComplete === 'function') onComplete();
      return;
    }

    const overlay = document.createElement('div');
    overlay.className = 'shooting-ch101-tutorial-overlay shooting-ch104-rescue-overlay';
    overlay.innerHTML = `
      <div class="shooting-ch101-tutorial-card">
        <img class="shooting-ch101-tutorial-portrait" src="" alt="" draggable="false">
        <div class="shooting-ch101-tutorial-speaker"></div>
        <div class="shooting-ch101-tutorial-text"></div>
        <div class="shooting-ch101-tutorial-tap">TAP TO CONTINUE</div>
      </div>`;
    root.appendChild(overlay);

    let pageIndex = 0;
    const card = overlay.querySelector('.shooting-ch101-tutorial-card');
    const portrait = overlay.querySelector('.shooting-ch101-tutorial-portrait');
    const speakerEl = overlay.querySelector('.shooting-ch101-tutorial-speaker');
    const textEl = overlay.querySelector('.shooting-ch101-tutorial-text');

    const renderPage = () => {
      const page = pages[pageIndex];
      const speaker = String(page.speaker || '');
      const portraitSrc = getChapter104Portrait(speaker);

      card.classList.toggle('no-speaker', !speaker);
      speakerEl.textContent = speaker;
      textEl.textContent = String(page.text || '');

      const isImpactWhite = String(page && page.location || '') === '白化画面';
      overlay.classList.toggle('is-impact-white', isImpactWhite);
      const backgroundSrc = isImpactWhite ? '' : getChapter104RescueBackground(page);
      overlay.style.backgroundImage = backgroundSrc ? `url("${backgroundSrc}")` : 'none';

      if (portrait) {
        if (portraitSrc) {
          portrait.src = portraitSrc;
          portrait.style.display = '';
        } else {
          portrait.removeAttribute('src');
          portrait.style.display = 'none';
        }
      }
    };

    const holdCurrentBackgroundThenMessage = (nextIndex, holdMs = 1500, nextBackgroundHoldMs = 0) => {
      overlay.classList.add('is-cinematic-reveal');
      setTimeout(() => {
        if (!overlay.isConnected) return;
        pageIndex = nextIndex;
        renderPage();
        const nextHold = Math.max(0, Number(nextBackgroundHoldMs || 0));
        if (nextHold > 0) {
          setTimeout(() => {
            if (!overlay.isConnected) return;
            overlay.classList.remove('is-cinematic-reveal');
            impactTransitioning = false;
          }, Math.max(1500, nextHold));
          return;
        }
        overlay.classList.remove('is-cinematic-reveal');
        impactTransitioning = false;
      }, Math.max(1500, Number(holdMs || 1500)));
    };

    const revealWhiteFadeThenMessage = (nextIndex, holdMs = 1700, fadeMs = 980) => {
      overlay.classList.add('is-cinematic-reveal');
      overlay.querySelectorAll('.shooting-ch104-whiteout').forEach(el => el.remove());
      pageIndex = nextIndex;
      renderPage();

      const whiteout = document.createElement('div');
      whiteout.className = 'shooting-ch104-whiteout';
      overlay.appendChild(whiteout);
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          if (whiteout.isConnected) whiteout.classList.add('fade-out');
        });
      });
      setTimeout(() => {
        if (whiteout.isConnected) whiteout.remove();
      }, Math.max(600, Number(fadeMs || 980)) + 120);

      setTimeout(() => {
        if (!overlay.isConnected) return;
        overlay.classList.remove('is-cinematic-reveal');
        impactTransitioning = false;
      }, Math.max(1500, Number(holdMs || 1700)));
    };

    const finish = () => {
      // CH01-04 rescue -> Arno battle handoff: keep the story cover alive until
      // Arno has already replaced Jig underneath and the battle-start dialogue
      // overlay has been created. This prevents a one-frame Jig battle flash.
      if (options && options.handoffBeforeRemove) {
        if (!state || state.ended || state.finishing) {
          overlay.remove();
          return;
        }
        prevTs = performance.now();
        if (typeof onComplete === 'function') onComplete();
        setTimeout(() => {
          overlay.classList.remove('show');
          setTimeout(() => overlay.remove(), 180);
        }, 50);
        return;
      }

      overlay.classList.remove('show');
      setTimeout(() => {
        overlay.remove();
        if (!state || state.ended || state.finishing) return;
        prevTs = performance.now();
        if (typeof onComplete === 'function') onComplete();
      }, 180);
    };

    let impactTransitioning = false;
    overlay.addEventListener('pointerup', event => {
      event.preventDefault();
      event.stopPropagation();
      if (impactTransitioning) return;

      const currentPage = pages[pageIndex];
      const nextPage = pages[pageIndex + 1];

      // 「――大きな衝撃音。」の直後：大きなシェイク＋白フラッシュを入れてから、
      // 吹き飛ばされる描写へ進める。
      if (currentPage && currentPage.cue === 'impact_1' && nextPage && nextPage.cue === 'impact_2') {
        impactTransitioning = true;
        playChapter104EventFlash(overlay, 'heavy');
        playChapter104ImpactShake(() => {
          if (!overlay.isConnected) return;
          pageIndex += 1;
          renderPage();
          impactTransitioning = false;
        });
        return;
      }

      // 「ジグとエリは、強い力で吹き飛ばされる。」の直後：画面を真っ白にし、
      // 白を徐々にフェードアウトさせながらアルノ登場背景を全画面で見せてから、
      // rescue_1 のナレーションへ進める。
      if (currentPage && currentPage.cue === 'impact_2' && nextPage && nextPage.cue === 'rescue_1') {
        impactTransitioning = true;
        revealWhiteFadeThenMessage(pageIndex + 1, 1800, 1500);
        return;
      }

      pageIndex += 1;
      if (pageIndex >= pages.length) {
        finish();
        return;
      }
      renderPage();
    }, { passive:false });

    renderPage();
    const initialHoldMs = Math.max(0, Number(options.initialCinematicMs || 0));
    if (initialHoldMs > 0) {
      overlay.classList.add('is-cinematic-reveal');
      impactTransitioning = true;
    }
    requestAnimationFrame(() => overlay.classList.add('show'));
    if (initialHoldMs > 0) {
      setTimeout(() => {
        if (!overlay.isConnected) return;
        overlay.classList.remove('is-cinematic-reveal');
        impactTransitioning = false;
      }, Math.max(1500, initialHoldMs));
    }
  }

  function playChapter104EventFlash(target, strength = 'light') {
    const host = target && target.isConnected ? target : document.getElementById(ROOT_ID);
    if (!host) return;

    host.querySelectorAll('.shooting-ch104-event-flash').forEach(el => el.remove());
    const flash = document.createElement('div');
    flash.className = `shooting-ch104-event-flash ${strength === 'heavy' ? 'is-heavy' : 'is-light'}`;
    host.appendChild(flash);
    const ttl = strength === 'heavy' ? 680 : 420;
    setTimeout(() => { if (flash.isConnected) flash.remove(); }, ttl);
  }

  function getChapter104VisibleShakeTarget() {
    const root = document.getElementById(ROOT_ID);
    if (!root) return null;

    // build1119: CH01-04のストーリー中は、戦闘画面の上に全画面背景オーバーレイが載る。
    // 背面のshooting-stageを揺らしても見えないため、表示中のオーバーレイ自体を最優先で揺らす。
    const overlay = root.querySelector('.shooting-ch104-rescue-overlay.show') ||
      root.querySelector('.shooting-ch104-rescue-overlay');
    if (overlay) return overlay;

    return root.querySelector('.shooting-stage') || root;
  }

  function playChapter104DamageShake(onComplete) {
    const target = getChapter104VisibleShakeTarget();
    const player = document.getElementById(PLAYER_ID);
    const done = () => { if (typeof onComplete === 'function') onComplete(); };

    // HPは削らず、直撃したような短い被弾フィードバックだけを出す。
    if (player) {
      player.classList.remove('damaged');
      void player.offsetWidth;
      player.classList.add('damaged');
      setTimeout(() => player.classList.remove('damaged'), 420);
    }
    if (!target || typeof target.animate !== 'function') {
      triggerPlayerHitScreenShake();
      setTimeout(done, 360);
      return;
    }
    try {
      const animation = target.animate([
        { transform:'translate3d(0,0,0) scale(1)', offset:0 },
        { transform:'translate3d(-12px,6px,0) scale(1.008)', offset:.16 },
        { transform:'translate3d(10px,-5px,0) scale(1.006)', offset:.34 },
        { transform:'translate3d(-7px,4px,0) scale(1.004)', offset:.54 },
        { transform:'translate3d(5px,-2px,0) scale(1.002)', offset:.74 },
        { transform:'translate3d(0,0,0) scale(1)', offset:1 }
      ], { duration:420, easing:'cubic-bezier(.18,.72,.22,1)', fill:'none' });
      animation.addEventListener('finish', done, { once:true });
      animation.addEventListener('cancel', done, { once:true });
    } catch (_) {
      triggerPlayerHitScreenShake();
      setTimeout(done, 380);
    }
  }

  function playChapter104ImpactShake(onComplete) {
    const target = getChapter104VisibleShakeTarget();
    const done = () => { if (typeof onComplete === 'function') onComplete(); };
    if (!target || typeof target.animate !== 'function') {
      triggerPlayerHitScreenShake();
      setTimeout(done, 620);
      return;
    }
    try {
      const animation = target.animate([
        { transform:'translate3d(0,0,0) rotate(0deg) scale(1)', offset:0 },
        { transform:'translate3d(-28px,14px,0) rotate(-1.15deg) scale(1.024)', offset:.08 },
        { transform:'translate3d(24px,-15px,0) rotate(.95deg) scale(1.021)', offset:.18 },
        { transform:'translate3d(-21px,11px,0) rotate(-.78deg) scale(1.017)', offset:.31 },
        { transform:'translate3d(17px,-8px,0) rotate(.62deg) scale(1.014)', offset:.45 },
        { transform:'translate3d(-12px,6px,0) rotate(-.46deg) scale(1.010)', offset:.60 },
        { transform:'translate3d(8px,-4px,0) rotate(.30deg) scale(1.006)', offset:.73 },
        { transform:'translate3d(-4px,2px,0) rotate(-.14deg) scale(1.003)', offset:.86 },
        { transform:'translate3d(0,0,0) rotate(0deg) scale(1)', offset:1 }
      ], { duration:720, easing:'cubic-bezier(.10,.74,.16,1)', fill:'none' });
      animation.addEventListener('finish', done, { once:true });
      animation.addEventListener('cancel', done, { once:true });
    } catch (_) {
      triggerPlayerHitScreenShake();
      setTimeout(done, 620);
    }
  }

  function showChapter104ArnoBattleStart(onComplete) {
    if (!state || !isChapter104BossStage()) {
      if (typeof onComplete === 'function') onComplete();
      return;
    }
    ensureChapter101TutorialStyle();
    const root = document.getElementById(ROOT_ID);
    if (!root) {
      if (typeof onComplete === 'function') onComplete();
      return;
    }

    const entry = getChapter104CombatEntry('arno_battle_start') || {
      speaker:'アルノ',
      text:'相手はこっちだ…こい。'
    };

    const overlay = document.createElement('div');
    overlay.className = 'shooting-ch101-tutorial-overlay shooting-ch104-battle-start-overlay';
    overlay.innerHTML = `
      <div class="shooting-ch101-tutorial-card">
        <img class="shooting-ch101-tutorial-portrait" src="images/chara_20_panel.webp" alt="アルノ" draggable="false">
        <div class="shooting-ch101-tutorial-speaker">アルノ</div>
        <div class="shooting-ch101-tutorial-text"></div>
        <div class="shooting-ch101-tutorial-tap">TAP TO CONTINUE</div>
      </div>`;
    const textEl = overlay.querySelector('.shooting-ch101-tutorial-text');
    if (textEl) textEl.textContent = String(entry.text || '相手はこっちだ…こい。');
    root.appendChild(overlay);

    let closed = false;
    const finish = () => {
      if (closed) return;
      closed = true;
      overlay.classList.remove('show');
      setTimeout(() => {
        overlay.remove();
        if (typeof onComplete === 'function') onComplete();
      }, 170);
    };
    overlay.addEventListener('pointerup', event => {
      event.preventDefault();
      event.stopPropagation();
      finish();
    }, { passive:false });
    requestAnimationFrame(() => overlay.classList.add('show'));
  }

  function applyChapter104ShockwaveDamage() {
    if (!state || !isChapter104BossStage() || state.ended || state.finishing) return;
    const member = getActiveMember();
    if (!member) return;

    // build1116: イベント確定被弾。無敵・属性相性・防御補正を通さず、最大HPの66%分を直接削る。
    // 既に削れている場合も回復させず、最低1HPは残して救援シーンへ繋ぐ。
    const forcedDamage = Math.max(1, Math.round(Number(member.hpMax || 1) * 0.66));
    const appliedDamage = Math.max(0, Math.min(Math.max(0, Number(member.hp || 0) - 1), forcedDamage));
    member.hp = Math.max(1, Number(member.hp || 0) - appliedDamage);
    member.hitCount = (member.hitCount || 0) + 1;
    state.totalHitsTaken = (state.totalHitsTaken || 0) + 1;
    resetCombo();

    triggerPlayerHitScreenShake();
    showDamageNumber(state.player.x, state.player.y, appliedDamage, 'player', true, '');

    const player = document.getElementById(PLAYER_ID);
    if (player) {
      player.classList.remove('damaged');
      void player.offsetWidth;
      player.classList.add('damaged');
      sustainHitFeedback(player, 420);
    }
    state.player.invulnUntil = Math.max(Number(state.player.invulnUntil || 0), performance.now() + 2400);
    renderHud();
  }

  function playChapter104UnavoidableShockwave(onComplete) {
    if (!state || !isChapter104BossStage()) {
      if (typeof onComplete === 'function') onComplete();
      return;
    }

    const arena = document.getElementById('shooting-arena');
    if (!arena) {
      applyChapter104ShockwaveDamage();
      if (typeof onComplete === 'function') onComplete();
      return;
    }

    arena.querySelectorAll('.shooting-ch104-shockwave,.shooting-ch104-shockwave-flash').forEach(el => el.remove());

    const wave = document.createElement('div');
    wave.className = 'shooting-ch104-shockwave';
    wave.style.left = `${Number(state.boss && state.boss.x || arena.clientWidth / 2)}px`;
    wave.style.top = `${Number(state.boss && state.boss.y || arena.clientHeight * .28)}px`;

    const flash = document.createElement('div');
    flash.className = 'shooting-ch104-shockwave-flash';
    arena.appendChild(flash);
    arena.appendChild(wave);

    // 波面が自機へ届くタイミングで確定被弾。回避判定は持たせない。
    setTimeout(() => {
      if (!state || state.ended || state.finishing) return;
      applyChapter104ShockwaveDamage();
    }, 360);

    setTimeout(() => {
      wave.remove();
      flash.remove();
      if (typeof onComplete === 'function') onComplete();
    }, 820);
  }

  function switchChapter104ToArno() {
    if (!state || !isChapter104BossStage()) return;

    const arnoId = Number(CHARACTER_ID.ARNO || 20);
    const arno = applyTitleEffectToProfile(buildResonatedCharacterProfile(arnoId), state.titleBattleMul);
    if (!arno) return;

    state.characterProfiles[arnoId] = arno;

    // CH01-04: REMNANT01本体との戦闘は、救援前がエリ＋ジグ、救援後はアルノ単独。
    // アウラは小型レムナント群との別戦闘中なので、ボス戦partyには含めない。
    // 救援後はエリとジグもアウラ側の援護へ回るため、ボス戦から離脱する。
    const arnoMember = {
      id: arnoId,
      hp: arno.hp,
      hpMax: arno.hp,
      burst: 0,
      ultReadyNotified: false,
      hitCount: 0,
      ultUseCount: 0
    };
    state.party = [arnoMember];
    selectedPartyIds = [arnoId];

    state.ch104ArnoJoined = true;
    endAinaStealth();
    state.activeCharacterId = arnoId;
    selectedCharacterId = arnoId;
    state.switchReadyAt = performance.now() + 800;
    state.player.invulnUntil = Math.max(Number(state.player.invulnUntil || 0), performance.now() + 1600);
    state.lastShotAt = -9999;
    applySelectedCharacterToUi();
    renderSwitchRail(true);

    const player = document.getElementById(PLAYER_ID);
    if (player) {
      player.classList.remove('character-swap');
      void player.offsetWidth;
      player.classList.add('character-swap');
      setTimeout(() => player.classList.remove('character-swap'), 260);
    }
  }

  function maybeTriggerChapter104Rescue() {
    if (
      !state ||
      !isChapter104BossStage() ||
      state.ended ||
      state.finishing ||
      state.ch104RescueTriggered ||
      !state.boss ||
      state.boss.hp <= 0
    ) {
      return false;
    }

    // Phase 1: まずエリだけで80回バリアへ攻撃を当てる。
    if (
      state.ch104ForcedBattlePhase === 'eri' &&
      Number(state.ch104EriBarrierContactHits || 0) >= 80
    ) {
      state.ch104ForcedBattlePhase = 'eri-dialogue';
      beginChapter104StoryPause();
      renderSwitchRail(false);
      showChapter104BattleDialogue(['pressure_1', 'pressure_1_jig'], () => {
        if (!state || state.ended || state.finishing) return;
        const jigId = Number(CHARACTER_ID.JIG || 5);
        state.ch104ForcedBattlePhase = 'jig';
        window.switchShootingCharacter(jigId, true);
        endChapter104StoryPause();
        state.lastBossShotAt = performance.now();
        state.lastShotAt = performance.now();
        renderSwitchRail(false);
        renderHud();
      });
      return true;
    }

    // Phase 2: ジグでも80回バリアへ当てる。ここから完全な負けイベントへ。
    if (
      state.ch104ForcedBattlePhase === 'jig' &&
      Number(state.ch104JigBarrierContactHits || 0) >= 80
    ) {
      state.ch104ForcedBattlePhase = 'jig-dialogue';
      state.ch104RescueTriggered = true;
      state.ch104PreRescueElapsedMs = Math.max(0, performance.now() - Number(state.startedAt || performance.now()));
      beginChapter104StoryPause();
      renderSwitchRail(false);

      showChapter104BattleDialogue(['pressure_2', 'pressure_3'], () => {
        if (!state || state.ended || state.finishing || !state.boss || state.boss.hp <= 0) return;

        // 「ジグ！あぶない…っ！！」直後。戦闘盤面のまま被弾演出を入れる。
        playChapter104EventFlash(document.getElementById(ROOT_ID), 'heavy');
        playChapter104ImpactShake(() => {
          if (!state || state.ended || state.finishing) return;

          showChapter104RescuePages([
            'pressure_4',
            'pressure_5',
            'pressure_6',
            'pressure_7',
            'pressure_8',
            'pressure_9',
            'pressure_10',
            'pressure_9_urgent',
            'pressure_11',
            'pressure_12',
            'impact_1',
            'impact_2',
            'rescue_1',
            'rescue_2',
            'rescue_3',
            'rescue_4',
            'rescue_5',
            'rescue_6'
          ], () => {
            if (!state || state.ended || state.finishing || !state.boss || state.boss.hp <= 0) return;

            clearProjectiles();
            state.ch104StoryPaused = false;
            state.ch104StoryPauseStartedAt = 0;

            // 救援後はアルノ単独。BOSSは最初から2ゲージ設計で、満タンPHASE1から開始する。
            switchChapter104ToArno();
            if (state.boss) {
              state.boss.hp = state.boss.hpMax;
              state.boss.phase = 1;
            }

            state.running = false;
            renderHud();

            showChapter104ArnoBattleStart(() => {
              if (!state || state.ended || state.finishing || !state.boss || state.boss.hp <= 0) return;
              state.phaseTransition = false;
              state.resumeElapsedMsPending = Math.max(0, Number(state.ch104PreRescueElapsedMs || 0));
              state.lastBossShotAt = performance.now();
              state.lastShotAt = performance.now();
              prevTs = performance.now();
              runStartCountdown();
            });
          }, { initialCinematicMs: 1500, handoffBeforeRemove: true });
        });
      });
      return true;
    }

    return false;
  }

  function isCh404SummonerBattle() {
    return isSelectedBaseStage(SHOOTING_STAGE_ID.CH04_04);
  }

  // ============================================================
  // CH07-3 群がる強化個体（swarmBattle）
  // 弾は撃たない。一番近い味方オブジェクト（TRAP設置済み / デコイ / ミト召喚獣 / 自機）へ這い寄る。
  // 自機・召喚獣へは既存の接触判定でダメージ。デコイ（build1668〜壊れない）には群がるだけ。TRAPは3秒後に爆発する囮。
  // ============================================================
  function getSwarmBattleConfig() {
    return (selectedStage && selectedStage.swarmBattle) || null;
  }

  function isSwarmBattle() {
    return !!(isNormalBattle() && getSwarmBattleConfig());
  }

  function getSwarmLargeTotal() {
    return Math.max(1, Math.floor(Number(getSwarmBattleConfig()?.largeCount || 3)));
  }

  // 小蜘蛛は討伐ノルマ外。大蜘蛛と三頭狼だけをカウントする。
  function getSwarmGuardTotal() {
    return getSwarmBattleConfig()?.guardEnemyId ? 1 : 0;
  }

  function getSwarmObjectiveTotal() {
    return getSwarmLargeTotal() + getSwarmGuardTotal();
  }

  function getSwarmObjectiveDefeated() {
    const large = Math.min(getSwarmLargeTotal(), Math.max(0, Number(state?.swarmLargeDefeated || 0)));
    const guard = Math.min(getSwarmGuardTotal(), Math.max(0, Number(state?.swarmGuardDefeated || 0)));
    return large + guard;
  }

  function spawnSwarmEnemy(enemyId, x, y, now, extra) {
    const base = getShootingEnemy(enemyId);
    if (!base || !base.implemented) return null;
    // build1593: 群れステージ側に倍率指定がある場合だけ、生成個体の定義を調整する。
    // 元の敵マスターは書き換えない（CH07-03/04やカミラには影響しない）。
    const swarmCfg = getSwarmBattleConfig() || {};
    const speedScale = Math.max(0.1, Number(swarmCfg.spiderMoveSpeedScale || 1));
    const damageScale = Math.max(0.1, Number(swarmCfg.spiderContactDamageScale || 1));
    // build1680: 位相回遊は階層倍率で蜘蛛のHPも上げる（spiderHpScale。塔13F・CH07には無いので従来どおり）
    const hpScale = Math.max(0.1, Number(swarmCfg.spiderHpScale || 1));
    const scaledHp = Math.max(1, Math.round(Number(base.hp || 1) * hpScale));
    const tuned = Object.assign({}, base, {
      moveSpeed: Number(base.moveSpeed || 0) * speedScale,
      contactDamage: Math.round(Number(base.contactDamage || 0) * damageScale),
      hp: scaledHp, ch404Hp: scaledHp, ch404Image: base.image
    });
    const enemy = createNormalEnemy(tuned, now);
    if (!enemy) return null;
    enemy.swarmRole = base.swarmRole || 'small';
    enemy.x = enemy.baseX = x;
    enemy.y = enemy.baseY = y;
    Object.assign(enemy, extra || {});
    if (enemy.el) enemy.el.classList.add('shooting-swarm-spider', 'swarm-' + enemy.swarmRole);
    positionUnit(enemy.el, enemy.x, enemy.y);
    positionMiniEnemyHp(enemy);
    state.normalEnemies.push(enemy);
    state.normalSpawned++;
    return enemy;
  }

  function spawnSwarmEnemies(now) {
    const cfg = getSwarmBattleConfig();
    const arena = document.getElementById('shooting-arena');
    if (!cfg || !arena) return;
    const w = arena.clientWidth, h = arena.clientHeight;

    // 開幕：大を横一列に配置（中断復帰時は、撃破済みの数だけ減らす）
    if (!state.swarmLargeSpawned) {
      state.swarmLargeSpawned = true;
      const total = getSwarmLargeTotal();
      const remain = Math.max(0, total - Number(state.swarmLargeDefeated || 0));
      const rates = total === 1 ? [.5] : Array.from({length: total}, (_, i) => .2 + .6 * i / (total - 1));
      if (cfg.guardEnemyId && Number(state.swarmGuardDefeated || 0) < getSwarmGuardTotal()) {
        const guardBase = getShootingEnemy(cfg.guardEnemyId);
        if (guardBase) {
          const guardHp = Math.max(1, Number(cfg.guardHp || guardBase.hp || 5000));
          const guard = createNormalEnemy(Object.assign({}, guardBase, {hp:guardHp,ch404Hp:guardHp}), now);
          if (guard) {
            guard.swarmRole = 'guard';
            guard.x = guard.baseX = w * .5;
            // 他の群れAIを使用せず、上空を左右移動して2秒おきに攻撃する。
            guard.y = guard.baseY = cfg.guardAi === 'tower13_upper_spread5'
              ? Math.max(86, h * Number(cfg.guardTopYRate || .20))
              : Math.max(82, h * .29);
            guard.lastShotAt = now;
            positionUnit(guard.el, guard.x, guard.y);
            positionMiniEnemyHp(guard);
            state.normalEnemies.push(guard);
            state.normalSpawned++;
          }
        }
      }
      for (let i = 0; i < remain; i++) {
        const interval = Math.max(500, Number(cfg.broodIntervalMs || 5000));
        spawnSwarmEnemy(cfg.largeEnemyId, w * rates[i], Math.max(96, h * .17), now, {
          // 3体が同時に産まないよう、最初の産卵タイミングをずらす
          swarmNextBroodAt: now + interval * (0.45 + 0.3 * i),
        });
      }
      return;
    }

    // 大は5秒に1体ずつ小を生む（1体につき同時 broodMaxPerLarge 体まで）
    const interval = Math.max(500, Number(cfg.broodIntervalMs || 5000));
    const maxBrood = Math.max(1, Math.floor(Number(cfg.broodMaxPerLarge || 3)));
    (state.normalEnemies || []).slice().forEach(parent => {
      if (!parent || parent.hp <= 0 || parent.swarmRole !== 'large') return;
      if (now < Number(parent.swarmNextBroodAt || 0)) return;
      parent.swarmNextBroodAt = now + interval;
      const alive = state.normalEnemies.filter(e => e && e.hp > 0 && e.swarmRole === 'small' && e.swarmParent === parent.uid).length;
      if (alive >= maxBrood) return;
      const a = Math.random() * Math.PI * 2;
      spawnSwarmEnemy(cfg.smallEnemyId,
        clamp(parent.x + Math.cos(a) * 18, 24, w - 24),
        clamp(parent.y + 26 + Math.sin(a) * 10, 40, h - 40),
        now, { swarmParent: parent.uid });
      if (parent.el) {
        parent.el.classList.remove('swarm-brooding');
        void parent.el.offsetWidth;
        parent.el.classList.add('swarm-brooding');
      }
    });
  }

  // build1512 — CH07-04：親個体なしの小蜘蛛の大群。
  // 既存の群れAIだけを再利用し、CH07-03と残響の塔13Fの産卵/討伐条件には触れない。
  function getCh704SpiderHorde() {
    return selectedStage && selectedStage.spiderHorde || null;
  }

  // build2119: 群れの出現方向を指定できるようにする（第10章エンカウント用）。
  //   spawnEdges: ['left','right','bottom','top'] の巡回リスト。bottom は自機の背後（画面下端）。
  //   warnMs    : 出現位置に予告マークを出してから湧くまでの時間。
  //   spawnEdges が無いステージ（CH07-04・位相回遊など）は従来どおりの出現位置。
  function pickFlankSpawnPoint(cfg, n, w, h) {
    const edges = cfg.spawnEdges;
    const edge = String(edges[n % edges.length] || 'top');
    const r = fixedStagePatternRandom('flank_spawn', n, 0);
    const margin = 23;
    const px = Number(state.player.x || w / 2), py = Number(state.player.y || h * .8);
    let x, y;
    if (edge === 'left' || edge === 'right') {
      x = edge === 'left' ? margin : w - margin;
      y = h * (0.30 + r * 0.58);
      // 自機の真横すぐには湧かせない
      if (Math.abs(x - px) < 120 && Math.abs(y - py) < 120) y = py > h * .55 ? py - 150 : py + 150;
    } else if (edge === 'bottom') {
      y = h - 26;
      x = w * (0.10 + r * 0.80);
      // 背後でも自機の足元には湧かせない。自機と反対側の半分へ寄せる
      if (Math.abs(x - px) < 130) x = px < w / 2 ? w * (0.62 + r * 0.28) : w * (0.10 + r * 0.28);
    } else {
      x = w * (0.14 + r * 0.72);
      y = 68 + ((n % 3) * 18);
    }
    return { edge, x: clamp(x, margin, w - margin), y: clamp(y, 40, h - 26) };
  }

  function showFlankSpawnWarning(point, warnMs) {
    const layer = document.getElementById('shooting-normal-enemy-layer');
    if (!layer) return null;
    const el = document.createElement('div');
    el.className = 'flank-spawn-warn edge-' + point.edge;
    el.style.left = point.x + 'px';
    el.style.top = point.y + 'px';
    el.style.setProperty('--warn-ms', Math.max(100, warnMs) + 'ms');
    el.setAttribute('aria-hidden', 'true');
    el.innerHTML = '<i>!</i>';
    layer.appendChild(el);
    return el;
  }

  function flushFlankSpawnQueue(cfg, now) {
    const queue = state.flankSpawnQueue;
    if (!queue || !queue.length) return;
    for (let i = queue.length - 1; i >= 0; i--) {
      const q = queue[i];
      if (now < q.at) continue;
      queue.splice(i, 1);
      q.el?.remove();
      if (state.finishing || state.ended) continue;
      const enemy = spawnSwarmEnemy(cfg.smallEnemyId, q.x, q.y, now, { ch704Horde: true, flankEdge: q.edge });
      if (!enemy) continue;
      enemy.el?.classList.add('ch704-horde-spider', 'flank-' + q.edge);
      enemy.hpEl?.classList.add('ch704-horde-spider-hp');
    }
  }

  function spawnCh704SpiderHorde(now) {
    const cfg = getCh704SpiderHorde();
    const arena = document.getElementById('shooting-arena');
    if (!cfg || !arena || !state) return;
    if (Array.isArray(cfg.spawnEdges) && cfg.spawnEdges.length) { spawnFlankHorde(cfg, arena, now); return; }
    const total = Math.max(1, Math.floor(Number(cfg.totalEnemies || 42)));
    const maxActive = Math.max(1, Math.floor(Number(cfg.maxActive || 21)));
    const interval = Math.max(250, Number(cfg.spawnIntervalMs || 900));
    if (state.normalSpawned >= total) return;
    if (now - Number(state.normalLastSpawnAt || -9999) < interval) return;
    // CH07-04 only: one count per spawn window; never allocate a new list each frame.
    let active = 0;
    for (const e of state.normalEnemies) {
      if (e && e.hp > 0 && e.ch704Horde) ++active;
    }
    if (active >= maxActive) return;
    state.normalLastSpawnAt = now;
    const w = arena.clientWidth, h = arena.clientHeight;
    const batch = Math.min(Math.max(1, Number(cfg.batchSize || 3)), total - state.normalSpawned,
      maxActive - active);
    for (let i = 0; i < batch; i++) {
      const n = Number(state.normalSpawned || 0);
      // 左右と画面上端から分散して出現。突然自機の足元へ湧かせない。
      const lane = n % 5;
      let x = lane === 0 ? 23 : lane === 1 ? w - 23 : w * (0.14 + ((n * 37) % 71) / 100);
      let y = lane <= 1 ? h * (0.25 + ((n * 11) % 43) / 100) : 68 + ((n % 3) * 18);
      const dist = Math.hypot(x - state.player.x, y - state.player.y);
      if (dist < 105) { x = x < w / 2 ? 23 : w - 23; y = 74; }
      const enemy = spawnSwarmEnemy(cfg.smallEnemyId, x, y, now, { ch704Horde: true });
      if (!enemy) break;
      enemy.el?.classList.add('ch704-horde-spider');
      enemy.hpEl?.classList.add('ch704-horde-spider-hp');
    }
  }

  function spawnFlankHorde(cfg, arena, now) {
    if (!state.flankSpawnQueue) state.flankSpawnQueue = [];
    flushFlankSpawnQueue(cfg, now);
    const queue = state.flankSpawnQueue;
    const total = Math.max(1, Math.floor(Number(cfg.totalEnemies || 24)));
    const maxActive = Math.max(1, Math.floor(Number(cfg.maxActive || 10)));
    const interval = Math.max(250, Number(cfg.spawnIntervalMs || 1100));
    const warnMs = Math.max(0, Number(cfg.warnMs || 0));
    const reserved = Number(state.normalSpawned || 0) + queue.length;
    if (reserved >= total) return;
    if (now - Number(state.normalLastSpawnAt || -9999) < interval) return;
    let active = queue.length;
    for (const e of state.normalEnemies) {
      if (e && e.hp > 0 && e.ch704Horde) ++active;
    }
    if (active >= maxActive) return;
    state.normalLastSpawnAt = now;
    const w = arena.clientWidth, h = arena.clientHeight;
    const batch = Math.min(Math.max(1, Number(cfg.batchSize || 3)), total - reserved, maxActive - active);
    // 1回の湧きは同じ方向からまとめて来る（どこから来るか読めるように）
    const n0 = Number(state.flankWaveIndex || 0);
    state.flankWaveIndex = n0 + 1;
    for (let i = 0; i < batch; i++) {
      const p = pickFlankSpawnPoint(cfg, n0, w, h);
      const spread = (i - (batch - 1) / 2) * 34;
      if (p.edge === 'bottom' || p.edge === 'top') p.x = clamp(p.x + spread, 23, w - 23);
      else p.y = clamp(p.y + spread, 40, h - 26);
      queue.push({ x: p.x, y: p.y, edge: p.edge, at: now + warnMs, el: warnMs > 0 ? showFlankSpawnWarning(p, warnMs) : null });
    }
    if (!warnMs) flushFlankSpawnQueue(cfg, now);
  }

  // 一番近い味方オブジェクト。自機はアイナの気配遮断中、偽の位置になる。
  function getSwarmLureTargets(now) {
    const targets = [];
    (state.bullets || []).forEach(p => {
      if (p && p.kind === 'remna_trap' && p.trapState === 'armed' && !p.trapExploded && p.el) {
        targets.push({ kind: 'trap', x: Number(p.x || 0), y: Number(p.y || 0) });
      }
    });
    (state.clarineDecoys || []).forEach(d => {
      if (d && d.el && Number(d.hp || 0) > 0) targets.push({ kind: 'decoy', x: Number(d.x || 0), y: Number(d.y || 0), ref: d });
    });
    if (state.mitoSummonActive) {
      targets.push({ kind: 'summon', x: Number(state.mitoSummonX || 0), y: Number(state.mitoSummonY || 0) });
    }
    const aim = getEnemyAimPosition();
    targets.push({ kind: 'player', x: Number(aim.x || 0), y: Number(aim.y || 0) });
    return targets;
  }

  function updateSwarmEnemy(enemy, dt, now, w, h, targets) {
    const cfg = getSwarmBattleConfig() || {};
    const def = enemy.def || {};
    let best = null, bestD = Infinity;
    targets.forEach(t => {
      const d = Math.hypot(t.x - enemy.x, t.y - enemy.y);
      if (d < bestD) { bestD = d; best = t; }
    });
    if (!best) return;

    // 小は標的の周りを取り囲むように群がる（全員が一点に重ならない）
    const age = getEnemyMotionAgeSeconds(enemy, now);
    const ring = enemy.ch704Horde ? 11 + (enemy.phaseSeed % 1) * 8
      : enemy.swarmRole === 'small' ? 16 + (enemy.phaseSeed % 1) * 10 : 0;
    const tx = best.x + Math.cos(enemy.phaseSeed * 3 + age * 1.6) * ring;
    const ty = best.y + Math.sin(enemy.phaseSeed * 3 + age * 1.6) * ring * .7;
    const dx = tx - enemy.x, dy = ty - enemy.y, dist = Math.hypot(dx, dy);
    const speed = Math.max(10, Number(def.moveSpeed || 60)) *
      (enemy.ch704Horde ? Math.max(1, Number(getCh704SpiderHorde()?.moveSpeedMultiplier || 1.75)) : 1);
    if (dist > 1) {
      const step = Math.min(dist, speed * dt);
      // 這い寄る揺らぎ
      const wob = Math.sin(age * 9 + enemy.phaseSeed) * (enemy.swarmRole === 'small' ? 0.35 : 0.15);
      const nx = dx / dist, ny = dy / dist;
      enemy.x += (nx - ny * wob) * step;
      enemy.y += (ny + nx * wob) * step;
    }
    // 群れ同士で押し合い、一点に重ならないようにする（大どうしは特に間隔を空ける）
    (state.normalEnemies || []).forEach(o => {
      if (!o || o === enemy || o.hp <= 0 || !o.el ||
          (o.swarmRole !== 'large' && o.swarmRole !== 'small')) return;
      const minD = (enemy.swarmRole === 'large' && o.swarmRole === 'large') ? 128
        : (enemy.swarmRole === 'large' || o.swarmRole === 'large') ? 40 : 15;
      const ox = enemy.x - o.x, oy = enemy.y - o.y;
      // AABB prefilter prevents expensive distance/sqrt for distant spiders.
      if (Math.abs(ox) >= minD || Math.abs(oy) >= minD) return;
      const d2 = ox * ox + oy * oy;
      if (d2 >= minD * minD) return;
      const od = Math.sqrt(d2);
      const push = (minD - od) * (enemy.swarmRole === 'large' && o.swarmRole !== 'large' ? .15 : .5);
      if (od < .01) { enemy.x += (Math.random() - .5) * 2; return; }
      enemy.x += ox / od * push;
      enemy.y += oy / od * push;
    });
    const maxY = enemy.swarmRole === 'large' ? h * Number(cfg.largeMaxYRate || .58) : h - 40;
    enemy.x = clamp(enemy.x, 24, w - 24);
    enemy.y = clamp(enemy.y, 60, Math.max(70, maxY));

    // build1668: クラリネのデコイは壊れない（群れは引き寄せられるだけ）。
  }

  // 残響の塔13F限定：三頭狼は群れに参加せず、画面上部を左右に往復し5WAYを2秒ごとに放つ。
  // CH07-02に登場する同一画像の三頭狼の挙動は変えない。
  function updateTower13GuardEnemy(enemy, now, w, h) {
    const cfg = getSwarmBattleConfig();
    if (!cfg || cfg.guardAi !== 'tower13_upper_spread5') return;

    const age = getEnemyMotionAgeSeconds(enemy, now);
    const sideMargin = Math.min(w * .5, Math.max(68, w * .18));
    const horizontalRoom = Math.max(0, (w - sideMargin * 2) / 2);
    const amplitude = Math.min(horizontalRoom, w * Number(cfg.guardMoveAmplitudeRate || .24));
    enemy.x = clamp(w * .5 + Math.sin(age * Number(cfg.guardMoveAngularSpeed || .92)) * amplitude,
      sideMargin, Math.max(sideMargin, w - sideMargin));
    enemy.y = clamp(h * Number(cfg.guardTopYRate || .20), 86, Math.max(86, h * .28));

    const fireInterval = Math.max(200, Number(cfg.guardShotIntervalMs || 2000));
    if (now - Number(enemy.lastShotAt || now) < fireInterval) return;
    enemy.lastShotAt = now;
    const target = getEnemyAimPosition();
    const aimAngle = Math.atan2(target.y - enemy.y, target.x - enemy.x);
    const stepAngle = Number(cfg.guardSpreadAngleRad || .23);
    const speed = Number(cfg.guardBulletSpeed || enemy.def?.bulletSpeed || 235);
    const damage = Number(cfg.guardBulletDamage || enemy.def?.bulletDamage || 120);
    // build1693: 位相回遊の高層は7WAY（guardWays）。塔13Fは従来どおり5WAY。
    const ways = Math.max(1, Math.min(9, Math.floor(Number(cfg.guardWays || 5))));
    Array.from({ length: ways }, (_, k) => k - (ways - 1) / 2).forEach(i => {
      shootNormalEnemyProjectile(enemy, aimAngle + stepAngle * i, speed, damage,
        'shooting-enemy-bullet shooting-mini-enemy-bullet shooting-tower13-wolf-bullet');
    });
  }

  function isNormalBattle() {
    return !!(state && state.battleType === 'normal');
  }

  function getNormalBattleConfig() {
    const source = (selectedStage && selectedStage.normalBattle) || {};

    // build1097: CH01-01 uses a dedicated 1 -> 2 -> 5 tutorial wave controller.
    if (isSelectedBaseStage(SHOOTING_STAGE_ID.CH01_01)) {
      return {
        ...source,
        tutorial: 'ch01_01',
        totalEnemies: 8,
        maxActive: 5,
        infiniteEnemies: false,
      };
    }

    return source;
  }

  function getBossAddsConfig() {
    return (selectedStage && selectedStage.bossAdds) || null;
  }

  function hasBossAdds() {
    if (isTowaDawnStage() && Number(state?.towaDawnSeg || 0)===0) return true;
    const cfg = getBossAddsConfig();
    // build1592: カミラは子蜘蛛（通常敵として扱い、自機弾で撃ち落とせる）を召喚する。
    if (isCamillaBattle()) return true;
    // build1643: イノリの鳥居も通常敵として扱う（自機弾・ULTが当たる）。召喚は updateInoriMechanics が管理。
    if (isInoriBattle()) return true;
    if (isEclipseBattle()) return true; // build1681: エクリプスの天秤
    if (getMemoryGuardianRule()) return true; // build1759: 記憶決戦の守護者
    if (isHazeBattle()) return true; // build1866: 陽炎の分身
    if (isNerisaBattle()) return true; // build2125: ネリサの分裂体
    if (isPartyEventStage()) return true; // build2150: 夜会の客
    return !!(cfg && Array.isArray(cfg.enemyIds) && cfg.enemyIds.length);
  }

  function positionMiniEnemyHp(enemy) {
    if (!enemy || !enemy.hpEl) return;

    const scale = Math.max(
      0.1,
      Number(enemy.displayScale || (enemy.def && enemy.def.uiScale) || 1)
    );

    // Base mobile enemy box is about 60px tall.
    // Keep the HP bar just above the visible unit as uiScale changes.
    const hpOffsetY = 30 * scale + 9;
    // build1726: イノリの鳥居は上側だとボスHP表示に重なって読めないため、鳥居の足元へ出す
    // build1762: 記憶決戦の守護者もボスの近く（画面上部のHP表示の下）にいるため、バーは足元へ出す
    const hpY = (enemy.inoriSide || enemy.memoryGuardian) ? enemy.y + 30 * scale + 4 : enemy.y - hpOffsetY;

    enemy.hpEl.style.transform =
      `translate3d(${enemy.x}px,${hpY}px,0) translate(-50%,-50%)`;

    if (enemy.elementEl) {
      const iconX = enemy.x - 43;
      enemy.elementEl.style.transform =
        `translate3d(${iconX}px,${hpY}px,0) translate(-50%,-50%)`;
    }

    if (enemy.weaknessBarrierEl) {
      // build836: 属性バリアは敵本体へ密着。
      // 実測済みサイズを最優先し、生成直後だけCSS基準サイズで補完する。
      // 旧82px基準の大きなリングは廃止し、敵画像の外周+約2%だけにする。
      const scale = Math.max(0.1, Number(enemy.displayScale || 1));
      const measuredDiameter = Math.max(
        Number(enemy._hw || 0) * 2,
        Number(enemy._hh || 0) * 2
      );
      const fallbackDiameter = 62 * scale;
      const barrierSize = Math.max(50, (measuredDiameter > 0 ? measuredDiameter : fallbackDiameter) * 1.02);
      enemy.weaknessBarrierEl.style.width = `${barrierSize}px`;
      enemy.weaknessBarrierEl.style.height = `${barrierSize}px`;
      enemy.weaknessBarrierEl.style.transform =
        `translate3d(${enemy.x}px,${enemy.y}px,0) translate(-50%,-50%)`;
    }
  }

  function renderMiniEnemyHp(enemy, flash) {
    if (!enemy || !enemy.hpEl) return;
    const fill = enemy.hpEl.querySelector('i');
    const max = Math.max(1, Number(enemy.hpMax || 1));
    const ratio = Math.max(0, Math.min(1, Number(enemy.hp || 0) / max));
    if (fill) fill.style.transform = `scaleX(${ratio})`;
    // build1762: HIT数で倒す敵は残りHIT数をバーの横に出す
    if (enemy.memoryHitHp) {
      let label = enemy.hpEl.querySelector('.mg-hits');
      if (!label) { label = document.createElement('b'); label.className = 'mg-hits'; enemy.hpEl.appendChild(label); }
      label.textContent = String(Math.max(0, Math.ceil(Number(enemy.hp || 0))));
    }

    enemy.hpEl.classList.toggle('low', ratio <= .30);

    // build1666: 強制レイアウト（offsetWidth）をやめ、次のフレームで付け直す。同じ敵へは約0.12秒に1回まで
    if (flash) {
      const now = performance.now();
      if (now - Number(enemy.hpFlashAt || 0) >= 120) {
        enemy.hpFlashAt = now;
        const hpEl = enemy.hpEl;
        hpEl.classList.remove('hit');
        requestAnimationFrame(() => {
          if (!hpEl.isConnected) return;
          hpEl.classList.add('hit');
          setTimeout(() => hpEl.classList.remove('hit'), 180);
        });
      }
    }
  }

  function resolveChapter02ZakoVariant(enemyDef, spawnIndex, variantConfig) {
    const stageId = String(getSelectedBaseStageId() || '');
    if (!/^shooting_ch02_(02|03|04)$/.test(stageId)) return enemyDef;

    const variants = Array.isArray(variantConfig?.enemyVariants) && variantConfig.enemyVariants.length
      ? variantConfig.enemyVariants
      : ['normal', 'atack'];
    const variant = String(variants[Math.max(0, Number(spawnIndex || 0)) % variants.length] || 'normal').toLowerCase();
    const base = enemyDef || {};

    if (variant === 'atack') {
      return Object.assign({}, base, {
        name: '光の残滓・突進型',
        image: 'images/zako_enemy_01_atack_light.webp',
        element: 'light',
        behavior: 'generic_element_charge_v1',
        telegraphMs: 760,
        chargeSpeed: Number(variantConfig?.chargeSpeed || base.chargeSpeed || 500),
        chargeDurationMs: 620,
        // CH02-04専用: 攻撃弾なし。予告後に味方ユニットへ6秒周期で突進。
        ...(stageId === 'shooting_ch02_04' ? {
          chargeIntervalMs: 6000,
          contactDamage: 180,
        } : {}),
      });
    }

    return Object.assign({}, base, {
      name: '光の残滓・遠隔型',
      image: 'images/zako_enemy_01_normal_light.webp',
      element: 'light',
      behavior: 'generic_element_shot_v1',
      shotPattern: stageId === 'shooting_ch02_04' ? 'spread5' : '',
      // CH02-04専用: 3秒毎、光属性の5WAY spread。
      fireRate: stageId === 'shooting_ch02_04' ? 3000 : Number(base.fireRate || 1280),
      bulletSpeed: Number(base.bulletSpeed || 215),
      bulletDamage: Number(base.bulletDamage || 90),
    });
  }

  function createNormalEnemy(enemyDef, now, opts) {
    combatElementTarget = null;
    const arena = document.getElementById('shooting-arena');
    const layer = document.getElementById('shooting-normal-enemy-layer');
    if (!arena || !layer || !enemyDef) return null;

    const w = arena.clientWidth;
    const h = arena.clientHeight;
    const el = document.createElement('img');
    el.className = 'shooting-mini-enemy spawning';
    // build1141: ステージ固有の雑魚画像を指定可能にする。
    // 既存ステージはenemyDef.imageをそのまま使用する。
    const stageEnemyImage = String(enemyDef.ch404Image || selectedStage?.normalBattle?.enemyImage || enemyDef.image || '');
    el.src = stageEnemyImage;
    el.alt = enemyDef.name || '敵';
    el.draggable = false;
    // build1659: 専用画像が未配置でも代わりの画像で表示する
    if (enemyDef.fallbackImage) {
      el.onerror = () => { el.onerror = null; el.src = String(enemyDef.fallbackImage); };
    }

    const baseDisplayScale = getNormalEnemyBaseDisplayScale(enemyDef);
    const isChapter02MidBoss =
      getSelectedBaseStageId() === 'shooting_ch02_04' &&
      enemyDef.behavior === 'mini_violence_v1';
    const displayScale = baseDisplayScale * getResponsiveCombatScaleProfile().normalEnemy;

    el.style.setProperty('--enemy-scale', String(displayScale));
    if (isChapter02MidBoss) el.classList.add('shooting-ch02-midboss');
    if (enemyDef.strongEnemy) el.classList.add('shooting-strong-enemy');
    layer.appendChild(el);

    // Only CH07-04 tiny spiders omit the invisible HP bar DOM entirely.
    const lightweightHordeSpider = !!(getCh704SpiderHorde() && enemyDef.swarmRole === 'small');
    let hpWrap = null;
    if (!lightweightHordeSpider) {
      hpWrap = document.createElement('div');
      hpWrap.className = 'shooting-mini-enemy-hp';
      hpWrap.setAttribute('aria-hidden', 'true');
      hpWrap.innerHTML = '<i></i>';
      // build1659: 樹獣の森の敵は、HPバーのすぐ下に成長ゲージ
      if (enemyDef.verdantGrowth && selectedStage?.verdant) {
        hpWrap.classList.add('has-verdant-growth');
        hpWrap.insertAdjacentHTML('beforeend', '<span class="verdant-growth-bar"><b></b></span>');
      }
      layer.appendChild(hpWrap);
    }

    // 属性アイコンはHPバーと同じレイヤーの独立DOMとして配置する。
    const enemyElement = getMemoryBarrierAddElement() || normalizeCombatElement(
      enemyDef.element ||
      selectedStage?.enemyElement ||
      selectedStage?.element
    );
    let elementEl = null;
    // build1687: カミラの子蜘蛛のように数が多い無属性の敵は、属性アイコンDOMを作らない（毎フレームの位置更新を減らす）
    const elementIconSrc = opts && opts.noElementIcon ? '' : getCombatElementIcon(enemyElement);
    if (elementIconSrc) {
      elementEl = document.createElement('img');
      elementEl.className = 'shooting-mini-enemy-element-icon';
      elementEl.src = elementIconSrc;
      elementEl.alt = '';
      elementEl.setAttribute('aria-hidden', 'true');
      elementEl.draggable = false;
      layer.appendChild(elementEl);
    }

    // build1018: 属性バリアは全ステージ共通ルール。
    // weakness-only対象は、自身の属性色の膜を常時まとい、本体へ完全追従する。
    // CH06の強敵もDAILY上級も同じ判定関数を使い、弱点属性以外はIMMUNE。
    let weaknessBarrierEl = null;
    if (enemyElement !== 'neutral' && isStageWeaknessOnlyTarget(enemyElement)) {
      weaknessBarrierEl = document.createElement('div');
      weaknessBarrierEl.className = `shooting-mini-enemy-weakness-barrier element-${enemyElement}`;
      weaknessBarrierEl.dataset.element = enemyElement;
      weaknessBarrierEl.setAttribute('aria-hidden', 'true');
      layer.appendChild(weaknessBarrierEl);
      el.classList.add('has-weakness-barrier');
    }

    const lane = state.normalSpawned % 4;
    const lanes = [w * .20, w * .40, w * .60, w * .80];
    const spawnIndex = Number(state.normalSpawned || 0);
    const x = enemyDef.strongEnemy
      ? w * .50
      : lanes[lane] + (fixedStagePatternRandom('normal_spawn_x', spawnIndex, 0) - .5) * Math.min(28, w * .06);
    // build1521: CH07-02は固定ボスHP欄の下に三頭狼を配置。HP UIと画像を重ねない。
    const isCh702Wolf = isSelectedBaseStage(SHOOTING_STAGE_ID.CH07_02) &&
      enemyDef.id === selectedStage?.enemyIds?.[0];
    const y = isCh702Wolf
      ? Math.max(148, h * .28)
      : (enemyDef.strongEnemy
        ? Math.max(86, h * .145)
        : Math.max(92, h * (.16 + (state.normalSpawned % 2) * .075)));
    const cfg = getNormalBattleConfig();
    const hpSequence = Array.isArray(cfg.enemyHpSequence) ? cfg.enemyHpSequence : null;
    const sequencedHp = hpSequence && hpSequence.length
      ? Number(hpSequence[spawnIndex % hpSequence.length])
      : NaN;
    const stageEnemyHp = Number(cfg.enemyHp);
    // build1643: 位相回遊の監視の眼は階層に応じたHP
    const watcherHp = enemyDef.behavior === 'po_watcher_v1' ? Number(selectedStage?.phaseOdyssey?.watcherHp || 0)
      : (enemyDef.behavior === 'inori_torii_v1' ? getInoriToriiHp()
        : (enemyDef.behavior === 'verdant_seed_v1' ? Number(selectedStage?.verdant?.seeds?.hp || 0) : 0)); // build1643: イノリの鳥居も階層・ステージ指定のHP／build1663: 成長の実
    const enemyHp = watcherHp > 0
      ? watcherHp
      : Number.isFinite(Number(enemyDef.ch404Hp)) && enemyDef.ch404Hp != null
      ? Math.max(1, Number(enemyDef.ch404Hp))
      : Number.isFinite(sequencedHp)
      ? Math.max(1, sequencedHp)
      : (Number.isFinite(stageEnemyHp)
        ? stageEnemyHp
        : Number(enemyDef.hp || 18));

    const enemy = {
      uid: `mini_${String(state.stageId || 'stage')}_${spawnIndex}`,
      ch404Role: enemyDef.ch404Role || null,
      def: enemyDef, el, hpEl: hpWrap, elementEl, weaknessBarrierEl, x, y, baseX: x, baseY: y,
      baseDisplayScale,
      displayScale,
      element: enemyElement,
      hp: enemyHp,
      hpMax: enemyHp,
      spawnedAt: now,
      lastShotAt: now + fixedStagePatternRandom('normal_first_shot', spawnIndex, 0) * 500,
      phaseSeed: fixedStagePatternRandom('normal_phase_seed', spawnIndex, 0) * Math.PI * 2,
      nextActionAt: now + 900 + fixedStagePatternRandom('normal_next_action', spawnIndex, 0) * 450,
      actionIndex: state.normalSpawned % 3,
      patternVolleyIndex: 0,
      attackState: 'idle',
      attackExecuteAt: 0,
      dashUntil: 0,
      dashVx: 0,
      dashVy: 0,
    };
    positionUnit(el, x, y);
    positionMiniEnemyHp(enemy);
    renderMiniEnemyHp(enemy);
    // build1458: 敵画像の読み込み（デコード）完了を待ってから、本体と
    // 属性バリア・HPバー・属性アイコンを同時に表示する。
    // 以前は画像が未デコードのまま spawning を外していたため、
    // バリアの輪だけが先に出て、少し遅れて敵本体が出ていた。
    const companions = [weaknessBarrierEl, hpWrap, elementEl].filter(Boolean);
    companions.forEach(node => node.classList.add('awaiting-enemy-image'));
    let revealed = false;
    const reveal = () => {
      if (revealed) return;
      revealed = true;
      requestAnimationFrame(() => {
        el.classList.remove('spawning');
        companions.forEach(node => node.classList.remove('awaiting-enemy-image'));
        // spawningクラス除去後(最終的な--enemy-scale込みの見た目)でサイズを実測してキャッシュする。
        // ここでのgetBoundingClientRect呼び出しは生成時に1回だけなので、毎フレームのコストにはならない。
        measureUnitSize(enemy);
        // 実測した敵サイズで属性バリアを即座に再フィットする。
        positionMiniEnemyHp(enemy);
      });
    };
    if (el.complete && el.naturalWidth > 0) {
      reveal();
    } else {
      const decodeOrLoad = typeof el.decode === 'function'
        ? el.decode().catch(() => {})
        : new Promise(resolve => {
            el.addEventListener('load', resolve, { once:true });
            el.addEventListener('error', resolve, { once:true });
          });
      decodeOrLoad.then(reveal);
      // 画像が遅い・失敗した場合でも、最長1.5秒で必ず表示する。
      setTimeout(reveal, 1500);
    }
    return enemy;
  }

  // CH04-4: one reinforced summoner at a time; surviving adds persist between phases.
  function spawnCh404Enemies(now) {
    const cfg = getNormalBattleConfig();
    const phaseElements = ['fire', 'aqua', 'light'];
    if (!Number.isInteger(state.ch404Phase)) state.ch404Phase = 0;
    if (state.ch404Phase >= phaseElements.length) return;
    const current = (state.normalEnemies || []).find(e => e && e.hp > 0 && e.ch404Role === 'summoner');
    if (!current) {
      const base = getShootingEnemy(selectedStage.enemyIds[0]);
      if (!base || !base.implemented) return;
      const element = phaseElements[state.ch404Phase];
      // A newly appearing reinforced enemy receives its own fresh barrier.
      const enemy = createNormalEnemy(Object.assign({}, base, {
        element, strongEnemy: true, ch404Role: 'summoner', ch404Hp: 1440,
      }), now);
      if (!enemy) return;
      state.normalEnemies.push(enemy);
      state.normalSpawned++;
      state.ch404SummonAt = now + 15000;
      return;
    }
    if (now < Number(state.ch404SummonAt || 0)) return;
    state.ch404SummonAt = now + 15000;
    const adds = state.normalEnemies.filter(e => e && e.hp > 0 && e.ch404Role === 'add');
    if (adds.length >= 4) return;
    const base = getShootingEnemy(selectedStage.enemyIds[0]);
    if (!base || !base.implemented) return;
    const enemy = createNormalEnemy(Object.assign({}, base, {
      element: 'neutral', strongEnemy: false, ch404Role: 'add', ch404Hp: 280,
    }), now);
    if (!enemy) return;
    state.normalEnemies.push(enemy);
    state.normalSpawned++;
  }

  function spawnNormalEnemies(now) {
    if (!isNormalBattle() || state.finishing || state.ended) return;
    if (isCh404SummonerBattle()) { spawnCh404Enemies(now); return; }
    if (isSwarmBattle()) { spawnSwarmEnemies(now); return; }
    if (getCh704SpiderHorde()) { spawnCh704SpiderHorde(now); return; }
    if (isChapter101TutorialStage() || isChapter102TutorialStage()) return;
    const cfg = getNormalBattleConfig();

    // アイテム収集ミッションは、必要数を拾うまで敵が枯渇しないよう保証する。
    // ステージ設定が有限敵でも、収集未達成の間だけは補充を継続する。
    const effectiveMission = getEffectiveNormalMission();
    const collectMissionActive =
      effectiveMission &&
      effectiveMission.type === SHOOTING_MISSION_TYPE.COLLECT_ITEM &&
      state.collectedItems < Number(effectiveMission.target || 3);

    const infiniteEnemies = !!cfg.infiniteEnemies || collectMissionActive;
    const total = Number(cfg.totalEnemies || 7);
    const maxActive = Number(cfg.maxActive || 2);
    const interval = Number(cfg.spawnIntervalMs || 900);

    // 無限湧き、または未達成の収集ミッションでは撃破数でスポーンを止めない。
    if ((!infiniteEnemies && state.normalSpawned >= total) || state.normalEnemies.filter(e => !(e && e.deinovaUltCore)).length >= maxActive) return; // build2060: ULTのコアは数えない
    if (now - state.normalLastSpawnAt < interval) return;
    const enemyIds = (
      selectedStage &&
      Array.isArray(selectedStage.enemyIds) &&
      selectedStage.enemyIds.length
    ) ? selectedStage.enemyIds : [];
    if (!enemyIds.length) return;

    const spawnOne = () => {
      const sequence = Array.isArray(cfg.enemySequence) ? cfg.enemySequence : null;
      const enemyId = sequence && sequence.length
        ? sequence[state.normalSpawned % sequence.length]
        : enemyIds[state.normalSpawned % enemyIds.length];
      const baseDef = getShootingEnemy(enemyId);
      if (!baseDef || !baseDef.implemented) return false;

      let def = resolveChapter02ZakoVariant(baseDef, state.normalSpawned, cfg);
      if (cfg.tower11Spread) def = Object.assign({}, def, {shotPattern:'tower11_spread7',fireRate:1280,bulletSpeed:188,bulletDamage:185});

      // ニーナ試遊専用: ミニ敵の属性と敵弾を闇へ。オリビア・通常ステージは元定義のまま。
      if (isGachaTrialStage() && gachaTrialCharacterId === 36) {
        def = Object.assign({}, def, { element: 'dark' });
      }
      // build1616: トワ試遊は光属性、スマイル試遊は闇属性の敵にする。
      if (isGachaTrialStage() && gachaTrialCharacterId === 101) {
        def = Object.assign({}, def, { element: 'light' });
      }
      if (isGachaTrialStage() && gachaTrialCharacterId === 56) {
        def = Object.assign({}, def, { element: 'dark' });
      }
      // build1732: ナイトシェード（闇）試遊は光属性の敵にして、属性有利（Weak）が見えるようにする。
      if (isGachaTrialStage() && gachaTrialCharacterId === 57) {
        def = Object.assign({}, def, { element: 'light' });
      }

      // build1241: 通常戦でスポーン順ごとの属性指定を許可する。
      // CH03-03は同じMINI_03を、木→火→水→闇→光の5属性で1体ずつ出す。
      const elementSequence = Array.isArray(cfg.enemyElementSequence)
        ? cfg.enemyElementSequence
        : null;
      if (elementSequence && elementSequence.length) {
        const forcedElement = normalizeCombatElement(
          elementSequence[state.normalSpawned % elementSequence.length]
        );
        if (forcedElement) {
          def = Object.assign({}, def, { element: forcedElement });
        }
      }

      // build1679: 位相回遊のお題「精鋭」：最初の1体がHP5倍・大型・連射やや速い
      const odysseyElite = (cfg.odysseyElite && state.normalSpawned === 0) ? cfg.odysseyElite : null;
      if (odysseyElite && Number(def.fireRate) > 0) def = Object.assign({}, def, { fireRate: Math.round(Number(def.fireRate) * Number(odysseyElite.fireRateMul || 0.8)) });
      const enemy = createNormalEnemy(def, now);
      if (!enemy) return false;
      if (odysseyElite) {
        const mul = Math.max(1, Number(odysseyElite.hpMul || 5));
        enemy.hp = Math.round(Number(enemy.hp || 1) * mul);
        enemy.hpMax = Math.round(Number(enemy.hpMax || enemy.hp) * mul);
        enemy.poElite = true;
        const sc = Math.max(1, Number(odysseyElite.scale || 1));
        enemy.baseDisplayScale = Number(enemy.baseDisplayScale || getNormalEnemyBaseDisplayScale(enemy.def || def) || 1) * sc;
        enemy.displayScale = Number(enemy.displayScale || 1) * sc;
        if (enemy.el) {
          enemy.el.style.setProperty('--enemy-scale', String(enemy.displayScale));
          enemy.el.classList.add('po-elite');
        }
        if (enemy.hpEl) enemy.hpEl.classList.add('po-elite-hp');
        if (enemy.elementEl) enemy.elementEl.classList.add('po-elite-icon');
      }
      state.normalEnemies.push(enemy);
      state.normalSpawned++;

      // build1245: CH02-02は最初の敵を盤面に表示した後でミモザの説明を出す。
      // 1フレーム待つことで、敵本体・属性バリアが先に描画される。
      if (
        isChapter202ElementTutorialStage() &&
        state.ch202ElementTutorialPending &&
        !state.ch202ElementTutorialShown &&
        state.normalSpawned === 1
      ) {
        state.ch202ElementTutorialPending = false;
        state.ch202ElementTutorialShown = true;
        requestAnimationFrame(() => {
          if (!state || state.ended || !isChapter202ElementTutorialStage()) return;
          showChapter202ElementTutorialIntro();
        });
      }

      return true;
    };

    if (cfg.spawnAllAtStart && state.normalSpawned === 0) {
      const burstCount = Math.min(total, maxActive);
      for (let i = 0; i < burstCount; i++) {
        if (!spawnOne()) break;
      }
      state.normalLastSpawnAt = now;
      return;
    }

    if (!spawnOne()) return;
    state.normalLastSpawnAt = now;
  }

  // ============================================================
  // build1643 ボス「オーバーシア」（STORY CH08-04 / 位相回遊）：監視ギミック
  //  ・配下「監視の眼」（最大3体）が首振りしながら扇形の視界を持つ
  //  ・自機が視界に入っている間だけ、画面上の全ての敵弾が自機へ追従する
  //  ・視界から外れる／監視の眼を倒すと、敵弾はその時の向きのまま直進に戻る
  // ============================================================
  // ============================================================
  // build1643 レムナント「イノリ」（位相回遊で先行実装）
  //  ・全属性バリア：張っている間、イノリ本体はどの攻撃も通らない（IMMUNE）
  //  ・開幕にイノリの左右・少し後方へ鳥居を2基召喚。鳥居はイノリに追従し、攻撃が通る
  //  ・鳥居は3秒おきに真下へ極太レーザー（予兆→照射）
  //  ・鳥居を2基とも破壊すると7秒間バリアが消え、その後鳥居が2基とも復活してバリアが戻る
  //  ・本体：WARNING弾（共通）／渦巻弾幕（鈍化の呪い弾は build1727 で廃止。curse:true で復活）
  // ============================================================
  function getInoriConfig() {
    return (BOSS && BOSS.inoriMechanics && selectedStage && selectedStage.type !== 'normal') ? BOSS.inoriMechanics : null;
  }
  function isInoriBattle() { return !!getInoriConfig(); }
  function isInoriBarrierUp() {
    return !!(state && state.inori && state.inori.barrierUp && isInoriBattle());
  }
  function getInoriToriiHp() {
    const po = Number(selectedStage?.phaseOdyssey?.toriiHp || 0);
    if (po > 0) return po;
    const stageHp = Number(selectedStage?.inoriToriiHp || 0) * (isInoriSpecialStage() ? getInoriSpecialLapConfig().torii : 1); // build1819
    if (stageHp > 0) return stageHp;
    const def = getShootingEnemy(window.ShootingEnemies?.SHOOTING_ENEMY_ID?.INORI_TORII || 'shooting_inori_torii');
    return Math.max(1, Number(def && def.hp || 1500));
  }
  function getAliveInoriTorii() {
    return (state && Array.isArray(state.normalEnemies) ? state.normalEnemies : [])
      .filter(e => e && e.hp > 0 && e.def && e.def.behavior === 'inori_torii_v1');
  }
  // 鳥居はイノリの左右・少し後方へ付き従う。レーザーの予兆〜照射中だけはその場に留まり（射線が動かない）、
  // 終わったら滑らかにイノリの横へ戻る。snap=true は召喚時の即配置。
  function placeInoriTorii(enemy, w, snap) {
    const cfg = getInoriConfig() || {};
    const side = Number(enemy.inoriSide || 1);
    const off = Math.min(Number(cfg.toriiOffsetX || 92), w * 0.26);
    const tx = clamp(Number(state.boss.x || w * .5) + side * off, 40, Math.max(40, w - 40));
    const ty = Math.max(70, Number(state.boss.y || 80) - Number(cfg.toriiBackY || 18));
    if (snap) { enemy.x = tx; enemy.y = ty; }
    else if (performance.now() >= Number(enemy.inoriHoldUntil || 0)) {
      enemy.x += (tx - enemy.x) * 0.12;
      enemy.y += (ty - enemy.y) * 0.12;
    }
    enemy.baseX = enemy.x; enemy.baseY = enemy.y;
  }
  function spawnInoriTorii(now, onlySides) {
    const arena = document.getElementById('shooting-arena');
    const def = getShootingEnemy(window.ShootingEnemies?.SHOOTING_ENEMY_ID?.INORI_TORII || 'shooting_inori_torii');
    if (!arena || !def) return;
    const w = arena.clientWidth;
    (Array.isArray(onlySides) ? onlySides : [-1, 1]).forEach(side => {
      const enemy = createNormalEnemy(def, now);
      if (!enemy) return;
      enemy.inoriSide = side;
      enemy.el.classList.add('inori-torii');
      if (enemy.hpEl) {
        enemy.hpEl.classList.add('inori-torii-hp');
        // 敵レイヤー（z9）はイノリ本体（z20）の下になるため、HPバーと属性アイコンだけ盤面直下へ移して前面に出す
        arena.appendChild(enemy.hpEl);
        if (enemy.elementEl) { enemy.elementEl.classList.add('inori-torii-icon'); arena.appendChild(enemy.elementEl); }
      }
      placeInoriTorii(enemy, w, true);
      positionUnit(enemy.el, enemy.x, enemy.y);
      positionMiniEnemyHp(enemy);
      state.normalEnemies.push(enemy);
    });
    state.inori.toriiSpawned = true;
    if (Array.isArray(onlySides)) return; // build1764: 片側だけの修復ではレーザー周期をリセットしない
    state.inori.nextLaserAt = now + 1600; // 出現直後は少し待ってから初撃
  }
  function syncInoriBarrierDom() {
    const arena = document.getElementById('shooting-arena');
    if (!arena || !state || !state.inori) return;
    let el = document.getElementById('inori-barrier');
    if (!state.inori.barrierUp || !(state.boss && state.boss.hp > 0)) { if (el) el.remove(); return; }
    if (!el) {
      el = document.createElement('div');
      el.id = 'inori-barrier';
      el.className = 'inori-barrier';
      el.setAttribute('aria-hidden', 'true');
      el.innerHTML = '<i></i><b>ALL ELEMENT BARRIER</b>';
      arena.appendChild(el);
    }
    const boss = document.getElementById(BOSS_ID);
    const base = Math.max(Number(boss && boss.offsetWidth || 126), Number(boss && boss.offsetHeight || 126));
    const size = Math.round(base * Math.max(.1, Number(getResponsiveBossDisplayScale() || 1)) * 1.12);
    el.style.width = size + 'px';
    el.style.height = size + 'px';
    el.style.transform = `translate3d(${Number(state.boss.x || 0)}px,${Number(state.boss.y || 0)}px,0) translate(-50%,-50%)`;
  }
  // build1726: 復活までの残り時間は、盤面中央の大きな帯をやめ、イノリ本体を囲む細いリング（減っていく）と
  //  足元の小さな秒数で表示する。バリアが戻る場所＝攻撃している場所なので視線を動かさずに読める。
  function syncInoriBreakBadge(now) {
    const arena = document.getElementById('shooting-arena');
    if (!arena || !state || !state.inori) return;
    let el = document.getElementById('inori-break-badge');
    if (state.inori.barrierUp || !(state.boss && state.boss.hp > 0)) { if (el) el.remove(); return; }
    if (!el) {
      el = document.createElement('div');
      el.id = 'inori-break-badge';
      el.className = 'inori-break-badge';
      el.setAttribute('aria-hidden', 'true');
      el.innerHTML = '<svg viewBox="0 0 100 100" aria-hidden="true"><circle class="track" cx="50" cy="50" r="46"/>'
        + '<circle class="remain" cx="50" cy="50" r="46" pathLength="100"/></svg>'
        + '<em><small>鳥居復活</small><b></b></em>';
      arena.appendChild(el);
    }
    const cfg = getInoriConfig() || {};
    const totalMs = isInoriSpecialStage() ? 8000 : Math.max(1000, Number(cfg.barrierDownMs || 7000));
    const leftMs = Math.max(0, Number(state.inori.reviveAt || 0) - now);
    const boss = document.getElementById(BOSS_ID);
    const base = Math.max(Number(boss && boss.offsetWidth || 126), Number(boss && boss.offsetHeight || 126));
    const size = Math.round(base * Math.max(.1, Number(getResponsiveBossDisplayScale() || 1)) * 1.12);
    el.style.width = size + 'px';
    el.style.height = size + 'px';
    el.style.transform = `translate3d(${Number(state.boss.x || 0)}px,${Number(state.boss.y || 0)}px,0) translate(-50%,-50%)`;
    const remain = el.querySelector('.remain');
    if (remain) remain.style.strokeDashoffset = String(100 - (leftMs / totalMs) * 100);
    const label = (leftMs / 1000).toFixed(1) + 's';
    const b = el.querySelector('b');
    if (b && b.textContent !== label) b.textContent = label;
    el.classList.toggle('is-soon', leftMs <= 2000);
  }
  function fireInoriToriiLasers(now) {
    const cfg = getInoriConfig() || {};
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const width = Math.max(24, Number(cfg.laserWidth || 56));
    const warnMs = Math.max(300, Number(cfg.laserWarnMs || 900));
    const fireMs = Math.max(200, Number(cfg.laserFireMs || 520));
    getAliveInoriTorii().forEach(torii => {
      torii.inoriHoldUntil = now + warnMs + fireMs; // 予兆〜照射中は鳥居を動かさない
      const el = document.createElement('div');
      el.className = 'inori-torii-laser is-warn';
      el.setAttribute('aria-hidden', 'true');
      const topY = Number(torii.y || 0) + 34;
      el.style.left = `${Number(torii.x || 0)}px`;
      el.style.top = `${topY}px`;
      el.style.width = `${width}px`;
      el.innerHTML = '<i></i>';
      arena.appendChild(el);
      state.inori.beams.push({
        el, x: Number(torii.x || 0), topY, width,
        fireAt: now + Math.max(300, Number(cfg.laserWarnMs || 900)),
        endAt: now + Math.max(300, Number(cfg.laserWarnMs || 900)) + Math.max(200, Number(cfg.laserFireMs || 520)),
        firing: false, hit: false,
      });
    });
  }
  function updateInoriBeams(now) {
    const cfg = getInoriConfig() || {};
    state.inori.beams = (state.inori.beams || []).filter(beam => {
      if (!beam || !beam.el || !beam.el.isConnected) return false;
      if (now >= beam.endAt) { beam.el.remove(); return false; }
      if (!beam.firing && now >= beam.fireAt) {
        beam.firing = true;
        beam.el.classList.remove('is-warn');
        beam.el.classList.add('is-fire');
      }
      // build1875: 箱が光線の下に入ったら、光線は箱で止まる
      if (beam.firing) {
        const sh = findSmileBoxShield(beam.x, beam.topY, beam.x, beam.topY + 4000, 0);
        const bottom = sh ? Math.max(0, (beam.el.parentElement?.clientHeight || 0) - sh.y) : 0;
        if (beam.cutBottom !== bottom) { beam.cutBottom = bottom; beam.el.style.bottom = `${Math.round(bottom)}px`; }
        if (sh) showSmileBoxShield(sh, now, !beam.shieldShown), beam.shieldShown = true;
      }
      if (beam.firing && !beam.hit && state.player && Number(state.player.y || 0) >= beam.topY &&
          Math.abs(Number(state.player.x || 0) - beam.x) <= beam.width * 0.5 + 6 &&
          now >= Number(state.player.invulnUntil || 0) &&
          !findSmileBoxShieldAbove(beam.topY)) {
        beam.hit = true;
        damagePlayer(now, Math.max(1, Number(cfg.laserDamage || 350)), 'boss-heavy',
          normalizeCombatElement(state?.boss?.element || BOSS?.element), 'enemy-bullet');
      }
      return true;
    });
  }
  function fireInoriCurse(now) {
    if (!state || !state.boss) return;
    const aim = getEnemyAimPosition();
    const base = Math.atan2(aim.y - state.boss.y, aim.x - state.boss.x);
    const speed = 172;
    [-0.24, 0, 0.24].forEach(offset => {
      const a = base + offset;
      const p = makeProjectile('shooting-enemy-bullet shooting-inori-curse-bullet',
        state.boss.x, state.boss.y + 30, Math.cos(a) * speed, Math.sin(a) * speed, Number(BOSS.bulletDamage || 190));
      if (!p) return;
      p.inoriSlow = true;
      p.attackElement = 'dark';
      p.element = 'dark';
      p.canvasRadius = 11; // 紫の大きな呪い弾
      p.canvasHalfWidth = 11; p.canvasHalfHeight = 11;
      state.enemyBullets.push(p);
    });
    showFacelessBattleCut('鈍化の呪い', 'INORI');
  }
  // TICKET限定：必中「呪詛」。弾衝突や無敵判定を介さず、8秒間の速度30%低下。
  function applyInoriBinding(now) {
    if (!state || !state.inori || !state.player) return;
    state.inori.slowMemberId = Number(state.activeCharacterId) || -1;
    state.inori.slowUntil = now + 8000;
    syncInoriSlowDom();
    showFacelessBattleCut('呪詛', '移動速度 −30% / 8秒');
  }
  // 呪い弾が出場中キャラへ当たった：そのキャラの移動速度を下げる（交代で解除）
  function applyInoriSlow(now) {
    if (!state || !state.inori) return;
    const member = getActiveMember();
    if (!member || now < Number(member.invincibleUntil || 0)) return;
    state.inori.slowMemberId = Number(state.activeCharacterId);
    // TICKET限定：8秒間の呪詛。通常版の旧仕様には影響させない。
    if (isInoriSpecialStage()) state.inori.slowUntil = now + 8000;
    syncInoriSlowDom();
  }
  function clearInoriSlow() {
    if (!state || !state.inori || !state.inori.slowMemberId) return;
    state.inori.slowMemberId = 0;
    state.inori.slowUntil = 0;
    syncInoriSlowDom();
  }
  function isInoriSlowActive() {
    if (isInoriSpecialStage() && state?.inori?.slowMemberId &&
        performance.now() >= Number(state.inori.slowUntil || 0)) {
      clearInoriSlow();
      return false;
    }
    return !!(state && state.inori && state.inori.slowMemberId &&
      (isInoriSpecialStage() || Number(state.inori.slowMemberId) === Number(state.activeCharacterId)));
  }
  function getPlayerMoveMultiplier() {
    // build1679: 位相回遊の異常「鈍化」は移動75%
    const poSlow = (getPhaseOdysseyAnomaly() === 'slow' ? 0.75 : 1) *
      (isNerisaTideSlowActive() ? NERISA_TIDE_SLOW : 1); // build2119: ネリサの満ち潮（水中）
    if (!isInoriSlowActive()) return poSlow;
    return poSlow * (isInoriSpecialStage() ? 0.70 : Math.max(0.1, Math.min(1, Number(getInoriConfig()?.slowMultiplier || 0.5))));
  }
  function syncInoriSlowDom() {
    const on = isInoriSlowActive();
    document.getElementById(PLAYER_ID)?.classList.toggle('inori-slowed', on);
    const arena = document.getElementById('shooting-arena');
    let tag = document.getElementById('inori-slow-tag');
    if (!on) { if (tag) tag.remove(); return; }
    if (!tag && arena) {
      tag = document.createElement('div');
      tag.id = 'inori-slow-tag';
      tag.className = 'inori-slow-tag';
      tag.innerHTML = isInoriSpecialStage()
        ? '<strong>呪詛</strong><span class="inori-slow-effect">移動速度 −30%</span><span class="inori-slow-remaining" aria-label="呪詛の残り時間">8.0秒</span>'
        : '<strong>鈍化</strong><span>移動速度50%ダウン ─ キャラ交代で解除</span>';
      arena.appendChild(tag);
    }
    // 光輪と同じ戦闘ループで更新する。表示は実際の状態の期限と常に同期。
    if (isInoriSpecialStage() && tag) {
      const remaining = Math.max(0, (Number(state.inori.slowUntil || 0) - performance.now()) / 1000);
      const label = tag.querySelector('.inori-slow-remaining');
      if (label) label.textContent = remaining.toFixed(1) + '秒';
    }
  }
  function removeInoriDom() {
    document.querySelectorAll('#inori-barrier, #inori-break-badge, #inori-slow-tag, .inori-torii-laser, .inori-torii-hp, .inori-torii-icon').forEach(el => el.remove());
    document.getElementById(PLAYER_ID)?.classList.remove('inori-slowed');
    if (state && state.inori) { state.inori.beams = []; state.inori.slowMemberId = 0; }
  }
  // TICKETイノリ限定：双鳥居破壊時に1個、ランダム位置へ神罰対策の加護を出現させる。
  // 入手から3秒なので、神罰の着弾間際に取りに行くタイミングゲームとなる。
  function spawnInoriJudgmentCharm(now) {
    if (!isInoriSpecialStage() || !state || !state.inori || state.inori.charmSpawned) return;
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    state.inori.charmSpawned = true;
    const w = arena.clientWidth, h = arena.clientHeight;
    if (!w || !h) return;
    // ボスの下方をゆっくり漂う。プレイヤーが回収できる範囲に留める。
    const bx = Number(state.boss.x);
    const by = Number(state.boss.y);
    const centerX = Math.max(w * 0.30, Math.min(w * 0.70, Number.isFinite(bx) ? bx : w * 0.5));
    const centerY = Math.max(h * 0.40, Math.min(h * 0.67, (Number.isFinite(by) ? by : h * 0.20) + h * 0.30));
    const phase = Math.random() * Math.PI * 2;
    const x = Math.max(34, Math.min(w - 34, centerX + Math.sin(phase) * Math.min(44, w * 0.12)));
    const y = Math.max(h * 0.34, Math.min(h * 0.78, centerY + Math.cos(phase * 0.7) * Math.min(22, h * 0.03)));
    const el = document.createElement('div');
    el.className = 'inori-judgment-charm';
    el.setAttribute('role', 'img');
    el.setAttribute('aria-label', '神除けの札・取得すると3秒間無敵');
    // TICKETイノリ専用の防御札。既存の出現位置・取得判定・無敵時間は変更しない。
    el.innerHTML = '<img src="images/inori_shugo_fuda.webp" alt="" draggable="false" decoding="async" style="display:block;width:100%;height:100%;object-fit:contain;pointer-events:none;user-select:none;-webkit-user-drag:none">';
    arena.appendChild(el);
    positionUnit(el, x, y);
    state.inori.charm = {el, x, y, spawnedAt:now, phase, centerX, centerY};
  }
  function updateInoriJudgmentCharm(now) {
    if (!isInoriSpecialStage() || !state || !state.inori?.charm) return;
    const item = state.inori.charm;
    if (!item.el?.isConnected || state.ended || state.finishing || !state.boss || state.boss.hp <= 0) {
      item.el?.remove(); state.inori.charm = null; return;
    }
    const arena = document.getElementById('shooting-arena');
    if (arena) {
      const w = arena.clientWidth, h = arena.clientHeight;
      const t = Math.max(0, (now - item.spawnedAt) / 1000);
      // 軌道はサイン波を重ねた漂流。直線移動、急旋回、テレポートを行わない。
      // 初期位相は出現ごとにランダム。常に画面内かつボスの下方を漂う。
      const driftX = Math.sin(t * 0.52 + item.phase) * Math.min(47, w * 0.13)
        + Math.sin(t * 0.23 + item.phase * 0.62) * Math.min(12, w * 0.03);
      const driftY = Math.cos(t * 0.41 + item.phase * 0.7) * Math.min(24, h * 0.034)
        + Math.sin(t * 0.67 + item.phase) * Math.min(9, h * 0.012);
      item.x = Math.max(34, Math.min(w - 34, item.centerX + driftX));
      item.y = Math.max(h * 0.34, Math.min(h * 0.78, item.centerY + driftY));
      positionUnit(item.el, item.x, item.y);
    }
    const member = getActiveMember();
    // 取得の可否は実際に操作中の味方が生存しているかで判断する。
    // Phase遷移フラグは演出後にも残ることがあるため、取得判定の遮断には使わない。
    if (!member || member.hp <= 0 || state.koTransition) return;
    // 光輪と自機の両方を画面上の同じ座標系で比較する。
    // CSSのscale/transform、PWAの画面倍率などの差を吸収できる。
    const playerEl = document.getElementById(PLAYER_ID);
    const haloRect = item.el.getBoundingClientRect();
    const playerRect = playerEl && playerEl.getBoundingClientRect();
    let isTouching = false;
    if (playerRect && haloRect.width > 0 && haloRect.height > 0 &&
        playerRect.width > 0 && playerRect.height > 0) {
      const hx = (haloRect.left + haloRect.right) / 2;
      const hy = (haloRect.top + haloRect.bottom) / 2;
      // 味方の表示領域から光輪までの距離（見た目で重なったら取得）。
      const nearestX = Math.max(playerRect.left, Math.min(hx, playerRect.right));
      const nearestY = Math.max(playerRect.top, Math.min(hy, playerRect.bottom));
      const radius = Math.min(haloRect.width, haloRect.height) * 0.44 + 7;
      isTouching = Math.hypot(hx - nearestX, hy - nearestY) <= radius;
    }
    // 画面表示範囲が取得できない場合のみ、従来のアリーナ内部座標にフォールバック。
    if ((!playerRect || !haloRect.width || !haloRect.height) && !isTouching) {
      const px = Number(state.player?.x), py = Number(state.player?.y);
      isTouching = Number.isFinite(px) && Number.isFinite(py) &&
        Math.hypot(px - item.x, py - item.y) <= 36;
    }
    if (!isTouching) return;
    member.invincibleUntil = Math.max(Number(member.invincibleUntil || 0), now + 3000);
    state.player.invulnUntil = Math.max(Number(state.player.invulnUntil || 0), now + 3000);
    item.el.remove(); state.inori.charm = null;
    showShootingItemEffectNotice('神除けの札', '3秒間無敵');
    renderHud();
  }
  // ============================================================
  // build2006: TICKETイノリの背景
  //  通常：inori_stage_bg ／ 呪場（右）：inori_stage_bg_right ／ 呪場（左）：inori_stage_bg_left
  //  ・3枚を .shooting-bg の中に重ねて最初から読み込み・展開しておき、表示だけを切り替える（切替に遅れが出ない）
  //  ・ステージを開いた瞬間から通常背景（カウントダウン・イントロ明けも同じ。共通背景 battle_bg_01 は出さない）
  //  ・呪場の展開と同時に左右版へ、解除（時間切れ・呪核破壊・PHASE終了）と同時に通常へ
  // ============================================================
  const INORI_STAGE_BGS = Object.freeze({ base: 'images/inori_stage_bg.webp', left: 'images/inori_stage_bg_left.webp', right: 'images/inori_stage_bg_right.webp' });
  let inoriStageBgImages = [];
  function preloadInoriStageBgs() {
    if (inoriStageBgImages.length) return;
    inoriStageBgImages = Object.values(INORI_STAGE_BGS).map(src => {
      const img = new Image();
      img.decoding = 'async';
      img.src = src;
      try { if (img.decode) img.decode().catch(() => {}); } catch (_) {}
      return img; // 参照を持ち続けて、展開済みの画像を手放させない
    });
  }
  function ensureInoriStageBgLayers() {
    const root = document.getElementById(ROOT_ID);
    const bg = root && root.querySelector('.shooting-bg');
    if (!bg) return;
    const want = isInoriSpecialStage();
    const has = bg.querySelector('.inori-bg-layer');
    if (!want) {
      if (has) bg.querySelectorAll('.inori-bg-layer').forEach(el => el.remove());
      root.removeAttribute('data-inori-field');
      return;
    }
    preloadInoriStageBgs();
    if (!has) {
      ['base', 'left', 'right'].forEach(k => {
        const el = document.createElement('div');
        el.className = 'inori-bg-layer is-' + k;
        el.setAttribute('aria-hidden', 'true');
        bg.appendChild(el);
      });
    }
    setInoriStageBgField('none');
  }
  function setInoriStageBgField(side) {
    const root = document.getElementById(ROOT_ID);
    if (!root) return;
    const v = side === 'left' || side === 'right' ? side : 'none';
    if (root.getAttribute('data-inori-field') !== v) root.setAttribute('data-inori-field', v);
  }

  // TICKETイノリ Phase3: 呪場刑葬 / 呪核（バリアなし）
  // warning 3s / active 6s / 18s cycle / maximum HP 10% per second.
  function removeInoriExecutionField(reset = true) {
    const f = state && state.inoriExecutionField;
    if (f) { f.areaEl?.remove(); f.coreEl?.remove(); f.noticeEl?.remove(); }
    if (reset && state) state.inoriExecutionField = null;
    setInoriStageBgField('none'); // build2006: 呪場が消えたら同じフレームで通常背景へ
  }
  function damageInoriExecutionCore(amount, now) {
    const f = state?.inoriExecutionField;
    if (!f || f.mode !== 'active' || !(f.hp > 0)) return false;
    const n = Math.max(0, Number(amount || 0));
    if (!n) return false;
    f.hp = Math.max(0, f.hp - n); // 呪核は属性相性・イノリ本体バリアの対象外
    if (f.barEl) f.barEl.style.width = `${100 * f.hp / f.maxHp}%`;
    if (f.hp <= 0) {
      removeInoriExecutionField();
      showMemoryGuardNotice('呪核破壊・呪場解除', true, 'CURSE');
    } else if (f.coreEl) {
      f.coreEl.classList.remove('is-hit');
      void f.coreEl.offsetWidth;
      f.coreEl.classList.add('is-hit');
    }
    return true;
  }
  function ensureInoriExecutionFieldStyle() {
    if (document.getElementById('inori-execution-field-style')) return;
    const st = document.createElement('style');
    st.id = 'inori-execution-field-style';
    st.textContent = `
      #shooting-arena .inori-execution-area{position:absolute;top:0;bottom:0;width:50%;z-index:7;pointer-events:none;box-sizing:border-box;
        background:repeating-linear-gradient(142deg,rgba(142,43,78,.08) 0 12px,rgba(45,8,39,.18) 12px 24px),linear-gradient(90deg,rgba(107,21,59,.53),rgba(70,12,52,.48));
        box-shadow:inset 0 0 36px rgba(211,75,103,.38);}
      #shooting-arena .inori-execution-area.is-right{right:0;border-left:2px solid rgba(250,132,166,.9)}
      #shooting-arena .inori-execution-area.is-left{left:0;border-right:2px solid rgba(250,132,166,.9)}
      #shooting-arena .inori-execution-area.is-warning{background:repeating-linear-gradient(142deg,rgba(142,43,78,.05) 0 12px,rgba(45,8,39,.08) 12px 24px),rgba(126,29,76,.16);box-shadow:none;animation:inoriFieldWarning .6s ease-in-out infinite alternate}
      @keyframes inoriFieldWarning{from{opacity:.48}to{opacity:1}}
      #shooting-arena .inori-execution-core{position:absolute;width:88px;height:100px;z-index:20;pointer-events:none;transform:translate(-50%,-50%)}
      /* build2006: 呪核が呪場の背景に沈まないよう、周りに柔らかい光を少しだけ */
      #shooting-arena .inori-execution-core::before{content:'';position:absolute;left:50%;top:42px;width:128px;height:128px;transform:translate(-50%,-50%);z-index:0;
        background:radial-gradient(circle,rgba(255,252,254,.62) 0,rgba(255,234,243,.34) 36%,rgba(255,214,232,.12) 56%,rgba(255,214,232,0) 70%);
        animation:inoriCoreHalo 2.6s ease-in-out infinite alternate}
      @keyframes inoriCoreHalo{from{opacity:.75;transform:translate(-50%,-50%) scale(.96)}to{opacity:1;transform:translate(-50%,-50%) scale(1.04)}}
      #shooting-arena .inori-execution-core img{position:relative;z-index:1;width:100%;height:84px;object-fit:contain;display:block;
        filter:drop-shadow(0 0 3px rgba(255,250,252,.9)) drop-shadow(0 0 10px rgba(255,224,236,.55)) drop-shadow(0 0 16px rgba(243,76,121,.4))}
      #shooting-arena .inori-execution-core b{position:relative;z-index:1}
      #shooting-arena .inori-execution-core b{display:block;height:4px;background:rgba(26,8,24,.92);border:1px solid rgba(255,212,229,.8);border-radius:4px;overflow:hidden}
      #shooting-arena .inori-execution-core b i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#d95489,#ffe1eb)}
      #shooting-arena .inori-execution-core.is-hit img{animation:inoriCoreHit .16s ease}
      @keyframes inoriCoreHit{50%{filter:brightness(2.4)}}
      #shooting-arena .inori-execution-notice{position:absolute;top:23%;left:50%;transform:translateX(-50%);z-index:31;pointer-events:none;text-align:center;white-space:nowrap;color:#ffe3ed;font:700 17px/1.5 serif;letter-spacing:.1em;text-shadow:0 2px 6px #260414,0 0 12px #e14a7e}
      #shooting-arena .inori-execution-notice small{display:block;font:500 11px/1.4 sans-serif;letter-spacing:.03em;color:#ffe6ec}
      @media(prefers-reduced-motion:reduce){#shooting-arena .inori-execution-area.is-warning,#shooting-arena .inori-execution-core::before{animation:none}}
    `;
    document.head.appendChild(st);
  }
  function updateInoriExecutionField(now) {
    if (!state || !isInoriSpecialStage() || !state.inori || !state.boss || state.ended || state.finishing || state.boss.hp <= 0) {
      if (state?.inoriExecutionField) removeInoriExecutionField();
      return;
    }
    const phase = Number(state.boss.phase || 1);
    if (phase !== 3) {
      if (state.inoriExecutionField) removeInoriExecutionField();
      return;
    }
    if (state.koTransition || state.phaseTransition) return;
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    let f = state.inoriExecutionField;
    if (!f) {
      state.inoriExecutionField = {mode:'idle',nextAt:now+5500,lastAt:now};
      return;
    }
    // 時間停止は予告、呪場と発動時計を止める。移動・射出・行動停止は呪場の経過を止めない。
    const elapsed = Math.max(0, Math.min(250, now - Number(f.lastAt || now)));
    f.lastAt = now;
    if (getEnemyStopCapabilities(now).time) {
      f.nextAt += elapsed;
      if (f.endsAt) f.endsAt += elapsed;
      return;
    }
    if (f.mode === 'idle' && now >= f.nextAt) {
      ensureInoriExecutionFieldStyle();
      f.mode = 'warning'; f.endsAt = now+3000;
      f.side = Math.random() < .5 ? 'left' : 'right';
      f.areaEl = document.createElement('div');
      f.areaEl.className = `inori-execution-area is-warning is-${f.side}`;
      arena.appendChild(f.areaEl);
      f.noticeEl = document.createElement('div');
      f.noticeEl.className = 'inori-execution-notice';
      f.noticeEl.innerHTML = '呪場刑葬<small>危険領域から退避せよ</small>';
      arena.appendChild(f.noticeEl);
      return;
    }
    if (f.mode === 'warning' && now >= f.endsAt) {
      f.mode = 'active'; f.endsAt = now+6000; f.lastDamageAt=now;
      f.maxHp=2500; f.hp=2500;
      f.coreX=arena.clientWidth*(f.side==='left'?.25:.75);
      f.coreY=arena.clientHeight*.58;
      f.areaEl.classList.remove('is-warning');
      setInoriStageBgField(f.side); // build2006: 呪場の展開と同じフレームで左右版の背景へ
      f.coreEl=document.createElement('div'); f.coreEl.className='inori-execution-core';
      f.coreEl.style.left=`${f.coreX}px`; f.coreEl.style.top=`${f.coreY}px`;
      f.coreEl.innerHTML='<img src="images/inori_jukaku.webp" alt="呪核" draggable="false"><b><i></i></b>';
      f.barEl=f.coreEl.querySelector('b i');
      arena.appendChild(f.coreEl);
      f.noticeEl.innerHTML='呪場刑葬<small>呪核を破壊せよ　最大HP 10%/秒</small>';
      return;
    }
    if (f.mode !== 'active') return;
    if (now >= f.endsAt) {
      removeInoriExecutionField();
      state.inoriExecutionField={mode:'idle',nextAt:now+9000,lastAt:now};
      return;
    }
    const member=getActiveMember();
    if (!member || member.hp<=0) return;
    const pw=arena.clientWidth;
    const inside=(f.side==='left' ? state.player.x < pw*.5 : state.player.x >= pw*.5);
    const delta=Math.max(0,Math.min(250, now-Number(f.lastDamageAt||now)));
    f.lastDamageAt=now;
    if (!inside || now < Number(member.invincibleUntil||0) || now < Number(state.player.invulnUntil||0)) return;
    const maxHp=Math.max(1,Number(member.hpMax||member.maxHp||member.hp));
    const dmg=Math.min(member.hp,maxHp*.10*delta/1000);
    if(dmg<=0)return;
    member.hp=Math.max(0,member.hp-dmg);
    renderHud();
    if(member.hp<=0)beginPlayerDefeat();
  }
  function hitInoriExecutionCoreProjectile(p,prevX,prevY,now){
    const f=state?.inoriExecutionField;
    if(!f||f.mode!=='active'||f.hp<=0)return false;
    const x=Number(p.x||0),y=Number(p.y||0);
    const dx=x-prevX,dy=y-prevY;
    const t=Math.max(0,Math.min(1, ((f.coreX-prevX)*dx+(f.coreY-prevY)*dy)/Math.max(1,dx*dx+dy*dy)));
    if(Math.hypot(prevX+dx*t-f.coreX,prevY+dy*t-f.coreY)>38)return false;
    if(p.pierce){
      if(!p.piercedTargets)p.piercedTargets=new Set();
      if(p.piercedTargets.has(f))return false;
      p.piercedTargets.add(f);
    }
    damageInoriExecutionCore(p.damage,now);
    return !p.pierce;
  }

  function updateInoriMechanics(dt, now, bossHalted) {
    const cfg = getInoriConfig();
    if (!cfg || !state || state.ended || state.finishing || !state.boss) return;
    if (!state.inori) {
      state.inori = {
        barrierUp: true, toriiSpawned: false, reviveAt: 0, waitingForJudgment: false, nextLaserAt: 0,
        nextCurseAt: now + Math.max(1000, Number(cfg.slowFirstMs || 6500)), cursePhase: 1, beams: [], slowMemberId: 0, slowUntil: 0,
      };
      spawnInoriTorii(now);
    }
    const inori = state.inori;
    const alive = getAliveInoriTorii();

    // build1832: TICKETイノリは2基破壊で8秒の神罰を開始し、着弾後に鳥居・結界を再生する。
    if (inori.barrierUp && inori.toriiSpawned && !alive.length) {
      inori.barrierUp = false;
      // 神罰は鳥居破壊時に一度だけ予約される。破壊時点で行動停止中なら予約されない。
      // 予約成立後の行動停止では取消・延期不可。時間停止だけがカウントダウンを凍結する。
      // 予約直前の③行動停止または④時間停止のみを阻止条件とする。
      // ①射出停止／②移動停止では、既に予知された神罰を止められない。
      const stopCaps = getEnemyStopCapabilities(now);
      const stopBeforeReservation = isInoriSpecialStage() && (
        stopCaps.action || stopCaps.time ||
        now < Number(state.bossStunUntil || 0) ||
        now < Number(state.normalEnemyStunUntil || 0)
      );
      inori.waitingForJudgment = isInoriSpecialStage() && !stopBeforeReservation;
      inori.reviveAt = now + (inori.waitingForJudgment ? 8000 : Math.max(1000, Number(cfg.barrierDownMs || 7000)));
      if (inori.waitingForJudgment) spawnInoriJudgmentCharm(now);
      else if (stopBeforeReservation) showMemoryGuardNotice('神罰の予約を阻止', true, 'JUDGMENT');
      (inori.beams || []).forEach(b => b.el && b.el.remove());
      inori.beams = [];
      showFacelessBattleCut('BARRIER BREAK', '全属性バリア消失');
    }
    // build1764: 記憶決戦の掟「連なる鳥居」— 片方だけ壊すと、残った鳥居が reviveMs 後に修復してしまう
    const link = getMemoryRule('linked_torii');
    if (link && inori.barrierUp && inori.toriiSpawned && state.boss.hp > 0) {
      if (alive.length === 1) {
        const reviveMs = Math.max(1000, Number(link.reviveMs || 3000));
        if (!inori.linkBrokenAt) {
          inori.linkBrokenAt = now;
          showMemoryGuardNotice('鳥居が共鳴している', false, 'TORII');
        } else if (now >= inori.linkBrokenAt + reviveMs) {
          inori.linkBrokenAt = 0;
          const missing = Number(alive[0].inoriSide || 1) * -1;
          spawnInoriTorii(now, [missing]);
          showMemoryGuardNotice('鳥居、修復', false, 'TORII');
        }
      } else {
        inori.linkBrokenAt = 0;
      }
    }
    // 神罰の着弾より前に鳥居・結界が復活しないようにする。
    if (!inori.barrierUp && !inori.waitingForJudgment && now >= inori.reviveAt && state.boss.hp > 0) {
      inori.barrierUp = true;
      inori.charm?.el?.remove();
      inori.charm = null;
      inori.charmSpawned = false;
      spawnInoriTorii(now);
      showFacelessBattleCut('TORII REVIVE', '鳥居が再び顕現');
    }

    // 敵の全体停止（スタン系ULT）・BREAK演出中は、レーザーと呪いの新規発動を止める（予約は後ろへずらす）
    const stopUntil = Math.max(
      Number(state.normalEnemyStunUntil || 0), Number(state.fullEnemyStopUntil || 0), Number(state.angeEnemyFreezeUntil || 0));
    const paused = bossHalted || now < stopUntil || state.phaseTransition || state.koTransition;
    if (paused) {
      if (inori.nextLaserAt && inori.nextLaserAt < now + 400) inori.nextLaserAt = now + 400;
      if (inori.nextCurseAt < now + 400) inori.nextCurseAt = now + 400;
    } else {
      if (inori.barrierUp && alive.length && inori.nextLaserAt && now >= inori.nextLaserAt) {
        inori.nextLaserAt = now + Math.max(1000, Number(cfg.laserEveryMs || 3000));
        fireInoriToriiLasers(now);
      }
      // TICKETイノリ：Phase2/3開幕に必中「呪詛」。以後Phase2=15秒、Phase3=12秒ごと。
      // Phase切替中は発動させず、操作再開フレームを各Phaseの初回とする。
      if (isInoriSpecialStage()) {
        const phase = Math.max(1, Number(state.boss.phase || 1));
        if (phase === 2 || phase === 3) {
          if (inori.cursePhase !== phase) {
            inori.cursePhase = phase;
            inori.nextCurseAt = now; // 開幕即時
          }
          if (now >= inori.nextCurseAt && state.boss.hp > 0) {
            inori.nextCurseAt = now + (phase === 2 ? 15000 : 12000);
            applyInoriBinding(now);
          }
        }
      } else if (cfg.curse === true && now >= inori.nextCurseAt && state.boss.hp > 0) {
        inori.nextCurseAt = now + Math.max(3000, Number(cfg.slowEveryMs || 11000));
        fireInoriCurse(now);
      }
    }
    updateInoriBeams(now);

    // バリアは「どの攻撃も通らない」。ダメージ計算側でも0にしているが、属性計算を通らない経路の保険としてHPを固定。
    if (inori.barrierUp) {
      if (!(inori.hpLock > 0)) inori.hpLock = Number(state.boss.hp || 0);
      if (state.boss.hp < inori.hpLock) state.boss.hp = inori.hpLock;
    } else {
      inori.hpLock = 0;
    }
    syncInoriBarrierDom();
    syncInoriBreakBadge(now);
    if (isInoriSpecialStage() && inori.slowMemberId) syncInoriSlowDom();
  }

  // ============================================================
  // build1681/1682: 位相回遊 100F・150F・200F…の確定ボス「エクリプス」
  //  ・ふだん本体は無敵（applyElementDamage で 0／IMMUNE）。HPは lockHp で固定（保険）
  //  ・光の天秤を壊す → 光状態8秒：本体に攻撃が通る
  //  ・闇の天秤を壊す → 闇状態8秒：自機の周りしか見えない暗転＋弾幕加速（本体は無敵のまま）
  //  ・状態は最後に壊した天秤で上書き。壊れた天秤はそれぞれ8秒後に復活
  //  ・天秤はうろつき、交互に自機へ突進（予告 → 突進中だけ接触ダメージ）。PHASE3は蝕の手
  // ============================================================
  function getEclipseConfig() {
    return (BOSS && BOSS.eclipseMechanics && selectedStage && selectedStage.type !== 'normal') ? BOSS.eclipseMechanics : null;
  }
  function isEclipseBattle() { return !!getEclipseConfig(); }
  function getEclipseMode(now = performance.now()) {
    const ec = state && state.eclipse;
    if (!ec || !isEclipseBattle() || !ec.mode || now >= Number(ec.modeUntil || 0)) return '';
    return ec.mode;
  }
  // 本体が無敵か（エクリプス戦で、光状態でない間）
  function isEclipseImmune() { return isEclipseBattle() && !!state && getEclipseMode() !== 'light'; }
  function isEclipseBlackoutActive() { return false; } // 旧仕様（日食）の名残。暗転は闇状態の専用ベールで行う
