        if (inner) {
          const cut = shCol ? Math.max(0, (hd.el.clientHeight || 0) - shCol.y) : 0;
          if (hd.cutBottom !== cut) { hd.cutBottom = cut; inner.style.bottom = `${Math.round(cut)}px`; }
        }
