  // build1991: visionFullRange の眼は、視界を画面の端まで伸ばす（途中で切らない）
  function getWatcherVisionRange(def, h) {
    if (def && def.visionFullRange) {
      const arena = document.getElementById('shooting-arena');
      const w = arena ? arena.clientWidth : 390;
      return Math.hypot(w, h) + 20;
    }
    return h * Number((def && def.visionRangeRate) || .6);
  }
  function isPointInWatcherSight(enemy, px, py, h, now) {
    const def = enemy.def || {};
    const range = getWatcherVisionRange(def, h);
    const dx = px - enemy.x, dy = py - enemy.y;
    if (dx * dx + dy * dy > range * range) return false;
    let diff = Math.atan2(dy, dx) - Number(enemy.poFacing || Math.PI / 2);
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    return Math.abs(diff) <= (Number(def.visionHalfAngleDeg || 19) * Math.PI / 180);
  }
  function updateOverseerWatch(dt, now, bossHalted) {
    const cfg = getOverseerWatchConfig();
    if (!cfg) return;
    const arena = document.getElementById('shooting-arena');
    if (!arena || !state.player) return;
    const layer = document.getElementById('shooting-normal-enemy-layer') || arena;
    const w = arena.clientWidth, h = arena.clientHeight;
    if (!state.poWatchCones) state.poWatchCones = new Map();
    const cones = state.poWatchCones;
    const alive = new Set();
    let seen = false;
    const px = Number(state.player.x || 0), py = Number(state.player.y || 0);
    (state.normalEnemies || []).forEach(enemy => {
      if (!enemy || enemy.hp <= 0 || !enemy.def || enemy.def.behavior !== 'po_watcher_v1') return;
      alive.add(enemy.uid);
      const def = enemy.def;
      const age = Math.max(0, (now - Number(enemy.spawnedAt || now)) / 1000);
      // 監視の眼が出現演出中・停止中でも首振りは続ける（停止系ULT中は止める）
      const frozen = now < getNormalEnemyLockUntil(enemy, now);
      if (!frozen) enemy.poFacing = Math.PI / 2 + Math.sin(age * Number(def.sweepSpeed || .55) + enemy.phaseSeed) * Number(def.sweepRad || .85);
      if (enemy.poFacing == null) enemy.poFacing = Math.PI / 2;
      const range = getWatcherVisionRange(def, h);
      const half = Number(def.visionHalfAngleDeg || 19) * Math.PI / 180;
      const coneH = Math.max(20, 2 * range * Math.tan(half));
      let cone = cones.get(enemy.uid);
      if (!cone || !cone.isConnected) {
        cone = document.createElement('div');
        cone.className = 'po-watch-cone';
        cone.setAttribute('aria-hidden', 'true');
        layer.insertBefore(cone, layer.firstChild);
        cones.set(enemy.uid, cone);
      }
      const inSight = !frozen && !bossHalted && isPointInWatcherSight(enemy, px, py, h, now);
      if (inSight) seen = true;
      cone.style.width = `${range}px`;
      cone.style.height = `${coneH}px`;
      cone.style.transform = `translate3d(${enemy.x}px,${enemy.y - coneH / 2}px,0) rotate(${enemy.poFacing}rad)`;
      cone.classList.toggle('is-seeing', inSight);
      cone.classList.toggle('is-full', !!def.visionFullRange);
      cone.classList.toggle('is-frozen', frozen);
    });
    cones.forEach((el, uid) => { if (!alive.has(uid)) { el.remove(); cones.delete(uid); } });

    state.poWatched = seen;
    document.getElementById(ROOT_ID)?.classList.toggle('po-watched', seen);
    let alert = arena.querySelector('.po-watch-alert');
    if (seen && !alert) {
      alert = document.createElement('div');
      alert.className = 'po-watch-alert';
      alert.setAttribute('aria-hidden', 'true');
      alert.textContent = '監視されている ― 敵弾が追従';
      const vignette = document.createElement('div');
      vignette.className = 'po-watch-vignette';
      vignette.setAttribute('aria-hidden', 'true');
      arena.append(vignette, alert);
    } else if (!seen && alert) {
      alert.remove();
      arena.querySelectorAll('.po-watch-vignette').forEach(el => el.remove());
    }
  }
  // 見られている間だけ、敵弾の向きを自機へ少しずつ曲げる（速さは変えない）
  function steerEnemyBulletToPlayer(p, moveDt) {
    const cfg = getOverseerWatchConfig();
    if (!cfg || !state.poWatched || !p || p.poNoHoming) return;
    const vx = Number(p.vx), vy = Number(p.vy);
    if (!Number.isFinite(vx) || !Number.isFinite(vy)) return;
    const speed = Math.hypot(vx, vy);
    if (speed < 1) return;
    const aim = getEnemyAimPosition();
    const desired = Math.atan2(Number(aim.y || 0) - Number(p.y || 0), Number(aim.x || 0) - Number(p.x || 0));
    let cur = Math.atan2(vy, vx);
    let diff = desired - cur;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    const maxTurn = Math.max(0.2, Number(cfg.homingTurnRadPerSec || 2.4)) * Math.max(0, moveDt);
    cur += clamp(diff, -maxTurn, maxTurn);
    p.vx = Math.cos(cur) * speed;
    p.vy = Math.sin(cur) * speed;
  }


  function spawnBossAdds(now) {
    if (isNormalBattle() || !hasBossAdds() || state.finishing || state.ended) return;

    const cfg = getBossAddsConfig();
    if (!cfg) return;
    const total = Math.max(0, Number(cfg.totalEnemies || 0));
    const maxActive = Math.max(1, Number(cfg.maxActive || 1));
    const interval = Math.max(500, Number((state.verdantQueenGrown && cfg.grownSpawnIntervalMs) || cfg.spawnIntervalMs || 7000)); // build1659: 開花後は召喚が速い
    const startDelay = Math.max(0, Number(cfg.startDelayMs || 0));

    if (total > 0 && state.normalSpawned >= total) return;
    if (state.normalEnemies.filter(e => e && e.hp > 0 && !e.deinovaUltCore && !(e.def && (e.def.behavior === 'verdant_seed_v1' || e.def.behavior === 'deinova_core_v1'))).length >= maxActive) return; // build2003: 生存中だけを同時召喚数として計上
    // 記憶オーバーシア：撃破から5秒は新たな監視者を補充しない。
    if (selectedStage?.memoryBattle?.no === 5 && now < Number(state.overseerWatcherReviveAt || 0)) return;
    if (now - state.startedAt < startDelay) return;
    if (now - state.normalLastSpawnAt < interval) return;

    const enemyIds = cfg.enemyIds;
    const enemyId = enemyIds[state.normalSpawned % enemyIds.length];
    const baseDef = getShootingEnemy(enemyId);
    if (!baseDef || !baseDef.implemented || baseDef.kind !== 'normal') return;
    const def = resolveChapter02ZakoVariant(baseDef, state.normalSpawned, cfg);

    const enemy = createNormalEnemy(def, now);
    if (!enemy) return;

    state.normalEnemies.push(enemy);
    state.normalSpawned++;
    state.normalLastSpawnAt = now;
  }

  // 12F: threatening light/dark WARNING bullets, drawn in the existing enemy Canvas.
  function fireTower12LethalVolley(now) {
    const cfg = selectedStage?.towerLethalVolley;
    if (!cfg || !state || state.ended || state.finishing) return;
    if (now - Number(state.tower12LastLethalAt || 0) < Number(cfg.intervalMs || 2900)) return;
    const enemies = state.normalEnemies.filter(e => e && e.hp > 0 &&
      now >= getNormalEnemyLockUntil(e, now)).slice(0, Number(cfg.maxEnemyCount || 2));
    if (!enemies.length) {
      // 12FのWARNING発射時計も停止後に再始動。解除直後の集中発射を避ける。
      state.tower12LastLethalAt = Math.max(Number(state.tower12LastLethalAt || 0), now);
      return;
    }
    state.tower12LastLethalAt = now;
    if (!enemies.length || state.enemyBullets.length > 95) return;
    const aim = getEnemyAimPosition();
    enemies.forEach(enemy => {
      const angle = Math.atan2(aim.y - enemy.y, aim.x - enemy.x);
      const offsets = Number(cfg.shotsPerEnemy || 2) >= 3 ? [-.22,0,.22] : [-.16,.16];
      offsets.forEach(offset => {
        const a = angle + offset;
        const p = makeProjectile('shooting-enemy-bullet shooting-danger-bullet',enemy.x,enemy.y+22,
          Math.cos(a)*218,Math.sin(a)*218,999999);
        if (p) {
          p.attackElement = getCombatTargetElement(enemy, enemy?.def?.element);
          p.element = p.attackElement;
          state.enemyBullets.push(p);
        }
      });
    });
  }

  // build1666: 樹獣の森は全員が育ち切ると弾が一気に増えるため、ステージ全体で通常弾の上限を設ける（WARNING等の危険弾は対象外）
  function isVerdantBulletCapReached() {
    const cap = Number(selectedStage && selectedStage.verdant && selectedStage.verdant.enemyBulletCap || 0);
    if (!(cap > 0) || !state) return false;
    let n = 0;
    for (const p of state.enemyBullets) { if (p && p.el && !isProtectedEnemyProjectile(p)) n++; }
    return n >= cap;
  }
  function shootNormalEnemyProjectile(enemy, angle, speed, damage, className) {
    if (!enemy || !state) return null;
    if (isVerdantBulletCapReached()) return null;
    const now = performance.now();
    const lockedUntil = getNormalEnemyLockUntil(enemy, now);
    if (now < lockedUntil) {
      deferNormalEnemyAttackResume(enemy, lockedUntil);
      return null;
    }
    const projectile = makeProjectile(
      className || 'shooting-enemy-bullet shooting-mini-enemy-bullet',
      enemy.x, enemy.y + 24,
      Math.cos(angle) * speed,
      Math.sin(angle) * speed,
      damage
    );
    if (projectile) {
      projectile.attackElement = getCombatTargetElement(enemy, enemy && enemy.def && enemy.def.element);
      applyEnemyProjectileElementVisual(projectile, projectile.attackElement);
      state.enemyBullets.push(projectile);
    }
    return projectile;
  }


  // ============================================================
  // CHAPTER 06 - 破壊不能の遮断壁
  // HPを持たず、通常Projectileを止める。Laser / Shotgun(pierce)は通過。
  // Homingは敵より壁を最優先で追尾する。
  // ============================================================
  function getChapter6BarrierConfig() {
    // 試遊専用の壁はオリビア(ID40)だけ。CH06/DAILYの判定には一切影響させない。
    if (isGachaTrialStage()) {
      if (gachaTrialCharacterId === 40) return GACHA_TRIAL_OLIVIA_WALL;
      if (gachaTrialCharacterId === 56) return GACHA_TRIAL_SMILE_WALL;
      return [];
    }
    if (selectedStage && Array.isArray(selectedStage.chapter6Barriers) && selectedStage.chapter6Barriers.length) {
      const timedWall = selectedStage.towerTimedWall;
      if (timedWall && state) {
        const elapsed = Math.max(0, performance.now() - Number(state.startedAt || performance.now()));
        const first = Math.max(0, Number(timedWall.firstAtMs || 20000));
        const interval = Math.max(1000, Number(timedWall.intervalMs || 20000));
        const duration = Math.min(interval, Math.max(0, Number(timedWall.durationMs || 10000)));
        if (elapsed < first || ((elapsed - first) % interval) >= duration) return [];
      }
      // build1038: ノアの移動壁はWAVE2以降、かつHP50%未満でのみ出現。
      // 条件未達時は空配列を返すため、既に壁が出ていて条件外になった場合も
      // ensureChapter6Barriers() 側で即時クリアされる。
      if (String(selectedStage.id || '') === 'shooting_event_bullet_hell_test') {
        const bossPhase = Math.max(1, Number(state && state.boss && state.boss.phase || 1));
        const hp = Math.max(0, Number(state && state.boss && state.boss.hp || 0));
        const hpMax = Math.max(1, Number(state && state.boss && state.boss.hpMax || 1));
        const hpRatio = hp / hpMax;
        if (bossPhase < 2 || hpRatio >= 0.5) return [];
      }
      return selectedStage.chapter6Barriers;
    }

    // build550: DAILY上級は旧stage定義がキャッシュされていても壁を必ず生成する。
    // CH06の壁ロジックをそのまま再利用する固定1枚構成。
    if (isDailyAdvancedGimmickStage()) {
      return [{ xRate:.50, yRate:.49, widthRate:.70, height:23, moveRangeRate:.10, moveSpeed:.30, contactDamage:85 }];
    }

    return [];
  }

  function clearChapter6Barriers() {
    if (!state) return;
    (state.chapter6Barriers || []).forEach(barrier => barrier && barrier.el && barrier.el.remove());
    state.chapter6Barriers = [];
    const arena = document.getElementById('shooting-arena');
    if (arena) arena.querySelectorAll('.shooting-ch06-barrier').forEach(el => el.remove());
    clearBarrierSparks();
  }

  function ensureChapter6Barriers() {
    if (!state) return [];
    const cfg = getChapter6BarrierConfig();
    if (!cfg.length) {
      if ((state.chapter6Barriers || []).length) clearChapter6Barriers();
      return [];
    }
    const arena = document.getElementById('shooting-arena');
    if (!arena) return [];
    if ((state.chapter6Barriers || []).length === cfg.length) return state.chapter6Barriers;

    clearChapter6Barriers();
    state.chapter6Barriers = cfg.map((def, index) => {
      const el = document.createElement('div');
      el.className = 'shooting-ch06-barrier';
      el.innerHTML = '<i></i><b></b>';
      el.setAttribute('aria-hidden', 'true');
      arena.appendChild(el);
      return {
        uid: `ch06_barrier_${index}`,
        isChapter6Barrier: true,
        def,
        el,
        x: 0,
        y: 0,
        width: 0,
        height: Math.max(22, Number(def.height || 44)),
      };
    });
    return state.chapter6Barriers;
  }

  function updateChapter6Barriers(now) {
    const barriers = ensureChapter6Barriers();
    if (!barriers.length) return;
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const w = Number(arena.clientWidth || 0);
    const h = Number(arena.clientHeight || 0);
    const t = Math.max(0, Number(now || performance.now()) - Number(state.startedAt || now)) / 1000;

    barriers.forEach((barrier, index) => {
      const def = barrier.def || {};
      const baseX = w * Number(def.xRate != null ? def.xRate : .5);
      const moveRange = w * Math.max(0, Number(def.moveRangeRate || 0));
      const moveSpeed = Math.max(0, Number(def.moveSpeed || 0));
      const phase = Number(def.phase || index * 1.7);
      barrier.x = clamp(baseX + Math.sin(t * moveSpeed + phase) * moveRange, 34, Math.max(34, w - 34));
      barrier.y = h * Number(def.yRate != null ? def.yRate : .48);
      barrier.width = Math.max(70, w * Number(def.widthRate || .55));
      barrier.height = Math.max(22, Number(def.height || 44));
      if (barrier._appliedWidth !== barrier.width) {
        barrier._appliedWidth = barrier.width;
        barrier.el.style.width = `${barrier.width}px`;
      }
      if (barrier._appliedHeight !== barrier.height) {
        barrier._appliedHeight = barrier.height;
        barrier.el.style.height = `${barrier.height}px`;
      }
      barrier.el.style.transform = `translate3d(${barrier.x}px,${barrier.y}px,0) translate(-50%,-50%)`;
    });
  }

  function getChapter6BarrierRect(barrier, arenaRect) {
    if (!barrier || !arenaRect) return null;
    const halfW = Number(barrier.width || 0) * .5;
    const halfH = Number(barrier.height || 0) * .5;
    const cx = Number(arenaRect.left || 0) + Number(barrier.x || 0);
    const cy = Number(arenaRect.top || 0) + Number(barrier.y || 0);
    return { left:cx-halfW, right:cx+halfW, top:cy-halfH, bottom:cy+halfH };
  }

  function findChapter6BarrierCollision(projectileRect, arenaRect, projectile) {
    if (!projectileRect || !state || !(state.chapter6Barriers || []).length) return null;
    return (state.chapter6Barriers || []).find(barrier => {
      if (!barrier || !barrier.el) return false;
      if (projectile && projectile.pierce && projectile.piercedTargets && projectile.piercedTargets.has(barrier)) return false;
      const rect = getChapter6BarrierRect(barrier, arenaRect);
      return !!rect && rectsHit(projectileRect, rect, 0, 0);
    }) || null;
  }

  // ============================================================
  // build1455: 遮断壁の被弾で「光の粒」を飛ばす
  // 壁専用の小さなCanvasを1枚だけ arena に重ね、粒がある間だけ描画ループを回す。
  // 粒は最大90個のプール。視差効果を減らす設定の端末では出さない。
  // ============================================================
  const barrierSparkFx = { canvas:null, ctx:null, parts:[], raf:0, last:0, dpr:1, w:0, h:0 };
  const BARRIER_SPARK_MAX = 90;
  const barrierSparkReducedMotion = (() => {
    try { return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches); }
    catch (_) { return false; }
  })();

  function ensureBarrierSparkCanvas() {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return null;
    let canvas = barrierSparkFx.canvas;
    if (!canvas || !canvas.isConnected || canvas.parentElement !== arena) {
      canvas = document.createElement('canvas');
      canvas.className = 'shooting-barrier-sparks';
      canvas.setAttribute('aria-hidden', 'true');
      arena.appendChild(canvas);
      barrierSparkFx.canvas = canvas;
      barrierSparkFx.ctx = canvas.getContext('2d');
      barrierSparkFx.w = 0;
      barrierSparkFx.h = 0;
    }
    const w = Number(arena.clientWidth || 0);
    const h = Number(arena.clientHeight || 0);
    if (w !== barrierSparkFx.w || h !== barrierSparkFx.h) {
      const dpr = Math.min(2, Math.max(1, Number(window.devicePixelRatio || 1)));
      barrierSparkFx.dpr = dpr;
      barrierSparkFx.w = w;
      barrierSparkFx.h = h;
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
    }
    return canvas;
  }

  function stepBarrierSparks(ts) {
    const fx = barrierSparkFx;
    const ctx = fx.ctx;
    if (!ctx || !fx.canvas || !fx.canvas.isConnected) { fx.parts.length = 0; fx.raf = 0; return; }
    const dt = Math.min(48, Math.max(0, ts - (fx.last || ts)));
    fx.last = ts;
    ctx.setTransform(fx.dpr, 0, 0, fx.dpr, 0, 0);
    ctx.clearRect(0, 0, fx.w, fx.h);
    // 明るい背景でも見えるよう通常合成＋金の縁取り（加算合成だと白背景で消える）
    ctx.globalCompositeOperation = 'source-over';
    const k = dt / 1000;
    let alive = 0;
    for (let i = 0; i < fx.parts.length; i++) {
      const q = fx.parts[i];
      q.age += dt;
      if (q.age >= q.life) continue;
      q.vx *= Math.pow(.12, k);
      q.vy = q.vy * Math.pow(.12, k) - 22 * k; // ゆっくり上へ漂う
      q.x += q.vx * k;
      q.y += q.vy * k;
      const t = q.age / q.life;
      const a = t < .12 ? t / .12 : 1 - (t - .12) / .88;
      const r = q.size * (1 - t * .4);
      // 外側のにじみ（金）
      ctx.globalAlpha = a * .42;
      ctx.fillStyle = q.gold ? '#f2b546' : '#f7cf78';
      ctx.beginPath(); ctx.arc(q.x, q.y, r * 2.4, 0, 6.2832); ctx.fill();
      // 金の縁
      ctx.globalAlpha = a * .95;
      ctx.fillStyle = '#e5a73a';
      ctx.beginPath(); ctx.arc(q.x, q.y, r * 1.25, 0, 6.2832); ctx.fill();
      // 芯（白）
      ctx.fillStyle = '#fffdf3';
      ctx.beginPath(); ctx.arc(q.x, q.y, r * .8, 0, 6.2832); ctx.fill();
      // 一部の粒は十字にきらめく
      if (q.star) {
        const L = r * 4.4 * (1 - t * .55);
        ctx.globalAlpha = a * .9;
        ctx.fillStyle = '#f1b84c';
        ctx.fillRect(q.x - L, q.y - .8, L * 2, 1.6);
        ctx.fillRect(q.x - .8, q.y - L, 1.6, L * 2);
        ctx.fillStyle = '#fffdf3';
        ctx.fillRect(q.x - L * .7, q.y - .4, L * 1.4, .8);
        ctx.fillRect(q.x - .4, q.y - L * .7, .8, L * 1.4);
      }
      fx.parts[alive++] = q;
    }
    fx.parts.length = alive;
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    if (alive) fx.raf = requestAnimationFrame(stepBarrierSparks);
    else { ctx.clearRect(0, 0, fx.w, fx.h); fx.raf = 0; fx.last = 0; }
  }

  function spawnBarrierSparks(barrier, hitX, hitY) {
    if (barrierSparkReducedMotion || !barrier) return;
    if (!ensureBarrierSparkCanvas()) return;
    const fx = barrierSparkFx;
    const halfW = Number(barrier.width || 0) * .5;
    const cx = Number(barrier.x || 0);
    const cy = Number(barrier.y || 0);
    // 着弾点が分からない場合は壁の中央付近。x は壁の範囲内に収める。
    let x = Number.isFinite(Number(hitX)) ? Number(hitX) : cx + (Math.random() - .5) * halfW;
    x = Math.max(cx - halfW + 6, Math.min(cx + halfW - 6, x));
    // 下から当たった弾は下側へ、上からは上側へ散らす
    const fromBelow = !Number.isFinite(Number(hitY)) || Number(hitY) >= cy;
    const y = cy + (fromBelow ? 3 : -3);
    const count = 7 + Math.floor(Math.random() * 4);
    for (let i = 0; i < count; i++) {
      if (fx.parts.length >= BARRIER_SPARK_MAX) fx.parts.shift();
      const spread = (Math.random() - .5) * Math.PI * .95;
      const base = fromBelow ? Math.PI / 2 : -Math.PI / 2;
      const ang = base + spread;
      const sp = 60 + Math.random() * 110;
      fx.parts.push({
        x: x + (Math.random() - .5) * 10,
        y,
        vx: Math.cos(ang) * sp * 1.35,
        vy: Math.sin(ang) * sp,
        age: 0,
        life: 420 + Math.random() * 380,
        size: 1.5 + Math.random() * 1.8,
        gold: Math.random() < .55,
        star: Math.random() < .35,
      });
    }
    if (!fx.raf) { fx.last = 0; fx.raf = requestAnimationFrame(stepBarrierSparks); }
  }

  function clearBarrierSparks() {
    const fx = barrierSparkFx;
    if (fx.raf) cancelAnimationFrame(fx.raf);
    fx.raf = 0; fx.last = 0; fx.parts.length = 0;
    if (fx.canvas) fx.canvas.remove();
    fx.canvas = null; fx.ctx = null; fx.w = 0; fx.h = 0;
  }

  function pulseChapter6Barrier(barrier, hitX, hitY) {
    if (!barrier || !barrier.el) return false;

    // build551: 高速多弾が壁へ当たるたびoffsetWidthを読むと、
    // 1発ごとに同期レイアウトが発生してiOSの入力まで止まりやすい。
    // 判定自体は全弾処理し、見た目のパルスだけ約10fpsに制限する。
    const now = performance.now();
    if (now < Number(barrier._hitFxUntil || 0)) return false;
    barrier._hitFxUntil = now + 96;
    spawnBarrierSparks(barrier, hitX, hitY);

    barrier.el.classList.add('hit');
    if (barrier._hitFxTimer) clearTimeout(barrier._hitFxTimer);
    barrier._hitFxTimer = setTimeout(() => {
      if (barrier && barrier.el) barrier.el.classList.remove('hit');
      barrier._hitFxTimer = null;
    }, 120);
    return true;
  }

  function getChapter4CurtainConfig() {
    if (!selectedStage) return null;
    return selectedStage.chapter4Curtain || null;
  }

  function getChapter4ShrinkBounds(now, arenaWidth) {
    if (!state || !selectedStage) return { left:0, right:0, ratio:1, progress:0 };

    if (isChapter43BossStage() && state.chapter43Wave2CountdownTriggered) {
      const cfg43 = getChapter43Config();
      const start = Number(state.chapter43CollapseStartedAt || now);
      const end = Math.max(start + 1000, Number(state.chapter43CollapseDeadlineAt || start + 45000));
      const minWidthRatio = clamp(Number(cfg43?.collapseMinWidthRatio || .20), .16, 1);
      const progress = clamp((Number(now) - start) / (end - start), 0, 1);
      const ratio = 1 - (1 - minWidthRatio) * progress;
      const inset = Math.max(0, arenaWidth * (1 - ratio) * .5);
      return { left:inset, right:inset, ratio, progress };
    }

    const cfg = selectedStage.shrinkWalls;
    if (!cfg || !isSelectedBaseStage(SHOOTING_STAGE_ID.CH04_02)) {
      return { left:0, right:0, ratio:1, progress:0 };
    }
    const elapsed = Math.max(0, (Number(now || performance.now()) - Number(state.startedAt || performance.now())) / 1000);
    const startAt = Math.max(0, Number(cfg.startAtSeconds || 0));
    const endAt = Math.max(startAt + .001, Number(cfg.endAtSeconds || getBattleTimeLimitSeconds() || 60));
    const minWidthRatio = clamp(Number(cfg.minWidthRatio || .5), .2, 1);
    const progress = elapsed <= startAt ? 0 : clamp((elapsed - startAt) / (endAt - startAt), 0, 1);
    const ratio = 1 - (1 - minWidthRatio) * progress;
    const inset = Math.max(0, arenaWidth * (1 - ratio) * .5);
    return { left:inset, right:inset, ratio, progress };
  }

  function ensureChapter4ShrinkWalls() {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return { leftWall: null, rightWall: null };
    let leftWall = arena.querySelector('.shooting-ch04-shrink-wall.left');
    let rightWall = arena.querySelector('.shooting-ch04-shrink-wall.right');
    if (!leftWall) {
      leftWall = document.createElement('div');
      leftWall.className = 'shooting-ch04-shrink-wall left';
      arena.appendChild(leftWall);
    }
    if (!rightWall) {
      rightWall = document.createElement('div');
      rightWall.className = 'shooting-ch04-shrink-wall right';
      arena.appendChild(rightWall);
    }
    return { leftWall, rightWall };
  }

  function updateChapter4ShrinkWalls(now) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const walls = ensureChapter4ShrinkWalls();

    // CH04-2の迫る壁は「実戦中かつ縮小開始後」だけ表示する。
    // RETRY直後 / BOSS INTRO / カウントダウン中は、前回のinline widthも含めて完全に初期化。
    const inActiveBattle = !!(
      state &&
      state.running &&
      !state.countdown &&
      !state.ended &&
      !state.finishing &&
      selectedStage &&
      isSelectedBaseStage(SHOOTING_STAGE_ID.CH04_02) &&
      selectedStage.shrinkWalls
    );

    const bounds = inActiveBattle
      ? getChapter4ShrinkBounds(now, Number(arena.clientWidth || 0))
      : { left: 0, right: 0, progress: 0 };
    const visible = inActiveBattle && Number(bounds.progress || 0) > 0;

    [walls.leftWall, walls.rightWall].forEach(el => {
      if (!el) return;
      if (!visible) {
        el.style.display = 'none';
        el.style.width = '0px';
      } else {
        el.style.display = 'block';
      }
    });
    if (!visible) return;

    if (walls.leftWall) walls.leftWall.style.width = `${Math.round(bounds.left)}px`;
    if (walls.rightWall) walls.rightWall.style.width = `${Math.round(bounds.right)}px`;
  }

  function fireChapter4CurtainVolley(now, damage, bulletClassName) {
    const arena = document.getElementById('shooting-arena');
    const cfg = getChapter4CurtainConfig();
    if (!arena || !cfg) return;
    const w = Number(arena.clientWidth || 0);
    const speed = Math.max(50, Number(cfg.speed || 120));
    const rowGapY = Math.max(10, Number(cfg.rowGapY || 24));
    const stageInset = getChapter4ShrinkBounds(now, w);
    const laneLeft = 7 + Number(stageInset.left || 0);
    const laneRight = Math.max(laneLeft + 60, w - 7 - Number(stageInset.right || 0));
    const laneWidth = Math.max(60, laneRight - laneLeft);
    const baseClass = bulletClassName || 'shooting-enemy-bullet shooting-mini-enemy-bullet';

    // v74: CH04の▼を全体で約20%減。
    // 等間隔は使わず、左右端までまんべんなく散らす。
    // 7区画に分けてランダム化し、総数は上4 + 下3 = 7発にする。
    const volleyIndex = Number(state.chapter4CurtainVolleyIndex || 0);
    state.chapter4CurtainVolleyIndex = volleyIndex + 1;
    const totalCount = 7;
    const segment = laneWidth / totalCount;
    const positions = [];
    for (let i = 0; i < totalCount; i++) {
      const segLeft = laneLeft + i * segment;
      const margin = Math.min(8, segment * 0.16);
      const innerLeft = segLeft + margin;
      const innerRight = segLeft + segment - margin;
      const x = innerLeft + fixedStagePatternRandom('ch04_curtain_x', volleyIndex, i) * Math.max(1, innerRight - innerLeft);
      positions.push(x);
    }

    // 毎波の並び替えも固定シード化。再挑戦しても同じ順序になる。
    for (let i = positions.length - 1; i > 0; i--) {
      const j = Math.floor(fixedStagePatternRandom('ch04_curtain_shuffle', volleyIndex, i) * (i + 1));
      [positions[i], positions[j]] = [positions[j], positions[i]];
    }

    const top = positions.slice(0, 4);
    const bottom = positions.slice(4, 7);
    const spawn = (list, y, rowIndex) => {
      list.forEach((x, i) => {
        const p = makeProjectile(`${baseClass} shooting-ch04-curtain-bullet`, x, y, 0, speed, damage);
        if (!p) return;
        // 縦落ちに固定せず、緩い横揺れを加える。
        p.chapter4CurtainDrift = true;
        p.canvasTone = ((i + rowIndex * 2) % 4) + 1;
        p.chapter4CurtainBaseX = x;
        p.chapter4CurtainAge = 0;
        const bulletSalt = rowIndex * 16 + i;
        p.chapter4CurtainAmp = 10 + fixedStagePatternRandom('ch04_curtain_amp', volleyIndex, bulletSalt) * 7;
        p.chapter4CurtainFreq = 1.75 + fixedStagePatternRandom('ch04_curtain_freq', volleyIndex, bulletSalt) * 0.8;
        p.chapter4CurtainPhase = fixedStagePatternRandom('ch04_curtain_phase', volleyIndex, bulletSalt) * Math.PI * 2 + rowIndex * 0.8 + i * 0.17;
        state.enemyBullets.push(p);
      });
    };
    spawn(top, -8, 0);
    spawn(bottom, -8 - rowGapY, 1);
  }


  function fireNormalEnemy(enemy, now) {
    if (!enemy || !enemy.el || !state) return;
    const lockedUntil = getNormalEnemyLockUntil(enemy, now);
    if (now < lockedUntil) {
      freezeNormalEnemyAction(enemy, lockedUntil);
      return;
    }
    const def = enemy.def || {};
    if (def.behavior === 'po_watcher_v1') return; // 監視の眼は攻撃しない
    // build1659: 芽吹き＝狙い撃ち1発／大樹＝自機方向を中心に9方向の弾幕
    if (def.behavior === 'verdant_sprout_v1') {
      const fireRate = Number(def.fireRate || 1500);
      if (now - enemy.lastShotAt < getStageAdjustedEnemyFireInterval(fireRate)) return;
      enemy.lastShotAt = now;
      const aim = getEnemyAimPosition();
      const base = Math.atan2(aim.y - enemy.y, aim.x - enemy.x);
      const ways = Math.max(1, Math.floor(Number(def.spreadWays || 1)));
      const cls = 'shooting-enemy-bullet shooting-mini-enemy-bullet';
      for (let i = 0; i < ways; i++) {
        const off = ways > 1 ? (i - (ways - 1) / 2) * 0.24 : 0;
        shootNormalEnemyProjectile(enemy, base + off, Number(def.bulletSpeed || 210), Number(def.bulletDamage || 95), cls);
      }
      return;
    }
    if (def.behavior === 'inori_torii_v1') return; // 鳥居の攻撃（レーザー）は updateInoriMechanics
    if (def.behavior === 'eclipse_scale_v1') return; // build1681: 天秤は弾を撃たない（突進は updateEclipseScale）
    if (def.behavior === 'verdant_seed_v1') return; // build1663: 成長の実は攻撃しない
    if (def.behavior === 'deinova_core_v1' || def.behavior === 'deinova_ult_core_v1') return; // build2058: 放電コアは攻撃しない／build2060: ULTのコアも

    // v212 generic elemental angels
    if (def.behavior === 'generic_element_shot_v1') {
      const fireRate = Number(def.fireRate || 1280);
      if (now - enemy.lastShotAt < fireRate) return;
      enemy.lastShotAt = now;

      const dx = getEnemyAimPosition().x - enemy.x;
      const dy = getEnemyAimPosition().y - enemy.y;
      const angle = Math.atan2(dy, dx);
      const element = normalizeCombatElement(def.element);
      // CH02-04専用: NORMALの移動AIを維持しつつ、3秒に1回だけ5発SPREAD。
      // 他ステージのNORMALは従来通り単発を撃つ。
      const offsets = def.shotPattern === 'tower11_spread7'
        ? [-.69,-.46,-.23,0,.23,.46,.69]
        : (def.shotPattern === 'spread5' ? [-0.36,-0.18,0,0.18,0.36] : [0]);
      offsets.forEach(offset => shootNormalEnemyProjectile(
        enemy,
        angle + offset,
        Number(def.bulletSpeed || 215),
        Number(def.bulletDamage || 90),
        `shooting-enemy-bullet shooting-mini-enemy-bullet shooting-generic-zako-shot shooting-enemy-element-${element || 'neutral'}`
      ));
      return;
    }

    if (def.behavior === 'generic_element_laser_v1') {
      const fireRate = Number(def.fireRate || 2050);
      if (now - enemy.lastShotAt < fireRate) return;
      enemy.lastShotAt = now;

      const element = normalizeCombatElement(def.element);
      const p = makeProjectile(
        `shooting-enemy-bullet shooting-mini-enemy-bullet shooting-generic-zako-laser shooting-enemy-element-${element || 'neutral'}`,
        enemy.x,
        enemy.y + 42,
        0,
        Number(def.laserSpeed || 540),
        Number(def.laserDamage || 145)
      );
      if (p) {
        p.genericZakoLaser = true;
        p.attackElement = element;
        applyEnemyProjectileElementVisual(p, element);
        p._hw = 5;
        p._hh = 46;
        state.enemyBullets.push(p);
      }
      return;
    }

    // v218 FIRE CHARGE: warning -> lock direction -> straight dash.
    if (def.behavior === 'generic_element_charge_v1') {
      if (enemy.attackState === 'telegraph') {
        if (now < enemy.attackExecuteAt) return;

        enemy.el.classList.remove('generic-charge-warning');
        const dx = getEnemyAimPosition().x - enemy.x;
        const dy = getEnemyAimPosition().y - enemy.y;
        const len = Math.max(1, Math.hypot(dx, dy));
        const speed = Math.max(120, Number(def.chargeSpeed || 500));

        enemy.dashVx = (dx / len) * speed;
        enemy.dashVy = (dy / len) * speed;
        enemy.dashUntil = now + Math.max(280, Number(def.chargeDurationMs || 620));
        // CH02-04専用: この突進開始時刻を記録し、次の突進との間隔を6秒に保つ。
        if (Number(def.chargeIntervalMs || 0) > 0) enemy.lastDashStartedAt = now;
        enemy.attackState = 'dash';
        enemy.el.classList.add('generic-charge-dash');
        return;
      }

      if (enemy.attackState === 'dash') return;
      if (now < (enemy.nextActionAt || 0)) return;

      enemy.attackState = 'telegraph';
      enemy.attackExecuteAt = now + Math.max(350, Number(def.telegraphMs || 760));
      enemy.el.classList.add('generic-charge-warning');
      return;
    }

    // CHAPTER 02: 暴威の残穢
    // 「重撃 → 圧力弾 → 突進」を繰り返し、弾幕ではなく個の圧力を作る。
    if (def.behavior === 'mini_violence_v1') {
      if (enemy.attackState === 'telegraph') {
        if (now < enemy.attackExecuteAt) return;

        enemy.el.classList.remove('violence-warning');
        const dx = getEnemyAimPosition().x - enemy.x;
        const dy = getEnemyAimPosition().y - enemy.y;
        const baseAngle = Math.atan2(dy, dx);
        const action = enemy.actionIndex % 3;

        if (action === 0) {
          // 重撃：大きく、速く、痛い単発。
          shootNormalEnemyProjectile(
            enemy,
            baseAngle,
            Number(def.bulletSpeed || 250),
            Number(def.heavyShotDamage || 210),
            'shooting-enemy-bullet shooting-mini-enemy-bullet shooting-violence-heavy'
          );
        } else if (action === 1) {
          // 圧力弾：3方向で逃げ道を削る。
          [-0.34, 0, 0.34].forEach(offset => {
            shootNormalEnemyProjectile(
              enemy,
              baseAngle + offset,
              Number(def.bulletSpeed || 250) * .88,
              Number(def.pressureShotDamage || 150),
              'shooting-enemy-bullet shooting-mini-enemy-bullet shooting-violence-pressure'
            );
          });
        } else {
          // 突進：予兆後、プレイヤーの現在位置へ一気に踏み込む。
          const stageChargeSpeed = Number(selectedStage?.normalBattle?.chargeSpeed || 0);
          const speed = stageChargeSpeed > 0 ? stageChargeSpeed : Number(def.chargeSpeed || 520);
          enemy.dashVx = Math.cos(baseAngle) * speed;
          enemy.dashVy = Math.sin(baseAngle) * speed;
          enemy.dashUntil = now + 520;
          enemy.attackState = 'dash';
          enemy.el.classList.add('violence-dash');
          return;
        }

        enemy.actionIndex = (enemy.actionIndex + 1) % 3;
        enemy.attackState = 'idle';
        enemy.nextActionAt = now + Number(def.fireRate || 1900);
        return;
      }

      if (enemy.attackState === 'dash') return;
      if (now < (enemy.nextActionAt || 0)) return;

      enemy.attackState = 'telegraph';
      enemy.attackExecuteAt = now + Number(def.telegraphMs || 520);
      enemy.el.classList.add('violence-warning');
      return;
    }

    if (def.behavior === 'mini_mirage_v1') {
      const cfg = getNormalBattleConfig();
      const fireRate = Number(cfg.enemyFireRate || def.fireRate || 1080);
      const speed = Number(cfg.enemyBulletSpeed || def.bulletSpeed || 230);
      const damage = Number(cfg.enemyBulletDamage || def.bulletDamage || 120);
      const warningEveryMs = Math.max(0, Number(cfg.mirageWarningEveryMs || 0));
      const telegraphMs = Math.max(350, Number(cfg.mirageWarningTelegraphMs || 700));

      // CH05-2: 3体それぞれが位相をずらしてWARNINGを撃つため、危険弾が多めに来る。
      if (warningEveryMs > 0) {
        if (!enemy.mirageNextWarningAt) {
          enemy.mirageNextWarningAt = now + 1700 + (enemy.actionIndex % 3) * 1150;
        }
        if (enemy.mirageWarningExecuteAt && now >= enemy.mirageWarningExecuteAt) {
          enemy.mirageWarningExecuteAt = 0;
          const dx = getEnemyAimPosition().x - enemy.x;
          const dy = getEnemyAimPosition().y - enemy.y;
          const angle = Math.atan2(dy, dx);
          const p = shootNormalEnemyProjectile(
            enemy,
            angle,
            speed * 0.82,
            999999,
            'shooting-enemy-bullet shooting-danger-bullet shooting-mirage-warning-bullet'
          );
          if (p) p.mirageWarning = true;
          enemy.mirageNextWarningAt = now + warningEveryMs;
          removeBossDangerWarning();
          return;
        }
        if (!enemy.mirageWarningExecuteAt && now >= enemy.mirageNextWarningAt) {
          enemy.mirageWarningExecuteAt = now + telegraphMs;
          showBossDangerWarning();
          return;
        }
      }

      if (now - enemy.lastShotAt < fireRate) return;
      enemy.lastShotAt = now;
      const dx = getEnemyAimPosition().x - enemy.x;
      const dy = getEnemyAimPosition().y - enemy.y;
      const baseAngle = Math.atan2(dy, dx);
      const spread = (enemy.actionIndex++ % 2) === 0
        ? [-0.28, 0, 0.28]
        : [-0.42, -0.21, 0, 0.21, 0.42];
      spread.forEach(offset => {
        shootNormalEnemyProjectile(
          enemy,
          baseAngle + offset,
          speed,
          damage,
          'shooting-enemy-bullet shooting-mini-enemy-bullet shooting-mirage-bullet'
        );
      });
      return;
    }

    if (def.behavior === 'mini_barrage_v1') {
      const cfg = getNormalBattleConfig();
      const level = Math.max(1, Math.min(3, Number(cfg.barrageLevel || 2)));
      const fireRate = Number(cfg.enemyFireRate || def.fireRate || 1220);

      if (now - enemy.lastShotAt < fireRate) return;
      enemy.lastShotAt = now;

      const dx = getEnemyAimPosition().x - enemy.x;
      const dy = getEnemyAimPosition().y - enemy.y;
      const baseAngle = Math.atan2(dy, dx);
      const speed = Number(cfg.enemyBulletSpeed || def.bulletSpeed || 220);
      const damage = Number(cfg.enemyBulletDamage || def.bulletDamage || 105);
      const volleyIndex = Number(enemy.patternVolleyIndex || 0);
      enemy.patternVolleyIndex = volleyIndex + 1;

      if (level === 1) {
        // CH03-01 弱:
        // 3WAY → 5WAY。正面中心で、弾間隔も広い。
        const pattern = enemy.actionIndex % 2;

        if (pattern === 0) {
          [-0.28, 0, 0.28].forEach(offset => {
            shootNormalEnemyProjectile(
              enemy,
              baseAngle + offset,
              speed,
              damage,
              'shooting-enemy-bullet shooting-mini-enemy-bullet'
            );
          });
        } else {
          [-0.42, -0.21, 0, 0.21, 0.42].forEach(offset => {
            shootNormalEnemyProjectile(
              enemy,
              baseAngle + offset,
              speed * 0.94,
              damage,
              'shooting-enemy-bullet shooting-mini-enemy-bullet'
            );
          });
        }

        enemy.actionIndex = (enemy.actionIndex + 1) % 2;
        return;
      }

      if (level === 2) {
        // CH03-02 中:
        // 5WAY → 揺れる7WAY → 8発リング。
        const pattern = enemy.actionIndex % 3;

        if (pattern === 0) {
          [-0.42, -0.21, 0, 0.21, 0.42].forEach(offset => {
            shootNormalEnemyProjectile(
              enemy,
              baseAngle + offset,
              speed,
              damage,
              'shooting-enemy-bullet shooting-mini-enemy-bullet'
            );
          });
        } else if (pattern === 1) {
          const phaseOffset = Math.sin((enemy.phaseSeed || 0) + volleyIndex * fireRate * 0.0028) * 0.12;
          [-0.54, -0.36, -0.18, 0, 0.18, 0.36, 0.54].forEach(offset => {
            shootNormalEnemyProjectile(
              enemy,
              baseAngle + offset + phaseOffset,
              speed * 0.96,
              damage,
              'shooting-enemy-bullet shooting-mini-enemy-bullet'
            );
          });
        } else {
          const startAngle = (enemy.phaseSeed || 0) + volleyIndex * fireRate * 0.0018;
          for (let i = 0; i < 8; i++) {
            const angle = startAngle + (Math.PI * 2 * i / 8);
            shootNormalEnemyProjectile(
              enemy,
              angle,
              speed * 0.80,
              Math.max(1, damage - 10),
              'shooting-enemy-bullet shooting-mini-enemy-bullet'
            );
          }
        }

        enemy.actionIndex = (enemy.actionIndex + 1) % 3;
        return;
      }

      // CH03-03 強:
      // 7WAY → 回転9WAY → 12発リング。
      // BOSS前の最終練習として、通路を読む必要がある密度にする。
      const pattern = enemy.actionIndex % 3;

      if (pattern === 0) {
        [-0.57, -0.38, -0.19, 0, 0.19, 0.38, 0.57].forEach(offset => {
          shootNormalEnemyProjectile(
            enemy,
            baseAngle + offset,
            speed,
            damage,
            'shooting-enemy-bullet shooting-mini-enemy-bullet'
          );
        });
      } else if (pattern === 1) {
        const phaseOffset = Math.sin((enemy.phaseSeed || 0) + volleyIndex * fireRate * 0.0035) * 0.20;
        [-0.72, -0.54, -0.36, -0.18, 0, 0.18, 0.36, 0.54, 0.72].forEach(offset => {
          shootNormalEnemyProjectile(
            enemy,
            baseAngle + offset + phaseOffset,
            speed * 1.02,
            damage,
            'shooting-enemy-bullet shooting-mini-enemy-bullet'
          );
        });
      } else {
        const startAngle = (enemy.phaseSeed || 0) + volleyIndex * fireRate * 0.0027;
        for (let i = 0; i < 12; i++) {
          const angle = startAngle + (Math.PI * 2 * i / 12);
          shootNormalEnemyProjectile(
            enemy,
            angle,
            speed * 0.86,
            Math.max(1, damage - 12),
            'shooting-enemy-bullet shooting-mini-enemy-bullet'
          );
        }
      }

      enemy.actionIndex = (enemy.actionIndex + 1) % 3;
      return;
    }

    // CHAPTER 04: 美しい弾幕
    // CH03のように弾数そのものを増やすのではなく、軌道の規則性を見せる。
    if (def.behavior === 'mini_beautiful_v1') {
      const cfg = getNormalBattleConfig();
      const curtainCfg = getChapter4CurtainConfig();
      const level = Math.max(1, Math.min(3, Number(cfg.beautifulLevel || 1)));
      const fireRate = Number((curtainCfg && curtainCfg.intervalMs) || cfg.enemyFireRate || def.fireRate || 1180);
      if (now - enemy.lastShotAt < fireRate) return;
      enemy.lastShotAt = now;

      const speed = Number(cfg.enemyBulletSpeed || def.bulletSpeed || 205);
      const damage = Number(cfg.enemyBulletDamage || def.bulletDamage || 95);
      const beautifulVolleyIndex = Number(enemy.patternVolleyIndex || 0);
      enemy.patternVolleyIndex = beautifulVolleyIndex + 1;
      if (curtainCfg) {
        fireChapter4CurtainVolley(now, damage, 'shooting-enemy-bullet shooting-mini-enemy-bullet');
        enemy.actionIndex = (enemy.actionIndex + 1) % 2;
        return;
      }
      const pattern = enemy.actionIndex % (level >= 3 ? 2 : 1);

      const spawnSpiral = (arms, reverse = false) => {
        const originX = enemy.x;
        const originY = enemy.y + 22;
        const spin = (reverse ? -1 : 1) * (level === 1 ? 0.36 : 0.44);
        const radialSpeed = speed * (level === 1 ? 0.58 : 0.64);
        const start = (enemy.phaseSeed || 0) + beautifulVolleyIndex * fireRate * 0.00055;
        for (let i = 0; i < arms; i++) {
          const a = start + Math.PI * 2 * i / arms;
          const p = makeProjectile(
            'shooting-enemy-bullet shooting-mini-enemy-bullet shooting-beautiful-bullet shooting-beautiful-spiral',
            originX, originY,
            Math.cos(a) * radialSpeed,
            Math.sin(a) * radialSpeed,
            damage
          );
          if (!p) continue;
          p.beautifulSpiral = true;
          p.el.classList.add(`shooting-beautiful-tone-${(i % 4) + 1}`);
          p.canvasTone = (i % 4) + 1;
          p.beautifulAge = 0;
          p.beautifulOriginX = originX;
          p.beautifulOriginY = originY;
          p.beautifulStartAngle = a;
          p.beautifulAngularSpeed = spin;
          p.beautifulRadialSpeed = radialSpeed;
          state.enemyBullets.push(p);
        }
      };

      const spawnWave = (count, mirror = false) => {
        const center = enemy.x;
        const gap = level === 2 ? 18 : 16;
        const phaseSeed = (enemy.phaseSeed || 0) + beautifulVolleyIndex * fireRate * 0.002;
        for (let i = 0; i < count; i++) {
          const offset = (i - (count - 1) / 2) * gap;
          const x = center + offset;
          const p = makeProjectile(
            'shooting-enemy-bullet shooting-mini-enemy-bullet shooting-beautiful-bullet shooting-beautiful-wave',
            x, enemy.y + 24,
            0, speed,
            damage
          );
          if (!p) continue;
          p.beautifulWave = true;
          p.el.classList.add(`shooting-beautiful-tone-${(i % 4) + 1}`);
          p.canvasTone = (i % 4) + 1;
          p.beautifulAge = 0;
          p.beautifulWaveBaseX = x;
          p.beautifulWaveAmp = level === 2 ? 18 : 23;
          p.beautifulWaveFreq = level === 2 ? 3.15 : 3.55;
          p.beautifulWavePhase = phaseSeed + i * 0.72 + (mirror ? Math.PI : 0);
          state.enemyBullets.push(p);
        }
      };

      if (level === 1) {
        // 6本の螺旋。毎射ごとに回転方向を反転し、花が開閉するように見せる。
        spawnSpiral(6, (enemy.actionIndex % 2) === 1);
      } else if (level === 2) {
        // 等間隔の弾列が左右へ同期して揺れる「波」。
        spawnWave(7, (enemy.actionIndex % 2) === 1);
      } else if (pattern === 0) {
        // 螺旋を少し細かく。密度より軌跡を読ませる。
        spawnSpiral(8, (enemy.actionIndex % 4) >= 2);
      } else {
        // 9列の波。隣同士の位相をずらし、編み目のような規則性を作る。
        spawnWave(9, (enemy.actionIndex % 4) >= 2);
      }

      enemy.actionIndex = (enemy.actionIndex + 1) % 4;
      return;
    }

    if (def.behavior === 'faceless_minion_v1') {
      if (now - enemy.lastShotAt < getStageAdjustedEnemyFireInterval(Number(def.fireRate || 1180))) return;
      enemy.lastShotAt = now;
      const base = Math.atan2(getEnemyAimPosition().y - enemy.y, getEnemyAimPosition().x - enemy.x);
      [-0.18, 0, 0.18].forEach(offset => {
        shootNormalEnemyProjectile(
          enemy,
          base + offset,
          Number(def.bulletSpeed || 205),
          Number(def.bulletDamage || 105),
          'shooting-enemy-bullet shooting-mini-enemy-bullet shooting-faceless-bullet'
        );
      });
      return;
    }

    if (def.behavior === 'remnant07_clone_v1') {
      if (now - enemy.lastShotAt < getStageAdjustedEnemyFireInterval(Number(def.fireRate || 980))) return;
      enemy.lastShotAt = now;
      const base = Math.atan2(getEnemyAimPosition().y - enemy.y, getEnemyAimPosition().x - enemy.x);
      [-0.30,-0.15,0,0.15,0.30].forEach(offset => {
        shootNormalEnemyProjectile(
          enemy,
          base + offset,
          Number(def.bulletSpeed || 225),
          Number(def.bulletDamage || 135),
          'shooting-enemy-bullet shooting-mini-enemy-bullet shooting-ch07-clone-bullet'
        );
      });
      return;
    }

    // CHAPTER 01など既存敵。
    if (now - enemy.lastShotAt < getStageAdjustedEnemyFireInterval(Number(def.fireRate || 1550))) return;
    enemy.lastShotAt = now;
    const dx = getEnemyAimPosition().x - enemy.x;
    const dy = getEnemyAimPosition().y - enemy.y;
    const angle = Math.atan2(dy, dx);
    const speed = Number(def.bulletSpeed || 185);
    shootNormalEnemyProjectile(
      enemy,
      angle,
      speed,
      Number(def.bulletDamage || 85),
      'shooting-enemy-bullet shooting-mini-enemy-bullet'
    );
  }

  // 捕縛中の敵本体に蜘蛛糸を表示。終了・撃破後は必ず解除する。
  // build1659: 敵画像（<img>）には疑似要素が描けないため、捕縛中の敵ごとに蜘蛛の巣の表示要素を重ねて追従させる。
  function syncCamillaBoundWebVisual(now) {
    if (!state) return;
    // build1666: 誰も捕縛されておらず、表示中の巣もなければ何もしない（毎フレームのDOM走査・計測を避ける）
    const anyBound = (state.normalEnemies || []).some(e => e && now < Number(e.camillaWebRootUntil || 0)) ||
      !!(state.boss && now < Number(state.boss.camillaWebRootUntil || 0));
    if (!anyBound && !state.camillaWebFxActive) return;
    state.camillaWebFxActive = anyBound;
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const sync = (holder, x, y, size, bound) => {
      let fx = holder.camWebFx;
      if (!bound) { if (fx) { fx.remove(); holder.camWebFx = null; } return; }
      if (!fx || !fx.isConnected) {
        ensureConjureVisualStyles();
        fx = document.createElement('div');
        fx.className = 'shooting-camilla-bound-web-fx';
        fx.style.backgroundImage = `url("${getCamillaWebDataUri()}")`;
        fx.style.zIndex = String(getCamillaShotWebZ(holder.el || (holder === state.boss ? document.getElementById(BOSS_ID) : null)));
        arena.appendChild(fx);
        holder.camWebFx = fx;
      }
      const px = Math.round(size); // build1797: 大きさは変わった時だけ書く
      if (fx._sizePx !== px) { fx._sizePx = px; fx.style.width = fx.style.height = `${px}px`; }
      positionUnit(fx, x, y);
    };
    for (const e of (state.normalEnemies || [])) {
      if (!e) continue;
      const bound = !!e.el && Number(e.hp) > 0 && now < Number(e.camillaWebRootUntil || 0);
      const size = Math.max(52, Math.max(Number(e._hw || 0), Number(e._hh || 0)) * 2 * 1.25 || 72);
      sync(e, Number(e.x || 0), Number(e.y || 0), size, bound);
    }
    if (state.boss) {
      const bound = !isNormalBattle() && Number(state.boss.hp) > 0 && now < Number(state.boss.camillaWebRootUntil || 0);
      // build1797: ボスの幅は毎フレーム測らない（getBossHalfWidthFast は幅×倍率×0.32 を0.5秒キャッシュ）
      const size = Math.max(90, getBossHalfWidthFast(now) / 0.32 * 0.95);
      sync(state.boss, Number(state.boss.x || 0), Number(state.boss.y || 0), size, bound);
    }
    // 撃破されて一覧から外れた敵の表示も残さない（build1797: 掃除は0.5秒ごと）
    if (now - Number(state.camWebSweepAt || 0) < 500 && anyBound) return;
    state.camWebSweepAt = now;
    arena.querySelectorAll('.shooting-camilla-bound-web-fx').forEach(fx => {
      const owned = (state.normalEnemies || []).some(e => e && e.camWebFx === fx) || (state.boss && state.boss.camWebFx === fx);
      if (!owned) fx.remove();
    });
  }

  // カミラの蜘蛛糸: 移動位置だけ固定し、敵の射撃AIは実行させる。
  // ------------------------------------------------------------
  // build1659: 樹獣の森 ─ 成長システム
  //  ・敵が「実際に動いた」フレームだけ成長ゲージが溜まる（捕縛・スタン・凍結など、止まっている間は溜まらない）
  //  ・満タンで成長：HP全快＆最大HP増、ひと回り大きくなり、行動が強化される（敵ごとの verdantGrowth）
  // ------------------------------------------------------------
  function updateVerdantGrowth(dt, now) {
    const cfg = selectedStage && selectedStage.verdant;
    if (!cfg || !state || state.ended || state.finishing) return;
    const growthMs = Math.max(1000, Number(cfg.growthMs || 8000));
    (state.normalEnemies || []).forEach(enemy => {
      if (!enemy || !enemy.el || enemy.hp <= 0) return;
      const g = enemy.def && enemy.def.verdantGrowth;
      if (!g && !(enemy.verdantBase && enemy.verdantBase.verdantGrowth)) return;
      const lx = Number(enemy.verdantLastX), ly = Number(enemy.verdantLastY);
      enemy.verdantLastX = enemy.x; enemy.verdantLastY = enemy.y;
      if (enemy.verdantGrown || !Number.isFinite(lx)) return;
      const moved = Math.hypot(Number(enemy.x) - lx, Number(enemy.y) - ly) > 0.01; // 捕縛・スタン中は座標が完全に止まる
      if (moved) enemy.verdantGrowthMs = Number(enemy.verdantGrowthMs || 0) + Math.max(0, dt) * 1000;
      const ratio = Math.max(0, Math.min(1, Number(enemy.verdantGrowthMs || 0) / growthMs));
      // build1666: 変化した時だけDOMへ書く
      const pct = Math.round(ratio * 100) / 100;
      if (enemy.verdantBarPct !== pct) {
        enemy.verdantBarPct = pct;
        const bar = enemy.hpEl && enemy.hpEl.querySelector('.verdant-growth-bar b');
        if (bar) bar.style.transform = `scaleX(${pct})`;
      }
      if (enemy.hpEl && enemy.verdantHalted !== !moved) { enemy.verdantHalted = !moved; enemy.hpEl.classList.toggle('is-verdant-halted', !moved); }
      if (ratio >= 1) growVerdantEnemy(enemy, now);
    });
  }
  function growVerdantEnemy(enemy, now) {
    const g = enemy.def && enemy.def.verdantGrowth;
    if (!g || enemy.verdantGrown) return;
    enemy.verdantGrown = true;
    enemy.verdantBase = enemy.def;
    enemy.def = Object.assign({}, enemy.def, g.grownDef || {}, { name: g.name || enemy.def.name });
    // HP全快＆最大HP増
    enemy.hpMax = Math.max(1, Math.round(Number(enemy.hpMax || 1) * Math.max(1, Number(g.hpMul || 1.5))));
    enemy.hp = enemy.hpMax;
    renderMiniEnemyHp(enemy, true);
    // ひと回り大きく
    const mul = Math.max(1, Number(g.scaleMul || 1.25));
    enemy.baseDisplayScale = Number(enemy.baseDisplayScale || getNormalEnemyBaseDisplayScale(enemy.verdantBase)) * mul;
    enemy.displayScale = Number(enemy.displayScale || 1) * mul;
    enemy.el.style.setProperty('--enemy-scale', String(enemy.displayScale));
    if (g.grownImage) {
      const fallback = enemy.el.getAttribute('src');
      enemy.el.onerror = () => { enemy.el.onerror = null; enemy.el.src = fallback; };
      enemy.el.src = String(g.grownImage);
    }
    enemy.el.classList.add('verdant-grown');
    enemy.hpEl?.classList.add('is-verdant-grown');
    // 大樹はその場に根を張る（今いる場所を基準位置にする）
    enemy.baseX = enemy.x; enemy.baseY = enemy.y;
    requestAnimationFrame(() => { try { measureUnitSize(enemy); positionMiniEnemyHp(enemy); } catch (_) {} });
    const arena = document.getElementById('shooting-arena');
    if (arena) {
      const pop = document.createElement('div');
      pop.className = 'verdant-grow-pop';
      pop.textContent = `成長！ ${g.name || ''}`;
      arena.appendChild(pop);
      positionUnit(pop, enemy.x, enemy.y - 40);
      setTimeout(() => { try { pop.remove(); } catch (_) {} }, 1100);
    }
  }

  // build1659: 樹獣の女王の成長（動いている間だけ溜まる。満タンで「開花」）
  // ------------------------------------------------------------
  // build1663: 成長の実
  //  一定間隔で戦場に実る（同時に最大 max 個）。ripenMs で熟すと、女王が蔓で吸い上げて成長ゲージが queenBoost 分進む。
  //  熟す前に配下（樹獣・芽吹き）が触れると、その配下の成長ゲージが addBoost 分進む。
  //  撃ち壊せば何も起きない ＝ 「止める」以外にも成長を阻止できる手段。
  // ------------------------------------------------------------
  function getVerdantSeedConfig() {
    return (selectedStage && selectedStage.verdant && selectedStage.verdant.seeds) || null;
  }
  function getVerdantSeeds() {
    return (state && state.normalEnemies || []).filter(e => e && e.el && e.hp > 0 && e.def && e.def.behavior === 'verdant_seed_v1');
  }
  function removeVerdantSeed(seed) {
    if (!seed) return;
    [seed.el, seed.hpEl, seed.elementEl, seed.weaknessBarrierEl].forEach(n => { try { n && n.remove(); } catch (_) {} });
    if (seed.camWebFx) { try { seed.camWebFx.remove(); } catch (_) {} seed.camWebFx = null; }
    seed.hp = 0;
    state.normalEnemies = state.normalEnemies.filter(e => e !== seed);
  }
  function spawnVerdantSeed(now) {
    const arena = document.getElementById('shooting-arena');
    const def = getShootingEnemy(window.ShootingEnemies?.SHOOTING_ENEMY_ID?.VERDANT_SEED || 'shooting_verdant_seed');
    if (!arena || !def || !state || !state.boss) return;
    const w = arena.clientWidth, h = arena.clientHeight;
    // 女王から離れた位置に実らせる（出た瞬間に吸われないように）
    let x = w * .5, y = h * .36;
    for (let i = 0; i < 8; i++) {
      x = w * (.12 + Math.random() * .76);
      y = h * (.27 + Math.random() * .22);
      if (Math.hypot(x - Number(state.boss.x || 0), y - Number(state.boss.y || 0)) > 110) break;
    }
    const seed = createNormalEnemy(def, now);
    if (!seed) return;
    state.verdantSeedSerial = Number(state.verdantSeedSerial || 0) + 1;
    seed.uid = 'verdant_seed_' + state.verdantSeedSerial;
    seed.x = seed.baseX = x; seed.y = seed.baseY = y;
    seed.seedBornAt = now;
    seed.el.classList.add('verdant-seed');
    // 実専用の見やすいゲージ：HP（太め）＋「熟すまで」のバー
    if (seed.hpEl) {
      seed.hpEl.classList.add('verdant-seed-hp');
      seed.hpEl.insertAdjacentHTML('beforeend', '<span class="verdant-seed-ripe"><b></b></span><em class="verdant-seed-label">成長の実</em>');
    }
    positionUnit(seed.el, x, y);
    positionMiniEnemyHp(seed);
    state.normalEnemies.push(seed);
  }
  function showVerdantAbsorbFx(seed, tx, ty, label) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const dx = tx - seed.x, dy = ty - seed.y, len = Math.hypot(dx, dy);
    if (len > 8) {
      const vine = document.createElement('div');
      vine.className = 'verdant-seed-vine';
      vine.style.width = len + 'px';
      vine.style.transform = `translate3d(${seed.x}px,${seed.y}px,0) rotate(${Math.atan2(dy, dx)}rad)`;
      arena.appendChild(vine);
      setTimeout(() => { try { vine.remove(); } catch (_) {} }, 520);
    }
    const pop = document.createElement('div');
    pop.className = 'verdant-grow-pop';
    pop.textContent = label;
    positionUnit(pop, tx, ty - 34);
    arena.appendChild(pop);
    setTimeout(() => { try { pop.remove(); } catch (_) {} }, 1100);
  }
  function updateVerdantSeeds(now) {
    const cfg = getVerdantSeedConfig();
    if (!cfg || !state || !state.boss || isNormalBattle() || state.ended || state.finishing || state.boss.hp <= 0) return;
    const seeds = getVerdantSeeds();
    // 実る
    if (!state.verdantNextSeedAt) state.verdantNextSeedAt = state.startedAt + Math.max(0, Number(cfg.firstAtMs || 5000));
    if (now >= state.verdantNextSeedAt) {
      if (seeds.length < Math.max(1, Number(cfg.max || 2))) spawnVerdantSeed(now);
      state.verdantNextSeedAt = now + Math.max(1500, Number(cfg.intervalMs || 7000));
    }
    const ripenMs = Math.max(1500, Number(cfg.ripenMs || 7000));
    const growthCfg = selectedStage.verdant || {};
    const reach = Math.max(10, Number(cfg.addReach || 46));
    for (const seed of seeds) {
      // 画像の読み込み前・失敗時でも撃てるよう、当たり判定は最低限の大きさを保証
      seed._hw = Math.max(Number(seed._hw || 0), 20);
      seed._hh = Math.max(Number(seed._hh || 0), 20);
      const ratio = Math.max(0, Math.min(1, (now - Number(seed.seedBornAt || now)) / ripenMs));
      // build1666: 見た目の更新は10段階に間引く（光の再描画を毎フレーム起こさない）
      const step = Math.floor(ratio * 10) / 10;
      if (seed.seedVisualStep !== step) {
        seed.seedVisualStep = step;
        seed.el.style.setProperty('--seed-ripe', String(step));
        // 熟すほど大きく（位置ずれしないよう、配置用の --enemy-scale で拡大する）
        seed.el.style.setProperty('--enemy-scale', (Math.max(.1, Number(seed.displayScale || 1)) * (.72 + step * .42)).toFixed(3));
        seed.el.classList.toggle('is-ripening', step >= .7);
        if (seed.hpEl) {
          const rb = seed.hpEl.querySelector('.verdant-seed-ripe b');
          if (rb) rb.style.transform = `scaleX(${step})`;
          seed.hpEl.classList.toggle('is-ripening', step >= .7);
        }
      }
      // 熟す前に配下が触れたら、その配下が吸収
      const add = (state.normalEnemies || []).find(e => e && e !== seed && e.el && e.hp > 0 && e.def &&
        e.def.verdantGrowth && !e.verdantGrown && Math.hypot(e.x - seed.x, e.y - seed.y) <= reach);
      if (add) {
        add.verdantGrowthMs = Number(add.verdantGrowthMs || 0) + Math.max(1000, Number(growthCfg.growthMs || 8000)) * Number(cfg.addBoost || .5);
        showVerdantAbsorbFx(seed, add.x, add.y, '吸収！');
        removeVerdantSeed(seed);
        continue;
      }
      // 熟したら女王が吸い上げる（開花後は吸い上げても何も起きないが、実は消える）
      if (ratio >= 1) {
        if (!state.verdantQueenGrown) {
          state.verdantQueenGrowthMs = Number(state.verdantQueenGrowthMs || 0) + Math.max(2000, Number(growthCfg.bossGrowthMs || 18000)) * Number(cfg.queenBoost || .22);
        }
        showVerdantAbsorbFx(seed, Number(state.boss.x || 0), Number(state.boss.y || 0), state.verdantQueenGrown ? '吸収' : '成長が進んだ！');
        removeVerdantSeed(seed);
      }
    }
  }
  function removeVerdantDom() {
    document.querySelectorAll('#verdant-boss-growth, .verdant-grow-pop, .verdant-seed-vine').forEach(el => el.remove());
  }
  function updateVerdantBossGrowth(dt, now) {
    const cfg = selectedStage && selectedStage.verdant;
    const g = BOSS && BOSS.verdantBossGrowth;
    if (!cfg || !g || !state || !state.boss || isNormalBattle() || state.ended || state.finishing) return;
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const growthMs = Math.max(2000, Number(cfg.bossGrowthMs || 18000));
    const lx = Number(state.verdantQueenLastX), ly = Number(state.verdantQueenLastY);
    state.verdantQueenLastX = state.boss.x; state.verdantQueenLastY = state.boss.y;
    let el = document.getElementById('verdant-boss-growth');
    if (state.verdantQueenGrown || state.boss.hp <= 0) { if (el) el.remove(); return; }
    const moved = Number.isFinite(lx) && Math.hypot(Number(state.boss.x) - lx, Number(state.boss.y) - ly) > 0.01;
    if (moved && !state.phaseTransition) state.verdantQueenGrowthMs = Number(state.verdantQueenGrowthMs || 0) + Math.max(0, dt) * 1000;
    const ratio = Math.max(0, Math.min(1, Number(state.verdantQueenGrowthMs || 0) / growthMs));
    if (!el) {
      el = document.createElement('div');
      el.id = 'verdant-boss-growth';
      el.className = 'verdant-boss-growth';
      el.innerHTML = '<span>開花まで</span><i><b></b></i>';
      arena.appendChild(el);
    }
    if (el.__halted !== !moved) { el.__halted = !moved; el.classList.toggle('is-halted', !moved); }
    const pct = Math.round(ratio * 200) / 200;
    if (el.__pct !== pct) { el.__pct = pct; const bar = el.querySelector('b'); if (bar) bar.style.transform = `scaleX(${pct})`; }
    // build1666: ボスの高さは毎フレーム測らない（レイアウト再計算を避ける）。初回と開花時だけ測ってキャッシュ
    if (!(state.verdantBossHalfH > 0)) {
      const bossEl = document.getElementById(BOSS_ID);
      state.verdantBossHalfH = Math.max(50, Number(bossEl && bossEl.offsetHeight || 128) * Math.max(.1, Number(getResponsiveBossDisplayScale() || 1)) * 0.5);
    }
    positionUnit(el, Number(state.boss.x || 0), Number(state.boss.y || 0) + state.verdantBossHalfH + 4);
    if (ratio >= 1) bloomVerdantQueen(now);
  }
  function bloomVerdantQueen(now) {
    const g = BOSS && BOSS.verdantBossGrowth;
    if (!g || state.verdantQueenGrown) return;
    state.verdantQueenGrown = true;
    document.getElementById('verdant-boss-growth')?.remove();
    // 速度切替で座標が飛ばないよう、現在地から新しい軌道へ滑らかに移行
    state.bossMotionBlendFromX = state.boss.x; state.bossMotionBlendFromY = state.boss.y;
    state.bossMotionBlendStartedAt = getBossMotionTime(now); state.bossMotionBlendDurationMs = 900;
    // HP回復（現在のゲージの範囲内まで）
    const phase = Math.max(1, Number(state.boss.phase || 1));
    const gaugeTop = getBossGaugeFloorForPhase(phase) + getBossGaugeHpForPhase(phase);
    const heal = Math.max(0, Number(state.boss.hpMax || 0) * Math.max(0, Number(g.healRate || 0.25)));
    state.boss.hp = Math.min(gaugeTop, Number(state.boss.hp || 0) + heal);
    const bossEl = document.getElementById(BOSS_ID);
    if (bossEl) {
      const src = getSelectedBossImage();
      bossEl.src = src;
      bossEl.classList.add('verdant-bloomed');
      state.verdantBossHalfH = 0; // build1666: 開花後の大きさで測り直す
    }
    showFacelessBattleCut('開花', '樹獣の女王が目覚めた');
    renderHud();
  }

  function updateCamillaRootedEnemies(dt, now) {
    const tracked = (state?.normalEnemies || []).filter(e=>e&&e.el&&e.hp>0&&now<Number(e.camillaWebRootUntil||0))
      .map(e=>({e,x:e.x,y:e.y,baseX:e.baseX,baseY:e.baseY}));
    updateNormalEnemies(dt,now);
    tracked.forEach(({e,x,y,baseX,baseY})=>{
      if(!e.el || e.hp<=0)return;
      e.x=x;e.y=y;
      if(baseX!==undefined)e.baseX=baseX;
      if(baseY!==undefined)e.baseY=baseY;
      positionUnit(e.el,x,y);
      positionMiniEnemyHp(e);
    });
  }

  // build1666: アリーナの大きさは直近のフレームで測った値を使う（毎フレームの強制レイアウトを避ける）
  function getCachedArenaSize(arena) {
    if (performance.now() - lastArenaSize.at < 120 && lastArenaSize.w > 0) return lastArenaSize;
    lastArenaSize.w = arena.clientWidth; lastArenaSize.h = arena.clientHeight; lastArenaSize.at = performance.now();
    return lastArenaSize;
  }
  function updateNormalEnemies(dt, now) {
    if (!isNormalBattle() && !hasBossAdds()) return;
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const arenaSize = getCachedArenaSize(arena);
    const w = arenaSize.w;
    const h = arenaSize.h;
    let swarmTargets = null;

    state.normalEnemies.forEach(enemy => {
      if (!enemy || !enemy.el) return;
      if (enemy.dawnGuard) { positionUnit(enemy.el, enemy.x, enemy.y); positionMiniEnemyHp(enemy); return; }
      if (enemy.camSpider) { updateCamillaSpider(enemy, dt, now); return; }
      if (enemy.memoryGuardian) { updateMemoryGuardian(enemy, dt, now); return; }
      if (enemy.hazeClone) return; // build1866: 陽炎の分身は updateHazeMechanics が動かす
      if (enemy.nerisaClone) return; // build2125: ネリサの分裂体は updateNerisaClones が動かす
      if (enemy.partyTarget) return; // build2150: 夜会の客は updatePartyGuests が動かす（攻撃しない）
      const def = enemy.def || {};
      // build1643: イノリの鳥居は常にイノリの左右・少し後方に付き従う（移動AI・射撃なし。レーザーは本体側で管理）
      if (def.behavior === 'verdant_seed_v1' || def.behavior === 'deinova_core_v1' || def.behavior === 'deinova_ult_core_v1') { // build1663: 成長の実は動かない（熟し具合は updateVerdantSeeds）／build2058: 放電コアも固定
        enemy.x = enemy.baseX; enemy.y = enemy.baseY;
        positionUnit(enemy.el, enemy.x, enemy.y);
        positionMiniEnemyHp(enemy);
        return;
      }
      if (def.behavior === 'inori_torii_v1') {
        placeInoriTorii(enemy, w);
        positionUnit(enemy.el, enemy.x, enemy.y);
        positionMiniEnemyHp(enemy);
        return;
      }
      if (def.behavior === 'eclipse_scale_v1') { // build1681: 天秤はうろつき・突進（updateEclipseScale）
        updateEclipseScale(enemy, dt, now, w, h);
        return;
      }

      // build1157: CH01-02の貫通チュートリアルは3体を縦一列に固定する。
      // ジグのレーザーが複数体を貫通することを視覚的に学べるよう、移動・攻撃もしない。
      if (isChapter102TutorialStage() && enemy.ch102TutorialLocked) {
        positionUnit(enemy.el, enemy.x, enemy.y);
        positionMiniEnemyHp(enemy);
        return;
      }

      // build1527: 全体停止ULTをボス戦の増援まで適用する。
      // 通常戦のスタンだけでなく、ボス戦の全体停止・アンジェULTにも同じ規則を適用。
      // エルテナの吸引は別の分岐で位置を更新するため、ここで別途凍結しない。
      const globalStunUntil = Math.max(
        Number(state.normalEnemyStunUntil || 0),
        Number(state.fullEnemyStopUntil || 0),
        Number(state.angeEnemyFreezeUntil || 0)
      );
      if (now < globalStunUntil) {
        freezeNormalEnemyAction(enemy, globalStunUntil);
        positionUnit(enemy.el, enemy.x, enemy.y);
        positionMiniEnemyHp(enemy);
        return;
      }

      // ノアULT後：落雷を受けた敵だけスタン。
      if (now < Number(enemy.noahStunUntil || 0)) {
        freezeNormalEnemyAction(enemy, Number(enemy.noahStunUntil || now));
        positionUnit(enemy.el, enemy.x, enemy.y);
        positionMiniEnemyHp(enemy);
        return;
      }

      // マグダレーナULTで捕捉された敵は、拘束時間中は自発的な移動・攻撃を完全停止。
      // lastShotAt / nextActionAt を拘束終了後へ送ることで、解除直後に
      // 停止中の射撃予約がまとめて吐き出されることも防ぐ。
      if (now < Number(enemy.gojoPurpleFreezeUntil || 0)) {
        const resumeAt = Number(enemy.gojoPurpleFreezeUntil || now);
        freezeNormalEnemyAction(enemy, resumeAt);
        positionUnit(enemy.el, enemy.x, enemy.y);
        positionMiniEnemyHp(enemy);
        return;
      }

      // エルテナULT吸引中は通常の移動AIを止める。
      // 旧実装ではこの後の通常AIが毎フレーム baseX/baseY から位置を再計算し、
      // ブラックホール側の吸引移動を実質リセットしていたため、
      // 「移動ロックは掛かるが吸い込まれない敵」が発生していた。
      const activePullField = isEnemyPullFieldActive(now);

      if (activePullField) {
        // 攻撃も止め、吸引中は位置更新をブラックホール処理だけに一元化する。
        const pullResumeAt = Number(state.eltenaBlackHole?.activeUntil || now);
        freezeNormalEnemyAction(enemy, pullResumeAt);
        if (enemy.attackState === 'dash') {
          enemy.attackState = 'idle';
          enemy.el.classList.remove('violence-dash', 'generic-charge-dash');
        }
        enemy.el.classList.remove('generic-charge-warning');
        return;
      }

      // アヤネULTで掴まれている敵だけを個別拘束する。
      // global stunではなく、命中した敵だけ7秒間停止。
      if (now < Number(enemy.ayaneGrabUntil || 0)) {
        freezeNormalEnemyAction(enemy, Number(enemy.ayaneGrabUntil || now));
        positionUnit(enemy.el, enemy.x, enemy.y);
        positionMiniEnemyHp(enemy);
        return;
      }

      // 13Fの三頭狼は上部を往復して5WAY射撃。蜘蛛の群れAIには入れない。
      if (enemy.swarmRole === 'guard' && getSwarmBattleConfig()?.guardAi === 'tower13_upper_spread5') {
        updateTower13GuardEnemy(enemy, now, w, h);
        smoothEnemyMotionResume(enemy, now);
        positionUnit(enemy.el, enemy.x, enemy.y);
        positionMiniEnemyHp(enemy);
        return;
      }

      // CH07-3と13Fの蜘蛛だけが、一番近い味方オブジェクトへ這い寄る。
      if (enemy.swarmRole === 'large' || enemy.swarmRole === 'small') {
        let swarmDt = dt;
        if (enemy.ch704Horde) {
          // 30 fps for little spiders, without slowing them down at 60/120 Hz.
          const last = Number(enemy.ch704LastAiAt || 0);
          if (last > 0 && now - last < 33) return;
          swarmDt = last > 0 ? Math.min(.09, Math.max(0, (now - last) / 1000)) : dt;
          enemy.ch704LastAiAt = now;
        }
        if (!swarmTargets) swarmTargets = getSwarmLureTargets(now);
        updateSwarmEnemy(enemy, swarmDt, now, w, h, swarmTargets);
        smoothEnemyMotionResume(enemy, now);
        positionUnit(enemy.el, enemy.x, enemy.y);
        // CH07-04 tiny spiders have no HP bar/element overlay.
        if (!enemy.ch704Horde) positionMiniEnemyHp(enemy);
        return;
      }

      if (def.behavior === 'generic_element_charge_v1' && enemy.attackState === 'dash') {
        enemy.x += enemy.dashVx * dt;
        enemy.y += enemy.dashVy * dt;

        // Do not clamp during the dash itself: let the unit visibly commit to the line.
        // End the charge either by timer or once it reaches the arena margins.
        const outOfBounds =
          enemy.x < 28 || enemy.x > w - 28 ||
          enemy.y < 42 || enemy.y > h - 42;

        enemy.x = clamp(enemy.x, 28, w - 28);
        enemy.y = clamp(enemy.y, 42, h - 42);
        positionUnit(enemy.el, enemy.x, enemy.y);
        positionMiniEnemyHp(enemy);

        if (now >= enemy.dashUntil || outOfBounds) {
          enemy.attackState = 'idle';
          enemy.dashVx = 0;
          enemy.dashVy = 0;
          // CH02-04のみ、予告時間を含めて突進開始から次の突進開始まで6秒。
          const repeatMs = Number(def.chargeIntervalMs || 0);
          enemy.nextActionAt = repeatMs > 0
            ? Math.max(now, Number(enemy.lastDashStartedAt || now) + repeatMs - Math.max(350, Number(def.telegraphMs || 760)))
            : now + Math.max(700, Number(def.fireRate || 1650));
          enemy.baseX = enemy.x;
          enemy.baseY = clamp(enemy.y, 78, Math.max(90, h * .40));
          enemy.el.classList.remove('generic-charge-dash');
        }
        return;
      }

      if (def.behavior === 'mini_violence_v1' && enemy.attackState === 'dash') {
        enemy.x += enemy.dashVx * dt;
        enemy.y += enemy.dashVy * dt;
        enemy.x = clamp(enemy.x, 34, w - 34);
        enemy.y = clamp(enemy.y, 46, h - 48);
        positionUnit(enemy.el, enemy.x, enemy.y);
        positionMiniEnemyHp(enemy);

        if (now >= enemy.dashUntil) {
          enemy.attackState = 'idle';
          enemy.actionIndex = (enemy.actionIndex + 1) % 3;
          enemy.nextActionAt = now + 1150;
          enemy.baseX = enemy.x;
          enemy.baseY = clamp(enemy.y, 78, Math.max(90, h * .40));
          enemy.el.classList.remove('violence-dash');
        }
        return;
      }

      const age = getEnemyMotionAgeSeconds(enemy, now);
      if (def.behavior === 'faceless_minion_v1' && !enemy.facelessMaskSpawned) {
        const cfg = getChapter07Config() || {};
        const delay = Math.max(250, Number(cfg.maskSpawnDelayMs || 700));
        if (now - Number(enemy.spawnedAt || now) >= delay) {
          enemy.facelessMaskSpawned = true;
          const maskX = clamp(Number(enemy.x || w * .5) + (enemy.uid.charCodeAt(enemy.uid.length - 1) % 2 ? -42 : 42), 62, w - 62);
          const maskY = clamp(Number(enemy.y || h * .20) + 82, 120, h * .48);
          spawnFacelessObject(maskX, maskY, Number(cfg.maskWays || 2));
        }
      }

      if (def.behavior === 'faceless_minion_v1') {
        enemy.x = clamp(
          enemy.baseX + Math.sin(age * .72 + enemy.phaseSeed) * Math.min(48, w * .11),
          38,
          w - 38
        );
        enemy.y = Math.max(84, Math.min(h * .30, enemy.baseY)) +
          Math.sin(age * .56 + enemy.phaseSeed) * 8;
      } else if (def.behavior === 'remnant07_clone_v1') {
        enemy.x = clamp(
          enemy.baseX + Math.sin(age * 1.04 + enemy.phaseSeed) * Math.min(76, w * .17),
          44,
          w - 44
        );
        enemy.y = Math.max(78, Math.min(h * .28, enemy.baseY)) +
          Math.sin(age * .88 + enemy.phaseSeed * 1.2) * 14;
      } else if (def.behavior === 'generic_element_laser_v1') {
        enemy.x = clamp(
          enemy.baseX + Math.sin(age * .42 + enemy.phaseSeed) * Math.min(34, w * .08),
          36,
          w - 36
        );
        enemy.y = Math.max(78, Math.min(h * .29, enemy.baseY)) +
          Math.sin(age * .34 + enemy.phaseSeed) * 6;
      } else if (def.behavior === 'generic_element_shot_v1') {
        enemy.x = clamp(
          enemy.baseX + Math.sin(age * .92 + enemy.phaseSeed) * Math.min(54, w * .13),
          36,
          w - 36
        );
        enemy.y = Math.max(80, Math.min(h * .32, enemy.baseY)) +
          Math.sin(age * .66 + enemy.phaseSeed * 1.3) * 10;
      } else if (def.behavior === 'generic_element_charge_v1') {
        // CHARGE type stays comparatively still so the warning and dash direction are readable.
        enemy.x = clamp(
          enemy.baseX + Math.sin(age * .48 + enemy.phaseSeed) * Math.min(26, w * .06),
          36,
          w - 36
        );
        enemy.y = Math.max(82, Math.min(h * .30, enemy.baseY)) +
          Math.sin(age * .38 + enemy.phaseSeed * 1.15) * 6;
      } else if (def.behavior === 'mini_violence_v1') {
        // 強敵は細かく漂わず、重くゆっくりと位置を変える。
        const targetBaseY = Math.max(84, Math.min(h * .34, enemy.baseY));
        enemy.x = clamp(enemy.baseX + Math.sin(age * .62 + enemy.phaseSeed) * Math.min(38, w * .09), 36, w - 36);
        enemy.y = targetBaseY + Math.sin(age * .48 + enemy.phaseSeed) * 10;
      } else if (def.behavior === 'mini_barrage_v1') {
        // 弾幕担当の雑魚。上空で横移動しながら、交差する角度を作る。
        enemy.x = clamp(enemy.baseX + Math.sin(age * 1.08 + enemy.phaseSeed) * Math.min(72, w * .18), 36, w - 36);
        enemy.y = Math.max(76, Math.min(h * .34, enemy.baseY)) + Math.sin(age * .76 + enemy.phaseSeed * 1.7) * 14;
      } else if (def.behavior === 'verdant_sprout_v1') {
        // build1659: 芽吹きは画面の上半分を大きく歩き回る。成長して「大樹」になると、その場に根を張って動かない。
        if (enemy.verdantGrown) {
          enemy.x = enemy.baseX;
          enemy.y = enemy.baseY;
        } else {
          enemy.x = clamp(enemy.baseX + Math.sin(age * .9 + enemy.phaseSeed) * Math.min(130, w * .33), 36, w - 36);
          enemy.y = clamp(Math.max(90, Math.min(h * .30, enemy.baseY)) + Math.sin(age * .62 + enemy.phaseSeed * 1.7) * h * .11, 76, h * .46);
        }
      } else if (def.behavior === 'po_watcher_v1') {
        // build1643: 監視の眼。上空〜中段をゆっくり漂い、視界（扇形）を首振りさせる。
        enemy.x = clamp(enemy.baseX + Math.sin(age * .35 + enemy.phaseSeed) * Math.min(92, w * .22), 40, w - 40);
        enemy.y = clamp(Math.max(96, Math.min(h * .30, enemy.baseY)) + Math.sin(age * .27 + enemy.phaseSeed * 1.3) * h * .06, 84, h * .40);
        avoidBossOverlap(enemy, w, h, now); // build1990: BOSSの裏に入り込まない
      } else if (def.behavior === 'mini_beautiful_v1') {
        // CH04は発射源まで忙しくしない。ゆったり左右へ漂い、幾何学模様を崩さない。
        enemy.x = clamp(enemy.baseX + Math.sin(age * .58 + enemy.phaseSeed) * Math.min(54, w * .13), 36, w - 36);
        enemy.y = Math.max(78, Math.min(h * .30, enemy.baseY)) + Math.sin(age * .44 + enemy.phaseSeed * 1.35) * 8;
      } else {
        enemy.x = clamp(enemy.baseX + Math.sin(age * 1.25 + enemy.phaseSeed) * Math.min(58, w * .14), 36, w - 36);
        enemy.y = enemy.baseY + Math.sin(age * .9 + enemy.phaseSeed) * 8;
      }

      smoothEnemyMotionResume(enemy, now);
      positionUnit(enemy.el, enemy.x, enemy.y);
      positionMiniEnemyHp(enemy);
      fireNormalEnemy(enemy, now);
    });
  }

  // build1990: 雑魚がBOSSの絵に重ならないよう、BOSSの範囲（楕円）から押し出す。ずれはなめらかに追従させる。
  //  大きさだけ要素から測って覚え（0.6秒ごと）、中心は毎フレームの BOSS 座標を使う（動くBOSSに遅れない）
  let bossAvoidSize = null, bossAvoidSizeAt = 0;
  function getBossAvoidSize(now) {
    if (bossAvoidSize && now - bossAvoidSizeAt < 600) return bossAvoidSize;
    bossAvoidSizeAt = now;
    const el = document.querySelector('#' + ROOT_ID + ' .shooting-boss');
    const r = el && el.getBoundingClientRect();
    bossAvoidSize = (r && r.width > 4 && r.height > 4) ? { rx: r.width * .42, ry: r.height * .42 } : null;
    return bossAvoidSize;
  }
  function avoidBossOverlap(enemy, w, h, now) {
    let tx = 0, ty = 0;
    const size = (state && state.boss && state.boss.hp > 0) ? getBossAvoidSize(now) : null;
    if (size) {
      const margin = 34; // 雑魚自身の大きさぶん
      const rx = size.rx + margin, ry = size.ry + margin;
      const cx = Number(state.boss.x || 0), cy = Number(state.boss.y || 0);
      const inside = (x, y) => Math.hypot((x - cx) / rx, (y - cy) / ry) < 1;
      if (inside(enemy.x, enemy.y)) {
        const minX = 30, maxX = w - 30, minY = 60, maxY = h * .5;
        // 出口の候補：左・右・下・上。画面に収まるもののうち、いちばん近いものへ
        const dy = enemy.y - cy;
        const halfW = rx * Math.sqrt(Math.max(0, 1 - (dy / ry) ** 2));
        const dx = enemy.x - cx;
        const halfH = ry * Math.sqrt(Math.max(0, 1 - (dx / rx) ** 2));
        const cands = [
          { x: cx - halfW - 2, y: enemy.y },
          { x: cx + halfW + 2, y: enemy.y },
          { x: enemy.x, y: cy + halfH + 2 },
          { x: enemy.x, y: cy - halfH - 2 },
        ].filter(p => p.x >= minX && p.x <= maxX && p.y >= minY && p.y <= maxY);
        if (cands.length) {
          let best = cands[0], bd = Infinity;
          for (const p of cands) { const d = Math.hypot(p.x - enemy.x, p.y - enemy.y); if (d < bd) { bd = d; best = p; } }
          tx = best.x - enemy.x; ty = best.y - enemy.y;
        }
      }
    }
    const k = .2;
    enemy.bossAvoidX = (enemy.bossAvoidX || 0) + (tx - (enemy.bossAvoidX || 0)) * k;
    enemy.bossAvoidY = (enemy.bossAvoidY || 0) + (ty - (enemy.bossAvoidY || 0)) * k;
    enemy.x = clamp(enemy.x + enemy.bossAvoidX, 30, w - 30);
    enemy.y = clamp(enemy.y + enemy.bossAvoidY, 60, h * .5);
  }

  function shouldDropMissionItem(defeatedNo) {
    if (!selectedStage) return false;
    const mission = getEffectiveNormalMission();
    if (mission.type !== SHOOTING_MISSION_TYPE.COLLECT_ITEM) return false;

    const target = Number(mission.target || 3);
    if (state.collectedItems + state.collectibles.length >= target) return false;

    const cfg = getNormalBattleConfig();
    const configuredDropRate = Number(cfg.itemDropRate);

    // CH03: 確率設定は維持するが、抽選列はステージごとに固定。
    // 同じ撃破番号なら再挑戦時も必ず同じ結果になる。
    if (Number.isFinite(configuredDropRate)) {
      return fixedStagePatternRandom('mission_item_drop', defeatedNo, 0) < clamp(configuredDropRate, 0, 1);
    }

    // 既存CHAPTERの収集ステージは従来の保証ドロップ方式を維持。
    const total = Number(cfg.totalEnemies || 7);
    const milestones = Array.from({length: target}, (_, i) =>
      Math.max(1, Math.round(total * (i + 1) / (target + 1)))
    );
    return milestones.includes(defeatedNo) ||
      defeatedNo >= total - (target - state.collectedItems - state.collectibles.length);
  }

  function getMissionItemImagePath() {
    if (!selectedStage) return '';
    const mission = getEffectiveNormalMission();
    if (mission?.type !== SHOOTING_MISSION_TYPE.COLLECT_ITEM) return '';

    // build1141: ステージごとの収集アイテム画像を優先。
    // CH01-03はレムナントの残骸(item_memory_mini)を使用する。
    const configuredImage = String(
      mission?.itemImage || selectedStage?.normalBattle?.itemImage || ''
    ).trim();
    if (configuredImage) return configuredImage;

    const chapter = Number(selectedStage.chapter || 0);
    if (chapter === 1 || chapter === 3) {
      return 'images/item_life_energy.webp';
    }
    return '';
  }

  function spawnMissionItem(x, y) {
    const layer = document.getElementById('shooting-collectible-layer');
    if (!layer) return;
    const el = document.createElement('div');
    el.className = 'shooting-mission-item';
    const itemImagePath = getMissionItemImagePath();
    if (itemImagePath) {
      el.innerHTML = `<img class="shooting-mission-item-image" src="${itemImagePath}" alt="">`;
      el.classList.add('life-energy');
    } else {
      el.innerHTML = '<i></i>';
    }
    layer.appendChild(el);
    const item = { uid:`item_${Date.now()}_${Math.random().toString(36).slice(2,6)}`, el, x, y:Math.max(y + 18, 150) };
    state.collectibles.push(item);
    positionUnit(el, item.x, item.y);
  }

  function updateCollectibles(dt) {
    if (!isNormalBattle() || !state.collectibles.length) return;
    const playerCore = document.getElementById('shooting-player-core');
    const arena = document.getElementById('shooting-arena');
    if (!playerCore || !arena) return;

    const coreRect = playerCore.getBoundingClientRect();
    const arenaHeight = Number(arena.clientHeight || 0);

    state.collectibles = state.collectibles.filter(item => {
      if (!item || !item.el) return false;

      item.y += 16 * dt;
      positionUnit(item.el, item.x, item.y);

      if (rectsHit(item.el.getBoundingClientRect(), coreRect, -5, -3)) {
        item.el.remove();
        state.collectedItems++;
        state.score += 500;
        evaluateNormalMission(performance.now());
        return false;
      }

      // 取り逃したアイテムは画面外へ出た時点で破棄する。
      // state.collectiblesにも残さないことで、次の敵から再ドロップ可能にする。
      if (arenaHeight > 0 && item.y > arenaHeight + 40) {
        item.el.remove();
        return false;
      }

      return true;
    });
  }

  function damageNormalEnemy(enemy, amount, now, big, elementReaction = '', suppressVisual = false) {
    if (!enemy || enemy.hp <= 0) return 0;
    // build2060: ディノヴァULTの放電コア（味方の設置物）は撃破数・スコアに数えない
    if (enemy.deinovaUltCore) return damageDeinovaUltCore(enemy, amount, Number(now || performance.now()), big, elementReaction, suppressVisual);
    // build1761: HIT数で倒す敵（記憶決戦の守護者）。威力に関係なく、通った攻撃1回＝1ダメージ。
    // 属性結界などで0になった攻撃は数えない。連射の速いショットや多段ULTが有利。
    if (enemy.memoryHitHp && Number(amount) > 0) amount = 1;
    const appliedDamage = Math.min(enemy.hp, Math.max(0, Number(amount || 0)));
    if (appliedDamage > 0 && Number(now||performance.now()) < Number(enemy.camillaWebRootUntil||0)) absorbCamillaWebDamage(appliedDamage, now);
    enemy.hp = Math.max(0, enemy.hp - appliedDamage);

    if (isChapter403FireWallStage() && state && !state.ch403BarrierBroken && !state.ch403EncounterTriggered && elementReaction === 'immune') {
      if (!state.ch403PhaseStartedAt) state.ch403PhaseStartedAt = performance.now();
      state.ch403ImmuneHits = Math.max(0, Number(state.ch403ImmuneHits || 0)) + 1;
      const elapsed = Math.max(0, performance.now() - state.ch403PhaseStartedAt);
      if (state.ch403ImmuneHits >= 25 && elapsed >= 8000) requestAnimationFrame(() => triggerChapter403EncounterSequence());
    }

    // 試遊は高頻度連鎖HIT時、HPバーの幅は毎回更新しつつ強制リフローのflashだけ抑制。
    const trialImpactNow = Number(now || performance.now());
    const trialSmallHit = isGachaTrialStage() && !big;
    const trialFlash = !trialSmallHit || trialImpactNow >= Number(enemy._trialHpFlashNextAt || 0);
    if (appliedDamage > 0) {
      if (!enemy.ch704Horde) renderMiniEnemyHp(enemy, trialFlash);
      if (trialSmallHit && trialFlash) enemy._trialHpFlashNextAt = trialImpactNow + 120;
    }

    // build551: IMMUNE相手へSpread/Laser等を当て続けても、ゲーム判定は全件維持しつつ
    // HIT/0/IMMUNE/バリア発光のDOM演出だけ約9fpsへ間引く。
    const visualNow = Number(now || performance.now());
    const immuneVisual = elementReaction === 'immune';
    // ニーナ連鎖などの高頻度HITでも実ダメージは全件反映。
    // DOM生成を伴うHIT/数字/点滅のみ、試遊中の小HITを敵ごと約8fpsに抑える。
    const hordeImpactReady = !enemy.ch704Horde || visualNow >= Number(enemy._hordeVisualNextAt || 0);
    const renderImpact = !suppressVisual && hordeImpactReady &&
      (!immuneVisual || visualNow >= Number(enemy._immuneVisualNextAt || 0)) &&
      (!trialSmallHit || visualNow >= Number(enemy._trialVisualNextAt || 0));
    if (renderImpact) {
      if (enemy.ch704Horde) enemy._hordeVisualNextAt = visualNow + 140;
      if (immuneVisual) enemy._immuneVisualNextAt = visualNow + 110;
      if (trialSmallHit) enemy._trialVisualNextAt = visualNow + 125;

      createHit(enemy.x, enemy.y, !!big);
      showDamageNumber(enemy.x, enemy.y, appliedDamage, 'enemy', !!big, elementReaction);

      if (immuneVisual && enemy.weaknessBarrierEl) {
        const shield = enemy.weaknessBarrierEl;
        shield.classList.add('hit');
        if (enemy._weaknessBarrierFxTimer) clearTimeout(enemy._weaknessBarrierFxTimer);
        enemy._weaknessBarrierFxTimer = setTimeout(() => {
          if (shield && shield.isConnected) shield.classList.remove('hit');
          enemy._weaknessBarrierFxTimer = null;
        }, 140);
      }

      if (enemy.el) sustainHitFeedback(enemy.el, big ? 210 : 145);
    }
    if (enemy.partyTarget && appliedDamage > 0 && enemy.hp > 0) onPartyGuestHit(enemy); // build2150
    if (enemy.hp > 0) return appliedDamage;

    // build2003: 記憶オーバーシアの監視者は倒した瞬間から5秒間、再召喚を禁止。
    // 同時撃破の場合も最後に倒した時刻から5秒を確保する。
    if (selectedStage?.memoryBattle?.no === 5 && enemy.def?.behavior === 'po_watcher_v1') {
      state.overseerWatcherReviveAt = Math.max(Number(state.overseerWatcherReviveAt || 0), Number(now || performance.now()) + 5000);
    }

    // アヤネ拘束中に撃破された場合、残っている拘束演出を即掃除。
    enemy.ayaneGrabUntil = 0;
    if (enemy.ayaneGrabMarker) {
      enemy.ayaneGrabMarker.remove();
      enemy.ayaneGrabMarker = null;
    }
    if (enemy.el) enemy.el.classList.remove('ayane-grabbed', 'ayane-multi-grabbed');

    if (isCh404SummonerBattle() && enemy.ch404Role === 'summoner') {
      state.ch404Phase = Math.min(3, Number(state.ch404Phase || 0) + 1);
      // Summoned normal enemies are deliberately not removed.
    }
    if (enemy.swarmRole === 'large') {
      state.swarmLargeDefeated = Math.max(0, Number(state.swarmLargeDefeated || 0)) + 1;
    } else if (enemy.swarmRole === 'guard') {
      state.swarmGuardDefeated = Math.max(0, Number(state.swarmGuardDefeated || 0)) + 1;
    }
    state.normalDefeated++;
    if (enemy.partyTarget) onPartyGuestDefeated(enemy, Number(now || performance.now())); // build2150: 夜会の加点・減点（スコアは終了時に合算）
    else state.score += Number(enemy.def?.scoreValue || 650);
    spawnPhaseOdysseyBurst(enemy); // build1679: 位相回遊の異常「連鎖」
    handleChapter101TutorialEnemyDefeat();
    if (shouldDropMissionItem(state.normalDefeated)) spawnMissionItem(enemy.x, enemy.y);
    if (enemy.el) {
      const old = enemy.el;
      const isViolenceEnemy = enemy.def && enemy.def.behavior === 'mini_violence_v1';

      // CHAPTER 02の強敵は、倒したことが分かるように撃破演出を強化。
      old.classList.remove(
        'hit-flash',
        'violence-warning',
        'violence-dash',
        'generic-charge-warning',
        'generic-charge-dash'
      );
      old.classList.add('defeated');
      if (isViolenceEnemy) old.classList.add('violence-defeated');

      setTimeout(() => old.remove(), isViolenceEnemy ? 620 : 260);
    }
    if (enemy.hpEl) {
      const oldHp = enemy.hpEl;
      oldHp.classList.add('defeated');
      setTimeout(() => oldHp.remove(), 220);
    }
    if (enemy.elementEl) {
      const oldElement = enemy.elementEl;
      oldElement.classList.add('defeated');
      setTimeout(() => oldElement.remove(), 220);
    }
    if (enemy.weaknessBarrierEl) {
      const oldBarrier = enemy.weaknessBarrierEl;
      oldBarrier.classList.add('defeated');
      setTimeout(() => oldBarrier.remove(), 240);
    }
    removeIgnisBurnVisual(String(enemy.uid || 'enemy'));
    enemy.el = null;
    enemy.hpEl = null;
    enemy.elementEl = null;
    enemy.weaknessBarrierEl = null;
    evaluateNormalMission(now);
    return appliedDamage;
  }

  function evaluateNormalMission(now) {
    if (isGachaTrialStage()) return;
    if (!isNormalBattle() || state.ended || state.finishing) return;
    const mission = getEffectiveNormalMission();
    const cfg = getNormalBattleConfig();
    const total = Number(cfg.totalEnemies || 0);
    const allDefeated = isCh404SummonerBattle()
      ? Number(state.ch404Phase || 0) >= 3 && !(state.normalEnemies || []).some(e => e && e.hp > 0)
      : isSwarmBattle()
      ? (getSwarmObjectiveDefeated() >= getSwarmObjectiveTotal() &&
         !state.normalEnemies.some(e=>e&&e.hp>0&&(e.swarmRole==='large'||e.swarmRole==='guard')))
      : total > 0 && state.normalDefeated >= total && state.normalSpawned >= total;

    if (isChapter101TutorialStage() && allDefeated && !state.ch101TutorialUltTriggered) {
      state.missionComplete = false;
      return;
    }

    if (mission.type === SHOOTING_MISSION_TYPE.CLEAR_TIME) {
      if ((now - state.startedAt) / 1000 > Number(mission.targetSeconds || 60)) {
        state.missionFailed = true;
        endGame(false);
        return;
      }
      state.missionComplete = allDefeated;
    } else if (mission.type === SHOOTING_MISSION_TYPE.SURVIVE_TIME) {
      state.missionComplete = false;
      return;
    } else if (mission.type === SHOOTING_MISSION_TYPE.MAX_HITS_TAKEN) {
      if (state.totalHitsTaken > Number(mission.maxHits || 3)) {
        state.missionFailed = true;
        endGame(false);
        return;
      }
      state.missionComplete = allDefeated;
    } else if (mission.type === SHOOTING_MISSION_TYPE.COLLECT_ITEM) {
      // 敵全滅ではクリアしない。指定数を実際に取得した時だけ成立。
      state.missionComplete = isCollectMissionSatisfied(mission);
      if (!state.missionComplete) return;
    } else {
      state.missionComplete = allDefeated;
    }
    if (state.missionComplete) {
      if (!state.poClearAt) state.poClearAt = now; // build1679: 位相回遊「速攻」の判定用
      if (isChapter102TutorialStage()) {
        state.ch102TutorialPhase = 'complete';
        clearChapter102TutorialHint();
      }
      beginNormalStageClear();
    }
  }

  function showStageClearSequence(onComplete) {
    const root = document.getElementById(ROOT_ID);
    if (!root) {
      if (typeof onComplete === 'function') onComplete();
      return;
    }

    root.querySelectorAll('.shooting-clear-condition-achieved').forEach(el => el.remove());

    const overlay = document.createElement('div');
    overlay.className = 'shooting-clear-condition-achieved';
    overlay.setAttribute('aria-live', 'assertive');
    overlay.innerHTML = `
      <div class="shooting-clear-condition-achieved-line"></div>
      <div class="shooting-clear-condition-achieved-copy">
        <strong></strong>
      </div>
      <div class="shooting-clear-condition-achieved-line"></div>
    `;

    root.appendChild(overlay);

    const copy = overlay.querySelector('strong');
    const steps = isRpgEncounterStage()
      ? [{ text: 'WIN', phase: 'stage-clear-phase', hold: 820 }] // build2041: エンカウント戦は短く
      : [
      { text: 'クリア条件達成', phase: 'condition-phase', hold: 1320 },
      { text: 'STAGE CLEAR', phase: 'stage-clear-phase', hold: 1480 }
    ];
    let index = 0;

    const finish = () => {
      overlay.classList.add('sequence-out');
      setTimeout(() => {
        overlay.remove();
        if (typeof onComplete === 'function') onComplete();
      }, 620);
    };

    const showStep = () => {
      if (!overlay.isConnected || !copy) return finish();
      const step = steps[index];

      overlay.classList.remove('condition-phase', 'stage-clear-phase', 'step-out');
      overlay.classList.add(step.phase, 'show');
      copy.textContent = step.text;
      copy.classList.remove('ceremony-pop');
      void copy.offsetWidth;
      copy.classList.add('ceremony-pop');

      setTimeout(() => {
        if (!overlay.isConnected) return;
        overlay.classList.add('step-out');

        setTimeout(() => {
          index += 1;
          if (index < steps.length) showStep();
          else finish();
        }, 360);
      }, step.hold);
    };

    requestAnimationFrame(showStep);
  }

  function beginNormalStageClear() {
    if (!state || state.ended || state.finishing) return;

    // 最終防波堤: 収集ミッションは取得数不足ならCLEAR演出へ入れない。
    const mission = getEffectiveNormalMission();
    if (mission.type === SHOOTING_MISSION_TYPE.COLLECT_ITEM && !isCollectMissionSatisfied(mission)) {
      state.missionComplete = false;
      console.warn('[shooting] blocked premature collect-mission clear', {
        stageId: getSelectedBaseStageId(),
        collected: Number(state.collectedItems || 0),
        target: Number(mission.target || 3),
      });
      return;
    }

    state.finishing = true;
    state.running = false;
    cancelAnimationFrame(rafId);
    clearEnemyBulletsOnly();
    renderHud();
    document.getElementById(ROOT_ID)?.classList.add('normal-stage-clear');

    // 全通常ステージ共通：クリア条件達成 → STAGE CLEAR → RESULT。
    showStageClearSequence(() => {
      if (!state || state.ended) return;
      const root = document.getElementById(ROOT_ID);
      if (root) root.classList.remove('normal-stage-clear');
      state.finishing = false;
      endGame(true);
    });
  }

  function clearNormalBattleObjects() {
    clearChapter101TutorialOverlay();
    if (!state) return;
    // build1726: イノリの鳥居HPバー／属性アイコンは盤面直下にあるため、レイヤーの消去では消えない。個別に外す
    (state.normalEnemies || []).forEach(enemy => { enemy?.el?.remove(); if (enemy && enemy.inoriSide) { enemy.hpEl?.remove(); enemy.elementEl?.remove(); } });
    (state.collectibles || []).forEach(item => item?.el?.remove());
    (state.mimosaItems || []).forEach(item => item?.el?.remove());
    state.normalEnemies = [];
    clearChapter6Barriers();
    state.collectibles = [];
    state.mimosaItems = [];
    const layer = document.getElementById('shooting-normal-enemy-layer');
    if (layer) layer.innerHTML = '';
    const items = document.getElementById('shooting-collectible-layer');
    if (items) items.innerHTML = '';
  }

  function fireViolenceBoss(now) {
    const phase = state.boss.phase || 1;
    const interval = phase === 1 ? 1050 : phase === 2 ? 820 : 650;
    if (now - state.lastBossShotAt < getStageAdjustedEnemyFireInterval(interval)) return;
    state.lastBossShotAt = now;

    const dx = getEnemyAimPosition().x - state.boss.x;
    const dy = getEnemyAimPosition().y - state.boss.y;
    const baseAngle = Math.atan2(dy, dx);
    const speed = Number(BOSS.bulletSpeed || 285);

    // 暴力は弾数ではなく、一発の圧で押す。
    if (phase === 1) {
      appendEnemyProjectile(makeProjectile(
        'shooting-enemy-bullet shooting-violence-boss-heavy',
        state.boss.x, state.boss.y + 42,
        Math.cos(baseAngle) * speed,
        Math.sin(baseAngle) * speed,
        Number(BOSS.bulletDamage || 230)
      ));
      return;
    }

    if (phase === 2) {
      [-0.22, 0.22].forEach(offset => {
        const a = baseAngle + offset;
        appendEnemyProjectile(makeProjectile(
          'shooting-enemy-bullet shooting-violence-boss-heavy',
          state.boss.x, state.boss.y + 40,
          Math.cos(a) * speed * 1.04,
          Math.sin(a) * speed * 1.04,
          Number(BOSS.bulletDamage || 230)
        ));
      });
      return;
    }

    // 最終段階だけ3方向。弾幕化はさせず、逃げ道を削る。
    [-0.30, 0, 0.30].forEach(offset => {
      const a = baseAngle + offset;
      appendEnemyProjectile(makeProjectile(
        'shooting-enemy-bullet shooting-violence-boss-heavy',
        state.boss.x, state.boss.y + 38,
        Math.cos(a) * speed * 1.35,
        Math.sin(a) * speed * 1.35,
        Number(BOSS.bulletDamage || 230)
      ));
    });
  }

  // ============================================================
  // 超弾幕（STRESS TEST）専用の発射ロジック。
  // barrage_v1(REMNANT_03/レイド共用)には手を入れず、完全に独立させる。
  // 狙いはパターンの見栄えではなく「弾の絶対数」で負荷を測ること。
