  function ensurePartyDom() {
    const root = document.getElementById(ROOT_ID);
    const arena = document.getElementById('shooting-arena');
    if (!root || !arena) return null;
    let veil = arena.querySelector('.party-bonus-veil');
    if (!veil) {
      veil = document.createElement('div'); veil.className = 'party-bonus-veil'; veil.setAttribute('aria-hidden', 'true');
      arena.appendChild(veil);
    }
    let bar = root.querySelector('.party-bonus-bar');
    if (!bar) {
      bar = document.createElement('div'); bar.className = 'party-bonus-bar'; bar.setAttribute('aria-hidden', 'true');
      // build2172: 残りボーナスタイムを「CHEERS 3.2」＋減っていくバーで見せる
      bar.innerHTML = '<span class="pb-label">CHEERS</span><b class="pb-sec">0.0</b><span class="pb-track"><i></i></span>';
      root.appendChild(bar);
    }
    return { root, arena, bar };
  }
  function showPartyPop(x, y, value, big) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const el = document.createElement('div');
    el.className = 'party-pop ' + (value >= 0 ? 'plus' : 'minus') + (big ? ' big' : '');
    el.textContent = (value >= 0 ? '+' : '−') + Math.abs(Math.round(value)).toLocaleString('ja-JP');
    el.style.left = x + 'px'; el.style.top = y + 'px';
    arena.appendChild(el);
    setTimeout(() => el.remove(), 950);
  }
  // 出現：上（下へ歩く）・左右（横切る）・背後（下から上へ）。人間と料理を交互に近い割合で混ぜる
  function spawnPartyGuest(now, w, h, forceTower) {
    const pe = state.partyEv, cfg = getPartyConfig();
    const ids = window.ShootingEnemies?.SHOOTING_ENEMY_ID || {};
    const n = pe.spawnCount++;
    const r = fixedStagePatternRandom('party_spawn', n, 0);
    const r2 = fixedStagePatternRandom('party_spawn_kind', n, 0);
    let defId;
    if (forceTower) defId = ids.PARTY_TOWER;
    else if (r2 < Number(cfg.humanShare || .5)) defId = [ids.PARTY_WAITER, ids.PARTY_GUEST_A, ids.PARTY_GUEST_B][n % 3];
    else defId = ids.PARTY_DISH;
    const def = getShootingEnemy(defId);
    if (!def) return null;
    const rear = !forceTower && r < Number(cfg.rearShare || .2);
    const side = !forceTower && !rear && r < Number(cfg.rearShare || .2) + Number(cfg.sideShare || .3);
    const sp = (cfg.walkSpeed || [42, 64]);
    const speed = (sp[0] + (sp[1] - sp[0]) * fixedStagePatternRandom('party_speed', n, 0)) * (forceTower ? .55 : 1);
    let x, y, vx, vy, edge;
    if (rear) {
      edge = 'bottom';
      const p = pickFlankSpawnPoint({ spawnEdges: ['bottom'] }, n, w, h);
      x = p.x; y = h + 30; vx = (fixedStagePatternRandom('party_drift', n, 0) - .5) * 30; vy = -speed;
      // build2160: 予告マークは0.8秒で片付ける（群れの仕組みと違い自動では消えないため、下に溜まっていた）
      const warnEl = showFlankSpawnWarning({ edge: 'bottom', x: p.x, y: h - 26 }, 800);
      if (warnEl) setTimeout(() => { try { warnEl.remove(); } catch (_) {} }, 850);
    } else if (side) {
      edge = n % 2 ? 'left' : 'right';
      x = edge === 'left' ? -30 : w + 30;
      y = h * (.30 + fixedStagePatternRandom('party_side_y', n, 0) * .40);
      vx = edge === 'left' ? speed : -speed; vy = (fixedStagePatternRandom('party_drift', n, 0) - .5) * 16;
    } else {
      edge = 'top';
      x = w * (.12 + fixedStagePatternRandom('party_top_x', n, 0) * .76);
      y = 30; vx = (fixedStagePatternRandom('party_drift', n, 0) - .5) * 24; vy = speed;
    }
    const e = createNormalEnemy(def, now, { noElementIcon: Number(def.partyValue || 0) < 0 }); // 料理（光）は属性アイコンを出す
    if (!e) return null;
    const isHuman = Number(def.partyValue || 0) < 0;
    const hpMul = isHuman ? Math.max(1, Number(pe.opts.humanHpMul || 1)) : 1;
    e.hp = e.hpMax = Math.max(1, Math.round(Number(def.hp || 300) * hpMul));
    e.partyTarget = true; e.partyHuman = isHuman; e.uid = 'party_' + n;
    e.x = x; e.y = y; e.baseX = x; e.baseY = y;
    e.partyVx = vx; e.partyVy = vy; e.partySeed = r * Math.PI * 2; e.partyEdge = edge;
    e.partyBornAt = getPartyElapsedMs(now);
    e.partyLifeMs = forceTower ? Number(cfg.towerLifeMs || 9000) : Number(cfg.guestLifeMs || 7000);
    e.el.classList.add(isHuman ? 'party-human' : 'party-food');
    renderMiniEnemyHp(e, false);
    positionUnit(e.el, e.x, e.y);
    positionMiniEnemyHp(e);
    state.normalEnemies.push(e);
    attachPartyMark(e); // build2165
    return e;
  }
  // build2165: 人間＝足元の淡い青の保護リング（登場時だけ小さくPROTECT）、料理＝金の小さな照準。移動に追従
  function attachPartyMark(e) {
    if (!e || !e.el || !e.el.parentNode) return;
    const scale = Math.max(.5, parseFloat(e.el.style.getPropertyValue('--enemy-scale')) || 1);
    const human = !!e.partyHuman;
    const w = Math.round((human ? 50 : 38) * scale), h = Math.round((human ? 15 : 13) * scale);
    const m = document.createElement('div');
    m.className = 'party-mark ' + (human ? 'human' : 'food');
    m.setAttribute('aria-hidden', 'true');
    m.style.width = w + 'px'; m.style.height = h + 'px';
    if (human) {
      const t = document.createElement('span'); t.className = 'party-protect'; t.textContent = 'PROTECT';
      m.appendChild(t); setTimeout(() => { try { t.remove(); } catch (_) {} }, 1350);
    }
    e.el.parentNode.insertBefore(m, e.el);
    e.partyMarkEl = m; e.partyMarkW = w; e.partyMarkH = h;
    e.partyMarkDy = Math.round((human ? 27 : 20) * scale);
    positionPartyMark(e);
    requestAnimationFrame(() => m.classList.add('is-on'));
  }
  function positionPartyMark(e) {
    const m = e && e.partyMarkEl;
    if (!m) return;
    m.style.transform = `translate3d(${(e.x - e.partyMarkW / 2).toFixed(1)}px,${(e.y + e.partyMarkDy - e.partyMarkH / 2).toFixed(1)}px,0)`;
  }
  function removePartyMark(e, fade) {
    const m = e && e.partyMarkEl;
    if (!m) return;
    e.partyMarkEl = null;
    if (fade) { m.classList.add('is-leaving'); setTimeout(() => { try { m.remove(); } catch (_) {} }, 420); }
    else { try { m.remove(); } catch (_) {} }
  }
  function removePartyGuest(e) {
    removePartyMark(e, false);
    if (!e) return;
    [e.el, e.hpEl, e.elementEl, e.weaknessBarrierEl].forEach(n => { try { n && n.remove(); } catch (_) {} });
    e.hp = 0;
    state.normalEnemies = state.normalEnemies.filter(x => x !== e);
  }
  function updatePartyGuests(dt, now, w, h, halted) {
    const list = (state.normalEnemies || []).filter(e => e && e.partyTarget && e.hp > 0 && e.el);
    const sec = Math.max(0, Math.min(.05, Number(dt) || 0));
    for (const e of list) {
      if (!halted) {
        e.x += e.partyVx * sec;
        e.y += e.partyVy * sec;
        // 歩く揺れ（左右）
        const sway = Math.sin(getPartyElapsedMs(now) / 380 + e.partySeed) * 0.35;
        e.x += sway;
      }
      positionUnit(e.el, e.x, e.y);
      positionMiniEnemyHp(e);
      positionPartyMark(e); // build2165
      if (e.x < -70 || e.x > w + 70 || e.y < -70 || e.y > h + 70) { removePartyGuest(e); continue; }
      // build2154: 一定時間で立ち去る（ふっと消える）。消え始めたら当たり判定なし
      if (!halted && !e.partyLeaving && getPartyElapsedMs(now) - Number(e.partyBornAt || 0) > Number(e.partyLifeMs || 7000)) {
        e.partyLeaving = true;
        e.hp = 0; // 当たり判定から外す（DOMは消えるまで残す）
        e.el.classList.add('party-leave');
        removePartyMark(e, true); // build2165
        if (e.hpEl) e.hpEl.style.opacity = '0';
        if (e.elementEl) e.elementEl.style.opacity = '0';
        setTimeout(() => removePartyGuest(e), 480);
      }
    }
  }
  function startPartyBonus(now, ms) {
    const pe = state.partyEv;
    const el = getPartyElapsedMs(now);
    pe.bonusUntil = Math.max(Number(pe.bonusUntil || 0), el) + ms;
    pe.bonusTotalMs = Math.max(1, pe.bonusUntil - el);
  }
  function updatePartyGlass(now, w, h, halted) {
    const pe = state.partyEv, cfg = getPartyConfig();
    const el = getPartyElapsedMs(now);
    const times = (cfg.glassAtMs || []).slice();
    // build2179: OP04「祝杯のグラス+1」を廃止。出現回数は基本ステージ設定どおり。
    times.sort((a, b) => a - b);
    const arena = document.getElementById('shooting-arena');
    if (!pe.glass && pe.glassIdx < times.length && el >= times[pe.glassIdx] && !halted && arena) {
      pe.glassIdx++;
      // build2165: グラスは「触れて取る」アイテムと分かる見た目に（足元の金のマーカー・光の粒・出現直後だけTOUCH TO GET）
      const g = document.createElement('div');
      g.className = 'party-glass-wrap';
      g.setAttribute('aria-hidden', 'true');
      g.innerHTML = '<i class="pg-mark"></i><i class="pg-glass"></i><b class="pg-hint">TOUCH TO GET</b><i class="pg-dot"></i><i class="pg-dot"></i><i class="pg-dot"></i>';
      arena.appendChild(g);
      const hint = g.querySelector('.pg-hint');
      setTimeout(() => { try { hint && hint.remove(); } catch (_) {} }, 1850);
      // 出現位置・判定半径は従来どおり
      const gx = w * (.18 + Math.random() * .64), gy = h * (.38 + Math.random() * .28);
      pe.glass = { el: g, x: gx, y: gy, bornAt: el };
      g.style.transform = `translate3d(${gx.toFixed(1)}px,${gy.toFixed(1)}px,0)`;
    }
    if (!pe.glass) return;
    const g = pe.glass;
    const life = Number(cfg.glassLifeMs || 7000);
    const age = el - g.bornAt;
    g.el.classList.toggle('fading', age > life - 1800);
    const px = Number(state.player.x || 0), py = Number(state.player.y || 0);
    const dist = Math.hypot(px - g.x, py - g.y);
    g.el.classList.toggle('is-near', dist < 120);
    if (!halted && dist < 44) {
      g.el.remove(); pe.glass = null; pe.glassTaken++;
      startPartyBonus(now, Number(cfg.bonusMs || 5000) + Number(pe.opts.bonusExtraMs || 0));
      // build2165: 取った瞬間、グラスの位置から金の光が広がってボーナスタイムへつなぐ
      const burst = document.createElement('div');
      burst.className = 'party-glass-burst'; burst.setAttribute('aria-hidden', 'true');
      burst.style.transform = `translate3d(${g.x.toFixed(1)}px,${(g.y - 10).toFixed(1)}px,0)`;
      arena && arena.appendChild(burst);
      setTimeout(() => { try { burst.remove(); } catch (_) {} }, 620);
      const root = document.getElementById(ROOT_ID);
      if (root) {
        const c = document.createElement('div'); c.className = 'party-cheers'; c.setAttribute('aria-hidden', 'true'); c.textContent = 'CHEERS';
        root.appendChild(c); setTimeout(() => c.remove(), 1050);
      }
      return;
    }
    if (age > life) { g.el.remove(); pe.glass = null; }
  }
  // build2170: 懐中時計（制限時間 +5秒）。祝杯のグラスと同じく「触れて取る」。スコアの残り時間ボーナスは基本の60秒で計算する
  function getPartyExtraTimeSec() {
    if (!state || !state.partyEv || !isPartyEventStage()) return 0;
    return Math.max(0, Number(state.partyEv.extraSec || 0));
  }
  function updatePartyWatch(now, w, h, halted) {
    const pe = state.partyEv, cfg = getPartyConfig();
    const times = Array.isArray(cfg.watchAtMs) ? cfg.watchAtMs : [];
    if (!times.length) return;
    const el = getPartyElapsedMs(now);
    const arena = document.getElementById('shooting-arena');
    pe.watchIdx = pe.watchIdx || 0;
    if (!pe.watch && pe.watchIdx < times.length && el >= times[pe.watchIdx] && !halted && arena) {
      pe.watchIdx++;
      const sec = Math.max(1, Number(cfg.watchSec || 5));
      const g = document.createElement('div');
      g.className = 'party-glass-wrap is-watch';
      g.setAttribute('aria-hidden', 'true');
      g.innerHTML = '<i class="pg-mark"></i><i class="pg-glass"></i><b class="pg-hint">TIME +' + sec + '</b><i class="pg-dot"></i><i class="pg-dot"></i><i class="pg-dot"></i>';
      arena.appendChild(g);
      const hint = g.querySelector('.pg-hint');
      setTimeout(() => { try { hint && hint.remove(); } catch (_) {} }, 1850);
      // グラスと重ならない位置（グラスがあれば反対側）
      let gx = w * (.18 + Math.random() * .64);
      if (pe.glass && Math.abs(gx - pe.glass.x) < 90) gx = pe.glass.x < w / 2 ? w * .78 : w * .22;
      const gy = h * (.40 + Math.random() * .26);
      pe.watch = { el: g, x: gx, y: gy, bornAt: el, sec };
      g.style.transform = `translate3d(${gx.toFixed(1)}px,${gy.toFixed(1)}px,0)`;
    }
    if (!pe.watch) return;
    const g = pe.watch;
    const life = Number(cfg.watchLifeMs || 6000);
    const age = el - g.bornAt;
    g.el.classList.toggle('fading', age > life - 1800);
    const px = Number(state.player.x || 0), py = Number(state.player.y || 0);
    const dist = Math.hypot(px - g.x, py - g.y);
    g.el.classList.toggle('is-near', dist < 120);
    if (!halted && dist < 44) {
      g.el.remove(); pe.watch = null;
      pe.extraSec = Number(pe.extraSec || 0) + g.sec;
      pe.watchTaken = Number(pe.watchTaken || 0) + 1;
      const burst = document.createElement('div');
      burst.className = 'party-glass-burst is-watch'; burst.setAttribute('aria-hidden', 'true');
      burst.style.transform = `translate3d(${g.x.toFixed(1)}px,${(g.y - 10).toFixed(1)}px,0)`;
      arena && arena.appendChild(burst);
      setTimeout(() => { try { burst.remove(); } catch (_) {} }, 620);
      const pop = document.createElement('div');
      pop.className = 'party-pop time big';
      pop.textContent = '+' + g.sec + 's';
      pop.style.left = g.x + 'px'; pop.style.top = (g.y - 30) + 'px';
      arena && arena.appendChild(pop);
      setTimeout(() => pop.remove(), 950);
      const timer = document.getElementById('shooting-battle-timer');
      if (timer) { timer.classList.remove('party-time-plus'); void timer.offsetWidth; timer.classList.add('party-time-plus'); setTimeout(() => timer.classList.remove('party-time-plus'), 900); }
      return;
    }
    if (age > life) { g.el.remove(); pe.watch = null; }
  }
  function updatePartyMechanics(now) {
    if (!isPartyEventStage()) return;
    const pe = ensurePartyState();
    if (!pe) return;
    ensurePartyStyle();
    const dom = ensurePartyDom();
    const { w, h } = getShienArenaSize();
    const halted = !!(state.ended || state.finishing || state.countdown || state.koTransition || state.phaseTransition || !(state.boss && state.boss.hp > 0));
    const dt = pe.lastTick ? (now - pe.lastTick) / 1000 : 0;
    pe.lastTick = now;
    const el = getPartyElapsedMs(now);
    const cfg = getPartyConfig();
    if (!halted && !pe.startBonusGiven) {
      pe.startBonusGiven = true;
      const ms = Math.max(0, Number(pe.opts.startBonusMs || 0));
      if (ms > 0) startPartyBonus(now, ms);
      pe.nextSpawnAt = Number(cfg.spawnFirstMs || 1200);
      pe.nextTowerAt = Number(cfg.towerEveryMs || 15000) * (pe.opts.extraTower ? .66 : 1) * .5;
    }
    if (!halted) {
      const alive = (state.normalEnemies || []).filter(e => e && e.partyTarget && e.hp > 0).length;
      if (el >= pe.nextSpawnAt && alive < Number(cfg.maxActive || 9)) {
        spawnPartyGuest(now, w, h, false);
        pe.nextSpawnAt = el + Number(cfg.spawnEveryMs || 1250);
      }
      if (el >= pe.nextTowerAt) {
        spawnPartyGuest(now, w, h, true);
        pe.nextTowerAt = el + Number(cfg.towerEveryMs || 15000) * (pe.opts.extraTower ? .66 : 1);
      }
    }
    updatePartyGuests(dt, now, w, h, halted);
    updatePartyGlass(now, w, h, halted);
    updatePartyWatch(now, w, h, halted); // build2170
    const bonus = isPartyBonusActive(now);
    if (dom) {
      dom.root.classList.toggle('party-bonus', bonus);
      if (bonus) {
        const left = Math.max(0, pe.bonusUntil - el);
        const i = dom.bar.querySelector('.pb-track i');
        if (i) i.style.transform = 'scaleX(' + Math.max(0, Math.min(1, left / Math.max(1, pe.bonusTotalMs))).toFixed(3) + ')';
        const sec = dom.bar.querySelector('.pb-sec');
        if (sec) sec.textContent = (left / 1000).toFixed(1);
        dom.bar.classList.toggle('is-ending', left < 1500);
      }
    }
  }
  // 弾が人間に当たった（倒していない）：警告の震え
  function onPartyGuestHit(enemy) {
    if (!enemy || !enemy.partyHuman || !enemy.el || isPartyBonusActive(performance.now())) return;
    const el = enemy.el;
    if (el.classList.contains('party-warn')) return;
    el.classList.add('party-warn');
    setTimeout(() => el.classList.remove('party-warn'), 330);
  }
  // 夜会の客を倒した：加点／減点（ボーナス中は減点なし・人間も加点、料理は倍率）
  function onPartyGuestDefeated(enemy, now) {
    removePartyMark(enemy, true); // build2165
    const pe = ensurePartyState();
    if (!pe) return;
    const cfg = getPartyConfig();
    const def = enemy.def || {};
    const base = Number(def.partyValue || 0);
    const bonus = isPartyBonusActive(now);
    let v;
    if (base >= 0) {
      v = base * Math.max(1, Number(pe.opts.foodMul || 1)) * (bonus ? Math.max(Number(cfg.bonusPlusMul || 2), Number(pe.opts.bonusPlusMul || 0)) : 1);
      pe.foodKills++;
      if (def.id === window.ShootingEnemies?.SHOOTING_ENEMY_ID?.PARTY_TOWER) pe.towerKills++;
    } else if (bonus) {
      v = Number(cfg.bonusHumanValue || 300);
    } else {
      v = base * Math.max(0, Number(pe.opts.humanPenaltyMul == null ? 1 : pe.opts.humanPenaltyMul));
      pe.humanKills++;
    }
    v = Math.round(v);
    if (base >= 0) {
      if (def.id === window.ShootingEnemies?.SHOOTING_ENEMY_ID?.PARTY_TOWER) pe.towerScore = (pe.towerScore || 0) + v;
      else pe.dishScore = (pe.dishScore || 0) + v;
    } else if (bonus) pe.bonusHumanScore = (pe.bonusHumanScore || 0) + v;
    else pe.humanPenaltyScore = (pe.humanPenaltyScore || 0) + v;
    pe.points += v;
    state.score = Math.max(0, Math.round(pe.points)); // build2154: 右上のSCOREにその場で反映（討伐・時間・生存ボーナスは終了時に加算）
    if (typeof renderHud === 'function') renderHud();
    showPartyPop(enemy.x, enemy.y - 18, v, Math.abs(v) >= 1000);
  }
  function finalizePartyScore(win) {
    if (!state || !isPartyEventStage() || state.partyScoreFinalized) return;
    state.partyScoreFinalized = true;
    const pe = ensurePartyState() || { points: 0 };
    const cfg = getPartyConfig();
    let score = Number(pe.points || 0);
    state.partyBreakdown = { clear: 0, time: 0, survival: 0, party: Math.round(score) };
    if (win) {
      const limit = Math.max(1, getBattleTimeLimitSeconds());
      const elapsedSec = Math.max(0, Number(state.clearTimeMs || 0) / 1000);
      const timeRatio = clamp(1 - elapsedSec / limit, 0, 1);
      const party = Array.isArray(state.party) ? state.party : [];
      const hpMax = party.reduce((s, m) => s + Math.max(0, Number(m && m.hpMax || 0)), 0);
      const hp = party.reduce((s, m) => s + Math.max(0, Number(m && m.hp || 0)), 0);
      const surv = hpMax > 0 ? clamp(hp / hpMax, 0, 1) : 0;
      state.partyBreakdown.clear = Number(cfg.clearBonus || 8000);
      state.partyBreakdown.time = Math.round(Number(cfg.timeBonusMax || 8000) * timeRatio);
      state.partyBreakdown.survival = Math.round(Number(cfg.survivalBonusMax || 8000) * surv);
      score += state.partyBreakdown.clear + state.partyBreakdown.time + state.partyBreakdown.survival;
      state.partyRemainSec = Math.max(0, Math.floor(limit - elapsedSec));
    }
    state.score = Math.max(0, Math.round(score));
  }
  // build2164: パラレル・ソワレ専用のスコア明細。敗北時も加減点を表示。
  // 料理・塔・祝杯中の人間・人間撃破の合計は pe.points と必ず一致する。
  function renderPartyScoreBreakdown() {
    const result = document.getElementById('shooting-result');
    const card = result && result.querySelector('.shooting-result-card');
    if (!result || !card) return;
    const active = isPartyEventStage();
    result.classList.toggle('is-party-event-result', active);
    let detail = card.querySelector('#party-score-breakdown');
    if (!active) { if (detail) detail.remove(); return; }
    if (!detail) {
      detail = document.createElement('section');
      detail.id = 'party-score-breakdown';
      detail.className = 'party-score-breakdown';
      detail.setAttribute('aria-label', '夜会スコア内訳');
      const stats = card.querySelector('.shooting-result-stats');
      if (stats) stats.insertAdjacentElement('afterend', detail);
      else card.appendChild(detail);
    }
    if (!document.getElementById('party-result-breakdown-style-2164')) {
      const st = document.createElement('style');
      st.id = 'party-result-breakdown-style-2164';
      st.textContent = `
        /* build2174: 完全固定レイアウト。カードは画面の高さぴったりで、RETRY／戻るは常に最下部に固定。
           高さが足りない分は「スコア内訳」と「報酬」の中だけでスクロールする（画面・カード自体はスクロールしない） */
        html body #shooting-event-root #shooting-result.is-party-event-result{overflow:hidden !important;overscroll-behavior:none}
        html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-card{height:100% !important;max-height:100% !important;overflow:hidden !important;overflow-y:hidden !important;gap:8px !important}
        html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-card > *{flex-shrink:0 !important;min-height:0}
        html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-card > #party-score-breakdown{flex:0 1 auto !important;min-height:64px !important;max-height:220px !important;overflow-y:auto !important;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;touch-action:pan-y}
        html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-card > #shooting-result-rewards{flex:0 1 auto !important;min-height:64px !important;max-height:none !important;overflow-y:auto !important;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;touch-action:pan-y}
        html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-card > .shooting-result-actions{margin-top:auto !important;flex-shrink:0 !important}
        @media (max-height:700px){
          html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-card{gap:6px !important}
          html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-detail-row{min-height:40px !important;padding-top:2px !important;padding-bottom:2px !important}
          html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-card > #party-score-breakdown,
          html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-card > #shooting-result-rewards{min-height:56px !important}
        }
        @media (max-height:600px){
          html body #shooting-event-root #shooting-result.is-party-event-result #shooting-result-title{font-size:20px !important}
          html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-detail-row{min-height:30px !important;padding-top:0 !important;padding-bottom:0 !important}
          html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-card{gap:4px !important}
          html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-stats strong{font-size:22px !important;margin-top:2px !important}
          html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-stats > div{padding-top:5px !important;padding-bottom:5px !important}
          html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-card button{height:36px !important;margin-top:5px !important}
          html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-card > #party-score-breakdown,
          html body #shooting-event-root #shooting-result.is-party-event-result .shooting-result-card > #shooting-result-rewards{min-height:48px !important}
        }
        #shooting-result #party-score-breakdown > .psb-heading{position:sticky;top:-9px;z-index:1;margin:-9px -11px 0;padding:9px 11px 6px;background:rgba(255,251,243,.98)}
        #shooting-result.is-party-event-result .shooting-result-rank-wrap{margin:7px 0 8px}
        #shooting-result.is-party-event-result .shooting-result-rank{font-size:55px;line-height:.9}
        #shooting-result.is-party-event-result .shooting-result-stats{margin-bottom:8px}
        #party-score-breakdown{margin:2px 0 12px;padding:9px 11px 8px;text-align:left;border:1px solid rgba(157,127,79,.32);background:rgba(255,251,243,.75);font-family:'Noto Serif JP',serif}
        #party-score-breakdown .psb-heading{display:flex;justify-content:space-between;gap:8px;padding:0 0 6px;border-bottom:1px solid rgba(157,127,79,.27);font-size:10px;font-weight:700;color:#826338;letter-spacing:.09em}
        #party-score-breakdown .psb-row{display:flex;justify-content:space-between;gap:8px;padding:4px 0;font-size:11px;line-height:1.4;color:#64543e}
        #party-score-breakdown .psb-row b{font:600 12px/1.4 'Cinzel','Noto Serif JP',serif;color:#806337;white-space:nowrap;font-variant-numeric:tabular-nums}
        #party-score-breakdown .psb-row.negative b{color:#a3545d}
        #party-score-breakdown .psb-row.total{margin-top:3px;padding-top:8px;border-top:1px solid rgba(157,127,79,.35);font-weight:700}
        #party-score-breakdown .psb-row.total b{font-size:15px;color:#574025}
        #party-score-breakdown .psb-sub{font-size:9px;color:#9b8870;padding-top:4px}
        @media(max-height:740px){#shooting-result.is-party-event-result .shooting-result-card{padding-top:12px;padding-bottom:12px}#party-score-breakdown .psb-row{padding:3px 0}}
      `;
      document.head.appendChild(st);
    }
    const pe = state && state.partyEv || {};
    const breakdown = state && state.partyBreakdown || {};
    const dish = Math.round(Number(pe.dishScore || 0));
    const tower = Math.round(Number(pe.towerScore || 0));
    const cheers = Math.round(Number(pe.bonusHumanScore || 0));
    const human = Math.round(Number(pe.humanPenaltyScore || 0));
    const guestTotal = Math.round(Number(pe.points || 0));
    const tracked = dish + tower + cheers + human;
    // 旧形式で記録が欠ける場合の差分も隠さず開示。
    const other = guestTotal - tracked;
    const clear = Math.round(Number(breakdown.clear || 0));
    const time = Math.round(Number(breakdown.time || 0));
    const survival = Math.round(Number(breakdown.survival || 0));
    const rawTotal = guestTotal + clear + time + survival;
    const actual = Math.max(0,Math.round(Number(state && state.score || 0)));
    const adjustment = actual - rawTotal; // 負点時の合計0点補正
    const fmt = v => (v >= 0 ? '+' : '−') + Math.abs(v).toLocaleString('ja-JP');
    const row = (label,v,always) => (!always && !v) ? '' :
      '<div class="psb-row' + (v < 0 ? ' negative' : '') + '"><span>' + label + '</span><b>' + fmt(v) + '</b></div>';
    detail.innerHTML = '<div class="psb-heading"><span>SCORING DETAILS</span><span>スコア内訳</span></div>' +
      row('料理の撃破',dish,true) + row('シャンパンタワー',tower,true) +
      row('祝杯中の人間撃破',cheers,false) + row('人間の撃破（減点）',human,true) +
      row('その他の夜会スコア',other,false) +
      row('主催者討伐',clear,true) + row('残り時間ボーナス',time,true) +
      row('生存HPボーナス',survival,true) + row('0点未満の補正',adjustment,false) +
      '<div class="psb-row total"><span>合計 SCORE</span><b>' + actual.toLocaleString('ja-JP') + '</b></div>' +
      '<div class="psb-sub">※OP・祝杯効果による倍率は各得点に反映済み</div>';
  }

  function getPartyResultRank(score, win) {
    if (!win) return 'E';
    const cfg = getPartyConfig();
    const v = Number(score) || 0;
    if (v >= Number(cfg.rankS || 32000)) return 'S';
    if (v >= Number(cfg.rankA || 26000)) return 'A';
    return 'B';
  }
  // サーバー・パネル判定へ渡す1回分の記録
  function getPartyRunStats(win) {
    const pe = state && state.partyEv || {};
    return {
      win: !!win,
      score: Math.max(0, Math.round(Number(state && state.score || 0))),
      rank: getPartyResultRank(state && state.score, win),
      hitsTaken: Math.max(0, Math.floor(Number(state && state.totalHitsTaken || 0))),
      foodKills: Math.max(0, Number(pe.foodKills || 0)),
      humanKills: Math.max(0, Number(pe.humanKills || 0)),
      towerKills: Math.max(0, Number(pe.towerKills || 0)),
      glassTaken: Math.max(0, Number(pe.glassTaken || 0)),
      partyPoints: Math.round(Number(pe.points || 0)),
      remainSec: win ? Math.max(0, Number(state && state.partyRemainSec || 0)) : 0,
    };
  }
  function clearPartyDom() {
    try {
      const root = document.getElementById(ROOT_ID);
      if (root) {
        root.classList.remove('party-bonus');
        root.querySelectorAll('.party-bonus-bar,.party-bonus-veil,.party-glass,.party-glass-wrap,.party-glass-burst,.party-mark,.party-pop,.party-cheers,.flank-spawn-warn').forEach(n => n.remove());
      }
    } catch (_) {}
  }

  function gameLoop(ts) {
    if (!state || !state.running || state.ended || state.finishing || state.countdown) return;
    syncEnemyMotionFreezeClocks(ts);
    syncDeinovaDischargeGauge(ts); // build2057: 時間停止・PAUSE中もHP差分を取り、GAUGEに入れない

    if (state.paused) {
      // メニュー表示中はゲーム進行を完全停止。
      // RAFだけ継続して、復帰時のdtジャンプを防ぐ。
      prevTs = ts;
      rafId = requestAnimationFrame(gameLoop);
      return;
    }

    updateTowaDarkness(ts);
    trackEnemyAttackPause(ts);

    if (state.ch101TutorialPaused || state.ch102TutorialPaused || state.ch202ElementTutorialPaused) {
      prevTs = ts;
      renderHud();
      rafId = requestAnimationFrame(gameLoop);
      return;
    }

    // build1192: CH01-04の戦闘中セリフでは、敵・弾・戦闘時間だけを停止し、
    // プレイヤーのドラッグ追従は止めない。
    // 以前はここでupdateMovement自体を止めていたため、指を動かしているのに
    // キャラが固まり「処理落ち」に見えていた。入力座標は継続取得し、
    // playerOnlyでキャラ位置だけ毎フレーム反映する。
    if (state.ch104StoryPaused) {
      prevTs = ts;
      if (!state.koTransition) updateMovement(0, ts, true);

      // セリフ表示中にHUD全体を60fpsで再描画する必要はない。
      // DOM更新を間引き、iPhone/Safariでのレイアウト負荷を抑える。
      if (!Number.isFinite(Number(state.ch104PauseHudAt)) || ts - Number(state.ch104PauseHudAt || 0) >= 120) {
        state.ch104PauseHudAt = ts;
        renderHud();
      }

      rafId = requestAnimationFrame(gameLoop);
      return;
    }

    if (isChapter403FireWallStage() && state && !state.ch403BarrierBroken && !state.ch403EncounterTriggered && Number(state.ch403ImmuneHits || 0) >= 25 && Number(state.ch403PhaseStartedAt || 0) > 0 && performance.now() - state.ch403PhaseStartedAt >= 8000) {
      triggerChapter403EncounterSequence();
    }
    if (state.ch403StoryPaused) {
      prevTs = ts;
      if (!state.koTransition) updateMovement(0, ts, true);
      renderHud();
      rafId = requestAnimationFrame(gameLoop);
      return;
    }

    // アルノULT「瞬迅・千ノ刻」中は盤面時間を完全停止する。
    // RAFだけは継続し、停止中に敵の射撃時計・移動差分が蓄積しないよう毎フレーム基準時刻を更新する。
    if (state.arnoSlashActive) {
      prevTs = ts;
      deferAllEnemyAttackResume(Math.max(ts + 120, Number(state.arnoSlashUntil || ts)));
      renderHud();
      rafId = requestAnimationFrame(gameLoop);
      return;
    }

    if (state.ultCutinActive) {
      // ULTカットイン中はプレイヤー・敵・弾・DoT・召喚物を含めて完全停止。
      // build1527: 敵の射撃予約も先送りし、解除時の集中発射を防ぐ。
      prevTs = ts;
      deferAllEnemyAttackResume(ts + 120);
      renderHud();
      rafId = requestAnimationFrame(gameLoop);
      return;
    }

    // CH07 50%強化演出中：
    // 時間・移動・射撃・当たり判定・DoT・ギミックをすべて停止。
    // DOM生成とCSS演出だけを進める。
    if (state.ch07EnhanceTransitionActive) {
      prevTs = ts;
      renderHud();
      rafId = requestAnimationFrame(gameLoop);
      return;
    }

    // ノアULT落雷中：盤面上の敵全体の移動・攻撃を停止。
    // ステージ時間と新規スポーン判定だけは進める。
    if (Number(state.noahMovementFreezeUntil || 0) > 0) {
      if (ts < Number(state.noahMovementFreezeUntil || 0)) {
        if (checkBattleTimeLimit(ts)) return;
        updateFinalCountdown(ts); // build1835

        const noahFreezeDt = Math.min(0.032, Math.max(0, (ts - (prevTs || ts)) / 1000));
        prevTs = ts;

        if (!state.koTransition) updateMovement(noahFreezeDt, ts, true);

        if (isNormalBattle()) {
          spawnNormalEnemies(ts);
        }
        deferAllEnemyAttackResume(Number(state.noahMovementFreezeUntil || ts));

        renderHud();
        if (!state.ended) rafId = requestAnimationFrame(gameLoop);
        return;
      }
      state.noahMovementFreezeUntil = 0;
    }


    if (checkBattleTimeLimit(ts)) return;
    updateFinalCountdown(ts); // build1835
    respawnScoreAttackBoss(ts);

    const dt = Math.min(0.032, Math.max(0, (ts - (prevTs || ts)) / 1000));
    prevTs = ts;
    if (!isScoreAttackStage() && state.combo > 0 && Number(state.lastComboHitAt || 0) > 0 && ts - Number(state.lastComboHitAt || 0) >= getComboTimeoutMs()) {
      resetCombo(true);
    }
    if (!state.koTransition) updateMovement(dt, ts);
    updateAinaStealth(ts);
    updateHaoTrigger(ts);
    updateSmileBoxes(ts);
    updateTowaRayMarks(ts); // build1877
    updateTowaDawn(ts); // build1877
    updateMagaEyeAttack(ts); // build1974: 禍眼（magaEye 設定のある敵・ステージだけ）
    updateOverseerGaze(ts);  // build1982: 記憶決戦オーバーシアの凝視と安全地帯
    updateInoriGuard(ts); // build1817
    updateNightshadeSpinRings(ts);
    updateConjurePlacementPreview(ts);
    updateRemnaTrapPlacementPreview(ts);
    updateConjureDeployments(dt, ts);
    updateConjureTurrets(ts);
    updateSummonQueue(ts);
    updateCamillaCrimsonWeb(ts);
    syncCamillaBoundWebVisual(ts);
    rearmConjurePlacementWhileHeld(ts);
    rearmRemnaTrapPlacementWhileHeld(ts);
    updateConjureUlt(ts);
    updateChapter6Barriers(ts);
    updateChapter07Mechanics(ts);
    updateMitoSummon(dt, ts);
    updateGreshaBurnField(ts);
    updateClarineDecoys(dt, ts);
    updateIgnisFireWheel(ts);
    updateIgnisBurns(ts);
    updateRoseFortress(ts);
    updateWolfAtkField(ts);
    updateToyfelBlackHoleField(ts);
    if ((state.ignisLaserEl || (state.vLaserEls && state.vLaserEls.length)) && (
      String(getCurrentCharacter()?.shotType || '') !== 'laser' ||
      ts >= Number(state.ignisLaserHideAt || 0)
    )) {
      hideIgnisLaser();
    }
    const ultLocked = ts < (state.ultLockUntil || 0);
    const camillaRootedBoss = (state.boss && ts<Number(state.boss.camillaWebRootUntil||0))
      ? {x:state.boss.x,y:state.boss.y} : null;
    const bossGojoFrozen = ts < Number(state.gojoPurpleBossFreezeUntil || 0);
    const bossPullFrozen = isEnemyPullFieldActive(ts);
    const bossGrabbed = ts < (state.bossGrabUntil || 0) || bossGojoFrozen || bossPullFrozen;
    const bossStunned = ts < (state.bossStunUntil || 0);
    if (bossGojoFrozen) {
      // 拘束中は弾を生成しない。さらに発射時計を拘束終了へ送って、
      // 解除フレームで停止中の射撃をまとめて実行しないようにする。
      deferBossAttackResume(Number(state.gojoPurpleBossFreezeUntil || ts));
    }
    if (bossPullFrozen) {
      deferBossAttackResume(Number(state.eltenaBlackHole?.activeUntil || ts));
    }
    if (ts < Number(state.bossGrabUntil || 0)) {
      deferBossAttackResume(Number(state.bossGrabUntil || ts));
    }
    if (ts < Number(state.bossStunUntil || 0) || ts < Number(state.angeEnemyFreezeUntil || 0)) {
      deferBossAttackResume(Math.max(Number(state.bossStunUntil || 0), Number(state.angeEnemyFreezeUntil || 0)));
    }
    if (!state.phaseTransition && !state.koTransition && !ultLocked) {
      // 長いULT演出で通常射撃だけを止めたい場合は playerShotLockUntil を使う。
      // 敵の移動・攻撃は止めない。敵の行動停止は専用のfreeze/stun処理だけで行う。
      const tutorialUltOnly = isChapter101TutorialStage() && state.ch101TutorialPhase === 'ult_ready';
      if (!tutorialUltOnly && ts >= Number(state.playerShotLockUntil || 0)) firePlayer(ts);
      if (isNormalBattle()) {
        spawnNormalEnemies(ts);
        updateCamillaRootedEnemies(dt, ts);
        updateVerdantGrowth(dt, ts); // build1659: 樹獣の森（動いている敵だけ成長）
        fireTower12LethalVolley(ts);
      } else {
        if (hasBossAdds()) {
          spawnBossAdds(ts);
          updateCamillaRootedEnemies(dt, ts);
          updateVerdantGrowth(dt, ts); // build1659: 樹獣の森の配下（動いている敵だけ成長）
        }
        // build1643: オーバーシアの監視（視界に入っている間だけ敵弾が追従）
        updateOverseerWatch(dt, ts, bossGrabbed || bossStunned);
        // build1643: イノリ（鳥居・全属性バリア・レーザー・鈍化）
        updateInoriMechanics(dt, ts, bossGrabbed || bossStunned);
        // build1681: エクリプス（天秤・日食・蝕の手・本体無敵）
        updateEclipseMechanics(dt, ts, bossGrabbed || bossStunned);
        if (!bossGrabbed && !bossStunned && (!isScoreAttackStage() || state.boss.hp > 0)) {
          fireBoss(ts);
        }
      }
    }
    // build1571 RAID シエン: 霞化 / 回転斬り / 出血
    updateShienMechanics(ts);
    // build1750: テスト3段階目（降機）
    updateTestBodyMechanics(ts);
    // build1759: 記憶決戦の守護者・子蜘蛛
    updateInoriExecutionField(ts);
    updateMemoryMechanics(ts);
    // build1801: シオンULTの弱体化中、敵に「呪」の印を付けて追従
    syncShionCurseTags(ts);
    // build1592 RAID カミラ: 浮遊弾 / 巣レーザー / 捕縛罠 / 吸血子蜘蛛
    updateCamillaMechanics(ts);
    // build2121 RAID ネリサ: 雫のヴェール / 満ち潮（液状化はHPガード）
    updateNerisaMechanics(ts);
    // build2150 イベント「パラレル・ソワレ」: 夜会の客・祝杯のグラス・ボーナスタイム
    updatePartyMechanics(ts);
    // build1630: リズム弾幕（譜面・仮ドラム・判定）
    updateRhythmStage(ts);

    if(camillaRootedBoss && state.boss){
      state.boss.x=camillaRootedBoss.x;state.boss.y=camillaRootedBoss.y;
      if(state.boss.el)positionUnit(state.boss.el,state.boss.x,state.boss.y);
    }
    // build1659: 樹獣の女王（動いている間だけ成長→開花）。捕縛の位置戻し後に判定する。
    updateVerdantBossGrowth(dt, ts);
    updateVerdantSeeds(ts); // build1663: 成長の実
    // エルテナULTは通常の敵移動が終わった後に吸引を適用。
    // これによりAIの横移動よりブラックホールの集敵を優先する。
    updateEltenaBlackHole(dt, ts);
    updateGojoPurpleField(dt, ts);

    // build2057: ディノヴァ（plasmaレール・超放電）
    updateDeinovaMechanics(dt, ts);
    updateDeinovaUltCores(ts); // build2060: ディノヴァULTの放電コア（どのステージでも）

    // 敵の位置更新後、当たり判定で使うDOM矩形を一度だけまとめて取得。
    // contact/projectileの間でDOM read/writeを往復させない。
    const frameLayout = captureCombatFrameLayout();
    updateEnemyContactCollisions(ts, frameLayout);
    updateProjectiles(dt, ts, frameLayout);
    // 同じ更新済み座標を使って、検証ステージの敵弾だけを一枚へ描画する。
    // build1981: 描画で例外が出てもゲームループを止めない（以前はここで止まり「フリーズ」していた）
    try { renderCanvasEnemyBullets(); } catch (err) { noteCanvasAllocFailure(err); zsDiag('enemy-render-error', err && (err.stack || err.message) || err); }
    try { checkSpriteHealth(performance.now()); } catch (_) {} // build1993
    // build1811: 自機弾（Canvas対象のもの）を一枚へ描画
    try { renderPlayerBulletCanvas(); } catch (err) { console.warn('[shooting] player bullet canvas skipped:', err); }

    // SCORE ATTACKでは無関係なイベント/CH04系の更新を毎フレーム呼ばない。
    // キャラクター固有処理（Arno/Mimosa等）はゲーム性に関わるので維持。
    if (!isScoreAttackStage() && !isGachaTrialStage()) {
      updateFacelessObjects(dt, ts);
      updateAmbushStageMechanics(dt, ts);
      updateChapter4FinalItem(ts);
      updateChapter43MemoryFragment();
      updateChapter43Mechanics(ts);
      updateFacelessStageMechanics(ts);
      updateChapter4ShrinkWalls(ts);
      updateTower15Mechanics(ts);
      updatePhaseOdysseyVariety(ts);
      updatePhaseOdysseyLethalDrift(ts);
      updateCollectibles(dt);
    }
    updateArnoAura(ts);
    updateMimosaItems();
    if (isNormalBattle()) evaluateNormalMission(ts);

    // SCORE ATTACKとガチャ試遊のHUDは約10fps。移動/当たり判定/弾更新は60fpsのまま。
    if (isScoreAttackStage() || isGachaTrialStage()) {
      if (ts - Number(state.scoreAttackLastHudRenderAt || 0) >= 100) {
        state.scoreAttackLastHudRenderAt = ts;
        renderHud();
      }
    } else {
      renderHud();
    }

    if (!state.ended) rafId = requestAnimationFrame(gameLoop);
  }


  // build1643: PHASEごとの立ち絵差し替え（敵定義の phaseVisuals）。例：レイド「テスト」はPHASE3から別画像。
  function getActiveBossPhaseVisual() {
    const map = BOSS && BOSS.phaseVisuals;
    if (!map || !state || !state.boss) return null;
    return map[Number(state.boss.phase || 1)] || null;
  }
  function syncBossPhaseVisual() {
    const boss = document.getElementById(BOSS_ID);
    const root = document.getElementById(ROOT_ID);
    const visual = getActiveBossPhaseVisual();
    if (root) {
      if ((visual && visual.size === 'player') || (BOSS && BOSS.unitSize === 'player' && selectedStage && selectedStage.type !== 'normal')) root.setAttribute('data-boss-visual', 'player');
      else root.removeAttribute('data-boss-visual');
    }
    if (!boss || !BOSS || !BOSS.phaseVisuals) return;
    const src = getSelectedBossImage();
    if (src && boss.getAttribute('src') !== src) boss.src = src;
    boss.style.setProperty('--enemy-scale', String(getResponsiveBossDisplayScale()));
  }
  function preloadBossPhaseVisuals() {
    const map = BOSS && BOSS.phaseVisuals;
    if (!map) return;
    Object.keys(map).forEach(k => { if (map[k] && map[k].image) void preloadShootingImage(map[k].image, 7000); });
  }

  function getSelectedBossImage() {
    // build1659: 樹獣の女王は開花後の姿
    if (state && state.verdantQueenGrown && BOSS && BOSS.verdantBossGrowth && BOSS.verdantBossGrowth.grownImage) {
      return String(BOSS.verdantBossGrowth.grownImage);
    }
    const phaseVisual = getActiveBossPhaseVisual();
    if (phaseVisual && phaseVisual.image) return String(phaseVisual.image);
    // SCORE ATTACKだけ専用ボス画像に差し替える。
    // 同じenemyIdを使う他ステージ（楽園 -ノア-等）の画像は変更しない。
    if (isScoreAttackStage()) return 'images/scoata_boss.webp';
    // build1415: CH01-04 / CH02-04はそのステージで表示するBOSS画像だけ置換。
    // BOSSマスターの攻撃・HP・行動定義には触れない。
    if (selectedStage?.bossBattleImage) return String(selectedStage.bossBattleImage);
    return String(BOSS && BOSS.image || '');
  }

  function getBossIntroMeta() {
    if (!selectedStage || selectedStage.type !== 'boss' || !BOSS) return null;

    const battleImage = getSelectedBossImage();
    const fileName = battleImage.split('/').pop() || '';
    const lower = fileName.toLowerCase();

    // ファイル名を基準にイントロ画像・名称を判定。
    // battle画像とbattle_start画像を同じ命名規則に統一する。
    let introImage = '';
    // ステージ側で明示したイントロ画像を最優先する。
    // CH04-04のように専用素材が指定されている場合、命名推測で上書きしない。
    if (isScoreAttackStage()) {
      // SCORE ATTACK専用イントロ。バトル中のボス画像は従来のscoata_boss.webpを維持。
      introImage = 'images/score_attack_intro.webp';
    } else if (selectedStage.introImage) {
      introImage = String(selectedStage.introImage);
    } else if (isTestBodyBoss()) {
      // build1802: テスト（レイド・残響の塔16F・記憶決戦03）は共通のイントロ画像
      introImage = 'images/test_battle_start.webp';
    } else if (/_battle\.(webp|png|jpg|jpeg)$/i.test(battleImage)) {
      introImage = battleImage.replace(/_battle\.(webp|png|jpg|jpeg)$/i, '_battle_start.$1');
    }

    const meta = {
      image: introImage,
      kicker: 'BOSS ENCOUNTER',
      title: BOSS.name || 'BOSS',
      sub: '',
      key: lower,
    };

    if (isTowaDawnStage()) {
      meta.kicker = 'SPECIAL STAGE';
      meta.title = 'トワ -光の姿-';
      meta.sub = '夜明け';
      meta.image = selectedStage.introImage || meta.image;
    } else if (isAmbushStage()) {
      meta.kicker = 'EMERGENCY ENCOUNTER';
      meta.title = '???';
      meta.sub = 'DRAGON REMNANT VARIANT';
      meta.image = selectedStage.introImage || 'images/remnant_01_blk_battle_start.webp';
    } else if (isScoreAttackStage()) {
      meta.kicker = 'SCORE ATTACK';
      meta.title = 'すこあちゃん';
      meta.sub = selectedStage.difficultyLabel || '';
    } else if (isRhythmStage()) {
      meta.kicker = 'SPECIAL STAGE';
      meta.title = BOSS.name || 'リズム';
      meta.sub = '仮面舞踏会';
    } else if (BOSS && BOSS.behavior === 'tower15_echo_v1') {
      meta.kicker = 'ECHO TOWER 15F';
      meta.title = BOSS.name || 'トワ';
      meta.sub = 'THE LAST ECHO';
      meta.image = selectedStage.introImage || 'images/tower15_boss_battle_start.webp';
    } else if (isInoriSpecialStage()) {
      meta.kicker = 'SPECIAL STAGE';
      meta.title = '境界者：イノリ';
      meta.sub = `${getInoriSpecialLapConfig().lap}周目`;
      meta.image = selectedStage.introImage || 'images/memory_inori_battle_start.webp';
    } else if (isNoahStage()) {
      meta.kicker = 'SPECIAL STAGE';
      meta.title = '理想郷：ノア';
      meta.sub = '楽園 -ノア-';
      meta.image = selectedStage.introImage || 'images/noah_battle_start.webp';
    } else if (BOSS && BOSS.eclipseMechanics) {
      // build1681: 位相回遊 100F・150F…の確定ボス
      meta.kicker = 'PHASE ODYSSEY / FLOOR ' + String(selectedStage?.stageNo || 100);
      meta.title = BOSS.name || 'エクリプス';
      meta.sub = 'THE ECLIPSE';
      meta.image = selectedStage.introImage || 'images/eclipse_battle_start.webp';
    } else if (BOSS && BOSS.overseerWatch) {
      meta.kicker = isMemoryBattleStage() ? 'MEMORY BATTLE' : (isPhaseOdysseyStage() ? 'PHASE ODYSSEY' : 'TOWER GUARDIAN'); // build1982
      meta.title = BOSS.name || 'オーバーシア';
      meta.sub = isMemoryBattleStage() ? '監視者の記憶' : 'THE OVERSEER';
      meta.image = selectedStage.introImage || 'images/phase_odyssey_overseer_intro.webp';
    } else if (isSelectedBaseStage(SHOOTING_STAGE_ID.CH01_04) || lower.includes('remnant_01')) {
      meta.kicker = 'REMNANT 01';
      meta.title = '竜型レムナント';
      meta.sub = 'DRAGON REMNANT';
    } else if (isSelectedBaseStage(SHOOTING_STAGE_ID.CH02_04) || lower.includes('remnant_02')) {
      meta.kicker = 'REMNANT 02';
      meta.title = '白い影';
      meta.sub = 'WHITE SHADOW';
    } else if (lower.includes('remnant_03')) {
      meta.kicker = 'REMNANT 03';
      meta.title = 'リヴィア';
      meta.sub = 'RIVIA';
    } else if (lower.includes('remnant_04') || lower.includes('enemy_sakiel')) {
      meta.kicker = 'REMNANT 04';
      meta.title = 'サキエル';
      meta.sub = 'SAKIEL';
    } else if (lower.includes('remnant_06')) {
      meta.kicker = 'REMNANT 06';
      meta.title = 'レムナント06';
      meta.sub = 'LIGHT';
    } else if (lower.includes('faceless')) {
      meta.kicker = 'SPECIAL EVENT';
      meta.title = '無貌の天使';
      meta.sub = selectedStage.difficultyLabel || 'FACELESS';
      meta.image = selectedStage.introImage || 'images/enemy_faceless_battle_start.webp';
    } else {
      meta.sub = selectedStage.mission?.text || '';
    }

    return meta.image ? meta : null;
  }

  // build1559: ステージタイトル表示中にBOSSイントロ画像を先読みする。
  function warmBossStageIntroImage() {
    try {
      const meta = getBossIntroMeta();
      if (meta && meta.image) void preloadShootingImage(meta.image, 7000, false);
    } catch (_) {}
  }

  // build1559: options.revealMask=true の場合、白いステージ遷移マスクを
  // 「イントロを不透明で配置した後」に外す。タイトル → イントロ → 戦闘 の順になり、
  // イントロ前にシューティング画面が一瞬見えることがない。
  async function playBossStageIntro(onComplete, options = {}) {
    const revealMask = !!(options && options.revealMask);
    const onReveal = options && typeof options.onReveal === 'function' ? options.onReveal : null;
    let revealed = false;
    const reveal = () => {
      if (revealed) return Promise.resolve();
      revealed = true;
      const done = revealMask ? endShootingStageTransitionMask() : Promise.resolve();
      return Promise.resolve(done).then(() => { if (onReveal) onReveal(); });
    };
    const meta = getBossIntroMeta();

    // 通常ステージは従来通り、そのままカウントダウンへ。
    if (!meta) {
      await reveal();
      if (typeof onComplete === 'function') requestAnimationFrame(() => onComplete());
      return;
    }

    const root = document.getElementById(ROOT_ID);
    if (!root) {
      await reveal();
      if (typeof onComplete === 'function') onComplete();
      return;
    }

    await preloadShootingImage(meta.image, 7000, true);

    if (!document.getElementById(ROOT_ID) || !state || state.ended) {
      if (revealMask) clearShootingStageTransitionMask();
      return;
    }

    root.querySelectorAll('.shooting-boss-intro').forEach(el => el.remove());

    const intro = document.createElement('div');
    intro.className = 'shooting-boss-intro';
    intro.setAttribute('aria-hidden', 'true');
    intro.innerHTML = `
      <div class="shooting-boss-intro-media">
        <img class="shooting-boss-intro-image" src="${meta.image}" alt="">
        <div class="shooting-boss-intro-glitch g1"></div>
        <div class="shooting-boss-intro-glitch g2"></div>
        <div class="shooting-boss-intro-glitch g3"></div>
      </div>
      <div class="shooting-boss-intro-vignette"></div>
      <div class="shooting-boss-intro-noise"></div>
      <div class="shooting-boss-intro-scan"></div>
      <div class="shooting-boss-intro-flash"></div>
      <div class="shooting-boss-intro-copy">
        <small>${meta.kicker}</small>
        <strong>${meta.title}</strong>
        <span>${meta.sub || ''}</span>
      </div>
      <div class="shooting-boss-intro-line line-a"></div>
      <div class="shooting-boss-intro-line line-b"></div>
    `;

    // 最初のフレームから不透明。フェードインで背後の戦闘画面を透かさない。
    intro.style.transition = 'none';
    intro.style.opacity = '1';
    root.appendChild(intro);

    // 背景画像と同じ画像をglitch stripにも使用。
    intro.querySelectorAll('.shooting-boss-intro-glitch').forEach(glitch => {
      glitch.style.backgroundImage = `url("${meta.image}")`;
    });

    // イントロが描画された次のフレームで演出開始と同時にマスクを抜く。
    await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
    if (!intro.isConnected) {
      if (revealMask) clearShootingStageTransitionMask();
      return;
    }
    intro.classList.add('show', 'shake-entry');
    intro.style.removeProperty('opacity');
    intro.style.removeProperty('transition');
    void reveal();

    // 登場直後：画面全体へ短い衝撃。長く揺らさず、余韻だけ残す。
    setTimeout(() => {
      if (intro.isConnected) intro.classList.remove('shake-entry');
    }, 430);

    // タイトルが立ち上がる瞬間に二度目の小さなシェイク。
    setTimeout(() => {
      if (intro.isConnected) intro.classList.add('shake-title');
    }, 650);

    // 中盤で一瞬だけ強めのノイズ/glitchを出す。
    setTimeout(() => {
      if (intro.isConnected) intro.classList.add('glitch-burst');
    }, 720);

    setTimeout(() => {
      if (intro.isConnected) intro.classList.remove('shake-title');
    }, 1010);

    setTimeout(() => {
      if (intro.isConnected) intro.classList.remove('glitch-burst');
    }, 1050);

    // タイトルを少し長めに残し、余韻を保ったままゆっくり戦闘画面へ溶かす。
    setTimeout(() => {
      if (intro.isConnected) intro.classList.add('out');
    }, 2750);

    // フェードが完全に抜けてから READY カウントダウンへ。
    setTimeout(() => {
      intro.remove();
      if (typeof onComplete === 'function') onComplete();
    }, 3650);
  }


  function closeDailyStageSelect() {
    document.getElementById('shooting-daily-stage-select')?.remove();
  }

  function getDailyWeekdayKey() {
    let weekday = '';
    try {
      const parts = new Intl.DateTimeFormat('en-US', {
        timeZone: 'Asia/Tokyo',
        weekday: 'short',
      }).formatToParts(new Date());
      weekday = String(parts.find(part => part.type === 'weekday')?.value || '');
    } catch (_) {
      weekday = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][new Date().getDay()];
    }

    return {
      Mon: 'mon',
      Tue: 'tue',
      Wed: 'wed',
      Thu: 'thu',
      Fri: 'fri',
      Sat: 'sat',
      Sun: 'sun',
    }[weekday] || 'sun';
  }

  function getDailyStageId(level, kind = 'weekday') {
    const normalizedLevel = level === 'advanced' ? 'advanced' : 'intermediate';
    if (kind === 'exp') return `shooting_daily_exp_${normalizedLevel}`;
    return `shooting_daily_${getDailyWeekdayKey()}_${normalizedLevel}`;
  }

  function getDailySelectRewardInfo() {
    if (typeof window.getDailyWeekdayReward === 'function') {
      const info = window.getDailyWeekdayReward();
      if (info && info.reward) return info;
    }
    return {
      reward: {
        id: 'kyoumei_stone',
        name: '共鳴石',
        img: 'images/item_kyoumeistone.webp',
      },
      random: false,
      weekday: '',
    };
  }

  function getDailySelectAttempt(level, kind = 'weekday') {
    const key = kind === 'exp' ? `exp_${level === 'advanced' ? 'advanced' : 'intermediate'}` : (level === 'advanced' ? 'advanced' : 'intermediate');
    if (typeof window.getDailyAttemptState === 'function') {
      const attemptState = window.getDailyAttemptState(key);
      if (attemptState) return attemptState;
    }
    return { remaining: 1, max: 1 };
  }

  function refreshDailyStageSelect() {
    const overlay = document.getElementById('shooting-daily-stage-select');
    if (!overlay) return;

    const info = getDailySelectRewardInfo();
    const reward = info.reward || {};

    overlay.querySelectorAll('[data-daily-level]').forEach(row => {
      const level = row.getAttribute('data-daily-level') === 'advanced' ? 'advanced' : 'intermediate';
      const kind = row.getAttribute('data-daily-kind') === 'exp' ? 'exp' : 'weekday';
      const attempt = getDailySelectAttempt(level, kind);
      const materialSlot = row.querySelector('[data-daily-material-slot]');
      const remaining = row.querySelector('[data-daily-remaining]');

      if (materialSlot) {
        if (kind === 'exp') {
          const expItems = level === 'advanced'
            ? [
                {name:'強化素材・銀', img:'images/item_exp_silver.webp'},
                {name:'強化素材・金', img:'images/item_exp_gold.webp'}
              ]
            : [
                {name:'強化素材・銅', img:'images/item_exp_bronze.webp'},
                {name:'強化素材・金', img:'images/item_exp_gold.webp'},
                {name:'強化素材・銀', img:'images/item_exp_silver.webp'}
              ];
          materialSlot.classList.add('is-random-list','is-exp-daily');
          materialSlot.innerHTML = expItems.map(item => `
            <span class="zss-reward-chip shooting-daily-stage-random-item" title="${item.name}">
              <span class="zss-reward-icon"><img src="${item.img}" alt="${item.name}"></span>
              <span class="zss-reward-count"></span>
            </span>
          `).join('');
          materialSlot.setAttribute('aria-label', level === 'advanced'
            ? '強化素材・銀または金を合計10個。金の出現率が高い'
            : '強化素材・銅、金、銀を合計10個。出現率は銅、金、銀の順に高い');
        } else if (info.random && Array.isArray(info.rewards) && info.rewards.length) {
          const amount = level === 'advanced' ? 2 : 1;
          materialSlot.classList.add('is-random-list');
          materialSlot.classList.remove('is-exp-daily');
          materialSlot.innerHTML = info.rewards.map(item => `
            <span class="zss-reward-chip shooting-daily-stage-random-item" title="${item.name || ''}">
              <span class="zss-reward-icon"><img src="${item.img || ''}" alt="${item.name || ''}"></span>
              <span class="zss-reward-count"></span>
            </span>
          `).join('');
          materialSlot.setAttribute(
            'aria-label',
            `ランダム報酬候補：${info.rewards.map(item => item.name || '').filter(Boolean).join('、')} から ${amount}個`
          );
        } else {
          const amount = level === 'advanced' ? 2 : 1;
          materialSlot.classList.remove('is-random-list','is-exp-daily');
          materialSlot.innerHTML = `
            <span class="zss-reward-chip" title="${reward.name || 'デイリー報酬'}">
              <span class="zss-reward-icon"><img src="${reward.img || 'images/item_kyoumeistone.webp'}" alt="${reward.name || 'デイリー報酬'}"></span>
              <span class="zss-reward-count">×${amount}</span>
            </span>
          `;
          materialSlot.setAttribute('aria-label', `${reward.name || 'デイリー報酬'} ${amount}個`);
        }
      }

      if (remaining) remaining.textContent = `${Math.max(0, Number(attempt.remaining || 0))} / ${Math.max(1, Number(attempt.max || 1))}`;
      // build1816: 右欄の大きな数字＝今日の残り回数（CHAPTERのRANK表示と同じ位置・同じ書体）
      const left = row.querySelector('[data-daily-left]');
      if (left) left.textContent = String(Math.max(0, Number(attempt.remaining || 0)));
      const exhausted = Number(attempt.remaining || 0) <= 0;
      row.classList.toggle('is-exhausted', exhausted);
      row.setAttribute('aria-disabled', exhausted ? 'true' : 'false');
    });
  }

  function buildStageSelectAttributePreview(stageId) {
    const preview = window.ShootingStageAttributePreview;
    if (!preview || typeof preview.buildHtml !== 'function') return '';
    try {
      return preview.buildHtml(String(stageId || '')) || '';
    } catch (err) {
      console.warn('[shooting] stage attribute preview failed:', err);
      return '';
    }
  }

  const STAGE_GIMMICK_LABEL = Object.freeze({
    elementBarrier: 'バリア',
    timeLimit: '制限時間',
    blockingWall: '遮断壁',
  });

  function getStageBarrierPreviewElements(stage) {
    if (!stage) return [];
    const result = [];
    const pushUnique = (value) => {
      const element = normalizeCombatElement(value);
      if (!element || element === 'neutral' || result.includes(element) || result.length >= 3) return;
      result.push(element);
    };

    if (stage.weaknessOnlyElement) {
      pushUnique(stage.weaknessOnlyElement);
      return result;
    }

    const isDailyAdvanced = !!(
      (stage.dailyQuest && stage.dailyQuest.level === 'advanced') ||
      /^shooting_daily_(?:[a-z]{3}|exp)_advanced$/i.test(String(stage.id || ''))
    );

    if (stage.weaknessOnlyEnemies === true || isDailyAdvanced) {
      const normalCfg = stage.normalBattle || {};
      const sequence = Array.isArray(normalCfg.enemyElementSequence)
        ? normalCfg.enemyElementSequence
        : null;
      if (sequence && sequence.length) {
        for (const value of sequence) {
          pushUnique(value);
          if (result.length >= 3) break;
        }
      } else {
        const ids = Array.isArray(stage.enemyIds) ? stage.enemyIds : [];
        for (const enemyId of ids) {
          const def = getShootingEnemy(enemyId);
          if (!def || def.kind === 'boss') continue;
          pushUnique(def.element || stage.enemyElement || stage.element);
          if (result.length >= 3) break;
        }
      }
    }
    return result;
  }

  function getStageGimmickInfo(stageOrId) {
    const stage = (stageOrId && typeof stageOrId === 'object')
      ? stageOrId
      : getShootingStage(String(stageOrId || ''));
    if (!stage) return [];

    const gimmicks = [];
    // build2137: レイドは全ボス共通ステージなので、その日のボスの説明一覧（BOSS.raidGimmicks）からギミックを出す。
    if (stage.raid && BOSS && Array.isArray(BOSS.raidGimmicks) && BOSS.raidGimmicks.length) {
      for (const g of BOSS.raidGimmicks) {
        if (g.name === '属性バリア') {
          const els = BOSS.nerisaMechanics ? ['aqua'] : (BOSS.camillaMechanics ? ['fire'] : [normalizeCombatElement(BOSS.element)].filter(Boolean));
          gimmicks.push({ id:'elementBarrier', label:STAGE_GIMMICK_LABEL.elementBarrier, elements:els, desc:g.desc });
        } else {
          gimmicks.push({ id:'raidGimmick', label:g.name, desc:g.desc });
        }
      }
      return gimmicks;
    }
    if (stage.spiderHorde && Array.isArray(stage.spiderHorde.spawnEdges) && stage.spiderHorde.spawnEdges.length) {
      const edges = stage.spiderHorde.spawnEdges;
      gimmicks.push({ id:'flankHorde', label: edges.includes('bottom') ? '横・背後から群れが出現' : '左右から群れが出現' });
    } else if (stage.spiderHorde) gimmicks.push({ id:'ch704Horde', label:'小蜘蛛の大群・接触連撃' });
    if (stage.rhythm) gimmicks.push({ id:'rhythm', label:'リズム弾幕' });
    if (stage.verdant) {
      gimmicks.push({ id:'verdantCharge', label:'突進' });
      gimmicks.push({ id:'verdantGrowth', label:'動くと成長' });
      if (stage.verdant.seeds) gimmicks.push({ id:'verdantSeed', label:'成長の実' }); // build1663
    }
    const barrierElements = getStageBarrierPreviewElements(stage);
    const isDailyAdvanced = !!(
      (stage.dailyQuest && stage.dailyQuest.level === 'advanced') ||
      /^shooting_daily_(?:[a-z]{3}|exp)_advanced$/i.test(String(stage.id || ''))
    );

    if (stage.weaknessOnlyElement || stage.weaknessOnlyEnemies === true || isDailyAdvanced) {
      gimmicks.push({ id:'elementBarrier', label:STAGE_GIMMICK_LABEL.elementBarrier, elements:barrierElements });
    }
    if (Number(stage.timeLimitSeconds || 0) > 0) {
      gimmicks.push({ id:'timeLimit', label:STAGE_GIMMICK_LABEL.timeLimit, seconds:Math.max(1, Math.floor(Number(stage.timeLimitSeconds || 0))) });
    }
    // 遮断壁はstage定義に明示された場合に加え、DAILY上級でも自動生成される。
    if ((Array.isArray(stage.chapter6Barriers) && stage.chapter6Barriers.length > 0) || isDailyAdvanced) {
      gimmicks.push({ id:'blockingWall', label:STAGE_GIMMICK_LABEL.blockingWall });
    }
    return gimmicks;
  }

  function buildStageGimmickPreview(stageOrId) {
    const gimmicks = getStageGimmickInfo(stageOrId);
    if (!gimmicks.length) {
      return `
        <div class="shooting-stage-gimmicks is-none" aria-label="ステージギミック：なし">
          <span class="shooting-stage-gimmick-label">GIMMICK</span>
          <span class="shooting-stage-gimmick-list">
            <span class="shooting-stage-gimmick-chip gimmick-none"><b>なし</b></span>
          </span>
        </div>`;
    }

    const chips = gimmicks.map(item => {
      let extra = '';
      if (item.id === 'elementBarrier' && Array.isArray(item.elements) && item.elements.length) {
        extra = `<span class="shooting-stage-gimmick-elements">${
          item.elements.map(element => {
            const src = getCombatElementIcon(element);
            return src ? `<img src="${src}" alt="${String(element || '')}" draggable="false">` : '';
          }).join('')
        }</span>`;
      } else if (item.id === 'timeLimit' && item.seconds) {
        extra = `<small>${item.seconds}s</small>`;
      }
      return `<span class="shooting-stage-gimmick-chip gimmick-${item.id}"><b>${item.label}</b>${extra}</span>`;
    }).join('');

    return `
      <div class="shooting-stage-gimmicks" aria-label="ステージギミック">
        <span class="shooting-stage-gimmick-label">GIMMICK</span>
        <span class="shooting-stage-gimmick-list">${chips}</span>
      </div>`;
  }

  window.getShootingStageGimmickInfo = getStageGimmickInfo;
  window.buildShootingStageGimmickPreview = buildStageGimmickPreview;

  function showShootingStageGimmickNotice() {
    const gimmicks = getStageGimmickInfo(selectedStage);
    if (!gimmicks.length) return Promise.resolve();

    const root = document.getElementById(ROOT_ID);
    if (!root) return Promise.resolve();

    root.querySelectorAll('.shooting-stage-gimmick-notice').forEach(el => el.remove());

    const notice = document.createElement('div');
    notice.className = 'shooting-stage-gimmick-notice';
    const rows = gimmicks.map(item => {
      let detail = '';
      if (item.id === 'elementBarrier') {
        const icons = (item.elements || []).map(element => {
          const src = getCombatElementIcon(element);
          return src ? `<img src="${src}" alt="" draggable="false">` : '';
        }).join('');
        detail = `<span class="shooting-stage-gimmick-notice-elements">${icons}</span><small>対応属性または無属性で攻撃可能</small>`;
      } else if (item.id === 'timeLimit') {
        detail = `<small>${item.seconds || Math.max(1, Math.floor(Number(selectedStage?.timeLimitSeconds || 0)))}秒</small>`;
      } else if (item.id === 'blockingWall') {
        detail = '<small>射撃・移動を遮る壁に注意</small>';
      } else if (item.id === 'raidGimmick' && item.desc) {
        // build2137: レイドボスのギミックは説明文を出す
        detail = `<small>${item.desc}</small>`;
      }
      return `<div class="shooting-stage-gimmick-notice-row"><strong>${item.label}</strong>${detail}</div>`;
    }).join('');

    notice.innerHTML = `
      <div class="shooting-stage-gimmick-notice-card">
        <div class="shooting-stage-gimmick-notice-kicker">STAGE GIMMICK</div>
        ${rows}
      </div>`;
    root.appendChild(notice);

    return new Promise(resolve => {
      requestAnimationFrame(() => notice.classList.add('show'));
      setTimeout(() => notice.classList.add('out'), 900);
      setTimeout(() => {
        notice.remove();
        resolve();
      }, 1250);
    });
  }

  function openDailyStage(level, kind = 'weekday') {
    if (typeof window.requireChapter03ContentUnlock === 'function' && !window.requireChapter03ContentUnlock()) return false;
    const normalizedLevel = level === 'advanced' ? 'advanced' : 'intermediate';
    const normalizedKind = kind === 'exp' ? 'exp' : 'weekday';
    const attempt = getDailySelectAttempt(normalizedLevel, normalizedKind);

    if (Number(attempt.remaining || 0) <= 0) {
      const message = '本日の挑戦回数を使い切りました';
      if (typeof window.showToast === 'function') window.showToast(message);
      else alert(message);
      return false;
    }

    // デイリー巡行 → 種類/難易度選択 → パーティ編成。
    window.__shootingReturnContext = { type: 'dailyStageSelect' };
    closeDailyStageSelect();
    window.openShootingEvent({ stageId: getDailyStageId(normalizedLevel, normalizedKind) });
    return true;
  }


  // build1388: DAILYもCHAPTERと同一zss-card構造・同一CSSで描画する。
  // DAILY固有の挑戦回数のみ、RANK/HIGH SCOREの代わりに右側へ表示。
  function buildDailyStageCard(indexNo, levelLabel, mission, kind, level, gimmicks, hasCoin) {
    const missionText = String(mission || '').replace(/^クリア条件：?\s*/, '').trim() || '敵をすべて撃破';
    return `
      <div class="zss-card zss-story-shooting-card zds-card" role="button" tabindex="0"
           data-daily-kind="${kind}" data-daily-level="${level}"
           onclick="openDailyStage('${level}','${kind}')"
           onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openDailyStage('${level}','${kind}')}">
        <div class="zss-card-no" aria-hidden="true"><span>✧</span><b>${indexNo}</b><span>✧</span></div>
        <div class="zss-card-body">
          <div class="zss-card-name-row">
            <span class="zss-card-name">${levelLabel}</span>
          </div>
          <div class="zss-mission">クリア条件：${missionText}</div>
          <div class="zss-card-row zss-card-row-gimmick">
            <span class="zss-card-label">GIMMICK</span>
            <span class="zss-gimmicks">${gimmicks}</span>
          </div>
          <div class="zss-card-row zss-card-row-reward">
            <span class="zss-card-label">主な報酬</span>
            <span class="zss-rewards">
              ${hasCoin ? `<span class="zss-reward-chip"><span class="zss-reward-icon"><img src="images/icon_coin.webp" alt="コイン"></span><span class="zss-reward-count">×10,000</span></span>` : ''}
              <span class="zds-materials" data-daily-material-slot></span>
            </span>
          </div>
        </div>
        <div class="zss-record zds-record" aria-label="挑戦回数">
          <div class="zss-record-rank">
            <span>残り回数</span><b class="zds-record-state" data-daily-left>1</b>
          </div>
          <div class="zss-record-score">
            <span>DAILY</span><b data-daily-remaining>1 / 1</b>
          </div>
        </div>
        <span class="zss-arrow" aria-hidden="true">›</span>
      </div>`;
  }

  function showDailyStageSelect(options = {}) {
    if (typeof window.requireChapter03ContentUnlock === 'function' && !window.requireChapter03ContentUnlock()) return false;
    closeDailyStageSelect();

    const immediate = !!(options && options.immediate);
    const overlay = document.createElement('div');
    overlay.id = 'shooting-daily-stage-select';
    // NO old daily/faceless/special classes: they are heavily overridden by old CSS.
    overlay.className = 'zds-screen';
    if (immediate) {
      overlay.classList.add('show');
      overlay.style.transition = 'none';
    }

    const getGimmicks = (level, kind) => buildStageGimmickPreview(getDailyStageId(level, kind));
    overlay.innerHTML = `
      <div class="zds-surface">
        <div class="zds-pagehead">
          <button type="button" class="zds-back" onclick="closeDailyStageSelect()" aria-label="戻る">〈 戻る</button>
          <h2 class="zds-heading">デイリー巡行</h2>
          <div class="zds-ornament" aria-hidden="true"><span>✦</span></div>
        </div>
        <div class="zds-scroll">
          <section class="zds-section" aria-label="曜日素材">
            <div class="zds-sectionhead">
              <span class="zds-sectionicon" aria-hidden="true">✧</span>
              <strong>曜日素材</strong><span class="zds-section-sub">刻界突破素材</span>
              <img class="zds-section-art" src="images/icon_dairy.webp" alt="" aria-hidden="true" draggable="false">
            </div>
            ${buildDailyStageCard('01','中級','クリア条件：敵をすべて撃破','weekday','intermediate', getGimmicks('intermediate','weekday'), true)}
            ${buildDailyStageCard('02','上級','クリア条件：敵をすべて撃破','weekday','advanced', getGimmicks('advanced','weekday'), true)}
          </section>
          <section class="zds-section" aria-label="経験値素材">
            <div class="zds-sectionhead">
              <span class="zds-sectionicon zds-book" aria-hidden="true">✥</span>
              <strong>経験値素材</strong><span class="zds-section-sub">キャラクター強化素材</span>
              <img class="zds-section-art" src="images/icon_dairy.webp" alt="" aria-hidden="true" draggable="false">
            </div>
            ${buildDailyStageCard('03','中級','経験値素材を合計10個獲得','exp','intermediate', getGimmicks('intermediate','exp'), false)}
            ${buildDailyStageCard('04','上級','経験値素材を合計10個獲得','exp','advanced', getGimmicks('advanced','exp'), false)}
          </section>
        </div>
      </div>`;

    document.body.appendChild(overlay);
    // Leave original server-authoritative reward and attempt-state refresh unchanged.
    refreshDailyStageSelect();
    if (typeof window.syncDailyAttemptStateFromServer === 'function') {
      void window.syncDailyAttemptStateFromServer();
    }
    if (!immediate) requestAnimationFrame(() => overlay.classList.add('show'));
    else requestAnimationFrame(() => {
      if (overlay.isConnected) overlay.style.transition = '';
    });
    return true;
  }

  window.closeDailyStageSelect = closeDailyStageSelect;
  window.showDailyStageSelect = showDailyStageSelect;
  window.openDailyStage = openDailyStage;
  window.refreshDailyStageSelect = refreshDailyStageSelect;

  function closeFacelessStageSelect() {
    document.getElementById('shooting-faceless-stage-select')?.remove();
  }

  function openFacelessStage(stageId) {
    if (typeof window.requireChapter03ContentUnlock === 'function' && !window.requireChapter03ContentUnlock()) return false;
    // 「無貌の天使」ステージ一覧 → パーティ編成へ進んだことを保持。
    // 編成画面の「戻る」は、特別巡行トップではなく直前のステージ一覧へ戻す。
    window.__shootingReturnContext = { type: 'facelessStageSelect' };
    closeFacelessStageSelect();
    window.openShootingEvent({ stageId: String(stageId || '') });
  }

  // build1391: STORY / DAILY / FACELESS all use one canonical zss-card DOM/CSS.
  // This selector intentionally DOES NOT use legacy shooting-faceless-stage-select
  // or shooting-special-stage-select classes (old shooting_event.css overrides).
  function buildFacelessGimmickHtml(stageId) {
    const gimmicks = getStageGimmickInfo(stageId);
    if (!gimmicks.length) return '<span class="zss-gimmick-chip is-none"><b>なし</b></span>';
    return gimmicks.map(item => {
      let extra = '';
      if (item.id === 'elementBarrier' && Array.isArray(item.elements)) {
        extra = `<span class="zss-gimmick-elements">${item.elements.map(element => {
          const src = getCombatElementIcon(element);
          return src ? `<img src="${src}" alt="${element}" draggable="false">` : '';
        }).join('')}</span>`;
      } else if (item.id === 'timeLimit' && item.seconds) {
        extra = `<small>${item.seconds}秒</small>`;
      }
      return `<span class="zss-gimmick-chip gimmick-${item.id}"><b>${item.label}</b>${extra}</span>`;
    }).join('');
  }

  // ============================================================
  // build1637: クリア済み表示（無貌の天使・律動の難易度選択）
  //  端末内の記録（勝利時に即記録）＋サーバーの初回クリア記録を合わせて判定する。
  // ============================================================
  function getShootingClearedStorageKey() {
    return 'zeraphia_shooting_cleared_v1:' + String(getShootingUserId() || 'guest');
  }
  function readShootingClearedStages() {
    try {
      const raw = JSON.parse(localStorage.getItem(getShootingClearedStorageKey()) || '[]');
      return new Set(Array.isArray(raw) ? raw.map(String) : []);
    } catch (_) { return new Set(); }
  }
  function writeShootingClearedStages(set) {
    try { localStorage.setItem(getShootingClearedStorageKey(), JSON.stringify(Array.from(set))); } catch (_) {}
  }
  function markShootingStageCleared(stageId) {
    const id = String(stageId || '');
    if (!id) return;
    const set = readShootingClearedStages();
    if (set.has(id)) return;
    set.add(id);
    writeShootingClearedStages(set);
  }
  // build1638: 難易度選択の右欄（ストーリーと同じ RANK / HIGH SCORE）
  function getShootingBestRankStorageKey() {
    return 'zeraphia_shooting_best_rank_v1:' + String(getShootingUserId() || 'guest');
  }
  function readShootingBestRanks() {
    try { return JSON.parse(localStorage.getItem(getShootingBestRankStorageKey()) || '{}') || {}; } catch (_) { return {}; }
  }
  function shootingRankOrder(rank) {
    const list = RESULT_RANK_THRESHOLDS.map(t => String(t.rank));
    const i = list.indexOf(String(rank || ''));
    return i < 0 ? list.length + 1 : i;   // 小さいほど上位
  }
  function saveShootingBestRank(stageId, rank) {
    const id = String(stageId || '');
    if (!id || !rank) return;
    const map = readShootingBestRanks();
    if (map[id] && shootingRankOrder(map[id]) <= shootingRankOrder(rank)) return;
    map[id] = String(rank);
    try { localStorage.setItem(getShootingBestRankStorageKey(), JSON.stringify(map)); } catch (_) {}
  }
  function buildEventStageRecordHtml(stageId) {
    const rank = String(readShootingBestRanks()[String(stageId || '')] || '');
    const rankClass = rank ? ` rank-${rank.toLowerCase()}` : ' rank-none';
    const high = getLocalShootingHighScore(String(stageId || ''));
    return `
        <div class="zss-record" aria-label="ベスト記録">
          <div class="zss-record-rank${rankClass}"><span>RANK</span><b>${rank || '—'}</b></div>
          <div class="zss-record-score"><span>HIGH SCORE</span><b>${formatShootingScore(high)}</b></div>
        </div>`;
  }
  function buildStageClearBadgeHtml(stageId) {
    return readShootingClearedStages().has(String(stageId || ''))
      ? '<span class="zss-clear-badge" aria-label="クリア済み">✓ CLEAR</span>'
      : '';
  }
  // サーバーの初回クリア記録を取り込み、開いている難易度選択のバッジを更新する。
  let shootingClearedSyncPromise = null;
  function syncShootingClearedStagesFromServer() {
    if (shootingClearedSyncPromise) return shootingClearedSyncPromise;
    const sb = window.zsSupabase;
    if (!sb || typeof sb.rpc !== 'function') return Promise.resolve();
    shootingClearedSyncPromise = (async () => {
      try {
        const res = await sb.rpc('get_my_cleared_shooting_stages');
        if (res && res.error) throw res.error;
        const rows = Array.isArray(res && res.data) ? res.data : [];
        const set = readShootingClearedStages();
        rows.forEach(row => {
          const id = typeof row === 'string' ? row : (row && row.stage_id);
          if (id) set.add(String(id));
        });
        writeShootingClearedStages(set);
        document.querySelectorAll('#shooting-faceless-stage-select [data-stage-id]').forEach(card => {
          const id = card.getAttribute('data-stage-id');
          const nameRow = card.querySelector('.zss-card-name-row');
          if (nameRow && set.has(id) && !nameRow.querySelector('.zss-clear-badge')) {
            nameRow.insertAdjacentHTML('beforeend', buildStageClearBadgeHtml(id));
          }
        });
      } catch (err) {
        console.warn('[shooting] cleared stage sync failed:', err && (err.message || err));
      } finally {
        shootingClearedSyncPromise = null;
      }
    })();
    return shootingClearedSyncPromise;
  }

  // build1638: 見出しが長い（8文字以上など）ときは、戻るボタンに掛からない幅まで文字を縮める。
  function fitStageSelectHeading(overlay) {
    const h = overlay && overlay.querySelector('.zfs-heading');
    if (!h) return;
    const target = h.querySelector('.zfs-heading-main') || h;
    target.style.fontSize = '';
    let size = parseFloat(getComputedStyle(target).fontSize) || 24;
    let guard = 0;
    while (h.scrollWidth > h.clientWidth + 1 && size > 14 && guard++ < 20) {
      size -= 1;
      target.style.fontSize = size + 'px';
      target.style.letterSpacing = '.04em';
    }
  }

  function buildFacelessStageCard(stageId, number, title) {
    const stage = getShootingStage(stageId);
    const mission = stage?.mission?.text || 'フェイスレスを撃破';
    const waveCount = stage?.faceless?.waveHp?.length || 2;
    // Supabase first-clear reward: 上級5 / 最上級10 (one claim per stage).
    const firstClearGems = stage?.faceless?.difficulty === 'super' ? 10 : 5;
    const attrs = buildStageSelectAttributePreview(stageId);
    return `
      <div class="zss-card zss-story-shooting-card zfs-card" role="button" tabindex="0" data-stage-id="${stageId}"
           onclick="openFacelessStage('${stageId}')"
           onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openFacelessStage('${stageId}');}">
        <div class="zss-card-no" aria-hidden="true"><span>✧</span><b>${number}</b><span>✧</span></div>
        <div class="zss-card-body">
          <div class="zss-card-name-row"><span class="zss-card-name">${title}</span>${buildStageClearBadgeHtml(stageId)}</div>
          <div class="zss-mission">クリア条件：${mission}</div>
          <div class="zss-card-row zss-card-row-gimmick">
            <span class="zss-card-label">GIMMICK</span>
            <span class="zss-gimmicks">${buildFacelessGimmickHtml(stageId)}</span>
          </div>
          ${attrs ? `<div class="zfs-attributes">${attrs}</div>` : ''}
          <div class="zss-card-row zss-card-row-reward">
            <span class="zss-card-label">主な報酬</span>
            <span class="zss-rewards">
              <span class="zss-reward-chip" title="プレイヤーEXP"><span class="zss-reward-icon"><img src="images/icon_exp.webp" alt="プレイヤーEXP"></span></span>
              <span class="zss-reward-chip" title="コイン"><span class="zss-reward-icon"><img src="images/icon_coin.webp" alt="コイン"></span></span>
              <span class="zss-reward-chip zfs-first-clear-gem" title="初回クリア報酬：結晶 ×${firstClearGems}" aria-label="初回のみ 結晶 ${firstClearGems}個">
                <span class="zss-reward-icon"><img src="images/icon_gem.webp" alt="結晶"></span>
                <span class="zfs-gem-count">×${firstClearGems}</span>
                <span class="zfs-first-label">初回のみ</span>
              </span>
            </span>
          </div>
        </div>
        ${buildEventStageRecordHtml(stageId)}
        <span class="zss-arrow" aria-hidden="true">›</span>
      </div>`;
  }

  function showFacelessStageSelect(options = {}) {
    if (typeof window.requireChapter03ContentUnlock === 'function' && !window.requireChapter03ContentUnlock()) return false;
    closeFacelessStageSelect();
    const immediate = !!(options && options.immediate);
    const overlay = document.createElement('div');
    overlay.id = 'shooting-faceless-stage-select';
    overlay.className = 'zfs-screen';
    if (immediate) { overlay.classList.add('show'); overlay.style.transition = 'none'; }
    overlay.innerHTML = `
      <div class="zfs-surface">
        <div class="zfs-pagehead">
          <button type="button" class="zfs-back" onclick="closeFacelessStageSelect()" aria-label="戻る">〈 戻る</button>
          <h2 class="zfs-heading">無貌の天使</h2>
          <div class="zfs-ornament" aria-hidden="true"><span>✦</span></div>
        </div>
        <div class="zfs-scroll">
          <div class="zfs-list" aria-label="無貌の天使・難易度選択">
            ${buildFacelessStageCard(SHOOTING_STAGE_ID.FACELESS_ADVANCED, '01', '上級')}
            ${buildFacelessStageCard(SHOOTING_STAGE_ID.FACELESS_SUPER, '02', '最上級')}
          </div>
        </div>
      </div>`;
    document.body.appendChild(overlay);
    fitStageSelectHeading(overlay);
    void syncShootingClearedStagesFromServer();
    if (!immediate) requestAnimationFrame(() => overlay.classList.add('show'));
    else requestAnimationFrame(() => { if (overlay.isConnected) overlay.style.transition = ''; });
    return true;
  }

  // ============================================================
  // build1637: 律動 -仮面舞踏会- 難易度選択（無貌の天使と同じ画面構成）
  //  巡行 → 律動 → 上級/最上級 → パーティ編成。編成の「戻る」はこの画面へ戻る。
  // ============================================================
  function openRhythmStage(stageId) {
    if (typeof window.requireChapter03ContentUnlock === 'function' && !window.requireChapter03ContentUnlock()) return false;
    window.__shootingReturnContext = { type: 'rhythmStageSelect' };
    closeFacelessStageSelect();
    window.openShootingEvent({ stageId: String(stageId || '') });
  }

  function buildRhythmStageCard(stageId, number, title) {
    const stage = getShootingStage(stageId);
    const enemyId = stage && Array.isArray(stage.enemyIds) ? stage.enemyIds[0] : '';
    const enemy = enemyId && window.ShootingEnemies ? window.ShootingEnemies.getShootingEnemy(enemyId) : null;
    const phases = Math.max(1, Number(enemy && enemy.gauges || 3));
    const mission = stage?.mission?.text || 'リズムを撃破';
    const isVerdant = stage?.eventId === 'verdant';
    const firstClearGems = Math.max(0, Number(stage?.firstClearGems ?? 5));
    const firstClearShinjuPt = Math.max(0, Number(stage?.firstClearShinjuPt || 0));
    const fixed = Array.isArray(stage?.fixedItemDrops) ? stage.fixedItemDrops : [];
    const goldCount = fixed.filter(row => row && row.id === 'level_exp_large').reduce((sum, row) => sum + Number(row.count || 0), 0);
    const attrs = buildStageSelectAttributePreview(stageId);
    return `
      <div class="zss-card zss-story-shooting-card zfs-card" role="button" tabindex="0" data-stage-id="${stageId}"
           onclick="openRhythmStage('${stageId}')"
           onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openRhythmStage('${stageId}');}">
        <div class="zss-card-no" aria-hidden="true"><span>✧</span><b>${number}</b><span>✧</span></div>
        <div class="zss-card-body">
          <div class="zss-card-name-row"><span class="zss-card-name">${title}</span>${buildStageClearBadgeHtml(stageId)}</div>
          <div class="zss-mission">クリア条件：${mission}</div>
          <div class="zss-card-row zss-card-row-gimmick">
            <span class="zss-card-label">GIMMICK</span>
            <span class="zss-gimmicks">${buildFacelessGimmickHtml(stageId)}</span>
          </div>
          ${attrs ? `<div class="zfs-attributes">${attrs}</div>` : ''}
          <div class="zss-card-row zss-card-row-reward">
            <span class="zss-card-label">主な報酬</span>
            <span class="zss-rewards">
              <span class="zss-reward-chip" title="プレイヤーEXP"><span class="zss-reward-icon"><img src="images/icon_exp.webp" alt="プレイヤーEXP"></span></span>
              ${goldCount ? `<span class="zss-reward-chip zfs-first-clear-gem" title="強化素材・金 ×${goldCount}" aria-label="強化素材・金 ${goldCount}個">
                <span class="zss-reward-icon"><img src="images/item_exp_gold.webp" alt="強化素材・金"></span>
                <span class="zfs-gem-count">×${goldCount}</span>
              </span>` : ''}
              ${isVerdant ? `<span class="zss-reward-chip zfs-first-clear-gem" title="初回クリア報酬：創世pt ×${firstClearShinjuPt}" aria-label="初回のみ 創世pt ${firstClearShinjuPt}">
                <span class="zss-reward-icon"><img src="images/shinju_aura.webp" alt="創世pt"></span>
                <span class="zfs-gem-count">×${firstClearShinjuPt}</span>
                <span class="zfs-first-label">初回のみ・創世pt</span>
              </span>` : `<span class="zss-reward-chip zfs-first-clear-gem" title="初回クリア報酬：結晶 ×${firstClearGems}" aria-label="初回のみ 結晶 ${firstClearGems}個">
                <span class="zss-reward-icon"><img src="images/icon_gem.webp" alt="結晶"></span>
                <span class="zfs-gem-count">×${firstClearGems}</span>
                <span class="zfs-first-label">初回のみ</span>
              </span>`}
            </span>
          </div>
        </div>
        ${buildEventStageRecordHtml(stageId)}
        <span class="zss-arrow" aria-hidden="true">›</span>
      </div>`;
  }

  function showRhythmStageSelect(options = {}) {
    if (typeof window.requireChapter03ContentUnlock === 'function' && !window.requireChapter03ContentUnlock()) return false;
    closeFacelessStageSelect();
    const immediate = !!(options && options.immediate);
    const overlay = document.createElement('div');
    // 無貌の天使と同じ画面（idとCSSを共用）。閉じる処理も共通。
    overlay.id = 'shooting-faceless-stage-select';
    overlay.className = 'zfs-screen zfs-rhythm';
    if (immediate) { overlay.classList.add('show'); overlay.style.transition = 'none'; }
    overlay.innerHTML = `
      <div class="zfs-surface">
        <div class="zfs-pagehead">
          <button type="button" class="zfs-back" onclick="closeFacelessStageSelect()" aria-label="戻る">〈 戻る</button>
          <h2 class="zfs-heading zfs-heading-split"><span class="zfs-heading-main">律動</span><span class="zfs-heading-sub">仮面舞踏会</span></h2>
          <div class="zfs-ornament" aria-hidden="true"><span>✦</span></div>
        </div>
        <div class="zfs-scroll">
          <div class="zfs-list" aria-label="律動・難易度選択">
            ${buildRhythmStageCard(SHOOTING_STAGE_ID.RHYTHM_ADVANCED, '01', '上級')}
            ${buildRhythmStageCard(SHOOTING_STAGE_ID.RHYTHM_TEST, '02', '最上級')}
            ${buildRhythmStageCard(SHOOTING_STAGE_ID.RHYTHM_ULTRA, '03', '超級')}
          </div>
        </div>
      </div>`;
    document.body.appendChild(overlay);
    fitStageSelectHeading(overlay);
    void syncShootingClearedStagesFromServer();
    if (!immediate) requestAnimationFrame(() => overlay.classList.add('show'));
    else requestAnimationFrame(() => { if (overlay.isConnected) overlay.style.transition = ''; });
    return true;
  }

  window.openRhythmStage = openRhythmStage;
  window.showRhythmStageSelect = showRhythmStageSelect;

  // build1659: SPECIAL STAGE「樹獣の森」難易度選択（律動と同じ画面の作り）
  function openVerdantStage(stageId) {
    if (typeof window.requireChapter03ContentUnlock === 'function' && !window.requireChapter03ContentUnlock()) return false;
    window.__shootingReturnContext = { type: 'verdantStageSelect' };
    closeFacelessStageSelect();
    window.openShootingEvent({ stageId: String(stageId || '') });
  }
  function showVerdantStageSelect(options = {}) {
    if (typeof window.requireChapter03ContentUnlock === 'function' && !window.requireChapter03ContentUnlock()) return false;
    closeFacelessStageSelect();
    const immediate = !!(options && options.immediate);
    const overlay = document.createElement('div');
    overlay.id = 'shooting-faceless-stage-select';
    overlay.className = 'zfs-screen zfs-rhythm zfs-verdant';
    if (immediate) { overlay.classList.add('show'); overlay.style.transition = 'none'; }
    const card = (id, no, title) => buildRhythmStageCard(id, no, title).replace(/openRhythmStage\(/g, 'openVerdantStage(');
    overlay.innerHTML = `
      <div class="zfs-surface">
        <div class="zfs-pagehead">
          <button type="button" class="zfs-back" onclick="closeFacelessStageSelect()" aria-label="戻る">〈 戻る</button>
          <h2 class="zfs-heading zfs-heading-split"><span class="zfs-heading-main">樹獣の森</span><span class="zfs-heading-sub">VERDANT</span></h2>
          <div class="zfs-ornament" aria-hidden="true"><span>✦</span></div>
        </div>
        <div class="zfs-scroll">
          <p class="zfs-verdant-lead">樹獣の女王と配下は、動くと成長し、熟した「成長の実」を吸うと一気に成長する。実を撃ち壊すか、捕縛で動きを封じて、開花する前に倒せ。</p>
          <div class="zfs-list" aria-label="樹獣の森・難易度選択">
            ${card(SHOOTING_STAGE_ID.VERDANT_ADVANCED, '01', '上級')}
            ${card(SHOOTING_STAGE_ID.VERDANT_SUPER, '02', '最上級')}
          </div>
        </div>
      </div>`;
    document.body.appendChild(overlay);
    fitStageSelectHeading(overlay);
    void syncShootingClearedStagesFromServer();
    if (!immediate) requestAnimationFrame(() => overlay.classList.add('show'));
    else requestAnimationFrame(() => { if (overlay.isConnected) overlay.style.transition = ''; });
    return true;
  }
  window.openVerdantStage = openVerdantStage;
  window.showVerdantStageSelect = showVerdantStageSelect;

  window.closeFacelessStageSelect = closeFacelessStageSelect;
  window.openFacelessStage = openFacelessStage;
  // build1437: 楽園 -ノア- のステージ選択(index.html)も共通zss-cardで描画するため公開。
  window.buildShootingStageSelectGimmickChips = buildFacelessGimmickHtml;
  window.buildShootingStageSelectAttributes = buildStageSelectAttributePreview;

  function stopCountdownMovementLoop() {
    if (countdownMoveRafId) {
      cancelAnimationFrame(countdownMoveRafId);
      countdownMoveRafId = 0;
    }
  }

  function countdownMovementLoop(ts) {
    if (!state || state.ended || state.finishing || !state.countdown) {
      countdownMoveRafId = 0;
      return;
    }

    // カウントダウン中は「プレイヤー移動だけ」を動かす。
    // 敵・弾・自動射撃・ミッション時間・DoT等は一切開始しない。
    const dt = Math.min(0.032, Math.max(0, (ts - (prevTs || ts)) / 1000));
    prevTs = ts;

    if (!state.paused && !state.koTransition) {
      updateMovement(dt, ts, true);
    }

    renderHud();
    countdownMoveRafId = requestAnimationFrame(countdownMovementLoop);
  }

  // build922: 開始カウントダウン専用のPAUSE対応タイマー。
  // PAUSE中は残り時間を消費しないため、3・2・1・STARTの途中で
  // メニューを開いてもカウントダウンが裏で進行しない。
  function scheduleCountdownDelay(delayMs, callback) {
    let remaining = Math.max(0, Number(delayMs || 0));
    let lastTs = performance.now();

    const tick = () => {
      if (!state || state.ended || state.finishing || !state.countdown) return;

      const now = performance.now();
      if (!state.paused) {
        remaining -= Math.max(0, now - lastTs);
      }
      lastTs = now;

      if (remaining <= 0) {
        callback();
        return;
      }

      setTimeout(tick, Math.min(50, Math.max(16, remaining)));
    };

    setTimeout(tick, Math.min(50, Math.max(16, remaining)));
  }

  function runStartCountdown() {
    // build1983: すべての戦闘開始でここを通る（build1981 の記録はリトライ時しか通らない場所にあった）
    try { zsDiagBattleSnapshot('battle-start'); decideCanvasSpriteMode(); resetSpriteHealth(performance.now()); } catch (_) {}
    // 中断復帰など、ボス登場演出を経由しない開始経路でもBGMを必ず同期。
    if (!shootingBattleBgmSessionActive) activateShootingBattleBgm(false);
    else window.syncShootingBattleBgm();

    const countdown = document.getElementById('shooting-countdown');
    const copy = document.getElementById('shooting-start-copy');
    if (!state || !countdown) return;

    stopCountdownMovementLoop();

    state.countdown = true;
    state.running = false;
    if (copy) copy.classList.add('hide');
    // build1685: SUB MISSION・異常のバナーは戦闘開始前（カウントダウン中）に出し、開始と同時に消す
    const poVariant = getPhaseOdysseyVariant();
    if (poVariant) { state.poBannerShown = true; showPhaseOdysseyVarietyBanner(poVariant); }

    countdown.classList.remove('chapter4-rule-phase', 'chapter4-rule-first', 'ready-phase', 'number-phase', 'start-phase');

    const span = countdown.querySelector('span');
    // 全ステージ共通：前回のカウントダウン文字（START）がDOMに残ったまま
    // showされると、ARE YOU READYより前に一瞬STARTが見えるため、
    // オーバーレイを表示する前に必ず文字とアニメーションクラスを消す。
    if (span) {
      span.textContent = '';
      span.classList.remove('pop', 'ready-pop', 'start-pop');
      span.style.removeProperty('animation');
      span.style.removeProperty('opacity');
      span.style.removeProperty('transform');
      span.style.removeProperty('filter');
    }

    countdown.classList.add('show');
    countdown.setAttribute('aria-hidden', 'false');
    const sequence = [
      ...(isChapter43BossStage() ? [
        { text:'全2WAVE', phase:'chapter4-rule-phase', hold:1400 },
        { text:'サキエルを撃破せよ', phase:'chapter4-rule-phase', hold:1800 }
      ] : []),
      ...(isHorizontalControlReversed() ? [
        // CH05: この注意文だけは4.4秒間、文字そのものを表示し続ける。
        // ready-popを付けると1.18秒でopacity:0になるため専用フラグで固定表示する。
        { text:'このステージでは、\n左右の操作が反転します', phase:'chapter4-rule-phase', hold:4400, holdVisible:true }
      ] : []),
      // build1686: 位相回遊でSUB MISSIONのバナーを出す階は、読めるようにARE YOU READYを少し長く
      { text:'ARE YOU READY', phase:'ready-phase',  hold:getPhaseOdysseyVariant() ? 2300 : 1250 },
      { text:'3',             phase:'number-phase', hold:850 },
      { text:'2',             phase:'number-phase', hold:850 },
      { text:'1',             phase:'number-phase', hold:850 },
      { text:'START',         phase:'start-phase',  hold:1050 }
    ];
    // build2041: エンカウント戦は「START」だけ（ARE YOU READY・3・2・1なし）
    if (isRpgEncounterStage()) sequence.splice(0, sequence.length, { text:'START', phase:'start-phase', hold:650 });

    // 「ARE YOU READY」表示前からキャラを掴めるよう、
    // 戦闘ロジックとは独立した移動専用RAFを先に開始する。
    prevTs = performance.now();
    countdownMoveRafId = requestAnimationFrame(countdownMovementLoop);

    let i = 0;

    const showStep = () => {
      if (!state || state.ended || !span) return;

      const step = sequence[i];
      countdown.classList.remove('chapter4-rule-phase', 'chapter4-rule-first', 'ready-phase', 'number-phase', 'start-phase');
      countdown.classList.add(step.phase);
      if (step.phase === 'number-phase') hidePhaseOdysseyVarietyBanner(); // build1686: 3・2・1の前に消す
      if (isChapter04Stage() && i === 0) countdown.classList.add('chapter4-rule-first');

      if (step.html) {
        span.innerHTML = step.html;
      } else {
        span.textContent = step.text;
      }
      span.classList.remove('pop', 'ready-pop', 'start-pop');

      // 前ステップの固定表示指定を必ず解除してから次の演出へ。
      span.style.removeProperty('animation');
      span.style.removeProperty('opacity');
      span.style.removeProperty('transform');
      span.style.removeProperty('filter');
      span.style.removeProperty('line-height');
      span.style.removeProperty('white-space');
      void span.offsetWidth;

      if (step.holdVisible) {
        // 反転操作MESSAGE:
        // 4.4秒のhold中ずっと可視状態を維持し、終了直後にARE YOU READYへ切り替える。
        span.style.setProperty('animation', 'none', 'important');
        span.style.setProperty('opacity', '1', 'important');
        span.style.setProperty('transform', 'none', 'important');
        span.style.setProperty('filter', 'none', 'important');
      } else if (
        step.phase === 'chapter4-rule-phase' ||
        step.phase === 'ready-phase'
      ) {
        span.classList.add('ready-pop');
      } else if (step.phase === 'start-phase') {
        span.classList.add('start-pop');
      } else {
        span.classList.add('pop');
      }

      i += 1;

      if (i < sequence.length) {
        scheduleCountdownDelay(step.hold, showStep);
        return;
      }

      // STARTはカウントダウン演出として完結させる。
      // START表示中はまだ敵弾・自動射撃・時間計測を開始せず、
      // 文字が消えた直後から実戦を開始する。
      scheduleCountdownDelay(step.hold, () => {
        if (!state || state.ended || !state.countdown) return;

        countdown.classList.remove('show', 'ready-phase', 'number-phase', 'start-phase');
        countdown.setAttribute('aria-hidden', 'true');
        stopCountdownMovementLoop();

        state.countdown = false;
        state.running = true;
        hidePhaseOdysseyVarietyBanner(); // build1685
        const resumeElapsedMs = Math.max(0, Number(state.resumeElapsedMsPending || 0));
        const isResumingBattle = resumeElapsedMs > 0;
        state.startedAt = performance.now() - resumeElapsedMs;
        state.resumeElapsedMsPending = 0;
        state.lastShotAt = -9999;
        state.lastBossShotAt = -9999;

        // START直後の実座標から戦闘AIの軌道へ短くブレンドする。
        state.bossMotionBlendFromX = Number(state.boss?.x || 0);
        state.bossMotionBlendFromY = Number(state.boss?.y || 0);
        state.bossMotionBlendStartedAt = state.startedAt;

        // カウントダウン中から指を置いたままでも、
        // 現在位置を基準に相対ドラッグをそのまま継続する。
        rebaseTouchDragToPlayer();
        beginHeldShotAfterCountdown(performance.now()); // build1660: 指を置いたままSTART → 溜め撃ちもすぐ開始

        prevTs = performance.now();
        if (isChapter101TutorialStage()) {
          startChapter101TutorialBattle();
        }
        if (isChapter102TutorialStage()) {
          startChapter102TutorialBattle();
        }
        if (isChapter202ElementTutorialStage() && !isResumingBattle) {
          // build1245: 敵が盤面に現れて属性バリアが見えてから説明する。
          state.ch202ElementTutorialPending = true;
          state.ch202ElementTutorialShown = false;
        }
        if (rafId) cancelAnimationFrame(rafId);
        rafId = requestAnimationFrame(gameLoop);
      }, step.hold);
    };

    // 戦闘画面が見えた直後に一拍置いて開始。
    setTimeout(showStep, 260);
  }

  function respawnScoreAttackBoss(now) {
    if (!isScoreAttackStage() || !state || !state.boss || state.ended || state.finishing) return false;
    const readyAt = Number(state.scoreAttackBossRespawnAt || 0);
    if (!readyAt || now < readyAt) return false;
    state.scoreAttackBossRespawnAt = 0;
    state.boss.hpMax = SCORE_ATTACK_BOSS_HP;
    state.boss.hp = SCORE_ATTACK_BOSS_HP;
    state.boss.gaugeHp = SCORE_ATTACK_BOSS_HP;
    state.boss.gaugeHps = null;
    state.boss.gauges = 1;
    state.boss.phase = 1;
    renderHud();
    return true;
  }

  // ============================================================
  // build1877: 隠しステージ「夜明け」— 区間の切り替え
  //  ボス役を「中ボス → トワ → 中ボス …」と6回切り替える。中ボスのギミック（カミラ／シエン／テスト）は
  //  既存のものをそのまま使い、切り替えのたびに前のボスの状態とDOMを片付ける。
  // ============================================================
  function teardownTowaDawnBossMechanics() {
    try { teardownTestBody(); } catch (_) {}
    try { if (state.shien) clearShienTechniqueFx(state.shien); } catch (_) {}
    try { setShienBleedGauge(false); } catch (_) {}
    try { clearCamillaBind(); } catch (_) {}
    try { setTower15Blackout(false); } catch (_) {}
    (state.party || []).forEach(m => { if (m) { m.shienBleeding = false; } });
    if (state.camilla && state.camilla.web) { try { state.camilla.web.els.forEach(el => el.remove()); } catch (_) {} }
    state.camilla = null;
    state.shien = null;
    state.tower15 = null;
    document.querySelectorAll('.camilla-web-line,.camilla-trap,.camilla-drain-orb,.camilla-heal-num,.shien-smoke-fx,.shien-technique-zone,.shien-technique-caption,.shien-dash-path,.shien-split-clone,.tb-fx,#shooting-tower15-blackout')
      .forEach(el => el.remove());
    document.getElementById(PLAYER_ID)?.classList.remove('shien-bleeding');
    const bossEl = document.getElementById(BOSS_ID);
    bossEl?.classList.remove('camilla-unit-boss', 'shien-blade-boss', 'shien-smoke', 'shien-dash-warning', 'violence-charge-warning', 'defeated');
    // 手下（カミラの子蜘蛛など）も片付ける
    (state.normalEnemies || []).forEach(e => { try { e && e.el && e.el.remove(); e && e.hpEl && e.hpEl.remove(); e && e.elementEl && e.elementEl.remove(); e && e.layer && e.layer.remove(); } catch (_) {} });
    state.normalEnemies = [];
    // build1978: 前衛の固有スキルの残り（予告・巣・罠・捕縛）を片付ける
    try { cleanupDawnShien(); cleanupDawnCamilla(false); } catch (_) {}
    state.dawnShien = null; state.dawnCam = null;
    // build1977: PHASE I の前衛（倒れた後の残りも含む）を確実に片付ける
    (state.dawnGuardRefs || []).forEach(g => { try { g && g.el && g.el.remove(); g && g.hpEl && g.hpEl.remove(); g && g.elementEl && g.elementEl.remove(); } catch (_) {} });
    document.querySelectorAll('.dawn-trio-unit').forEach(el => el.remove());
    document.querySelectorAll('.dawn-whiteout-veil,.dawn-ray-warning,.dawn-ray-beam,.dawn-float-text').forEach(el=>el.remove());
    // build1970: 白飛びの予兆・PHASE Iの光の膜を解除
    const rootT = document.getElementById(ROOT_ID);
    if (rootT) { rootT.classList.remove('dawn-whiteout-pending','dawn-warp-out','dawn-warp-hidden','dawn-warp-in'); rootT.removeAttribute('data-dawn-guarded'); rootT.removeAttribute('data-dawn-phantom'); }
  }
  function applyTowaDawnSegment(seg, now) {
    teardownTowaDawnBossMechanics(); // 演出の間に前のボスの処理が状態を作り直していても、ここで確実に片付ける
    selectedEnemyId = seg.enemyId;
    BOSS = getCurrentShootingEnemy();
    const hps = (seg.gaugeHps || [5000]).map(v => Math.max(1, Number(v) || 1));
    const total = hps.reduce((a, b) => a + b, 0);
    state.boss.hp = total;
    state.boss.hpMax = total;
    state.boss.gaugeHps = hps.slice();
    state.boss.gauges = hps.length;
    state.boss.gaugeHp = hps[0];
    state.boss.phase = 1;
    state.boss.element = seg.element || BOSS.element || 'light';
    state.bossMotionOriginAt = getBossMotionTime(now);
    state.bossMotionResumeBlend = null;
    state.lastBossShotAt = now;
    state.nextBossDangerAt = now + 4200;
    const root = document.getElementById(ROOT_ID);
    if (root) {
      root.setAttribute('data-dawn-role', seg.role || 'mid');
      root.setAttribute('data-dawn-act', String(seg.act || 1));
      root.setAttribute('data-boss-phase', '1');
      if (BOSS.raidVisualId) root.setAttribute('data-raid-boss', BOSS.raidVisualId); else root.removeAttribute('data-raid-boss');
    }
    const bossEl = document.getElementById(BOSS_ID);
    if (bossEl) {
      bossEl.src = getSelectedBossImage();
      bossEl.alt = BOSS.name || '';
      bossEl.style.setProperty('--enemy-scale', String(getResponsiveBossDisplayScale()));
      bossEl.classList.remove('dawn-boss-enter');
      void bossEl.offsetWidth;
      bossEl.classList.add('dawn-boss-enter');
    }
    syncBossPhaseVisual();
    try { renderBossElementIcon(); } catch (_) {}
    ensureBossWeaknessBarrier();
  }
  function advanceTowaDawnSegment() {
    const segs = selectedStage.towaDawn.segments || [];
    const cur = Number(state.towaDawnSeg || 0);
    if (cur >= segs.length - 1) return false; // 最後のトワ：通常の撃破へ
    const now = performance.now();
    const prev = segs[cur];
    const next = segs[cur + 1];
    teardownTowaDawnBossMechanics(); // build1977: 前衛の参照が残っているうちに片付ける
    state.towaDawnSeg = cur + 1;
    state.dawnSegSwitching = true;
    state.dawnTrioCreated=false;state.dawnFinalStartedAt=0;state.dawnRayAt=0;state.dawnBarrageAt=0;
    state.dawnFinalPhase=0;state.dawnGuardRefs=null;state.dawnGuardEnraged='';state.dawnVeilBroken=false;state.dawnTowaMaterialized=true;state.magaEyeNextAt=0;
    state.dawnWarp=null;state.dawnWarpAnchor=null;state.dawnWarpNextClock=0;state.dawnRestrainedSince=0;state.dawnEmpowered=false;
    state.phaseTransition = true;
    clearProjectiles();
    teardownTowaDawnBossMechanics();
    showTowaDawnBreak(prev, next);
    // 撃破の余韻 → 次のボスが現れる
    const root = document.getElementById(ROOT_ID);
    if (root) root.classList.add('boss-phase-pause');
    state.boss.hp = 1; // 切替演出の間は撃破扱いにしない
    setTimeout(() => {
      if (!state || state.ended || state.finishing || !isTowaDawnStage()) return;
      applyTowaDawnSegment(next, performance.now());
      state.dawnSegSwitching = false;
      state.dawnEmpowered = false; // build1980: 切り替え中（HP1）を「半分以下」と数えない
      renderHud();
    }, 900);
    setTimeout(() => {
      if (!state || state.ended || state.finishing || !isTowaDawnStage()) return;
      state.phaseTransition = false;
      state.lastBossShotAt = performance.now();
      state.lastShotAt = performance.now();
      if (root) root.classList.remove('boss-phase-pause');
      renderHud();
    }, 2600);
    renderHud();
    return true;
  }
  // 中ボス撃破＝光の膜が割れてトワが前へ／トワ撃破＝光の粒になって退き、次の中ボス
  function showTowaDawnBreak(prev, next) {
    const arena = document.getElementById('shooting-arena');
    if (arena) {
      const fx = document.createElement('div');
      fx.className = 'dawn-break' + (next.role === 'towa' ? ' is-veil' : ' is-fade');
      fx.setAttribute('aria-hidden', 'true');
      fx.innerHTML = '<i class="db-flash"></i><i class="db-ring"></i><i class="db-ring r2"></i>' +
        Array.from({ length: 14 }, (_, i) => `<b style="transform:rotate(${(i * 360 / 14).toFixed(0)}deg);--d:${(60 + (i % 4) * 26)}px"><s></s></b>`).join('');
      fx.style.setProperty('--bx', `${Number(state.boss.x || 0)}px`);
      fx.style.setProperty('--by', `${Number(state.boss.y || 0)}px`);
      arena.appendChild(fx);
      setTimeout(() => fx.remove(), 1700);
    }
    const shade = document.querySelector('.dawn-towa-shade');
    if (shade) shade.remove();
    setTimeout(() => {
      try { showFacelessBattleCut(next.title || '', next.sub || ''); } catch (_) {}
    }, 520);
  }
  // 中ボスの間、トワは奥（光の膜の中）から光弾で援護する
  function ensureTowaDawnShade() {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return null;
    let el = arena.querySelector('.dawn-towa-shade');
    if (!el) {
      el = document.createElement('div');
      el.className = 'dawn-towa-shade';
      el.setAttribute('aria-hidden', 'true');
      el.innerHTML = '<i class="dts-veil"></i><img src="images/towa_light_battle.webp" alt="" draggable="false"><i class="dts-glint"></i>';
      arena.appendChild(el);
    }
    return el;
  }
  // 夜明け Phase1（build1977）: トワ（ボス・最後方・透過）＋ シエン（左）・カミラ（右）の個別HP。
  function ensureDawnTrio(now) {
    if (state.dawnTrioCreated || Number(state.towaDawnSeg || 0)!==0) return;
    const arena=document.getElementById('shooting-arena');
    if (!arena || !state.boss || !BOSS) return;
    const guards=(selectedStage.towaDawn && selectedStage.towaDawn.guards) || [];
    const w=arena.clientWidth||390,h=arena.clientHeight||700;
    const created=[];
    guards.forEach(gd=>{
      const def=getShootingEnemy(gd.enemyId);
      if (!def) return;
      const hp=Math.max(1,Number(gd.hp||8000));
      const guard=createNormalEnemy({...def,hp,behavior:'dawn_guard_v1',uiScale:Number(gd.scale||1.45),scoreValue:1000},now,{noElementIcon:true});
      if(!guard)return;
      guard.dawnGuard=gd.role;
      guard.hp=guard.hpMax=hp;
      guard.x=guard.baseX=w*Number(gd.x||.5);
      guard.y=guard.baseY=Math.max(120,h*Number(gd.y||.3));
      guard.el.classList.add('dawn-trio-unit','dawn-trio-'+gd.role);
      positionUnit(guard.el,guard.x,guard.y);
      positionMiniEnemyHp(guard);
      renderMiniEnemyHp(guard);
      state.normalEnemies.push(guard);
      state.normalSpawned++;
      created.push(guard);
    });
    normalizeDawnGuardSizes(created); // build1978: 見た目の大きさをそろえる
    if (created.length===guards.length && created.length) {
      state.dawnTrioCreated=true;
      state.dawnGuardRefs=created; // 撃破の検知用（倒れた後も参照を持つ）
      state.dawnGuardEnraged='';
      state.dawnVeilBroken=false;
      state.dawnTowaMaterialized=false;
      state.dawnPhantomHintAt=now+2400; // 開幕少ししてから「トワに攻撃は当たらない」と案内
    }
  }
  // build1970: 盤面に短い文字を浮かべる（光の膜・猛り などの合図）
  function showDawnFloatText(x,y,text,variant){
    const arena=document.getElementById('shooting-arena');
    if(!arena)return;
    if(variant)arena.querySelectorAll('.dawn-float-text.is-'+variant).forEach(n=>n.remove()); // 同じ種類の合図は最新だけ
    const el=document.createElement('div');
    el.className='dawn-float-text'+(variant?' is-'+variant:'');
    el.setAttribute('aria-hidden','true');
    el.textContent=text;
    // 画面端・上部HUDに掛からないよう、文字幅に合わせて位置を収める
    const w=arena.clientWidth||390;
    arena.appendChild(el);
    const half=Math.min(w/2,(el.offsetWidth||0)/2+8);
    el.style.left=`${Math.round(Math.max(half,Math.min(w-half,Number(x)||0)))}px`;
    el.style.top=`${Math.round(Math.max(150,Number(y)||0))}px`;
    setTimeout(()=>el.remove(),1700);
  }
  // build1970: 小さな光の破裂（ガード撃破・光の膜の消滅）
  function showDawnBurst(x,y,small){
    const arena=document.getElementById('shooting-arena');
    if(!arena)return;
    const fx=document.createElement('div');
    fx.className='dawn-break is-fade'+(small?' is-small':'');
    fx.setAttribute('aria-hidden','true');
    fx.innerHTML='<i class="db-flash"></i><i class="db-ring"></i>'+
      Array.from({length:10},(_,i)=>`<b style="transform:rotate(${(i*36).toFixed(0)}deg);--d:${(40+(i%3)*20)}px"><s></s></b>`).join('');
    fx.style.setProperty('--bx',`${Number(x)||0}px`);
    fx.style.setProperty('--by',`${Number(y)||0}px`);
    arena.appendChild(fx);
    setTimeout(()=>fx.remove(),1500);
  }
  // build1970: ガードが残っているのにカミラのHPが1で止まった時の案内（連打されないよう間引く）
  function showDawnGuardHint(){
    if(!state||!state.boss)return;
    const now=performance.now();
    if(now<Number(state.dawnGuardHintAt||0))return;
    state.dawnGuardHintAt=now+4200;
    showDawnFloatText(state.boss.x,Number(state.boss.y||0)+70,'トワに攻撃は届かない ― シエンとカミラを倒せ','veil');
  }
  function fireDawnArc(x,y,now,count,speed,danger=false){
    const aim=getEnemyAimPosition();
    const base=Math.atan2(aim.y-y,aim.x-x);
    for(let i=0;i<count;i++){
      const angle=base+(i-(count-1)/2)*(.14+(danger?.10:.03));
      const b=makeProjectile('shooting-enemy-bullet '+(danger?'shooting-danger-bullet dawn-lethal':'dawn-light-bullet'),x,y,
        Math.cos(angle)*speed,Math.sin(angle)*speed,danger?999999:155);
      if(b){b.attackElement='light';if(danger){b.dangerDrift=true;b.dangerDriftSpeed=speed;b.dangerDriftHeading=angle;b.dangerDriftPhase=i*1.57;b.dangerDriftTurnRate=.55;b.dangerExpireAt=now+13000;}appendEnemyProjectile(b);}
    }
  }
  // Phase1のシエン斬撃・トワ4即死弾を、既存敵弾と同じ衝突系に乗せる。
  // build1970: 片方が倒れると残った方が猛る（攻撃間隔 guardEnrageScale 倍）。両方倒れるとカミラの光の膜が消える。
  function getDawnGuardIntervalScale(role){
    const enraged=state&&state.dawnGuardEnraged;
    if(!enraged||enraged!==role)return 1;
    return Math.max(.5,Math.min(1,Number(selectedStage?.towaDawn?.guardEnrageScale||.78)));
  }
  function updateDawnGuardEvents(now){
    const refs=state.dawnGuardRefs||[];
    if(!refs.length)return;
    let fallen=null;
    refs.forEach(g=>{ if(g&&!g.dawnFallen&&!(g.hp>0)){ g.dawnFallen=true; fallen=g; } });
    const alive=refs.filter(g=>g&&g.hp>0);
    const root=document.getElementById(ROOT_ID);
    if(root){
      root.setAttribute('data-dawn-guarded',alive.length?'1':'0');
      root.setAttribute('data-dawn-phantom',state.dawnTowaMaterialized?'0':'1');
    }
    // 透けている間はトワのHPを減らさない（ULTなどの直接ダメージ対策）
    if(!state.dawnTowaMaterialized&&state.boss&&state.boss.hpMax>0&&state.boss.hp<state.boss.hpMax){
      state.boss.hp=state.boss.hpMax; state.boss.gaugeHp=Number(state.boss.gaugeHps?.[0]||state.boss.hpMax);
    }
    if(!state.dawnTowaMaterialized&&state.dawnPhantomHintAt&&now>=state.dawnPhantomHintAt){
      state.dawnPhantomHintAt=0;
      showDawnFloatText(state.boss.x,Number(state.boss.y||0)+70,'トワに攻撃は届かない ― シエンとカミラを倒せ','veil');
    }
    if(!fallen)return;
    showDawnBurst(fallen.x,fallen.y,true);
    if(alive.length===1&&!state.dawnGuardEnraged){
      const survivor=alive[0];
      state.dawnGuardEnraged=survivor.dawnGuard;
      survivor.el&&survivor.el.classList.add('dawn-trio-enraged');
      showDawnFloatText(survivor.x,Number(survivor.y||0)+56,survivor.dawnGuard==='camilla'?'カミラが猛る':'シエンが猛る','rage');
    }
    if(!alive.length&&!state.dawnTowaMaterialized){
      // 2体とも倒した：トワが実体化する
      state.dawnTowaMaterialized=true;
      state.dawnVeilBroken=true;
      state.tower15=null; // 実体化してから弾幕を始める
      state.lastBossShotAt=now+900;
      if(state.boss){
        state.boss.hp=state.boss.hpMax;
        showDawnBurst(state.boss.x,state.boss.y,false);
        showDawnFloatText(state.boss.x,Number(state.boss.y||0)+70,'トワが実体化した','veil');
        const bossEl=document.getElementById(BOSS_ID);
        if(bossEl){ bossEl.classList.remove('dawn-boss-materialize'); void bossEl.offsetWidth; bossEl.classList.add('dawn-boss-materialize'); }
      }
      if(root)root.setAttribute('data-dawn-phantom','0');
      renderHud();
    }
  }
  // ============================================================
  // build1978: PHASE I 前衛の固有スキルと移動
  //  既存のシエン（半月斬り・突進）／カミラ（赤い浮遊弾・蜘蛛の巣レーザー・足元の罠・子蜘蛛と吸血）の処理を流用する。
  //  既存の処理は「BOSSの位置・属性」を読むので、呼ぶ間だけ state.boss の位置と属性を前衛のものに差し替える。
  //  周期は「敵の時計」（停止系ULTの間は進まない）で数える。
  // ============================================================
  function withDawnGuardAsBoss(g, element, fn) {
    if (!state || !state.boss || !g) return;
    const bx = state.boss.x, by = state.boss.y, be = state.boss.element;
    state.boss.x = g.x; state.boss.y = g.y; state.boss.element = element;
    try { fn(); } finally { state.boss.x = bx; state.boss.y = by; state.boss.element = be; }
  }
  // 画像の不透明部分の高さを測り、前衛の見た目の大きさをそろえる（測れない時は設定の scale のまま）
  function normalizeDawnGuardSizes(list) {
    const target = Math.max(40, Number(selectedStage?.towaDawn?.guardVisibleHeight || 92));
    const responsive = Number(getResponsiveCombatScaleProfile()?.normalEnemy || 1);
    (list || []).forEach(g => {
      const el = g && g.el;
      if (!el) return;
      const apply = () => {
        try {
          const nw = el.naturalWidth, nh = el.naturalHeight;
          if (!nw || !nh) return;
          const cw = 96, ch = Math.max(1, Math.round(96 * nh / nw));
          const cv = document.createElement('canvas'); cv.width = cw; cv.height = ch;
          const cx = cv.getContext('2d', { willReadFrequently: true });
          cx.drawImage(el, 0, 0, cw, ch);
          const data = cx.getImageData(0, 0, cw, ch).data;
          releaseCanvasNow(cv); // build1981
          let top = -1, bottom = -1;
          for (let y = 0; y < ch && top < 0; y++) for (let x = 0; x < cw; x++) if (data[(y * cw + x) * 4 + 3] > 40) { top = y; break; }
          for (let y = ch - 1; y >= 0 && bottom < 0; y--) for (let x = 0; x < cw; x++) if (data[(y * cw + x) * 4 + 3] > 40) { bottom = y; break; }
          if (top < 0 || bottom <= top) return;
          const box = Math.max(1, el.clientWidth || 66); // 枠（object-fit:contain）
          const fit = Math.min(box / nw, box / nh);
          const visible = (bottom - top + 1) / ch * nh * fit; // 拡大率1の時の見た目の高さ
          if (visible < 8) return;
          const scale = clamp(target / visible, 0.6, 3.2) * responsive;
          el.style.setProperty('--enemy-scale', String(scale));
          g._hw = 0; g._hh = 0;
          try { measureUnitSize(g); positionMiniEnemyHp(g); } catch (_) {}
        } catch (_) { /* 画像が読めない環境では設定の scale のまま */ }
      };
      if (el.complete && el.naturalWidth) apply(); else el.addEventListener('load', apply, { once: true });
    });
  }
  function getDawnClock(now) { return getBossMotionElapsedSeconds(now) * 1000; }

  // ---- シエン：揺れながら移動し、半月斬りと突進を交互に。合間に3WAY斬撃 ----
  function cleanupDawnShien() {
    const sh = state && state.dawnShien;
    if (!sh) return;
    [sh.zone, sh.path].forEach(el => el && el.remove());
    sh.zone = null; sh.path = null; sh.mode = 'gone';
  }
  function updateDawnShienAI(now, clock, g, w, h, arena, halted) {
    const cfg = selectedStage.towaDawn.shienSkills || {};
    const sh = state.dawnShien || (state.dawnShien = { mode:'idle', next: clock + Number(cfg.firstAtMs || 3000), tech: 0, nextSlash: clock + 1600,
      homeX: g.x, homeY: g.y, struck:false, hit:false });
    if (!halted) {
      if (sh.mode === 'idle') {
        const t = clock / 1000;
        g.x = clamp(sh.homeX + Math.sin(t * .7) * w * .08, 40, w * .5 - 20);
        g.y = sh.homeY + Math.sin(t * 1.3) * 14;
        // 3WAY斬撃
        if (clock >= sh.nextSlash) {
          sh.nextSlash = clock + Number(cfg.slashEveryMs || 3400) * getDawnGuardIntervalScale('shien');
          const a = getEnemyAimPosition(), base = Math.atan2(a.y - g.y, a.x - g.x);
          for (let k = -1; k <= 1; k++) {
            const angle = base + k * .25;
            const b = makeProjectile('shooting-enemy-bullet shien-slash-bullet', g.x, g.y, Math.cos(angle) * 260, Math.sin(angle) * 260, 220);
            if (b) { b.attackElement = 'dark'; appendEnemyProjectile(b); }
          }
        }
        if (clock >= sh.next) {
          sh.tech = (sh.tech + 1) % 2;
          sh.startAt = clock; sh.struck = false; sh.hit = false;
          if (sh.tech === 1) {
            // 半月斬り：自機のいる側の大半を斬る（反対側の端が安全地帯）
            sh.mode = 'half';
            sh.idx = Number(state.player.x) >= w * .5 ? 1 : 2;
            sh.zone = document.createElement('div');
            sh.zone.className = 'shien-technique-zone ' + (sh.idx === 1 ? 'half-right' : 'half-left');
            arena.appendChild(sh.zone);
            layoutShienZone(sh, sh.idx, w, h);
          } else {
            // 突進：自機の位置へ予告線 → 一気に駆け抜けて戻る
            sh.mode = 'dash';
            const px = Number(state.player.x), py = Number(state.player.y);
            const dx = px - g.x, dy = py - g.y, d = Math.hypot(dx, dy) || 1;
            const over = 70;
            sh.from = { x: g.x, y: g.y };
            sh.to = { x: clamp(px + dx / d * over, 24, w - 24), y: clamp(py + dy / d * over, 60, h - 24) };
            sh.path = document.createElement('div');
            sh.path.className = 'shien-dash-path';
            sh.path.style.setProperty('--shien-band', `${SHIEN_DASH_HIT_R * 2}px`);
            positionShienLine(sh.path, sh.from.x, sh.from.y, sh.to.x, sh.to.y);
            arena.appendChild(sh.path);
            g.el && g.el.classList.add('shien-dash-warning');
          }
        }
      } else if (sh.mode === 'half') {
        const local = clock - sh.startAt, warn = Number(cfg.halfWarnMs || 1300);
        if (local >= warn && !sh.struck) {
          sh.struck = true;
          sh.zone && sh.zone.classList.add('cut');
          spawnShienSlashFx(sh.idx, w, h, arena);
          shakeShienStrike();
          withDawnGuardAsBoss(g, 'dark', () => hitShienBlade(now, sh, sh.idx, w, h)); // 命中で出血
        }
        if (local >= warn + 530) {
          sh.zone && sh.zone.remove(); sh.zone = null;
          sh.mode = 'idle'; sh.next = clock + Number(cfg.everyMs || 4600) * getDawnGuardIntervalScale('shien');
        }
      } else if (sh.mode === 'dash') {
        const local = clock - sh.startAt, warn = Number(cfg.dashWarnMs || 900), dashMs = Number(cfg.dashMs || 420), back = Number(cfg.returnMs || 700);
        if (local < warn) {
          g.x = sh.from.x + Math.sin(local / 30) * 1.5; // 溜めで小刻みに震える
        } else if (local < warn + dashMs) {
          if (!sh.struck) { sh.struck = true; sh.path && sh.path.classList.add('striking'); shakeShienStrike(); g.el && g.el.classList.remove('shien-dash-warning'); }
          const p = shienSmooth((local - warn) / dashMs);
          const prev = { x: g.x, y: g.y };
          g.x = sh.from.x + (sh.to.x - sh.from.x) * p;
          g.y = sh.from.y + (sh.to.y - sh.from.y) * p;
          if (!sh.hit && !state.koTransition && now >= Number(state.player.invulnUntil || 0)) {
            const member = getActiveMember();
            if (member && member.hp > 0 && shienSegmentHit({ x:Number(state.player.x), y:Number(state.player.y) }, prev, { x:g.x, y:g.y }, SHIEN_DASH_HIT_R)) {
              const hp0 = member.hp;
              damagePlayer(now, SHIEN_DASH_DAMAGE, 'boss-heavy', 'dark', 'boss-charge');
              if (member.hp < hp0) { sh.hit = true; triggerPlayerHitScreenShake(); flashShienHit(arena); }
            }
          }
        } else if (local < warn + dashMs + back) {
          if (sh.path) { sh.path.remove(); sh.path = null; }
          const p = shienSmooth((local - warn - dashMs) / back);
          g.x = sh.to.x + (sh.from.x - sh.to.x) * p;
          g.y = sh.to.y + (sh.from.y - sh.to.y) * p;
        } else {
          g.x = sh.from.x; g.y = sh.from.y;
          sh.mode = 'idle'; sh.next = clock + Number(cfg.everyMs || 4600) * getDawnGuardIntervalScale('shien');
        }
      }
    }
    positionUnit(g.el, g.x, g.y); positionMiniEnemyHp(g);
  }

  // ---- カミラ：漂いながら赤い浮遊弾・蜘蛛の巣レーザー・足元の罠・子蜘蛛（吸血でカミラが回復） ----
  function cleanupDawnCamilla(removeSpiders) {
    const cm = state && state.dawnCam;
    if (cm) {
      if (cm.web) { cm.web.els.forEach(el => el.remove()); cm.web = null; }
      (cm.traps || []).forEach(t => t.el && t.el.remove()); cm.traps = [];
      cm.spiderQueue = null; cm.gone = true;
    }
    if (removeSpiders) (state.normalEnemies || []).forEach(e => { if (e && e.camSpider && e.hp > 0) removeCamillaSpider(e); });
  }
  function updateDawnCamillaDrain(now, cm, cam, arena) {
    const member = getActiveMember();
    const spiders = state.normalEnemies.filter(e => e && e.camSpider && e.hp > 0 && e.el);
    if (!spiders.length) { cm.activeId = state.activeCharacterId; return; }
    if (cm.activeId !== state.activeCharacterId) { // 交代で振り払える
      cm.activeId = state.activeCharacterId;
      spiders.forEach(e => {
        if (e.camState !== 'latched') return;
        e.camState = 'crawl'; e.camRecoverAt = now + 1200;
        e.x += e.latchDx * 2.4; e.y += e.latchDy * 2.4 - 20;
        e.el.classList.remove('camilla-spider-latched');
      });
      return;
    }
    if (!member || member.hp <= 0 || state.koTransition) return;
    let drained = 0, healed = 0;
    for (const e of spiders) {
      if (e.camState !== 'latched') continue;
      if (now - Number(e.latchedAt || now) >= CAMILLA_LATCH_MAX_MS) { removeCamillaSpider(e); continue; }
      if (now < Number(e.nextDrainAt || 0)) continue;
      e.nextDrainAt = now + 1000;
      const baseDrain = Math.max(1, Math.floor(Number(member.hpMax || 0) * CAMILLA_DRAIN_RATE));
      const dmg = Math.min(member.hp, applyStatusResist(member, baseDrain));
      member.hp = Math.max(0, member.hp - dmg);
      drained += dmg;
      const before = cam.hp;
      cam.hp = Math.min(cam.hpMax, cam.hp + CAMILLA_HEAL_PER_TICK * Math.max(0, Math.min(1, dmg / baseDrain)));
      healed += Math.round(cam.hp - before);
      withDawnGuardAsBoss(cam, 'fire', () => spawnCamillaDrainFx(e.x, e.y, arena, 0));
    }
    if (drained > 0) {
      showDamageNumber(state.player.x, state.player.y, drained, 'player', false, '');
      if (healed > 0) { withDawnGuardAsBoss(cam, 'fire', () => spawnCamillaDrainFx(Number(state.player.x), Number(state.player.y), arena, healed)); try { renderMiniEnemyHp(cam); } catch (_) {} }
      renderHud();
      if (member.hp <= 0) beginPlayerDefeat();
    }
  }
  function updateDawnCamillaAI(now, clock, g, w, h, arena, halted) {
    const cfg = selectedStage.towaDawn.camillaSkills || {};
    const cm = state.dawnCam || (state.dawnCam = { ringIndex:0, web:null, traps:[], spiderQueue:null, activeId: state.activeCharacterId,
      nextRing: clock + 1800, nextWeb: clock + Number(cfg.webFirstAtMs || 5200), nextTrap: clock + Number(cfg.trapFirstAtMs || 3600),
      nextSpider: clock + Number(cfg.spiderFirstAtMs || 8000), homeX: g.x, homeY: g.y });
    if (!halted) {
      const t = clock / 1000;
      g.x = clamp(cm.homeX + Math.sin(t * .45 + 1) * w * .09, w * .5 + 20, w - 40);
      g.y = cm.homeY + Math.sin(t * .9) * 14;
      const sc = getDawnGuardIntervalScale('camilla');
      withDawnGuardAsBoss(g, 'fire', () => {
        if (clock >= cm.nextRing) { cm.nextRing = clock + Number(cfg.ringEveryMs || 2400) * sc; fireCamillaBloodRing(cm, { ringN: Number(cfg.ringN || 8), ringSpeed: Number(cfg.ringSpeed || 58) }); }
        if (!cm.web && clock >= cm.nextWeb) { cm.nextWeb = clock + Number(cfg.webEveryMs || 9500) * sc; createCamillaWeb(cm, { webWarn: Number(cfg.webWarnMs || 1100) }, clock, w, h, arena); }
        if (clock >= cm.nextTrap) { cm.nextTrap = clock + Number(cfg.trapEveryMs || 7500) * sc; placeCamillaTraps(cm, { trapN: Number(cfg.trapN || 2) }, clock, w, h, arena); }
        if (clock >= cm.nextSpider) {
          cm.nextSpider = clock + Number(cfg.spiderEveryMs || 13000) * sc;
          const alive = state.normalEnemies.filter(e => e && e.camSpider && e.hp > 0).length;
          if (alive < 8) spawnCamillaSpiders(cm, { spiderN: Number(cfg.spiderN || 4) }, now);
        } else if (cm.spiderQueue) flushCamillaSpiderQueue(cm, now);
        updateCamillaWeb(now, cm, clock);
        updateCamillaTraps(now, cm, { bindMs: Number(cfg.bindMs || 1400) }, clock);
      });
      updateDawnCamillaDrain(now, cm, g, arena);
    }
    positionUnit(g.el, g.x, g.y); positionMiniEnemyHp(g);
  }

  function updateDawnTrio(now){
    if (!state || Number(state.towaDawnSeg||0)!==0) return;
    ensureDawnTrio(now);
    updateDawnGuardEvents(now);
    const arena=document.getElementById('shooting-arena');
    if(!arena)return;
    const w=arena.clientWidth||390,h=arena.clientHeight||700;
    const halted=state.phaseTransition||state.ended||state.finishing||state.koTransition||isEntireEnemyActionLocked(now)||now<getBossLockUntil(now);
    const clock=getDawnClock(now);
    try{ ensureShienStyle(); ensureCamillaStyle(); }catch(_){}
    const refs=state.dawnGuardRefs||[];
    const shien=refs.find(e=>e&&e.dawnGuard==='shien');
    const camilla=refs.find(e=>e&&e.dawnGuard==='camilla');
    if(shien&&shien.hp>0) updateDawnShienAI(now,clock,shien,w,h,arena,halted);
    else if(state.dawnShien&&state.dawnShien.mode!=='gone') cleanupDawnShien();
    if(camilla&&camilla.hp>0) updateDawnCamillaAI(now,clock,camilla,w,h,arena,halted);
    else if(state.dawnCam&&!state.dawnCam.gone) cleanupDawnCamilla(true); // 主が倒れると子蜘蛛も消える
    try{ updateShienBleed(now,halted); }catch(_){}
    if(halted)return;
    const cfg=selectedStage.towaDawn||{};
    // 透けたトワ：最後方から漂う即死弾（4発）
    if(isTowaDawnPhantom()&&state.boss&&now>=Number(state.dawnLethalAt||0)){
      if(!state.dawnLethalAt){ state.dawnLethalAt=now+3200; }
      else{
        state.dawnLethalAt=now+Math.max(2500,Number(cfg.phantomLethalEveryMs||5600));
        fireDawnArc(state.boss.x,Number(state.boss.y||0)+20,now,4,93,true);
      }
    }
  }
  // Phase2（build1970で再構成）：
  //  ・光輪：速さの違う2重のリングを交互にずらして撃つ（旧：1.35秒ごとの単リング。毎秒の弾数は同じ）
  //  ・RAY：予告線が太りながら収束 → 発射。2ゲージ目は3本の扇
  //  ・夜明けの刻：白飛びは tower15 の暗転1系統。開始前に予兆、白飛び中は残り時間バー
  function getDawnFinalConfig(phase){
    const all=(selectedStage&&selectedStage.towaDawn&&selectedStage.towaDawn.final)||{};
    return all[phase]||all[1]||{ringEveryMs:2700,ringCount:22,raysPerVolley:1,rayEveryMs:6500,rayTelegraphMs:750};
  }
  function fireDawnRings(now,cfg,elapsed){
    const n=Math.max(8,Number(cfg.ringCount||22));
    const bx=state.boss.x,by=state.boss.y;
    const rot=elapsed*.00037;
    const layers=[{speed:128,off:0},{speed:162,off:Math.PI/n}];
    layers.forEach(layer=>{
      for(let i=0;i<n;i++){
        const a=2*Math.PI*i/n+rot+layer.off;
        const b=makeProjectile('shooting-enemy-bullet dawn-light-bullet',bx,by,Math.cos(a)*layer.speed,Math.sin(a)*layer.speed,160);
        if(b){b.attackElement='light';appendEnemyProjectile(b);}
      }
    });
  }
  function fireDawnRayVolley(now,cfg){
    const arena=document.getElementById('shooting-arena');
    if(!arena||!state||!state.boss)return;
    const aim=getEnemyAimPosition(),sx=state.boss.x,sy=state.boss.y;
    const base=Math.atan2(aim.y-sy,aim.x-sx);
    const count=Math.max(1,Math.round(Number(cfg.raysPerVolley||1)));
    const spread=Number(cfg.raySpread||.36);
    const angles=Array.from({length:count},(_,i)=>base+(i-(count-1)/2)*spread);
    const tele=Math.max(450,Number(cfg.rayTelegraphMs||750));
    const seg=Number(state.towaDawnSeg||0);
    const warnings=angles.map(angle=>{
      const line=document.createElement('div');
      line.className='dawn-ray-warning';
      line.setAttribute('aria-hidden','true');
      line.style.left=`${sx}px`;line.style.top=`${sy}px`;
      line.style.setProperty('--ang',`${angle}rad`);
      line.style.setProperty('--tele',`${tele}ms`);
      arena.appendChild(line);
      return line;
    });
    setTimeout(()=>{
      warnings.forEach(el=>el.remove());
      if(!state||state.ended||state.finishing||!isTowaDawnStage()||Number(state.towaDawnSeg||0)!==seg)return;
      const t=performance.now();
      if(state.phaseTransition||isEnemyProjectileSpawnSuppressed(t))return; // 光トワのULT（弾生成停止）中は撃たない
      angles.forEach(angle=>{
        const fx=document.createElement('div');
        fx.className='dawn-ray-beam';
        fx.setAttribute('aria-hidden','true');
        fx.style.left=`${sx}px`;fx.style.top=`${sy}px`;
        fx.style.setProperty('--ang',`${angle}rad`);
        fx.innerHTML='<i></i>';
        arena.appendChild(fx);
        setTimeout(()=>fx.remove(),420);
      });
      const player=state.player;
      if(!player)return;
      const dx=player.x-sx,dy=player.y-sy;
      const hit=angles.some(angle=>{
        const forward=dx*Math.cos(angle)+dy*Math.sin(angle);
        const lateral=Math.abs(dx*Math.sin(angle)-dy*Math.cos(angle));
        return forward>0&&lateral<15;
      });
      if(hit)damagePlayer(t,Math.max(1,Number(selectedStage?.towaDawn?.rayDamage||280)),'raw','light','dawn-ray');
    },tele);
  }
  // ============================================================
  // build1978: PHASE II ワープ
  //  ・敵の時計で一定間隔ごとに、トワが光にほどけて消え、ランダムな場所にふわっと現れる（消えている間は当たらない・撃たない）。
  //  ・停止系の効果（時間停止・スタン・拘束・吸引など）を受けて breakFreeMs（2秒）たつと、効果を振りほどいてワープで抜け出す。
  //    ワープ自体は実時間で進む（停止中でも動く）。
  // ============================================================
  function isDawnBossRestrained(now){
    if(!state||state.paused||state.ultCutinActive||state.arnoSlashActive)return false;
    return getBossLockUntil(now)>now+30 || now<Number(state.boss?.camillaWebRootUntil||0);
  }
  function breakDawnRestraint(now){
    // 停止系の効果をここで打ち切る（トワが振りほどいた）
    state.bossStunUntil=Math.min(Number(state.bossStunUntil||0),now);
    state.bossGrabUntil=Math.min(Number(state.bossGrabUntil||0),now);
    state.gojoPurpleBossFreezeUntil=Math.min(Number(state.gojoPurpleBossFreezeUntil||0),now);
    state.noahMovementFreezeUntil=Math.min(Number(state.noahMovementFreezeUntil||0),now);
    state.angeEnemyFreezeUntil=Math.min(Number(state.angeEnemyFreezeUntil||0),now);
    state.fullEnemyStopUntil=Math.min(Number(state.fullEnemyStopUntil||0),now);
    if(state.boss) state.boss.camillaWebRootUntil=Math.min(Number(state.boss.camillaWebRootUntil||0),now);
    if(state.eltenaBlackHole&&state.eltenaBlackHole.phase==='active') state.eltenaBlackHole.activeUntil=Math.min(Number(state.eltenaBlackHole.activeUntil||0),now);
    showDawnFloatText(state.boss.x,Number(state.boss.y||0)+70,'トワが拘束を振りほどいた','rage');
  }
  function setDawnWarpClass(stage){
    const root=document.getElementById(ROOT_ID);
    if(!root)return;
    root.classList.toggle('dawn-warp-out',stage==='out');
    root.classList.toggle('dawn-warp-hidden',stage==='hidden');
    root.classList.toggle('dawn-warp-in',stage==='in');
  }
  function startDawnWarp(now,reason){
    const wc=selectedStage.towaDawn.warp||{};
    state.dawnWarp={stage:'out',at:now,reason};
    setDawnWarpClass('out');
    showDawnBurst(state.boss.x,state.boss.y,true);
  }
  function updateDawnWarp(now,phase,arena){
    const wc=selectedStage.towaDawn.warp;
    if(!wc||!state.boss)return;
    const w=arena.clientWidth||390,h=arena.clientHeight||700;
    const clock=getDawnClock(now);
    // 拘束からの離脱（実時間で2秒）
    if(!state.dawnWarp&&!state.phaseTransition&&isDawnBossRestrained(now)){
      if(!state.dawnRestrainedSince) state.dawnRestrainedSince=now;
      else if(now-state.dawnRestrainedSince>=Number(wc.breakFreeMs||2000)){
        state.dawnRestrainedSince=0;
        breakDawnRestraint(now);
        startDawnWarp(now,'break');
      }
    } else if(!isDawnBossRestrained(now)) state.dawnRestrainedSince=0;
    // 定期ワープ（敵の時計）
    if(!state.dawnWarp&&!state.phaseTransition&&!isEntireEnemyActionLocked(now)){
      if(!state.dawnWarpNextClock) state.dawnWarpNextClock=clock+Number(wc.firstAtMs||7000);
      else if(clock>=state.dawnWarpNextClock){
        state.dawnWarpNextClock=clock+Number((wc.everyMs||{})[phase]||10000);
        startDawnWarp(now,'timer');
      }
    }
    const wp=state.dawnWarp;
    if(!wp)return;
    const age=now-wp.at;
    if(wp.stage==='out'&&age>=Number(wc.outMs||450)){
      wp.stage='hidden';wp.at=now;setDawnWarpClass('hidden');
      // 次の出現位置：今の位置から離れた、画面上部のどこか
      let nx=w*.5,ny=h*.2;
      for(let i=0;i<6;i++){
        nx=w*(.18+Math.random()*.64); ny=h*(.12+Math.random()*.2);
        if(Math.hypot(nx-state.boss.x,ny-state.boss.y)>w*.28)break;
      }
      state.dawnWarpAnchor={x:nx,y:ny};
    }else if(wp.stage==='hidden'&&age>=Number(wc.hiddenMs||450)){
      wp.stage='in';wp.at=now;setDawnWarpClass('in');
      const a=state.dawnWarpAnchor||{x:state.boss.x,y:state.boss.y};
      state.boss.x=a.x;state.boss.y=a.y;
      showDawnBurst(a.x,a.y,false);
    }else if(wp.stage==='in'&&age>=Number(wc.inMs||500)){
      state.dawnWarp=null;setDawnWarpClass('');
      state.lastBossShotAt=now; // 現れてすぐは撃たない
      if(state.tower15) state.tower15.lastAimAt=now;
    }
  }
  // build1980: 強化の演出（光が弾け、「トワの光が強まる」）。弾は消さない
  function empowerTowaDawn(now){
    const root=document.getElementById(ROOT_ID);
    if(root){ root.classList.remove('boss-phase-flash'); void root.offsetWidth; root.classList.add('boss-phase-flash'); setTimeout(()=>root.classList.remove('boss-phase-flash'),650); }
    showDawnBurst(state.boss.x,state.boss.y,false);
    showDawnFloatText(state.boss.x,Number(state.boss.y||0)+70,'トワの光が強まる','rage');
    const bossEl=document.getElementById(BOSS_ID);
    if(bossEl&&!state.dawnWarp){ bossEl.classList.remove('dawn-boss-materialize'); void bossEl.offsetWidth; bossEl.classList.add('dawn-boss-materialize'); }
    try{ shakeShienStrike(); }catch(_){}
  }
  function updateDawnFinal(now){
    if(!state||Number(state.towaDawnSeg||0)!==1||state.ended||state.finishing)return;
    const arena=document.getElementById('shooting-arena');if(!arena)return;
    const root=document.getElementById(ROOT_ID);
    const paused=state.phaseTransition||isEntireEnemyActionLocked(now);
    if(!state.dawnFinalStartedAt)state.dawnFinalStartedAt=now;
    const elapsed=now-state.dawnFinalStartedAt;
    // build1980: HPが半分を下回った瞬間に強化
    if(!state.dawnEmpowered&&!state.dawnSegSwitching&&!state.phaseTransition&&state.boss.hpMax>0&&state.boss.hp>0&&
       state.boss.hp<=state.boss.hpMax*Number(selectedStage.towaDawn?.empowerAtRatio??.5)){
      state.dawnEmpowered=true;
      empowerTowaDawn(now);
    }
    const phase=getTowaDawnPower();
    const cfg=getDawnFinalConfig(phase);
    const t15=state.tower15;
    updateDawnWarp(now,phase,arena);
    // 強化の瞬間：白飛びを一度切り、少し間を置いてから新しい周期で始める
    if(state.dawnFinalPhase!==phase){
      const first=!state.dawnFinalPhase;
      state.dawnFinalPhase=phase;
      if(!first){
        if(t15){ if(t15.blackoutUntil){ t15.blackoutUntil=0; setTower15Blackout(false); } t15.nextBlackoutAt=now+6500; }
        state.dawnRayAt=now+3600;
        state.dawnBarrageAt=now+2400;
      }
    }
    if(!paused&&Number(cfg.ringEveryMs)>0&&now>=Number(state.dawnBarrageAt||0)){ // build1977: ringEveryMs:0 で光輪なし
      state.dawnBarrageAt=now+Math.max(900,Number(cfg.ringEveryMs));
      fireDawnRings(now,cfg,elapsed);
    }
    if(!paused&&!state.dawnWarp&&now>=Number(state.dawnRayAt||0)){
      if(!state.dawnRayAt){ state.dawnRayAt=now+3000; }
      else {
        state.dawnRayAt=now+Math.max(2500,Number(cfg.rayEveryMs||6500));
        if(!isEnemyProjectileSpawnSuppressed(now)) fireDawnRayVolley(now,cfg);
      }
    }
    // 夜明けの刻：予兆と残り時間バー
    const echo=getTower15Config()||{};
    const warnMs=Math.max(0,Number(echo.whiteoutWarnMs||1400));
    const active=isTowaDawnWhiteoutActive(now);
    const pending=!active&&!paused&&t15&&Number(t15.nextBlackoutAt||0)>0&&Number(t15.nextBlackoutAt)-now<=warnMs;
    if(pending)ensureTower15Blackout(); // 予兆は白飛びの幕を薄く使う（初回はまだ幕がない）
    if(root)root.classList.toggle('dawn-whiteout-pending',!!pending);
    if(active){
      const bo=echo.blackout||{};
      const dur=Math.max(1,Number((bo[phase]||bo[1]||{}).durationMs||4800));
      const left=Math.max(0,Math.min(1,(Number(t15.blackoutUntil)-now)/dur));
      const meter=document.querySelector('#shooting-tower15-blackout .dawn-wo-meter i');
      if(meter)meter.style.transform=`scaleX(${left.toFixed(3)})`;
    }
  }
  function updateTowaDawn(now) {
    if (!isTowaDawnStage() || !state || !state.boss) return;
    const seg = getTowaDawnSegment();
    if (!seg) return;
    if(Number(state.towaDawnSeg||0)===0) updateDawnTrio(now);
    else updateDawnFinal(now);
    // PHASE1の光トワは独立HPの1体のみ。旧装飾用シルエットは生成しない。
    const shade = document.querySelector('.dawn-towa-shade');
    if (shade) shade.remove();
    const mid = seg.role === 'phantom' && isTowaDawnPhantom(); // build1977: 透けている間だけ援護射撃
    const rootD = document.getElementById(ROOT_ID);
    if (rootD && rootD.getAttribute('data-dawn-role') !== (seg.role || 'mid')) rootD.setAttribute('data-dawn-role', seg.role || 'mid');
    if (!mid || state.ended || state.finishing || state.phaseTransition || state.koTransition) return;
    if (isEntireEnemyActionLocked(now) || now < Number(state.towaDarkUntil || 0)) { state.towaDawnSupportAt = Math.max(Number(state.towaDawnSupportAt || 0), now + 600); return; }
    const cfg = selectedStage.towaDawn || {};
    if (!state.towaDawnSupportAt) state.towaDawnSupportAt = now + 2600;
    if (now < state.towaDawnSupportAt) return;
    state.towaDawnSupportAt = now + Math.max(1500, Number(cfg.supportEveryMs || 3600));
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const sx = Number(state.boss.x || 0), sy = Number(state.boss.y || 0) + 20;
    const aim = getEnemyAimPosition();
    const base = Math.atan2(aim.y - sy, aim.x - sx);
    const n = 5, spread = 0.62, speed = 150;
    for (let i = 0; i < n; i++) {
      const a = base - spread / 2 + spread * (i / (n - 1));
      const b = makeProjectile('shooting-enemy-bullet dawn-light-bullet', sx, sy, Math.cos(a) * speed, Math.sin(a) * speed, Math.max(1, Number(cfg.supportDamage || 150)));
      if (b) { b.attackElement = 'light'; state.enemyBullets.push(b); }
    }
  }

  // build1970: 夜明けの決着。ゲームループが止まる前に白飛び・予兆を確実に解除し、光が満ちる
  function playTowaDawnFinale() {
    try { setTower15Blackout(false); } catch (_) {}
    if (state && state.tower15) state.tower15.blackoutUntil = 0;
    document.querySelectorAll('.dawn-ray-warning,.dawn-ray-beam,.dawn-float-text').forEach(el => el.remove());
    const root = document.getElementById(ROOT_ID);
    if (root) root.classList.remove('dawn-whiteout-pending','dawn-warp-out','dawn-warp-hidden','dawn-warp-in');
    if (state) state.dawnWarp = null;
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    arena.querySelectorAll('.dawn-finale').forEach(el => el.remove());
    const fx = document.createElement('div');
    fx.className = 'dawn-finale';
    fx.setAttribute('aria-hidden', 'true');
    // build1971b: 下から昇る太陽は外し、トワの位置から広がる光＋白い幕＋横一線の光にした
    fx.innerHTML = '<i class="df-veil"></i><i class="df-burst"></i><i class="df-line"></i><strong>夜が、明ける</strong>';
    fx.style.setProperty('--bx', `${Number(state?.boss?.x || 0)}px`);
    fx.style.setProperty('--by', `${Number(state?.boss?.y || 0)}px`);
    arena.appendChild(fx);
    setTimeout(() => fx.remove(), 3200);
  }

  function beginBossDefeat() {
    if (!state || state.ended || state.finishing) return;
    // build1682: エクリプスは光状態の間だけ撃破できる。無敵中に他経路でHPが0になっても戻す。
    if (isEclipseImmune() && state.eclipse && Number(state.eclipse.lockHp) > 0) {
      state.boss.hp = Number(state.eclipse.lockHp);
      updateBossPhase();
      return;
    }

    // build1877: 夜明けは PHASE I（カミラ＋ガード2体）→ PHASE II（トワ -光の姿-）。最後のトワを倒すまで次の区間へ進む
    if (isTowaDawnStage() && Number(state.towaDawnSeg || 0)===0 &&
      (state.normalEnemies || []).some(e => e && e.dawnGuard && e.hp > 0)) {
      state.boss.hp=1; showDawnGuardHint(); renderHud(); return; // build1970: 光の膜で止まっていることを伝える
    }
    if (isTowaDawnStage() && state.dawnSegSwitching) { state.boss.hp = Math.max(1, Number(state.boss.hp || 0)); return; } // build1977
    if (isTowaDawnStage() && advanceTowaDawnSegment()) return;
    const towaDawnFinale = isTowaDawnStage(); // build1970: 最後のトワ撃破＝夜が明ける

    // build1662: デイリーレイド周回制。HP0で次の周へ（バトルは時間切れ・全滅まで続く）
    if (isRaidLapMode()) {
      advanceRaidLap();
      return;
    }

    if (isScoreAttackStage()) {
      // build1530: no premature results in this 60-second challenge.
      // Hold HP=0 for a short respawn interval; 0-HP enemies cannot be hit.
      if (Number(state.scoreAttackBossRespawnAt || 0) > 0) return;
      state.boss.hp = 0;
      state.scoreAttackBossDefeated = Number(state.scoreAttackBossDefeated || 0) + 1;
      state.scoreAttackBossRespawnAt = performance.now() + SCORE_ATTACK_BOSS_RESPAWN_MS;
      flashBossHit(true);
      renderHud();
      return;
    }

    // build1042: CH04-3は記憶のかけら未回収ゲートを撃破処理より優先。
    if (enforceChapter43MemoryGateBeforeDefeat()) return;

    // CH07: 完全シールド / 透明化中は撃破不可。
    if (isChapter07BossDamageBlocked()) {
      const restoreHp = Math.max(
        1,
        Number(state.ch07InitialShieldHp || 0),
        Number(state.ch07InvisibleHp || 0),
        Number(state.boss.hp || 0)
      );
      state.boss.hp = restoreHp;
      renderHud();
      return;
    }

    // CH07増殖後は分身体もすべて倒すまで本体の撃破を確定しない。
    if (
      isChapter07BossStage() &&
      (state.ch07ClonesSpawned || state.ch07EnhanceTransitionActive)
    ) {
      const clonesAlive = (state.facelessObjects || []).some(obj =>
        obj && obj.hp > 0 && obj.objectKind === 'remnant07_clone'
      );
      const clonesPending =
        state.ch07EnhanceTransitionActive ||
        Math.max(0, Number(state.ch07CloneSpawnRemaining || 0)) > 0;
      if (clonesAlive || clonesPending) {
        state.boss.hp = Math.max(1, Number(state.boss.hp || 0));
        renderHud();
        return;
      }
    }

    // build876: 通常ステージのCLEARは必ずevaluateNormalMission()経由に限定する。
    // BOSS専用経路が誤って呼ばれても、収集・時間・被弾条件を迂回させない。
    if (isNormalBattle()) {
      console.warn('[shooting] blocked boss-defeat clear path on normal stage', {
        stageId: getSelectedBaseStageId(),
        mission: getEffectiveNormalMission(),
        collectedItems: Number(state.collectedItems || 0),
      });
      evaluateNormalMission(performance.now());
      return;
    }

    if (isAmbushStage() && Number(state.ambushWave || 1) === 1) {
      beginAmbushWave2();
      return;
    }
    // build1518: Large SHOT/ULT bursts can take the boss directly from above
    // half HP to zero between animation frames. Previously beginBossDefeat
    // transitioned immediately, skipping both mask summons (wave 1 and wave 2).
    // Restore 1 HP until at least one summon is processed in each wave.
    if (isFacelessStage()) {
      if (!state.facelessSummonTriggered) {
        state.boss.hp = Math.max(1, Number(state.boss.hp || 0));
        const cfg = getFacelessConfig();
        const wave = Number(state.facelessWave || 1);
        const counts = Array.isArray(cfg?.waveObjectCount) ? cfg.waveObjectCount : [1, 2];
        beginFacelessObjectSummon(Number(counts[wave - 1] || (wave === 1 ? 1 : 2)), Number(cfg?.objectWays || 2));
        renderHud();
        return;
      }
      if (state.phaseTransition) {
        state.boss.hp = Math.max(1, Number(state.boss.hp || 0));
        renderHud();
        return;
      }
      if (Number(state.facelessWave || 1) === 1) {
        beginFacelessWave2();
        return;
      }
    }
    if (isStoryShootingStage() && !state.bossDefeatScoreAwarded) {
      state.bossDefeatScoreAwarded = true;
      state.score += Math.max(0, Number(selectedStage?.bossScoreValue || BOSS?.scoreValue || 6000));
    }
    // build2061: Once a memory boss has actually been defeated, a stale
    // KO/time-over callback may not override the legitimate victory.
    if (isMemoryBattleStage()) state.memoryBossDefeated = true;
    state.finishing = true;
    state.running = false;
    cancelAnimationFrame(rafId);

    // 撃破した瞬間に弾を止め、少し余韻を残してからリザルトへ。
    clearProjectiles();
    renderHud();

    // 全BOSSステージ共通：撃破エフェクトの余韻後、勝利セレモニーへ。
    // フェイスレスWAVE1では上の分岐でreturnするため誤表示しない。

    const boss = document.getElementById(BOSS_ID);
    const root = document.getElementById(ROOT_ID);
    if (boss) {
      boss.classList.remove('hit-flash', 'burst-hit');
      void boss.offsetWidth;
      boss.classList.add('defeated');
    }
    if (root) {
      root.classList.remove('boss-defeat-flash');
      void root.offsetWidth;
      root.classList.add('boss-defeat-flash');
    }

    // 大きめの撃破エフェクトを数回出す。
    createHit(state.boss.x, state.boss.y, true);
    setTimeout(() => createHit(state.boss.x - 24, state.boss.y + 12, true), 260);
    setTimeout(() => createHit(state.boss.x + 22, state.boss.y - 8, true), 520);
    if (towaDawnFinale) playTowaDawnFinale();

    setTimeout(() => {
      if (!state || state.ended) return;
      showStageClearSequence(() => {
        if (!state || state.ended) return;
        state.finishing = false;
        endGame(true);
      });
    }, towaDawnFinale ? 2300 : 1050);
  }


  const RESULT_RANK_THRESHOLDS = Object.freeze([
    { rank: 'S', score: 24000 },
    { rank: 'A', score: 20000 },
    { rank: 'B', score: 16000 },
    { rank: 'C', score: 12000 },
    { rank: 'D', score: 8000 },
  ]);

  // SCORE ATTACK専用ランク基準。
  // 通常シューティングの既存ランク基準には影響させない。
  const SCORE_ATTACK_RANK_THRESHOLDS = Object.freeze([
    { rank: 'S', score: 1500000 },
    { rank: 'A', score: 1000000 },
    { rank: 'B', score: 700000 },
    { rank: 'C', score: 400000 },
    { rank: 'D', score: 200000 },
  ]);

  function getResultRank(score, win) {
    const value = Number(score) || 0;

    // SCORE ATTACKは全滅/時間切れなどでクリア扱いにならなくても、
    // その時点までに稼いだスコアだけでランクを決定する。
    if (isScoreAttackStage()) {
      const hit = SCORE_ATTACK_RANK_THRESHOLDS.find(t => value >= t.score);
      return hit ? hit.rank : 'E';
    }

    // build2150: イベント「パラレル・ソワレ」専用ランク（討伐必須。S/Aはステージ設定 party.rankS/rankA）
    if (isPartyEventStage()) return getPartyResultRank(value, win);

    // build2063: 特別巡行「最恐 -デイノヴァ-」専用ランク判定。
    // サーバー claim_deinova_special_drop と S/A の閾値を一致させる（S 130万 / A 100万 / B クリア / E 敗北）。
    if (isDeinovaStage()) {
      if (!win) return 'E';
      if (value >= 1300000) return 'S';
      if (value >= 1000000) return 'A';
      return 'B';
    }

    // 通常シューティングは従来仕様を維持。
    if (!win) return 'E';
    const hit = RESULT_RANK_THRESHOLDS.find(t => value >= t.score);
    return hit ? hit.rank : 'E';
  }
  // build2007: 記憶決戦のRESULTのランクはスコアではなく記憶決戦の判定（A＝クリア／S＝Sランク条件でクリア）。
  //  勝利時はまず A を出し、サーバーの判定（memory_battle_claim_rank）が S なら S に差し替える。敗北は従来どおり E。
  //  ※ EXP 計算など他の用途の getResultRank はスコア基準のまま変えない。
  function getDisplayResultRank(score, win) {
    if (isMemoryBattleStage()) {
      if (!win) return 'E';
      const r = String(state && state.memoryResultRank || '').toUpperCase();
      return r === 'S' ? 'S' : 'A';
    }
    return getResultRank(score, win);
  }
  function applyMemoryResultRank(serverRank) {
    if (!isMemoryBattleStage() || !state || !state.lastResultWin) return;
    const r = String(serverRank || '').toUpperCase();
    if (r !== 'S' && r !== 'A') return;
    state.memoryResultRank = r;
    const el = document.getElementById('shooting-result-rank');
    if (el && el.textContent !== r) {
      el.textContent = r;
      el.setAttribute('data-rank', r);
      el.classList.remove('memory-rank-upgrade'); void el.offsetWidth; el.classList.add('memory-rank-upgrade');
    }
    try { saveShootingBestRank(state.stageId || (selectedStage && selectedStage.id), r); } catch (_) {}
  }


  // ============================================================
  // Clear rewards - STORY / SPECIAL EVENT / DAILY RAID
  // ============================================================
  // v281:
  // クリア時はプレイヤーEXPとコインを必ず付与する。
  // 進化素材は最大3枠。build1249ではCH02-03以降に経験値素材0～2個を別枠追加。
  // CHAPTER 01は進化素材を落とさず、共鳴石のみ5%で1個抽選する。
  // CHAPTER 02以降はstageNoに応じて追加ドロップ率を段階的に上げる。
  const SHOOTING_EVOLUTION_REWARD_POOL = Object.freeze([
    Object.freeze({ id: 'kyoumei_stone', name: '共鳴石', image: 'images/item_kyoumeistone.webp', rewardType: 'evolution' }),
    Object.freeze({ id: 'soul_vessel_fire', name: '魂の器(火)', image: 'images/type_fire.webp', rewardType: 'evolution' }),
    Object.freeze({ id: 'soul_vessel_aqua', name: '魂の器(水)', image: 'images/type_aqua.webp', rewardType: 'evolution' }),
    Object.freeze({ id: 'soul_vessel_wood', name: '魂の器(木)', image: 'images/type_wood.webp', rewardType: 'evolution' }),
    Object.freeze({ id: 'soul_vessel_dark', name: '魂の器(闇)', image: 'images/type_dark.webp', rewardType: 'evolution' }),
    Object.freeze({ id: 'soul_vessel_light', name: '魂の器(光)', image: 'images/type_light.webp', rewardType: 'evolution' }),
    Object.freeze({ id: 'shinju_nutrition', name: '聖樹の息吹', image: 'images/shinju_aura.webp', rewardType: 'shinju' }),
  ]);


  const SHOOTING_STORY_ITEM_POOL = Object.freeze(
    SHOOTING_EVOLUTION_REWARD_POOL.filter(item => item.rewardType === 'evolution')
  );

  // build1249:
  // CH02-03以降では、通常の追加素材とは別枠でキャラクター経験値素材を抽選する。
  // 個数: 0 / 1 / 2 を各1/3。
  // 種類: 銅50% / 銀30% / 金20%。
  const SHOOTING_STORY_LEVEL_EXP_REWARD_POOL = Object.freeze([
    Object.freeze({
      id: 'level_exp_small',
      name: '強化素材・銅',
      image: 'images/item_exp_bronze.webp',
      rewardType: 'level_exp',
      weight: 5,
    }),
    Object.freeze({
      id: 'level_exp_medium',
      name: '強化素材・銀',
      image: 'images/item_exp_silver.webp',
      rewardType: 'level_exp',
      weight: 3,
    }),
    Object.freeze({
      id: 'level_exp_large',
      name: '強化素材・金',
      image: 'images/item_exp_gold.webp',
      rewardType: 'level_exp',
      weight: 2,
    }),
  ]);

  function isStoryLevelExpRewardStage() {
    const stage = selectedStage || {};
    const chapter = Math.max(0, Math.floor(Number(stage.chapter || 0)));
    const stageNo = Math.max(0, Math.floor(Number(stage.stageNo || 0)));

    // build1249: メインストーリーの経験値素材は CH02-03 以降を継続対象にする。
    // 旧実装ではCH03-04で打ち切られており、CH04以降が対象外になっていた。
    if (chapter < 2) return false;
    if (chapter === 2) return stageNo >= 3;
    return chapter >= 3 && stageNo >= 1;
  }

  function pickWeightedStoryLevelExpMaterial() {
    const pool = SHOOTING_STORY_LEVEL_EXP_REWARD_POOL;
    const totalWeight = pool.reduce((sum, item) => sum + Math.max(0, Number(item.weight || 0)), 0);
    if (!pool.length || totalWeight <= 0) return null;

    let roll = Math.random() * totalWeight;
    for (const item of pool) {
      roll -= Math.max(0, Number(item.weight || 0));
      if (roll < 0) return item;
    }
    return pool[pool.length - 1] || null;
  }

  function pickStoryLevelExpMaterialDrops() {
    if (!isStoryLevelExpRewardStage()) return [];

    // build1262: CH02-03以降のSTORYでは経験値素材を必ず1～2個出す。
    // 旧実装は0～2個抽選だったため、対象ステージでもRESULTに1個も出ないケースがあった。
    const dropCount = 1 + Math.floor(Math.random() * 2);

    // 同じ素材が2回選ばれた場合は1行にまとめる。
    // secure reward RPCも同一run/materialの重複claimを許さないため、ここで集約する。
    const grouped = new Map();
    for (let i = 0; i < dropCount; i++) {
      const material = pickWeightedStoryLevelExpMaterial();
      if (!material) continue;
      const existing = grouped.get(material.id);
      if (existing) existing.count += 1;
      else grouped.set(material.id, { material, count: 1 });
    }
    return Array.from(grouped.values());
  }

  function getShootingStoryItemSlotRates() {
    const stage = selectedStage || {};
    const chapter = Math.max(1, Math.floor(Number(stage.chapter || 1)));
    const stageNo = Math.max(1, Math.floor(Number(stage.stageNo || 1)));

    // CHAPTER01は共鳴石5%だけ。魂の器など進化素材は出さない。
    if (chapter === 1) return [0.05];

    // 低難度の1ステージ目は追加ドロップをかなり絞る。
    // 2枠目・3枠目ほど大きく確率を落とし、最大3枠まで。
    const table = {
      1: [0.18, 0.04, 0.01],
      2: [0.28, 0.08, 0.02],
      3: [0.40, 0.15, 0.04],
      4: [0.55, 0.25, 0.08],
    };
    const base = table[Math.min(stageNo, 4)] || table[4];

    // 後半Chapterはわずかに底上げ。ただし上限は抑える。
    const chapterBonus = Math.min(0.12, Math.max(0, chapter - 2) * 0.025);
    return base.map((rate, index) => {
      const slotScale = index === 0 ? 1 : index === 1 ? 0.65 : 0.4;
      return Math.min(index === 0 ? 0.75 : index === 1 ? 0.40 : 0.15, rate + chapterBonus * slotScale);
    });
  }

  function pickStoryAdditionalItemDrops() {
    const stage = selectedStage || {};
    const chapter = Math.max(1, Math.floor(Number(stage.chapter || 1)));

    if (chapter === 1) {
      if (Math.random() >= 0.05) return [];
      const stone = SHOOTING_EVOLUTION_REWARD_POOL.find(item => item.id === 'kyoumei_stone');
      return stone ? [{ material: stone, count: 1 }] : [];
    }

    const rates = getShootingStoryItemSlotRates();
    const drops = [];
    const pool = Array.from(SHOOTING_STORY_ITEM_POOL);

    rates.slice(0, 3).forEach(rate => {
      if (!pool.length || Math.random() >= rate) return;
      const index = Math.floor(Math.random() * pool.length);
      const material = pool.splice(index, 1)[0];
      if (material) drops.push({ material, count: 1 });
    });

    return drops;
  }

  function getShootingClearRewardPlan() {
    const stage = selectedStage || {};

    // 聖樹の息吹は1個あたりの栄養値だけステージ種別で変える。
    // ドロップ「個数」はステージ種別ではなく最終スコアだけで決める。
    if (isRaidStage()) {
      return { nutritionExp: 150 };
    }

    if (isFacelessStage() || stage.eventId === 'bullet_hell_test') {
      const superDifficulty = stage.faceless && stage.faceless.difficulty === 'super';
      return { nutritionExp: superDifficulty ? 120 : 80 };
    }

    const chapter = Math.max(1, Number(stage.chapter || 1));
    const bossBonus = stage.type === 'boss' ? 1 : 0;
    return { nutritionExp: 30 + chapter * 10 + bossBonus * 20 };
  }

  function getShootingRewardCountRange(score) {
    const value = Math.max(0, Number(score || 0));
    if (value >= 1000000) return { min: 12, max: 12, label: '1,000,000+' };
    if (value >= 500000) return { min: 7, max: 8, label: '500,000–999,999' };
    if (value >= 300000) return { min: 4, max: 6, label: '300,000–499,999' };
    if (value >= 100000) return { min: 2, max: 4, label: '100,000–299,999' };
    return { min: 1, max: 2, label: '0–99,999' };
  }

  function rollShootingRewardCount(range) {
    const min = Math.max(1, Math.floor(Number(range && range.min || 1)));
    const max = Math.max(min, Math.floor(Number(range && range.max || min)));
    if (min === max) return min;
    return min + Math.floor(Math.random() * (max - min + 1));
  }

  function pickShootingEvolutionRewards(count = 2) {
    const pool = Array.from(SHOOTING_EVOLUTION_REWARD_POOL.filter(item => item.rewardType === 'evolution'));
    const picked = [];
    const target = Math.min(Math.max(1, Math.floor(Number(count || 2))), pool.length);

    while (picked.length < target && pool.length) {
      const index = Math.floor(Math.random() * pool.length);
      picked.push(pool.splice(index, 1)[0]);
    }
    return picked;
  }

  function pickDailyQuestMaterialRewards() {
    const cfg = getDailyQuestConfig();
    if (!cfg) return [];

    const count = Math.max(1, Math.floor(Number(cfg.rewardCount || 1)));
    const sourceIds = Array.isArray(cfg.rewardPool) && cfg.rewardPool.length
      ? Array.from(cfg.rewardPool)
      : [String(cfg.rewardId || '')].filter(Boolean);
    if (!sourceIds.length) return [];

    const picked = new Map();
    for (let i = 0; i < count; i++) {
      const id = sourceIds.length === 1
        ? sourceIds[0]
        : sourceIds[Math.floor(Math.random() * sourceIds.length)];
      const material = SHOOTING_EVOLUTION_REWARD_POOL.find(item => item.id === id);
      if (!material || material.rewardType !== 'evolution') continue;
      const current = picked.get(id);
      if (current) current.count += 1;
      else picked.set(id, { material, count: 1 });
    }
    return Array.from(picked.values());
  }

  function getShootingPlayerExpDifficulty() {
    const stage = selectedStage || {};
    if (isDailyQuestStage()) {
      return getDailyQuestConfig()?.level === 'advanced' ? 'hard' : 'normal';
    }
    if (isRaidStage()) return 'boss';
    if (isFacelessStage()) {
      return stage.faceless && stage.faceless.difficulty === 'super' ? 'boss' : 'hard';
    }
    if (stage.eventId === 'bullet_hell_test') return 'hard';
    if (stage.type === 'boss') return 'boss';
    return 'normal';
  }

  function getShootingPlayerExpReward() {
    // すこあた！は難易度・ランク・スコアに関係なくEXP 300固定。
    if (isScoreAttackStage()) return 300;

    const difficulty = getShootingPlayerExpDifficulty();
    const rank = getResultRank(state && state.score, true);

    // 本体の巡行EXP計算をそのまま流用する。
    // シューティングはクリア自体を報酬条件とし、周回でも通常倍率で付与する。
    if (typeof window.calcNodeExp === 'function') {
      try {
        return Math.max(1, Math.floor(Number(window.calcNodeExp(difficulty, rank, true) || 0)));
      } catch (err) {
        console.warn('[shooting reward] player exp calculation failed', err);
      }
    }

    // index側APIが未初期化でも報酬を欠損させないフォールバック。
    const base = difficulty === 'boss' ? 1000 : difficulty === 'hard' ? 500 : 250;
    const rankMul = rank === 'S' ? 1.5 : rank === 'A' ? 1.2 : rank === 'C' ? 0.7 : 1.0;
    return Math.max(1, Math.floor(base * rankMul));
  }

  function getShootingCoinReward(playerExp) {
    // build505: DAILY QUESTは難易度に関係なくコイン10,000固定。
    // 曜日別の進化素材報酬は既存dailyQuest設定をそのまま使用する。
    if (isDailyQuestStage()) return 10000;

    // v285:
    // コインは CHAPTERごとのベース + STAGE進行分。
    //
    // CHAPTER 01 base = 1,000
    // CHAPTER 02 base = 1,200
    // CHAPTER 03 base = 1,400
    // ...CHAPTERが1上がるごとにベース +200
    //
    // 各CHAPTER内では STAGEが1上がるごとに +300。
    // 例:
    // CH01-01 = 1,000 / CH01-02 = 1,300 / CH01-03 = 1,600 / CH01-04 = 1,900
    // CH02-01 = 1,200 / CH02-02 = 1,500 / CH02-03 = 1,800 / CH02-04 = 2,100
    const stage = selectedStage || {};
    const chapter = Math.max(1, Math.floor(Number(stage.chapter || 1)));
    const stageNo = Math.max(1, Math.floor(Number(stage.stageNo || 1)));
    const chapterBase = 1000 + ((chapter - 1) * 200);
    const stageBonus = (stageNo - 1) * 300;
    return chapterBase + stageBonus;
  }

  function grantCoinReward(amount) {
    const coin = Math.max(0, Math.floor(Number(amount || 0)));
    if (!coin || !window.userProfile) return false;

    const next = Math.max(0, Number(window.userProfile.coin || 0)) + coin;
    window.userProfile.coin = next;

    // v286: リザルト直後にヘッダーのコイン残高と端末キャッシュを即時同期。
    if (typeof window.refreshProfileHud === 'function') {
      window.refreshProfileHud();
    } else if (typeof window.updateMainUI === 'function') {
      window.updateMainUI();
    }

    if (typeof window.saveProfileToDB === 'function') {
      Promise.resolve(window.saveProfileToDB({
        coin: next,
        last_played: new Date().toISOString(),
      })).then(() => {
        if (typeof window.refreshProfileHud === 'function') window.refreshProfileHud();
      }).catch(err => {
        console.warn('[shooting reward] coin cloud save failed', err);
        if (typeof window.scheduleCloudSave === 'function') window.scheduleCloudSave();
      });
    } else if (typeof window.scheduleCloudSave === 'function') {
      window.scheduleCloudSave();
    }
    return true;
  }

  function grantPlayerExpReward(amount) {
    const exp = Math.max(0, Math.floor(Number(amount || 0)));
    if (!exp || !window.userProfile) return false;

    // v286:
    // addTotalScore() は旧セキュリティ仕様で無効化済みだったため、
    // リザルト上はEXPを獲得していてもHUDのtotal_scoreが更新されていなかった。
    // まず現在のプロフィールへ即時反映し、円形EXPリングを同期する。
    const before = Math.max(0, Number(window.userProfile.total_score || 0));
    const next = before + exp;
    window.userProfile.total_score = next;

    if (typeof window.refreshProfileHud === 'function') {
      window.refreshProfileHud();
    } else if (typeof window.updateMainUI === 'function') {
      window.updateMainUI();
    }

    // クラウド保存もベストエフォートで同期。
    // total_score/rankの権限制約がある環境では端末表示を巻き戻さない。
    if (typeof window.saveProfileToDB === 'function') {
      const rank = Math.max(1, Number(window.userProfile.rank || 1));
      Promise.resolve(window.saveProfileToDB({
        total_score: next,
        rank: rank,
        last_played: new Date().toISOString(),
      })).then(() => {
        if (typeof window.refreshProfileHud === 'function') window.refreshProfileHud();
      }).catch(err => {
        console.warn('[shooting reward] player exp cloud save skipped', err);
      });
    }
    return true;
  }

  function grantShinjuNutrition(exp, count) {
    // build896: Shinju reward issuance is server-authoritative.
    // Kept only as a compatibility hook for old callers.
    try {
      if (window.ShinjuProgress && typeof window.ShinjuProgress.refreshFromServer === 'function') {
        void window.ShinjuProgress.refreshFromServer();
      }
    } catch (_) {}
    return false;
  }

  function persistShootingEvolutionReward(materialId, amount) {
    // DAILY QUESTはsecure run tokenを発行しない既存仕様のため対象外。
    // STORY / SCORE ATTACK / EVENT / RAID系は、finish_secure_shooting_runで
    // run tokenが消費された後に専用RPCへ付与を確定させる。
    if (isDailyQuestStage()) return;

    const sb = window.zsSupabase;
    const userId = getShootingUserId();
    const runToken = String(state && state.secureRunToken || '').trim();
    if (!sb || typeof sb.rpc !== 'function' || !userId || !runToken) return;

    const finalizePromise = state && state.secureFinalizePromise
      ? state.secureFinalizePromise
      : Promise.resolve(null);

    void Promise.resolve(finalizePromise).then(async finalized => {
      if (!finalized) return;
      const res = await sb.rpc('claim_shooting_material_reward_secure', {
        p_user_id: userId,
        p_run_token: runToken,
        p_material_id: String(materialId || ''),
        p_quantity: Math.max(1, Math.floor(Number(amount || 1)))
      });
      if (res && res.error) throw res.error;
      if (typeof window.loadInventoryFromSupabase === 'function') {
        await window.loadInventoryFromSupabase(userId);
      }
    }).catch(err => {
      console.warn('[shooting reward] secure evolution material save failed', err && (err.message || err));
    });
  }

  function grantEvolutionReward(material, count) {
    const amount = Math.max(1, Math.floor(Number(count || 1)));
    try {
      if (typeof window.addEvolutionMaterial === 'function') {
        const result = window.addEvolutionMaterial(material.id, amount);
        persistShootingEvolutionReward(material.id, amount);
        return result || true;
      }
    } catch (err) {
      console.warn('[shooting reward] evolution material save failed', err);
    }
    return false;
  }

  function grantGemReward(amount) {
    const count = Math.max(0, Math.floor(Number(amount || 0)));
    if (!count || !window.userProfile) return false;

    const before = Math.max(0, Number(window.userProfile.gem || 0));
    const next = before + count;
    window.userProfile.gem = next;

    if (typeof window.updateMainUI === 'function') window.updateMainUI();
    if (typeof window.updateSummonGemUI === 'function') window.updateSummonGemUI();

    if (typeof window.saveProfileToDB === 'function') {
      Promise.resolve(window.saveProfileToDB({ gem: next, last_played: new Date().toISOString() }))
        .catch(err => {
          console.warn('[shooting reward] gem cloud save failed', err);
          // クラウド保存に失敗しても端末上のプレイ直後表示は維持。次の同期機会で再保存する。
          if (typeof window.scheduleCloudSave === 'function') window.scheduleCloudSave();
        });
    }
    return true;
  }

  const SHOOTING_FIRST_CLEAR_GEM_AMOUNT = 5;

  // v163: first-clear gem reward must be tied to a server-issued shooting run.
  // A stage_id alone is no longer enough to claim gems from the console.
  async function beginSecureShootingRun() {
    if (!state || !state.stageId || isDailyQuestStage() || isResonanceTowerStage() || isPhaseOdysseyStage() || isMemoryBattleStage() || isTowaDawnStage() || isRpgEncounterStage()) return null;
    if (state.secureRunToken) return state.secureRunToken;
    if (state.secureRunPromise) return state.secureRunPromise;

    const stageId = String(state.stageId || '').trim();
    const userId = getShootingUserId();
    const sb = window.zsSupabase;
    if (!stageId || !userId || !sb || typeof sb.rpc !== 'function') return null;

    state.secureRunPromise = (async () => {
      const result = await sb.rpc('begin_secure_shooting_run', {
        p_user_id: userId,
        p_stage_id: stageId,
      });
      if (result && result.error) throw result.error;
      const row = Array.isArray(result && result.data) ? result.data[0] : (result && result.data);
      const token = String(row && row.run_token || '').trim();
      if (!token) throw new Error('shooting run token was not issued');
      if (state && String(state.stageId || '') === stageId) state.secureRunToken = token;
      return token;
    })().catch(err => {
      console.warn('[shooting security] run begin failed:', err && (err.message || err));
      return null;
    }).finally(() => {
      if (state) state.secureRunPromise = null;
    });

    return state.secureRunPromise;
  }

  async function claimShootingFirstClearGemReward() {
    if (!state || !state.stageId) return { claimed: false, amount: 0, gem: null };
    if (state.firstClearGemPromise) return state.firstClearGemPromise;

    const stageId = String(state.stageId || '').trim();
    const userId = getShootingUserId();
    const sb = window.zsSupabase;

    state.firstClearGemPromise = (async () => {
      if (!stageId || !userId || !sb || typeof sb.rpc !== 'function') {
        return { claimed: false, amount: 0, gem: null };
      }

      const runToken = state.secureRunToken || await beginSecureShootingRun();
      if (!runToken) return { claimed: false, amount: 0, gem: null };

      const result = await sb.rpc('claim_shooting_first_clear_reward', {
        p_user_id: userId,
        p_run_token: runToken,
      });
      if (result && result.error) throw result.error;

      const row = Array.isArray(result && result.data)
        ? result.data[0]
        : (result && result.data);
      const claimed = !!(row && row.claimed);
      const amount = Math.max(0, Number(row && row.amount || 0));
      const gem = Number(row && row.gem);

      // 結晶残高はサーバーRPCの確定値を正として反映する。
      if (Number.isFinite(gem) && window.userProfile) {
        window.userProfile.gem = Math.max(0, gem);
        if (typeof window.updateMainUI === 'function') window.updateMainUI();
        if (typeof window.updateSummonGemUI === 'function') window.updateSummonGemUI();
      }

      return {
        claimed,
        amount: claimed ? Math.max(1, amount || SHOOTING_FIRST_CLEAR_GEM_AMOUNT) : 0,
        gem: Number.isFinite(gem) ? Math.max(0, gem) : null,
      };
    })().catch(err => {
      console.warn('[shooting reward] first clear gem claim failed:', err && (err.message || err));
      return { claimed: false, amount: 0, gem: null, error: true };
    });

    return state.firstClearGemPromise;
  }

  const SHOOTING_RESULT_EXP_ICON = 'images/icon_exp.webp';

  function buildShootingRewardItemHtml(drop) {
    const rewardImage = String((drop && drop.image) || '').trim() || (String(drop && drop.type || '') === 'exp' ? SHOOTING_RESULT_EXP_ICON : '');
    const isFirstClear = String(drop?.detail || '') === '初回クリア報酬';

    if (isFirstClear) {
      return `
        <div class="shooting-result-first-clear-bar">
          <span class="shooting-result-first-clear-label">初回クリア報酬</span>
          <span class="shooting-result-first-clear-main">
            ${rewardImage ? `<img src="${rewardImage}" alt="">` : ''}
            <b>${drop.name}</b>
            <strong>${drop.amountPrefix || '×'}${drop.amount}</strong>
          </span>
        </div>
      `;
    }

    return `
      <div class="shooting-result-reward-item shooting-result-reward-${drop.type}">
        <span class="shooting-result-reward-icon">${rewardImage ? `<img src="${rewardImage}" alt="">` : '<b>EXP</b>'}</span>
        <span class="shooting-result-reward-copy"><b>${drop.name}</b><small>${drop.detail}</small></span>
        <strong>${drop.amountPrefix || '×'}${drop.amount}</strong>
      </div>
    `;
  }

  // build1468: Sランククリア報酬。ステージ定義の sRankBonusRewards を、通常モードのSTORYでSランク勝利時のみ返す。
  function getStorySRankBonusDrops(excluded) {
    if (excluded || !state || !selectedStage) return [];
    if (selectedStage.beginnerMode) return [];
    if (typeof isStoryShootingStage === 'function' && !isStoryShootingStage()) return [];
    const list = Array.isArray(selectedStage.sRankBonusRewards) ? selectedStage.sRankBonusRewards : [];
    if (!list.length) return [];
    if (getResultRank(state.score, true) !== 'S') return [];
    return list.map(reward => ({
      material: {
        id: String(reward && reward.id || ''),
        name: String(reward && reward.name || '報酬'),
        image: String(reward && reward.image || ''),
        rewardType: String(reward && reward.rewardType || 'level_exp'),
      },
      count: Math.max(1, Math.floor(Number(reward && reward.count || 1))),
    })).filter(row => row.material.id);
  }

  function buildAndGrantShootingClearRewards() {
    if (isResonanceTowerStage() || isPhaseOdysseyStage() || isMemoryBattleStage() || isTowaDawnStage()) return [];
    if (!state || state.clearRewardsGranted) return Array.isArray(state && state.clearRewards) ? state.clearRewards : [];
    state.clearRewardsGranted = true;

    const dailyQuestReward = isDailyQuestStage();
    const scoreAttackFixedReward = isScoreAttackStage();
    let playerExp = getShootingPlayerExpReward();
    let coin = getShootingCoinReward(playerExp);
    const dailyServer = dailyQuestReward && state && state.dailyQuestServerRewards ? state.dailyQuestServerRewards : null;
    if (dailyServer) {
      playerExp = Math.max(0, Number(dailyServer.exp_reward || 0));
      coin = Math.max(0, Number(dailyServer.coin_reward || 0));
    }
    const rewardPlan = getShootingClearRewardPlan();

    let itemDrops = [];

    if (dailyQuestReward) {
      // build1249: デイリー報酬はサーバー確定結果をそのままRESULTへ正規化して表示する。
      // RPC世代差で items / reward_items のどちらが来ても拾えるようにする。
      const rawRows = dailyServer && Array.isArray(dailyServer.items)
        ? dailyServer.items
        : (dailyServer && Array.isArray(dailyServer.reward_items) ? dailyServer.reward_items : []);

      const levelExpDefs = {
        level_exp_small:  { id:'level_exp_small',  name:'強化素材・銅', image:'images/item_exp_bronze.webp', rewardType:'level_exp' },
        level_exp_medium: { id:'level_exp_medium', name:'強化素材・銀', image:'images/item_exp_silver.webp', rewardType:'level_exp' },
        level_exp_large:  { id:'level_exp_large',  name:'強化素材・金', image:'images/item_exp_gold.webp',   rewardType:'level_exp' },
      };

      itemDrops = rawRows.map(row => {
        const id = String(row && row.id || '').trim();

        // 経験値素材はRESULT表示に必要な名前/画像をここで必ず解決する。
        // CharacterLevelingの読み込み順に依存させない。
        let def = levelExpDefs[id] || null;

        if (!def) {
          const evoDef = (typeof window.getEvolutionMaterialDef === 'function')
            ? window.getEvolutionMaterialDef(id)
            : (typeof getEvolutionMaterialDef === 'function' ? getEvolutionMaterialDef(id) : null);
          if (evoDef) {
            def = {
              id: String(evoDef.id || id),
              name: String(evoDef.name || id || '素材'),
              image: String(evoDef.image || evoDef.img || ''),
              rewardType: String(evoDef.rewardType || 'evolution'),
            };
          }
        }

        if (!def && window.CharacterLeveling && Array.isArray(window.CharacterLeveling.MATERIALS)) {
          const levelMat = window.CharacterLeveling.MATERIALS.find(item => String(item && item.id || '') === id);
          if (levelMat) {
            def = { id:levelMat.id, name:levelMat.name, image:levelMat.img, rewardType:'level_exp' };
          }
        }

        return {
          material: def || { id:id, name:id || '素材', image:'', rewardType:'material' },
          count: Math.max(1, Number(row && row.quantity || 1))
        };
      }).filter(row => row && row.material && row.material.id);
    } else if (Array.isArray(selectedStage && selectedStage.fixedItemDrops)) {
      // build1636: ステージ固定の通常報酬（律動：強化素材・金×2）。
      const levelExpDefs = {
        level_exp_small:  { id:'level_exp_small',  name:'強化素材・銅', image:'images/item_exp_bronze.webp', rewardType:'level_exp' },
        level_exp_medium: { id:'level_exp_medium', name:'強化素材・銀', image:'images/item_exp_silver.webp', rewardType:'level_exp' },
        level_exp_large:  { id:'level_exp_large',  name:'強化素材・金', image:'images/item_exp_gold.webp',   rewardType:'level_exp' },
      };
      itemDrops = selectedStage.fixedItemDrops
        .map(row => ({ material: levelExpDefs[String(row && row.id || '')], count: Math.max(1, Number(row && row.count || 1)) }))
        .filter(row => row.material);
    } else if (scoreAttackFixedReward) {
      // すこあた！は従来の固定報酬感を維持しつつ、最大3枠以内。
      itemDrops = pickShootingEvolutionRewards(2).map(material => ({ material, count: 1 }));
    } else if (!isRaidStage() && !isFacelessStage()) {
      // STORY通常巡行。CH01だけ特例、CH02以降はstageNo別確率。
      itemDrops = pickStoryAdditionalItemDrops();
    } else {
      // 特殊/ボス系は通常STORYより少し報酬感を残す。
      const slotRates = [0.65, 0.28, 0.08];
      const pool = Array.from(SHOOTING_EVOLUTION_REWARD_POOL.filter(item => item.rewardType === 'evolution'));
      slotRates.forEach(rate => {
        if (!pool.length || Math.random() >= rate) return;
        const index = Math.floor(Math.random() * pool.length);
        itemDrops.push({ material: pool.splice(index, 1)[0], count: 1 });
      });
    }

    // build1249: CH02-03以降は経験値強化素材を別枠で0～2個追加。
    // 既存の進化素材ドロップはそのまま残す。
    if (!dailyQuestReward && !scoreAttackFixedReward && !isRaidStage() && !isFacelessStage() && !Array.isArray(selectedStage && selectedStage.fixedItemDrops)) {
      itemDrops = itemDrops.concat(pickStoryLevelExpMaterialDrops());
    }

    // build1468: Sランククリア報酬（ステージ定義 sRankBonusRewards）。通常モードのSTORYのみ。
    // 周回でも毎回付与。RESULTでは「Sランクボーナス」として別行で表示する。
    const sRankBonusDrops = getStorySRankBonusDrops(dailyQuestReward || scoreAttackFixedReward);

    // ステージ固有の確定報酬は既存仕様を維持。
    const guaranteedRewards = Array.isArray(selectedStage && selectedStage.guaranteedRewards)
      ? selectedStage.guaranteedRewards.map(reward => ({
          type: String(reward && reward.type || 'material'),
          id: String(reward && reward.id || ''),
          name: String(reward && reward.name || '報酬'),
          image: String(reward && reward.image || ''),
          count: Math.max(1, Math.floor(Number(reward && reward.count || 1))),
          detail: String(reward && reward.detail || '確定報酬'),
        })).filter(reward => reward.id)
      : [];

    const drops = [
      {
        type: 'exp',
        name: 'EXP',
        amount: playerExp,
        detail: 'プレイヤーEXP',
        image: SHOOTING_RESULT_EXP_ICON,
        amountPrefix: '+'
      },
      {
        type: 'coin',
        name: 'コイン',
        amount: coin,
        detail: 'クリア報酬',
        image: 'images/icon_coin.webp',
        amountPrefix: '+'
      },
      ...itemDrops.map(({ material, count }) => ({
        type: 'material',
        name: material.name,
        amount: count,
        detail: material.rewardType === 'shinju'
          ? '神樹成長素材'
          : (material.rewardType === 'level_exp' ? 'キャラクター強化素材' : '追加ドロップ'),
        image: material.image,
        materialId: material.id,
      })),
      ...guaranteedRewards.map(reward => ({
        type: reward.type,
        name: reward.name,
        amount: reward.count,
        detail: reward.detail,
        image: reward.image,
        materialId: reward.id,
      })),
      ...sRankBonusDrops.map(({ material, count }) => ({
        type: 'material',
        name: material.name,
        amount: count,
        detail: 'Sランクボーナス',
        image: material.image,
        materialId: material.id,
        sRankBonus: true,
      })),
    ];

    // v287:
    // 通常シューティングのEXP/コインは finish_secure_shooting_run 側で
    // run token 消費と同一トランザクション内にて確定付与する。
    // クライアント加算すると二重付与になるため、ここでは加算しない。
    // DAILYは既存の別経路を維持。
    // DAILYはcoin/EXP/素材すべてfinish_daily_quest_runで確定済み。
    // 通常シューティングだけ既存の追加素材付与処理を使用する。
    if (!dailyQuestReward) {
      // secure reward RPCは同一run・同一素材の重複claimを受け付けないため、
      // Sランクボーナスは通常ドロップと同じ素材なら個数を合算して1回で付与する。
      const grantDrops = itemDrops.map(({ material, count }) => ({ material, count }));
      sRankBonusDrops.forEach(({ material, count }) => {
        const same = grantDrops.find(row => row.material && row.material.id === material.id);
        if (same) same.count += count;
        else grantDrops.push({ material, count });
      });
      grantDrops.forEach(({ material, count }) => {
        if (material.rewardType === 'shinju') {
          grantShinjuNutrition(rewardPlan.nutritionExp, count);
        } else if (material.rewardType === 'level_exp') {
          // player_inventoryへの直接書込みは行わず、完了済みrun tokenを使うsecure RPCで付与。
          persistShootingEvolutionReward(material.id, count);
        } else {
          grantEvolutionReward(material, count);
        }
      });

      guaranteedRewards.forEach(reward => {
        grantEvolutionReward({ id: reward.id }, reward.count);
      });
    }

    state.clearRewards = drops;
    return drops;
  }

  function renderShootingClearRewards(win) {
    const section = document.getElementById('shooting-result-rewards');
    const list = document.getElementById('shooting-result-reward-list');
    const note = document.getElementById('shooting-result-reward-note');
    if (!section || !list) return;
    if (isResonanceTowerStage() || isPhaseOdysseyStage() || isTowaDawnStage() || isRpgEncounterStage()) {section.style.display='none';list.innerHTML='';return;} // build2040: エンカウント戦は報酬なし

    if (!win) {
      section.style.display = 'none';
      list.innerHTML = '';
      if (note) note.textContent = '';
      return;
    }

    // build1637: クリア済み表示用に端末へ記録（無貌の天使・律動の難易度選択で使用）
    markShootingStageCleared(state && state.stageId || (selectedStage && selectedStage.id));
    saveShootingBestRank(state && state.stageId || (selectedStage && selectedStage.id), getDisplayResultRank(state && state.score, true));
    const drops = buildAndGrantShootingClearRewards();
    section.style.display = '';

    // v283: EXP / コインは確定報酬として必ず先頭表示。
    // 旧stateを引き継いだ場合でも表示順を固定する。
    // build1263: キャラ経験値素材は付与されていても、従来のRESULT CSSが
    // 最大5行でoverflow:hiddenしていたため、追加ドロップが多いと下側で見切れていた。
    // 旧CSSがキャッシュに残っていても見えるよう、経験値素材をEXP/COIN直後へ優先配置する。
    const orderedDrops = Array.isArray(drops)
      ? [
          ...drops.filter(drop => drop && drop.type === 'exp'),
          ...drops.filter(drop => drop && drop.type === 'coin'),
          ...drops.filter(drop => drop && drop.materialId && /^level_exp_(?:small|medium|large)$/.test(String(drop.materialId))),
          ...drops.filter(drop => drop && drop.type !== 'exp' && drop.type !== 'coin' && !(drop.materialId && /^level_exp_(?:small|medium|large)$/.test(String(drop.materialId))))
        ]
      : [];

    list.innerHTML = orderedDrops.map(buildShootingRewardItemHtml).join('');
    if (note) {
      note.textContent = '';
      note.style.display = 'none';
    }

    // v172: 初回クリア結晶も、同じrun tokenを確定する結果RPCから受け取る。
    // score保存と初回報酬を別々のクライアント申告にしない。
    if (!isDailyQuestStage() && !state.firstClearGemRenderStarted) {
      state.firstClearGemRenderStarted = true;
      const finalizePromise = state.secureFinalizePromise
        || submitShootingHighScore(state.score, true);
      void Promise.resolve(finalizePromise).then(finalized => {
        if (!finalized || !finalized.firstClearClaimed || !finalized.firstClearAmount) return;
        const isVerdantFirstClear = ['shooting_event_verdant_advanced', 'shooting_event_verdant_super'].includes(String(state?.stageId || selectedStage?.id || ''));
        const gemDrop = {
          type: isVerdantFirstClear ? 'material' : 'gem',
          name: isVerdantFirstClear ? '創世pt' : '結晶',
          amount: finalized.firstClearAmount,
          detail: '初回クリア報酬',
          image: isVerdantFirstClear ? 'images/shinju_aura.webp' : 'images/icon_gem.webp',
        };
        if (isVerdantFirstClear && window.ShinjuProgress && typeof window.ShinjuProgress.refreshFromServer === 'function') {
          void window.ShinjuProgress.refreshFromServer();
        }
        state.clearRewards = Array.isArray(state.clearRewards)
          ? [...state.clearRewards, gemDrop]
          : [gemDrop];
        if (list && list.isConnected) {
          list.insertAdjacentHTML('beforeend', buildShootingRewardItemHtml(gemDrop));
        }
        if (note && note.isConnected) note.textContent = '';
      });
    }

    if (!isDailyQuestStage() && !state.shinjuRewardRenderStarted) {
      state.shinjuRewardRenderStarted = true;
      const finalizePromise = state.secureFinalizePromise
        || submitShootingHighScore(state.score, true);
      void Promise.resolve(finalizePromise).then(finalized => {
        if (isMemoryBattleStage() && finalized && finalized.memoryRank) applyMemoryResultRank(finalized.memoryRank); // build2007
        if (isMemoryBattleStage() && (!finalized || !finalized.memoryConfirmed)) {
          if (list && list.isConnected) {
            const warn = document.createElement('div');
            warn.className = 'memory-battle-result-warning';
            warn.style.cssText = 'grid-column:1/-1;padding:10px 12px;border:1px solid #bc685a;background:#fff0ed;color:#892f2f;font:700 12px/1.5 sans-serif;text-align:center';
            warn.textContent = '記憶決戦のクリア記録を確認できませんでした。報酬は未確定です。';
            list.appendChild(warn);
          }
          return;
        }
        // build2057: ディノヴァのドロップ表示（Sランク確定／Aランク50%。結果はサーバーが正）
        const dnDrop = isDeinovaStage() && finalized ? finalized.deinovaDrop : null;
        if (dnDrop && list && list.isConnected) {
          if (dnDrop.dropped) {
            const charaDrop = {
              type: 'material', name: 'ディノヴァ', amount: 1,
              detail: dnDrop.ownedCount > 1 ? `${dnDrop.ownedCount}体目（限界突破に使用できます）` : '新たな仲間',
              image: 'images/chara_113_panel.webp',
            };
            state.clearRewards = Array.isArray(state.clearRewards) ? [...state.clearRewards, charaDrop] : [charaDrop];
            list.insertAdjacentHTML('beforeend', buildShootingRewardItemHtml(charaDrop));
          } else if (dnDrop.error) {
            const warn = document.createElement('div');
            warn.style.cssText = 'grid-column:1/-1;padding:8px 12px;border:1px solid #bc685a;background:#fff0ed;color:#892f2f;font:700 11px/1.5 sans-serif;text-align:center';
            warn.textContent = 'ディノヴァの抽選結果を確認できませんでした。';
            list.appendChild(warn);
          }
        }
        const rewardExp = Math.max(0, Number(finalized && finalized.shinjuRewardExp || 0));
        if (!rewardExp) return;
        const shinjuDrop = {
          type: 'material',
          name: isMemoryBattleStage() ? '創世pt' : '聖樹の息吹',
          amount: 1,
          detail: isMemoryBattleStage() ? `創世pt +${rewardExp}` : `神樹成長素材 / 創世EXP +${rewardExp}`,
          image: 'images/shinju_aura.webp',
        };
        state.clearRewards = Array.isArray(state.clearRewards)
          ? [...state.clearRewards, shinjuDrop]
          : [shinjuDrop];
        if (list && list.isConnected) {
          list.insertAdjacentHTML('beforeend', buildShootingRewardItemHtml(shinjuDrop));
        }
      });
    }
  }


  function startRandomAmbushFromResult() {
    if (!state || !state.ended || isAmbushStage()) return;
    const root = document.getElementById(ROOT_ID);
    if (!root) return;

    const result = document.getElementById('shooting-result');
    const overlay = document.createElement('div');
    overlay.className = 'shooting-ambush-emergency';
    overlay.innerHTML = '<small>EMERGENCY</small><strong>緊急事態</strong><span>???が出現しました</span>';
    root.appendChild(overlay);

    setTimeout(() => {
      if (!overlay.isConnected) return;
      overlay.remove();

      resolveSelectedStage({ stageId: SHOOTING_STAGE_ID.OVERSEER_AMBUSH });
      BOSS = getCurrentShootingEnemy();
      clearProjectiles();
      clearNormalBattleObjects();
      resetState();
      // EMERGENCY ambush is a different stage_id, so it needs its own secure run token.
      void beginSecureShootingRun();

      const boss = document.getElementById(BOSS_ID);
      if (boss) {
        boss.src = getSelectedBossImage();
        boss.alt = BOSS.name || '';
        boss.style.setProperty('--enemy-scale', String(getResponsiveBossDisplayScale()));
        boss.style.display = '';
        boss.classList.remove('defeated');
      }
      if (result) {
        result.classList.remove('show');
        result.setAttribute('aria-hidden','true');
      }

      ensureBossWeaknessBarrier();
      root.setAttribute('data-shooting-stage', selectedStage.id);
      ensureInoriStageBgLayers(); // build2006
      // build1591: レイドはボスごとにバトル背景を変える（CSS: [data-raid-boss]）
      if ((isRaidStage() || BOSS?.raidVisualId) && BOSS?.id) root.setAttribute('data-raid-boss', BOSS.raidVisualId || BOSS.id); /* build1661: 塔のレイドボスもレイドと同じ見た目 */ else root.removeAttribute('data-raid-boss');
      root.setAttribute('data-battle-type','boss');
      root.setAttribute('data-boss-phase','1');
      root.classList.remove('boss-defeat-flash','boss-phase-flash','boss-phase-pause','player-defeat-flash');

      selectedCharacterId = selectedPartyIds[0] || selectedCharacterId;
      applySelectedCharacterToUi();
      setCharacterSelectVisible(false);
      setBattleHudVisible(true);
      setShootingHeaderMenuMode(true);
      placeInitialUnits();
      renderHud();
      playBossStageIntro(runStartCountdown);
    }, 1900);
  }

  function maybeQueueRandomAmbush(win) {
    // Random EMERGENCY encounter is intentionally disabled.
    // Keep the function as a no-op for compatibility with existing result flow.
    return;
  }

  // build1153: POSTノベル → RESULT の標準トランジション。
  // ノベルがフェードアウトしている間も白いベールを残し、背後のバトル画面を一切見せない。
  // RESULTをベールの下で先に表示してから、ベールだけをゆっくり解除する。
  const POST_RESULT_TRANSITION_ID = 'shooting-post-result-transition';
  const POST_RESULT_TRANSITION_MS = 760;

  function ensurePostResultTransition() {
    let overlay = document.getElementById(POST_RESULT_TRANSITION_ID);
    if (overlay) return overlay;

    overlay = document.createElement('div');
    overlay.id = POST_RESULT_TRANSITION_ID;
    overlay.setAttribute('aria-hidden', 'true');
    document.body.appendChild(overlay);

    if (!document.getElementById('shooting-post-result-transition-style-v1153')) {
      const style = document.createElement('style');
      style.id = 'shooting-post-result-transition-style-v1153';
      style.textContent = `
        #${POST_RESULT_TRANSITION_ID}{
          position:fixed;
          inset:0;
          z-index:260450;
          display:none;
          pointer-events:none;
          opacity:1;
          background:
            radial-gradient(circle at 50% 28%,rgba(255,255,255,.98) 0%,rgba(255,253,248,.96) 38%,rgba(247,242,232,.98) 100%);
          transition:opacity ${POST_RESULT_TRANSITION_MS}ms cubic-bezier(.22,.61,.36,1);
          will-change:opacity;
        }
        #${POST_RESULT_TRANSITION_ID}.is-active{display:block;opacity:1;}
        #${POST_RESULT_TRANSITION_ID}.is-releasing{opacity:0;}
        @media (min-width:500px){
          #${POST_RESULT_TRANSITION_ID}{
            left:50%;
            right:auto;
            width:100%;
            max-width:430px;
            transform:translateX(-50%);
          }
        }
        @media (prefers-reduced-motion:reduce){
          #${POST_RESULT_TRANSITION_ID}{transition-duration:180ms;}
        }
      `;
      document.head.appendChild(style);
    }

    return overlay;
  }

  function armPostResultTransition() {
    const overlay = ensurePostResultTransition();
    overlay.classList.remove('is-releasing');
    overlay.classList.add('is-active');
    overlay.style.display = 'block';
    overlay.setAttribute('aria-hidden', 'false');
    // ノベルより下、バトル/RESULTより上に常駐させる。
    // これによりノベル終了時にバトル画面が1フレームも露出しない。
    void overlay.offsetWidth;
    return overlay;
  }

  function releasePostResultTransition() {
    const overlay = document.getElementById(POST_RESULT_TRANSITION_ID);
    if (!overlay || !overlay.classList.contains('is-active')) return;
    requestAnimationFrame(() => {
      requestAnimationFrame(() => overlay.classList.add('is-releasing'));
    });
    window.setTimeout(() => {
      overlay.classList.remove('is-active', 'is-releasing');
      overlay.style.display = 'none';
      overlay.setAttribute('aria-hidden', 'true');
    }, POST_RESULT_TRANSITION_MS + 100);
  }

  // build1515: RESULT見出しの下に、今回挑戦したステージを表示する。
  // 戦闘開始前から保持しているselectedStageを使うので、再挑戦や事後ノベル後も同じ名称になる。
  function getShootingResultStageLabel() {
    const stage = selectedStage;
    if (!stage) return '';
    // build2173: パラレル・ソワレは名前だけ（SPECIAL PROC. や (LIMITED EVENT) は付けない）
    if (stage.eventId === 'party_event') return 'パラレル・ソワレ ～並行世界への招待状～';
    if (stage.eventId === 'phase_odyssey') {
      return `${String(stage.eventTitle || '位相回遊').trim()} ｜ FLOOR ${Math.max(1, Math.floor(Number(stage.stageNo || 1)))}`;
    }
    if (stage.eventId === 'memory_battle') {
      return `記憶決戦 ｜ MEMORY ${String(Math.max(1, Math.floor(Number(stage.stageNo || 1)))).padStart(2, '0')}  ${String(stage.name || '').trim()}`;
    }
    if (stage.eventId === 'resonance_tower') {
      const floor = Math.max(0, Math.floor(Number(stage.stageNo || 0)));
      const floorLabel = String(stage.difficultyLabel || '').trim() || `${String(floor).padStart(2, '0')}F`;
      return `${String(stage.eventTitle || '残響の塔').trim()} ｜ ${floorLabel}`;
    }
    if (Number(stage.chapter || 0) > 0 && Number(stage.stageNo || 0) > 0) {
      // ノベル側のstageTitleがある場合は、その実際の表示名を優先。
      const lines = getShootingStageInfoLines();
      return `${lines[0] || ''} ｜ ${lines[1] || ''}${lines[2] ? '  ' + lines[2] : ''}`.trim();
    }
    if (stage.dailyQuest) return `DAILY ｜ ${String(stage.name || '').trim()}`;
    const lines = getShootingStageInfoLines();
    return lines.filter(Boolean).join(' ｜ ');
  }

  async function endGame(win) {
    // build2061: boss-defeat wins against previously queued loss callbacks.
    if (!win && isMemoryBattleStage() && state?.memoryBossDefeated) {
      console.warn('[memory battle] stale loss callback ignored after boss defeat');
      win = true;
    }
    if (isGachaTrialStage()) return; // 試遊ではRESULT・報酬・履歴処理に絶対に入らない
    if (!state || state.ended) return;
    if (isRpgEncounterStage()) { finishRpgEncounterBattle(!!win); return; } // build2041: RESULTなしでRPGへ

    // build812: RESULT処理中にstage参照が変化してもDAILY判定を揺らさない。
    const dailyQuestAtResult = isDailyQuestStage();

    // RESULTへ入るタイミングで戦闘BGMを短くフェードアウト。
    fadeOutShootingBattleBgm(520, true);

    // build1835: 残り3秒のカウントはRESULTへ持ち越さない（TIME OVERの幕は自分で片付ける）
    document.querySelectorAll('#shooting-event-root .shooting-final-count').forEach(el => el.remove());
    if (state) state.finalCountShown = 0;

    // CH04専用ギミックはRESULTへ持ち越さない。
    removeOverseerWatchDom();
    removeInoriDom();
    removeVerdantDom();
    clearChapter4FinalItem();
    purgeChapter4ItemDom();
    clearChapter43RestoreItem();
    clearChapter43SealCountdown();
    clearChapter43Countdown();

    // 迫る壁もRESULTへ残さず、即座に初期幅へ戻す。
    const ch04ArenaForResult = document.getElementById('shooting-arena');
    if (ch04ArenaForResult) {
      ch04ArenaForResult.querySelectorAll('.shooting-ch04-shrink-wall').forEach(el => {
        el.style.display = 'none';
        el.style.width = '0px';
      });
    }

    // 通常戦はRESULT確定時点で復帰データを削除。
    // RAIDはfinishAttemptのSupabase確定が終わるまで復帰データを残す。
    if (!isRaidStage()) clearShootingResumeState();
    state.ended = true;

    // GAME OVERは戦闘画面専用。RESULTへ持ち越さない。
    document.querySelectorAll('.shooting-game-over-notice').forEach(el => el.remove());

    // RESULTへ切り替える前に、戦闘中だけの演出/HUD状態を確実に解除する。
    const rootForResult = document.getElementById(ROOT_ID);
    if (rootForResult) {
      rootForResult.classList.remove('normal-stage-clear', 'mission-item-get');
      rootForResult.querySelectorAll('.shooting-clear-condition-achieved').forEach(el => el.remove());
    }
    const missionHudForResult = document.getElementById('shooting-mission-hud');
    if (missionHudForResult) missionHudForResult.style.display = 'none';
    const battleTimerForResult = document.getElementById('shooting-battle-timer');
    if (battleTimerForResult) {
      battleTimerForResult.classList.remove('show','is-warning','is-danger');
      battleTimerForResult.setAttribute('aria-hidden','true');
    }
    const comboForResult = document.getElementById('shooting-combo');
    if (comboForResult) comboForResult.style.display = 'none';
    state.running = false;
    cancelAnimationFrame(rafId);
    clearEltenaBlackHole();
    clearProjectiles();
    clearNormalBattleObjects();
    document.getElementById(BOSS_ID)?.classList.remove('nem-stunned');
    document.getElementById(ROOT_ID)?.classList.remove('nem-stun-active');
    const result = document.getElementById('shooting-result');
    const kicker = document.getElementById('shooting-result-kicker');
    const title = document.getElementById('shooting-result-title');
    const stageLabel = document.getElementById('shooting-result-stage-label');
    const score = document.getElementById('shooting-result-score');
    const combo = document.getElementById('shooting-result-combo');
    const rank = document.getElementById('shooting-result-rank');
    const hitDetails = document.getElementById('shooting-result-hit-details');
    const hitTotal = document.getElementById('shooting-result-hit-total');
    const ultDetails = document.getElementById('shooting-result-ult-details');
    const ultTotal = document.getElementById('shooting-result-ult-total');
    const survivorDetails = document.getElementById('shooting-result-survivor-details');
    const survivorTotal = document.getElementById('shooting-result-survivor-total');
    const clearTime = document.getElementById('shooting-result-clear-time');
    const raidRow = document.getElementById('shooting-result-raid-row');
    const raidDamageEl = document.getElementById('shooting-result-raid-damage');
    const retryBtn = document.getElementById('shooting-result-retry');
    state.clearTimeMs = Math.max(0, performance.now() - (state.startedAt || performance.now()));
    // build1081: RESULTを閉じるまで勝敗を保持し、STORY後半ノベル判定に使う。
    state.lastResultWin = !!win;
    // 敗北/中断では上書きしない。実際に出撃したメンバー順を保持する。
    // 記憶決戦だけはサーバーが勝利を確定してから「クリア編成」を保存する。
    const lastClearStageId = state.stageId || selectedStage?.id;
    const lastClearPartyIds = Array.isArray(state.initialPartyIds) && state.initialPartyIds.length
      ? state.initialPartyIds.slice()
      : (Array.isArray(state.party) ? state.party.map(member => Number(member.id)) : []);
    if (win && !isRaidStage() && !isResonanceTowerReplay() && !isPhaseOdysseyStage() && !isMemoryBattleStage()) {
      saveShootingLastClearParty(lastClearStageId, lastClearPartyIds);
    }
    finalizeStoryClearScore(!!win);
    finalizePartyScore(!!win); // build2150
    if (isPartyEventStage()) { state.partyRunStats = getPartyRunStats(!!win); clearPartyDom(); }
    if (isScoreAttackStage()) {
      state.score = Math.min(SCORE_ATTACK_MAX_SCORE, Math.max(0, Math.floor(Number(state.score || 0))));
    }
    if (isMemoryBattleStage()) state.memoryResultRank = ''; // build2007: サーバーの判定が届くまでは A（勝利時）
    const rankLetter = getDisplayResultRank(state.score, win);

    if (dailyQuestAtResult) {
      if (raidRow) raidRow.style.display = 'none';
      if (retryBtn) retryBtn.style.display = 'none';
    } else if (isResonanceTowerStage() || isPhaseOdysseyStage() || isTowaDawnStage()) {
      if (raidRow) raidRow.style.display = 'none';
      if (retryBtn) retryBtn.style.display = 'none';
    } else if (isRaidStage()) {
      state.raidDamageDealt = getRaidDamageDealt(); // build1662: 周をまたいだ合計
      if (raidRow) raidRow.style.display = '';
      if (raidDamageEl) raidDamageEl.textContent = state.raidDamageDealt.toLocaleString('ja-JP') + (isRaidLapMode() && Number(state.raidLap || 1) > Math.max(1, Number(selectedRaidContext.lap) || 1) ? `（${Number(state.raidLap)}周目まで到達）` : '');
      if (retryBtn) retryBtn.style.display = 'none';
      if (!state.raidAttemptFinished && window.RaidEvent && typeof window.RaidEvent.finishAttempt === 'function') {
        state.raidAttemptFinished = true;
        const finishPromise = window.RaidEvent.finishAttempt(state.raidDamageDealt, { bossDefeated: !!win,
          partyIds: Array.isArray(state.party) ? state.party.map(m => Number(m.id)).filter(Boolean) : [],
          partyDetails: Array.isArray(state.party) ? state.party.map(m => {
            const id=Number(m.id);
            const owned=typeof getOwnedShootingInstance==='function' ? getOwnedShootingInstance(id) : null;
            return {id, level:Math.max(1,Math.floor(Number(owned&&(owned.characterLevel??owned.character_level) || 1))),limitBreak:Math.max(0,Math.floor(Number(owned&&(owned.limitBreak??owned.limit_break) || 0)))};
          }) : [] });
        Promise.resolve(finishPromise)
          .then(() => clearShootingResumeState())
          .catch(err => {
            // 通信失敗時は復帰データを残し、次回起動で同じ挑戦を再開できるようにする。
            console.warn('[shooting] raid finish failed; resume snapshot kept', err);
          });
      }
    } else {
      if (raidRow) raidRow.style.display = 'none';
      if (retryBtn) retryBtn.style.display = '';
    }
    // build1687: RETRYなしの時の1列レイアウトはクラスで切り替える（CSSの :has([style*=…]) は全DOMのstyle変更で再計算を誘発していた）
    if (retryBtn && retryBtn.parentElement) retryBtn.parentElement.classList.toggle('no-retry', retryBtn.style.display === 'none');

    // ステージ別最高スコアをローカルへ即時反映し、Supabaseへ非同期保存。
    // v172: score/result is accepted only against this battle's server run token.
    state.secureFinalizePromise = dailyQuestAtResult ? finalizeDailyQuestRun(state.score, !!win) : submitShootingHighScore(state.score, !!win);
    // build2150: サーバー未設定（RPC未作成）の間は、パネルの進み具合を端末に記録して試せるようにする（報酬は付かない）
    if (isPartyEventStage()) {
      const partyStats = state.partyRunStats;
      void Promise.resolve(state.secureFinalizePromise).then(r => {
        if (r && r.partyEventResult) return;
        if (window.PartyEvent && typeof window.PartyEvent.submitRun === 'function') return window.PartyEvent.submitRun(null, null, partyStats);
      }).catch(() => {});
    }
    if (win && isMemoryBattleStage()) {
      const memoryFinalizePromise = state.secureFinalizePromise;
      void Promise.resolve(memoryFinalizePromise).then(finalized => {
        if (finalized && finalized.memoryConfirmed === true) {
          saveShootingLastClearParty(lastClearStageId, lastClearPartyIds);
        }
      }).catch(err => console.warn('[memory battle] confirmed clear party save failed', err));
    }
    if (dailyQuestAtResult) {
      try {
        await state.secureFinalizePromise;
      } catch (err) {
        console.error('[DailyQuest] finalize failed:', err);
        if (typeof window.showToast === 'function') window.showToast('デイリー報酬の確定に失敗しました');
      }
    }
    // build2021: profile combo high-watermark, except dev sandbox.
    if (!isPhaseOdysseyTestStage()) try {
      window.dispatchEvent(new CustomEvent('zeraphia-profile-battle-result', {
        detail: { stageId: String(state.stageId || (selectedStage && selectedStage.id) || ''), maxCombo: Math.max(0, Math.floor(Number(state.maxCombo) || 0)) }
      }));
    } catch (_) {}
    // STORY進捗へシューティング結果を通知。
    // build1643: 位相回遊の階層は無限に増えるため、STORY記録・各種イベントへは通知しない。
    if (!isPhaseOdysseyStage()) try {
      window.dispatchEvent(new CustomEvent('shooting-stage-result', {
        detail: {
          stageId: state.stageId || (selectedStage && selectedStage.id) || null,
          chapter: selectedStage ? selectedStage.chapter : null,
          stageNo: selectedStage ? selectedStage.stageNo : null,
          win: !!win,
          storyReplay: isStoryReplayBattle(),
          score: Number(state.score || 0),
          maxCombo: Number(state.maxCombo || 0),
          clearTimeMs: Number(state.clearTimeMs || 0),
          hitsTaken: Number(state.totalHitsTaken || 0),
          collectedItems: Number(state.collectedItems || 0),
          partyIds: Array.isArray(state.party) ? state.party.map(m => Number(m.id)).filter(Boolean) : []
        }
      }));
    } catch (_) {}
    const totalHits = state.party.reduce((sum, m) => sum + (m.hitCount || 0), 0);
    const totalUlts = state.party.reduce((sum, m) => sum + (m.ultUseCount || 0), 0);
    const survivors = state.party.filter(m => m.hp > 0);
    const resultMemberHtml = (m, value, suffix, markDown) => {
      const c = getBattleCharacter(m.id);
      return `<span class="shooting-result-member${markDown && m.hp <= 0 ? ' down' : ''}" title="${c.name}"><img src="${getCharacterPanelImage(c)}" alt="${c.name}"><b>${value}${suffix}</b></span>`;
    };
    if (kicker) kicker.textContent = isPhaseOdysseyTestStage() ? 'DEVELOPER TEST · NO REWARDS' : isPhaseOdysseyStage()
      ? (win ? 'PHASE ODYSSEY · FLOOR CLEAR' : 'PHASE ODYSSEY · RUN END')
      : (isResonanceTowerReplay() ? 'FREE REPLAY · NO REWARDS' : (win ? '' : 'MISSION FAILED'));
    if (title) title.textContent = 'RESULT';
    if (stageLabel) {
      stageLabel.textContent = getShootingResultStageLabel();
      stageLabel.style.display = stageLabel.textContent ? '' : 'none';
      stageLabel.title = stageLabel.textContent;
    }
    if (score) score.textContent = String(state.score).padStart(6, '0');
    renderPartyScoreBreakdown(); // build2164: 夜会のみ。その他のリザルトでは明細を除去。
    if (combo) combo.textContent = String(state.maxCombo || 0);
    if (hitDetails) hitDetails.innerHTML = state.party.map(m => resultMemberHtml(m, m.hitCount || 0, '回', false)).join('');
    if (hitTotal) hitTotal.textContent = `${totalHits}回`;
    if (ultDetails) ultDetails.innerHTML = state.party.map(m => resultMemberHtml(m, m.ultUseCount || 0, '回', false)).join('');
    if (ultTotal) ultTotal.textContent = `${totalUlts}回`;
    if (survivorDetails) survivorDetails.innerHTML = state.party.map(m => resultMemberHtml(m, m.hp > 0 ? '生存' : 'LOST', '', true)).join('');
    if (survivorTotal) survivorTotal.textContent = `${survivors.length}/${state.party.length}`;
    if (clearTime) clearTime.textContent = `${(state.clearTimeMs / 1000).toFixed(2)}秒`;
    if (rank) {
      rank.textContent = rankLetter;
      rank.setAttribute('data-rank', rankLetter);
    }
    renderPhaseOdysseyResult(!!win);
    renderShootingClearRewards(!!win);

    // build1082:
    // STORYの表示順を
    // 事前ノベル → バトル → 事後ノベル → RESULT
    // に固定する。RESULT自体は先に内容だけ生成し、POSTノベル完了まで非表示。
    setBattleHudVisible(false);

    // build1193: バトル開始時のステージタイトルオーバーレイが、
    // 事後ノベルへ遷移した後も残留しないよう明示的に破棄する。
    // CH01-04 では「STAGE04 / 兆し」がPOSTノベル中央に残るケースがあった。
    const stageInfoOverlay = document.getElementById('shooting-stage-info');
    if (stageInfoOverlay) {
      stageInfoOverlay.classList.remove('is-visible', 'is-revealing', 'is-fading');
      stageInfoOverlay.setAttribute('aria-hidden', 'true');
      const stageInfoLines = stageInfoOverlay.querySelectorAll('.shooting-stage-info-line');
      stageInfoLines.forEach((line) => { line.textContent = ''; });
    }

    let postResultTransitionArmed = false;

    const showResultAfterStory = function(){
      if (result) {
        // 白いベールの下でRESULTを先に完成させる。
        // ベールを後からゆっくり外すことで、ノベル→RESULTを標準で滑らかにつなぐ。
        result.classList.add('show');
        result.setAttribute('aria-hidden', 'false');
      }
      if (postResultTransitionArmed) {
        releasePostResultTransition();
        postResultTransitionArmed = false;
      }
      maybeQueueRandomAmbush(!!win);
      if (win && isStoryShootingStage()) {
        void (async () => {
          try {
            await (state.secureFinalizePromise || Promise.resolve());
            const sb = window.zsSupabase;
            if (!sb || typeof sb.rpc !== 'function') return;
            const response = await sb.rpc('claim_story_memory_fragments');
            if (response.error) throw response.error;
            const amount = Math.max(0, Number(response.data?.claimed || 0));
            if (amount && typeof window.showToast === 'function') {
              window.showToast(`記憶の欠片 ×${amount} を入手しました。`);
            }
            if(typeof window.loadInventoryFromSupabase === 'function' && typeof userId !== 'undefined'){
              try { await window.loadInventoryFromSupabase(userId); }
              catch(refreshError){ console.warn('[story memory fragments] inventory refresh failed', refreshError); }
            }
            const status = await sb.rpc('get_story_memory_fragment_status');
            if (!status.error) {
              localStorage.setItem('zeraphia_memory_fragment_claim_keys_v1',JSON.stringify(status.data?.claimed_keys || []));
              window.dispatchEvent(new Event('shooting-stage-record-updated'));
            }
          } catch(e) { console.warn('[story memory fragments] reward sync failed',e); }
        })();
      }
    // build1411: CH06-03クリアでトイフェル・アイナ・ベロニカを加入させる。サーバーで初回クリア実績を検証し、未所持分のみLv1付与。
    if (win && ['shooting_ch04_04','shooting_ch06_03'].includes(storyStageId)) {
      void (async () => {
        try {
          await (state.secureFinalizePromise || Promise.resolve());
          const sb = window.zsSupabase;
          if (!sb) return;
          const reply = await sb.rpc('claim_story_chapter_characters');
          if (reply.error) throw reply.error;
          const grants = (reply.data && reply.data.characters) || [];
          if (!grants.length) return;
          const names = {25:'リュネ',37:'トイフェル',22:'ベロニカ',17:'アイナ'};
          const message = grants.map(c => `${c.rarity}キャラ[${names[c.id]}]（Lv.1）を入手しました。`).join('\n') + '\n\n育成して強化しましょう。';
          const overlay = document.createElement('div');
          overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;background:#17131bc9;display:flex;align-items:center;justify-content:center;padding:20px';
          const panel = document.createElement('div');
          panel.style.cssText = 'width:min(100%,380px);background:#faf6ed;color:#594935;padding:25px 18px;text-align:center;font-family:"Noto Serif JP",serif;border:1px solid #c6a46b';
          const title = document.createElement('div');
          title.textContent='NEW CHARACTER';
          title.style.cssText='font-size:12px;letter-spacing:.2em;color:#9b7a44;margin-bottom:15px';
          const content = document.createElement('div');
          content.textContent=message;
          content.style.cssText='white-space:pre-line;font-size:14px;line-height:2';
          const button = document.createElement('button');
          button.textContent='OK';
          button.style.cssText='margin-top:20px;padding:12px 48px;background:#a88b5b;color:white;border:0;font-family:inherit';
          button.onclick=()=>{overlay.remove();location.reload();};
          panel.append(title,content,button);
          overlay.append(panel);document.body.append(overlay);
        } catch(err) { console.warn('[story grant] claim failed',err); }
      })();
    }

    };

    const storyStageId = String(
      (selectedStage && (selectedStage.baseStageId || selectedStage.id)) ||
      state.stageId ||
      ''
    );

    const hasPostStory = !!(
      win && !isStoryReplayBattle() &&
      window.StoryNovel &&
      typeof window.StoryNovel.hasPost === 'function' &&
      window.StoryNovel.hasPost(storyStageId)
    );

    // POSTノベル開始前からベールをノベルの背面へ待機させる。
    // ノベル自身がフェードアウトしても、その下にはベールしか見えない。
    if (hasPostStory) {
      armPostResultTransition();
      postResultTransitionArmed = true;
    }

    if (win && window.StoryNovel && !isStoryReplayBattle()) {
      // shooting-stage-result の同期イベントでqueuePost済みならそれを消費。
      if (
        typeof window.StoryNovel.consumePendingPost === 'function' &&
        window.StoryNovel.consumePendingPost(storyStageId, showResultAfterStory)
      ) {
        return;
      }

      // キューを取りこぼしても、postが定義されていれば直接再生。
      if (
        typeof window.StoryNovel.hasPost === 'function' &&
        window.StoryNovel.hasPost(storyStageId) &&
        typeof window.StoryNovel.playPost === 'function'
      ) {
        window.StoryNovel.playPost(storyStageId, {
          onComplete: showResultAfterStory,
          onExit: showResultAfterStory
        });
        return;
      }
    }



    showResultAfterStory();
  }

  function rebaseTouchDragToPlayer(preserveTarget = false) {
    if (!pointerActive || !pointerIsTouch || !state || !state.player) return;

    dragStartClientX = lastPointerClientX;
    dragStartClientY = lastPointerClientY;

    if (preserveTarget) {
      // キャラチェンジ中も、指が向かっている「現在の移動目標」を捨てない。
      // 同じ指位置で次のpointermoveが来てもtargetが変わらないため、
      // 一瞬ブレーキが掛かったような操作感を防ぐ。
      dragStartPlayerX = pointerX;
      dragStartPlayerY = pointerY;
      return;
    }

    // 入力基準は常に現在のtargetを維持する。
    // pointercancel / identifier差し替えが起きても指とのオフセットを蓄積させない。
    dragStartPlayerX = pointerX;
    dragStartPlayerY = pointerY;
  }

  function beginTouchDrag(e) {
    if (!state || !state.player) return;

    pointerActive = true;
    pointerIsTouch = true;
    activePointerId = e.pointerId;

    lastPointerClientX = e.clientX;
    lastPointerClientY = e.clientY;
    dragStartClientX = e.clientX;
    dragStartClientY = e.clientY;

    // 指を置いた瞬間はキャラをワープさせない。
    // 以後はこの位置を基準に、指の移動量とキャラの移動量を完全1:1にする。
    dragStartPlayerX = state.player.x;
    dragStartPlayerY = state.player.y;
    pointerX = state.player.x;
    pointerY = state.player.y;
  }

  // build1436: 下部バー（交代ボタン含む）から始まったタッチは移動ドラッグとして扱う。
  // MENUなどの操作ボタン（.shooting-battle-controls）だけはUI操作のまま。
  function isShootingFooterDragTarget(target) {
    if (!target || typeof target.closest !== 'function') return false;
    if (!target.closest('.shooting-footer')) return false;
    return !target.closest('.shooting-battle-controls, a, input, select, textarea');
  }

  function isShootingUiInteractionTarget(target) {
    if (!target || typeof target.closest !== 'function') return false;
    if (isShootingFooterDragTarget(target)) return false;
    return !!target.closest(
      '.shooting-character-select, ' +
      '.shooting-result, ' +
      '.shooting-character-info-modal, ' +
      '.shooting-switch-rail, ' +
      '.shooting-footer, ' +
      'button, a, input, select, textarea'
    );
  }

