  function getIgnisBurnFx(key) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return null;
    return arena.querySelector(`.shooting-ignis-burn[data-burn-key="${key}"]`);
  }

  function createIgnisBurnVisual(key, x, y) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return null;

    ensureIgnisBurnEffectStyle();

    let burn = getIgnisBurnFx(key);
    if (!burn) {
      burn = document.createElement('div');
      burn.className = 'shooting-ignis-burn';
      burn.dataset.burnKey = key;
      burn.setAttribute('aria-hidden', 'true');
      burn.innerHTML = `
        <span class="ignis-burn-aura"></span>
        <span class="ignis-burn-ring"></span>
        <span class="ignis-burn-heat"></span>
        <i class="ignis-burn-ember e1"></i>
        <i class="ignis-burn-ember e2"></i>
        <i class="ignis-burn-ember e3"></i>
        <i class="ignis-burn-ember e4"></i>
        <i class="ignis-burn-ember e5"></i>
      `;
      arena.appendChild(burn);
    }

    // 足元寄りに置き、炎そのものではなく赤い熱と火の粉で燃焼状態を見せる。
    positionUnit(burn, x, y + 10);
    return burn;
  }

  function pulseIgnisBurnVisual(key) {
    const burn = getIgnisBurnFx(key);
    if (!burn) return;
    burn.classList.remove('tick');
    void burn.offsetWidth;
    burn.classList.add('tick');
    setTimeout(() => burn.classList.remove('tick'), 320);
  }

  function removeIgnisBurnVisual(key) {
    const burn = getIgnisBurnFx(key);
    if (!burn) return;
    burn.classList.add('fade');
    setTimeout(() => burn.remove(), 180);
  }

  function igniteIgnisTarget(target, c, now) {
    if (!state || !target) return;
    const duration = Number(c.burnDurationMs || 5000);

    if (target.isBoss) {
      state.ignisBossBurnUntil = Math.max(state.ignisBossBurnUntil || 0, now + duration);
      if (!state.ignisBossBurnNextTickAt || state.ignisBossBurnNextTickAt < now) {
        state.ignisBossBurnNextTickAt = now + Number(c.burnTickMs || 1000);
      }
      const bossEl = document.getElementById(BOSS_ID);
      if (bossEl) bossEl.classList.add('ignis-burning');
      createIgnisBurnVisual('boss', state.boss.x, state.boss.y);
      return;
    }

    target.ignisBurnUntil = Math.max(Number(target.ignisBurnUntil || 0), now + duration);
    if (!target.ignisBurnNextTickAt || target.ignisBurnNextTickAt < now) {
      target.ignisBurnNextTickAt = now + Number(c.burnTickMs || 1000);
    }
    if (target.el) {
      target.el.classList.add('ignis-burning');
      createIgnisBurnVisual(String(target.uid || 'enemy'), target.x, target.y);
    }
  }

  function updateIgnisBurns(now) {
    if (!state) return;
    const c = getBattleCharacter(CHARACTER_ID.IGNIS);
    if (!c) return;

    const tickMs = Number(c.burnTickMs || 1000);
    const damage = Number(c.atk || 0) * Number(c.burnDamageAtkRate || 0.30);

    if (isNormalBattle()) {
      const targets = [...(state.normalEnemies || [])];
      targets.forEach(enemy => {
        if (!enemy || !enemy.el || enemy.hp <= 0) return;

        const burnKey = String(enemy.uid || 'enemy');

        if (now >= Number(enemy.ignisBurnUntil || 0)) {
          enemy.el.classList.remove('ignis-burning');
          removeIgnisBurnVisual(burnKey);
          return;
        }

        // 炎エフェクトは敵本体の座標へ追従させる。
        createIgnisBurnVisual(burnKey, enemy.x, enemy.y);

        if (now >= Number(enemy.ignisBurnNextTickAt || 0)) {
          enemy.ignisBurnNextTickAt = now + tickMs;
          pulseIgnisBurnVisual(burnKey);
          const targetElement = getCombatTargetElement(enemy);
          const finalDamage = applyElementDamage(damage, getUltAttackElement(c), targetElement);
          damageNormalEnemy(enemy, finalDamage, now, true, getElementDamageReaction(getUltAttackElement(c), targetElement));
        }
      });
      state.normalEnemies = state.normalEnemies.filter(enemy => enemy && enemy.hp > 0);
      return;
    }

    const bossEl = document.getElementById(BOSS_ID);
    if (now >= Number(state.ignisBossBurnUntil || 0)) {
      if (bossEl) bossEl.classList.remove('ignis-burning');
      removeIgnisBurnVisual('boss');
      return;
    }

    if (state.boss && state.boss.hp > 0) {
      createIgnisBurnVisual('boss', state.boss.x, state.boss.y);
    }

    if (state.boss && state.boss.hp > 0 && now >= Number(state.ignisBossBurnNextTickAt || 0)) {
      state.ignisBossBurnNextTickAt = now + tickMs;
      pulseIgnisBurnVisual('boss');
      const targetElement = getCombatTargetElement(state.boss);
      const finalDamage = applyElementDamage(damage, getUltAttackElement(c), targetElement);
      const appliedDamage = Math.min(state.boss.hp, Math.max(0, Number(finalDamage || 0)));
      state.boss.hp = Math.max(0, state.boss.hp - appliedDamage);
      createHit(state.boss.x, state.boss.y, true);
      showBossDamageNumber(appliedDamage, true, getElementDamageReaction(getUltAttackElement(c), targetElement));
      flashBossHit(true);
      if (!addScoreAttackDamageScore(appliedDamage)) {
        addLegacyCombatScore(Math.round(damage * 100));
      }
      updateBossPhase();
      if (state.boss.hp <= 0) beginBossDefeat();
    }
  }

  function removeIgnisFireWheel() {
    if (!state || !state.ignisFireWheel) return;
    const wheel = state.ignisFireWheel;
    if (wheel.el) {
      wheel.el.classList.add('fade');
      setTimeout(() => wheel.el && wheel.el.remove(), 300);
    }
    state.ignisFireWheel = null;
  }

  function updateIgnisFireWheel(now) {
    if (!state || !state.ignisFireWheel) return;
    const wheel = state.ignisFireWheel;
    const c = getBattleCharacter(CHARACTER_ID.IGNIS);
    if (!c) return;

    if (now >= wheel.endAt) {
      removeIgnisFireWheel();
      return;
    }

    const arena = document.getElementById('shooting-arena');
    if (!arena || !wheel.el) return;

    const elapsed = (now - wheel.startedAt) / 1000;
    const angle = wheel.startAngle + elapsed * Number(c.fireWheelAngularSpeed || 1.15);
    const cx = arena.clientWidth * 0.5;
    const cy = arena.clientHeight * 0.43;

    // 大きく駆け回るのではなく、盤面をゆっくり漂うように旋回。
    const floatX =
      Math.sin(elapsed * Number(c.fireWheelFloatSpeedX || 0.72) + wheel.floatSeedX) *
      Number(c.fireWheelFloatX || 18);
    const floatY =
      Math.cos(elapsed * Number(c.fireWheelFloatSpeedY || 0.94) + wheel.floatSeedY) *
      Number(c.fireWheelFloatY || 14);

    wheel.x =
      cx +
      Math.cos(angle) * Number(c.fireWheelOrbitRadiusX || 118) +
      floatX;

    wheel.y =
      cy +
      Math.sin(angle) * Number(c.fireWheelOrbitRadiusY || 172) +
      floatY;

    positionUnit(wheel.el, wheel.x, wheel.y);

    // 見た目と当たり判定を一致させる。
    // 旧実装は「火炎車の中心点と敵の中心点の距離」だけで判定していたため、
    // 画像同士は明らかに重なっていても、中心距離が少し遠いだけで
    // やけどが付かないケースがあった。
    const wheelRect = wheel.el.getBoundingClientRect();

    if (isNormalBattle()) {
      (state.normalEnemies || []).forEach(enemy => {
        if (!enemy || !enemy.el || enemy.hp <= 0) return;

        const enemyRect = enemy.el.getBoundingClientRect();

        // 炎の輪と敵画像が視覚的に重なったらやけど付与。
        if (rectsHit(wheelRect, enemyRect, 6, 8)) {
          igniteIgnisTarget(enemy, c, now);
        }
      });
    } else if (state.boss && state.boss.hp > 0) {
      const bossEl = document.getElementById(BOSS_ID);
      if (!bossEl) return;

      const bossRect = bossEl.getBoundingClientRect();

      if (rectsHit(wheelRect, bossRect, 8, 12)) {
        igniteIgnisTarget({ isBoss: true }, c, now);
      }
    }
  }

  function useIgnisUlt(c) {
    if (!state) return;

    showUltCut(c.ultName, c.effectKey);
    ultScreenFlash('ult-flash-eri');

    removeIgnisFireWheel();

    const arena = document.getElementById('shooting-arena');
    if (!arena) return;

    const el = document.createElement('div');
    el.className = 'shooting-ignis-fire-wheel';
    el.innerHTML = '<i></i><b></b><span></span>';
    el.style.width = `${Number(c.fireWheelSize || 104)}px`;
    el.style.height = `${Number(c.fireWheelSize || 104)}px`;
    arena.appendChild(el);

    const now = performance.now();
    state.ignisFireWheel = {
      el,
      x: arena.clientWidth * 0.5,
      y: arena.clientHeight * 0.5,
      startedAt: now,
      endAt: now + Number(c.fireWheelDurationMs || 3500),
      startAngle: -Math.PI / 2,
      floatSeedX: Math.random() * Math.PI * 2,
      floatSeedY: Math.random() * Math.PI * 2,
    };

    state.ultLockUntil = now + 280;
    requestAnimationFrame(() => el.classList.add('active'));
    updateIgnisFireWheel(now);
  }

  // ============================================================
  // build1668: クラリネ ULT「空想遊戯」を刷新（スマイルの箱に近い仕様）
  //  ・自機の目の前にバトルユニットと同じ大きさのデコイを1体だけ置く（動かない）
  //  ・4秒間居座り、その間は敵弾を遮断（HPなし・壊れない）
  //  ・0.21秒ごとに8方向へ散弾。爆発はせず、時間で消える
  //  ・遮断は前フレーム位置→現在位置の線分判定（スマイルと同じ）で高速弾の貫通も防ぐ
  // ============================================================
  function getClarineDecoyConfig() {
    return getBattleCharacter(CHARACTER_ID.CLARINE) || {};
  }

  function removeClarineDecoy(decoy) {
    if (!decoy) return;
    if (decoy.el) {
      const el = decoy.el;
      el.classList.add('expired');
      setTimeout(() => el.remove(), 260);
      decoy.el = null;
    }
  }

  function clearClarineDecoys() {
    if (!state) return;
    (state.clarineDecoys || []).forEach(d => d?.el?.remove());
    state.clarineDecoys = [];
  }

  function tryBlockEnemyBulletWithClarineDecoy(bullet, fromX, fromY, now) {
    if (!state || !Array.isArray(state.clarineDecoys) || !state.clarineDecoys.length) return false;
    const toX = Number(bullet.x || 0);
    const toY = Number(bullet.y || 0);
    const hw = Math.max(0, Number(bullet._hw || bullet.canvasHalfWidth || 0));
    const hh = Math.max(0, Number(bullet._hh || bullet.canvasHalfHeight || 0));
    for (const d of state.clarineDecoys) {
      if (!d || !d.el || now >= d.expireAt) continue;
      const t = segmentAabbEntryT(
        fromX, fromY, toX, toY,
        d.x - d.blockHalfW - hw, d.x + d.blockHalfW + hw,
        d.y - d.blockHalfH - hh, d.y + d.blockHalfH + hh
      );
      if (t === null) continue;
      // 被弾の光：再スタートのためのレイアウト読み（offsetWidth）を使わず Web Animations で鳴らす
      if (now - Number(d.lastHitFxAt || 0) >= 110) {
        d.lastHitFxAt = now;
        try {
          d.img?.animate([{ filter:'brightness(1.7)' }, { filter:'brightness(1)' }], { duration:120, easing:'ease-out' });
        } catch (_) {}
      }
      return true;
    }
    return false;
  }

  // 大きさ＝発動時のクラリネのバトルユニット（表示中の画像の実寸）。発動時に1回だけ測る。
  function getClarineUnitDisplaySize() {
    const img = document.querySelector('#shooting-player img');
    let w = 0, h = 0;
    // 画像の読み込み前・失敗時は実寸が当てにならないので既定サイズを使う
    if (img && img.complete && img.naturalWidth > 0) {
      const r = img.getBoundingClientRect();
      w = r.width; h = r.height;
    }
    if (!(w > 24 && h > 40)) {
      const wide = window.innerWidth >= 700;
      w = wide ? 76 : 70; h = wide ? 136 : 122;
    }
    return { w, h };
  }

  function createClarineDecoy(c, now) {
    const arena = document.getElementById('shooting-arena');
    if (!arena || !state) return null;
    const width = Math.max(120, Number(arena.clientWidth || 0));
    const height = Math.max(120, Number(arena.clientHeight || 0));
    const size = getClarineUnitDisplaySize();
    const halfW = size.w / 2, halfH = size.h / 2;
    // 自機のすぐ前（自機の上端とデコイの下端が少し離れる位置）
    const gap = Number(c.decoyFrontGap ?? 10);
    const x = clamp(Number(state.player.x ?? width * .5), halfW + 6, Math.max(halfW + 6, width - halfW - 6));
    const y = clamp(Number(state.player.y ?? height * .75) - (size.h + gap),
      halfH + 40, Math.max(halfH + 40, height - halfH - 6));

    const el = document.createElement('div');
    el.className = 'shooting-clarine-decoy';
    el.style.width = `${Math.round(size.w)}px`;
    el.style.height = `${Math.round(size.h)}px`;
    const img = document.createElement('img');
    img.src = c.decoyImage || 'images/chara_27_battle_decoy.webp';
    img.alt = 'デコイ';
    img.draggable = false;
    el.appendChild(img);
    arena.appendChild(el);
    positionUnit(el, x, y);
    requestAnimationFrame(() => el.classList.add('show'));

    const blockW = Math.max(0.4, Math.min(1, Number(c.decoyBlockWidthRate ?? 0.86)));
    const blockH = Math.max(0.4, Math.min(1, Number(c.decoyBlockHeightRate ?? 0.9)));
    return {
      id: `clarine_decoy_${++state.clarineDecoySeq}`,
      ownerId: c.id,
      x, y, el, img,
      // 敵の群れ（蜘蛛など）がデコイを狙う判定用。HPは減らない。
      hp: 1,
      blockHalfW: halfW * blockW,
      blockHalfH: halfH * blockH,
      _hw: halfW, _hh: halfH,
      expireAt: now + Math.max(500, Number(c.decoyDurationMs || 4000)),
      nextShotAt: now + 120,
      fireIntervalMs: Math.max(60, Number(c.decoyFireIntervalMs || 210)),
      ways: Math.max(1, Math.floor(Number(c.decoyShotWays || 8))),
      bulletSpeed: Number(c.decoyBulletSpeed || 300),
      bulletDamage: Number(c.decoyBulletDamage || 1.2),
      lastHitFxAt: 0,
    };
  }

  function fireClarineDecoyBurst(decoy, c) {
    if (!state || !decoy || !decoy.el) return;
    const attrClass = getCharacterBulletClass(c);
    const cls = 'shooting-bullet shooting-bullet-clarine-decoy' + attrClass;
    // 8方向（真上から45°ごと）
    for (let i = 0; i < decoy.ways; i++) {
      const angle = -Math.PI / 2 + (i / decoy.ways) * Math.PI * 2;
      const p = makeProjectile(
        cls, decoy.x, decoy.y,
        Math.cos(angle) * decoy.bulletSpeed,
        Math.sin(angle) * decoy.bulletSpeed,
        decoy.bulletDamage, decoy.ownerId
      );
      if (p) {
        // ULTそのものが次のULTゲージやCOMBOを生まないようにする。
        p.noUltGain = true;
        p.noComboGain = true;
        p.sourceType = 'clarine_decoy';
        state.bullets.push(p);
      }
    }
  }

  function updateClarineDecoys(dt, now) {
    if (!state || !Array.isArray(state.clarineDecoys) || !state.clarineDecoys.length) return;
    if (state.ended || state.finishing) { clearClarineDecoys(); return; }
    const c = getClarineDecoyConfig();
    state.clarineDecoys = state.clarineDecoys.filter(decoy => {
      if (!decoy || !decoy.el) return false;
      if (now >= decoy.expireAt) {
        removeClarineDecoy(decoy);
        return false;
      }
      if (now >= decoy.nextShotAt) {
        fireClarineDecoyBurst(decoy, c);
        decoy.nextShotAt = now + decoy.fireIntervalMs;
      }
      return true;
    });
  }

  function useClarineUlt(c) {
    if (!state) return;
    showUltCut(c.ultName, c.effectKey);
    ultScreenFlash('ult-flash-eri');

    const now = performance.now();
    state.ultLockUntil = now + 320;

    // デコイは常に1体。残っている間に再発動したら、古い方を消して新しく置き直す。
    (state.clarineDecoys || []).forEach(d => removeClarineDecoy(d));
    state.clarineDecoys = [];
    const decoy = createClarineDecoy(c, now);
    if (decoy) state.clarineDecoys.push(decoy);

    renderHud();
  }

  // build1523 — スゥ ULT「時空操環」
  // 描画は要素1個とCSSの薄い同心円だけ。Canvas/粒子/画面フィルターは使わない。
  // 領域は現在操作中の自機に追従。切替時も効果時間中は継続する。
  function isSuiTimeDomainActive(now = performance.now()) {
    return !!(state && !state.ended && !state.finishing &&
      now < Number(state.suiTimeDomainUntil || 0));
  }

  function getSuiTimeDomainAtkMultiplier(now = performance.now()) {
    // 領域は自機を中心に移動するため、現在操作中のキャラは常に内部にいる。
    return isSuiTimeDomainActive(now)
      ? Math.max(1, Number(state.suiTimeDomainAtkMultiplier || 1.3)) : 1;
  }

  function syncSuiTimeDomainVisual(now = performance.now()) {
    if (!state) return;
    let ring = state.suiTimeDomainEl;
    if (!isSuiTimeDomainActive(now)) {
      if (ring && ring.isConnected) ring.remove();
      state.suiTimeDomainEl = null;
      return;
    }
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    if (!ring || !ring.isConnected || ring.parentElement !== arena) {
      ring = document.createElement('div');
      ring.className = 'shooting-sui-time-domain';
      ring.setAttribute('aria-hidden', 'true');
      const diameter = Math.max(1, Number(state.suiTimeDomainRadius || 275)) * 2;
      ring.style.width = `${diameter}px`;
      ring.style.height = `${diameter}px`;
      arena.appendChild(ring);
      state.suiTimeDomainEl = ring;
      state.suiTimeDomainVisualX = NaN;
      state.suiTimeDomainVisualY = NaN;
    }
    const x = Number(state.player?.x || 0);
    const y = Number(state.player?.y || 0);
    if (x !== state.suiTimeDomainVisualX || y !== state.suiTimeDomainVisualY) {
      ring.style.transform = `translate3d(${x}px,${y}px,0) translate(-50%,-50%)`;
      state.suiTimeDomainVisualX = x;
      state.suiTimeDomainVisualY = y;
    }
  }

  function useSuiTimeDomainUlt(c) {
    if (!state || state.ended || state.finishing) return;
    const now = performance.now();
    showUltCut(c.ultName || '時空操環', c.effectKey, c);
    state.suiTimeDomainUntil = now + Math.max(1000, Number(c.suiDomainDurationMs || 6000));
    state.suiTimeDomainRadius = Math.max(190, Number(c.suiDomainRadius || 275));
    state.suiTimeDomainBulletSpeedMultiplier = Math.max(0.05, Math.min(1, Number(c.suiDomainBulletSpeedMultiplier || 0.2)));
    state.suiTimeDomainAtkMultiplier = Math.max(1, Number(c.suiDomainAtkMultiplier || 1.3));
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + 230);
    syncSuiTimeDomainVisual(now);
    renderHud();
  }

  function ensureArnoSlashStyle() {
    if (document.getElementById('shooting-arno-slash-style')) return;
    const style = document.createElement('style');
    style.id = 'shooting-arno-slash-style';
    style.textContent = `
      .shooting-arno-slash-overlay{
        position:absolute;inset:0;z-index:88;pointer-events:auto;touch-action:none;
        background:radial-gradient(circle at 50% 42%,rgba(255,255,255,.08),rgba(18,18,22,.10) 66%,rgba(10,10,14,.18));
        -webkit-tap-highlight-color:transparent;
      }
      .shooting-arno-slash-prompt{
        position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
        min-width:180px;text-align:center;
        color:#fff;font-family:"Noto Serif JP",serif;
        pointer-events:none;
        text-shadow:
          0 2px 8px rgba(0,0,0,.72),
          0 0 18px rgba(255,255,255,.72);
      }
      .shooting-arno-slash-prompt b{
        display:block;
        font-size:34px;
        line-height:1;
        font-weight:700;
        letter-spacing:.12em;
        white-space:nowrap;
        animation:shootingArnoRapidTapPrompt .46s ease-in-out infinite alternate;
      }
      .shooting-arno-slash-prompt small{
        display:block;margin-top:8px;font-size:15px;letter-spacing:.18em;font-weight:600;
      }
      @keyframes shootingArnoRapidTapPrompt{
        from{opacity:.76;transform:scale(.94)}
        to{opacity:1;transform:scale(1.06)}
      }
      .shooting-arno-slash-fx{
        position:absolute;z-index:89;width:96px;height:3px;left:0;top:0;
        transform-origin:center center;pointer-events:none;
        background:linear-gradient(90deg,transparent,rgba(255,255,255,.98) 22%,#fff 50%,rgba(225,230,236,.92) 76%,transparent);
        box-shadow:0 0 6px rgba(255,255,255,.96),0 0 13px rgba(210,220,235,.62);
        animation:shootingArnoSlashFx 180ms ease-out forwards;
      }
      @keyframes shootingArnoSlashFx{
        0%{opacity:0;filter:blur(2px);scale:.65 1}
        18%{opacity:1;filter:blur(0);scale:1.08 1}
        100%{opacity:0;filter:blur(1px);scale:1.22 1}
      }
      #shooting-event-root.arno-slash-time-stop .shooting-wash{
        background:linear-gradient(180deg,rgba(255,255,255,.16),rgba(220,225,232,.05) 48%,rgba(235,235,240,.14));
      }
    `;
    document.head.appendChild(style);
  }

  function getArnoSlashTarget() {
    if (!state) return null;
    const px = Number(state.player?.x || 0);
    const py = Number(state.player?.y || 0);
    const candidates = [];

    (state.normalEnemies || []).forEach(enemy => {
      if (!enemy || !enemy.el || enemy.hp <= 0) return;
      candidates.push({
        kind:'normal', key:`normal:${enemy.uid || ''}`, ref:enemy,
        x:Number(enemy.x || 0), y:Number(enemy.y || 0)
      });
    });

    if (!isNormalBattle() && state.boss && state.boss.hp > 0) {
      candidates.push({
        kind:'boss', key:'boss', ref:state.boss,
        x:Number(state.boss.x || 0), y:Number(state.boss.y || 0)
      });
    }

    if (!candidates.length) return null;
    candidates.sort((a,b) => {
      const da = (a.x-px)*(a.x-px) + (a.y-py)*(a.y-py);
      const db = (b.x-px)*(b.x-px) + (b.y-py)*(b.y-py);
      return da-db;
    });
    return candidates[0];
  }

  function moveArnoInFrontOfTarget(target) {
    if (!state || !target) return;
    const arena = document.getElementById('shooting-arena');
    const player = document.getElementById(PLAYER_ID);
    if (!arena || !player) return;
    const marginX = 36;
    const marginY = 44;
    const x = clamp(Number(target.x || 0), marginX, Math.max(marginX, arena.clientWidth - marginX));
    // 敵の「手前」＝画面下側へ約72px。画面端では安全域へクランプする。
    const y = clamp(Number(target.y || 0) + 72, marginY, Math.max(marginY, arena.clientHeight - marginY));
    state.player.x = x;
    state.player.y = y;
    positionUnit(player, x, y);
  }

  function createArnoSlashFx(target, slashCount) {
    const arena = document.getElementById('shooting-arena');
    if (!arena || !target) return;
    const fx = document.createElement('div');
    fx.className = 'shooting-arno-slash-fx';
    const angleSet = [-36,-22,-10,12,25,39];
    const angle = angleSet[Math.abs(Number(slashCount || 0)) % angleSet.length] + (Math.random() - .5) * 8;
    const x = Number(target.x || 0) + (Math.random() - .5) * 28;
    const y = Number(target.y || 0) + (Math.random() - .5) * 24;
    fx.style.transform = `translate3d(${x - 48}px,${y - 1.5}px,0) rotate(${angle}deg)`;
    arena.appendChild(fx);
    setTimeout(() => { if (fx.isConnected) fx.remove(); }, 220);
  }

  function damageArnoSlashTarget(c, target, now) {
    if (!state || !target || !c) return false;
    const baseDamage = Math.max(0, Number(c.atk || 0) * Number(c.arnoSlashDamageAtkRate || 0.35));
    if (target.kind === 'normal') {
      const enemy = target.ref;
      if (!enemy || !enemy.el || enemy.hp <= 0) return false;
      const targetElement = getCombatTargetElement(enemy);
      const attackElement = getUltAttackElement(c);
      const finalDamage = applyElementDamage(baseDamage, attackElement, targetElement);
      damageNormalEnemy(enemy, finalDamage, now, true, getElementDamageReaction(attackElement, targetElement));
      return true;
    }

    if (target.kind === 'boss') {
      if (!state.boss || state.boss.hp <= 0) return false;
      const targetElement = getCombatTargetElement(state.boss);
      const attackElement = getUltAttackElement(c);
      const finalDamage = applyElementDamage(baseDamage, attackElement, targetElement);
      const appliedDamage = Math.min(state.boss.hp, Math.max(0, Number(finalDamage || 0)));
      state.boss.hp = Math.max(0, state.boss.hp - appliedDamage);
      showBossDamageNumber(appliedDamage, true, getElementDamageReaction(attackElement, targetElement));
      if (!addScoreAttackDamageScore(appliedDamage)) addLegacyCombatScore(Math.round(appliedDamage * 100));
      createHit(state.boss.x, state.boss.y, true);
      flashBossHit(true);
      updateBossPhase();
      if (state.boss.hp <= 0) beginBossDefeat();
      return true;
    }
    return false;
  }

  function finishArnoUlt() {
    if (!state || !state.arnoSlashActive) return;
    const now = performance.now();
    const startedAt = Number(state.arnoSlashStartedAt || now);
    const frozenFor = Math.max(0, now - startedAt);
    const root = document.getElementById(ROOT_ID);
    const player = document.getElementById(PLAYER_ID);
    const overlay = root && root.querySelector('.shooting-arno-slash-overlay');

    // ULT中に経過した実時間を、戦闘時計・敵AI時計・バフ等の絶対時刻へまとめて加算。
    // これにより解除直後の弾まとめ撃ち、移動位置ジャンプ、クリアタイム加算を防ぐ。
    if (frozenFor > 0) shiftPausedTimestamps(state, frozenFor);
    resetEnemyMotionFreezeSampling(now);

    clearEnemyBulletsOnly();
    state.arnoSlashActive = false;
    state.arnoSlashStartedAt = 0;
    state.arnoSlashUntil = 0;
    state.arnoSlashLastTapAt = -9999;
    state.arnoSlashTargetKey = '';
    state.arnoSlashTimerId = 0;

    // 接敵位置のまま再開すると接触ダメージを受けるため、発動前の位置へ戻してから解除する。
    // 戻った後は1秒だけ盤面を硬直させ、その後に味方・敵とも通常進行へ復帰する。
    const recoveryUntil = now + 1000;
    if (state.player) {
      state.player.x = Number(state.arnoSlashOriginX || state.player.x || 0);
      state.player.y = Number(state.arnoSlashOriginY || state.player.y || 0);
      state.player.invulnUntil = Math.max(Number(state.player.invulnUntil || 0), recoveryUntil);
      if (player) positionUnit(player, state.player.x, state.player.y);
    }

    // shiftPausedTimestamps()でULT中の絶対時刻を保護した後、
    // 千ノ刻専用のロックだけは「終了後1秒」に正規化する。
    // これを行わないとULT時間分が二重加算され、解除後に数秒硬直する。
    state.ultLockUntil = recoveryUntil;
    state.playerShotLockUntil = recoveryUntil;
    state.lastShotAt = now;

    // 敵の射撃時計もULT中に未来へ送られているため、終了時点へ正規化する。
    // 1秒の共通硬直中はultLockUntilで敵AI更新自体が止まり、解除後は通常の攻撃間隔で再開する。
    (state.normalEnemies || []).forEach(enemy => {
      if (!enemy || enemy.hp <= 0) return;
      enemy.lastShotAt = now;
      enemy.nextActionAt = recoveryUntil;
      enemy.attackExecuteAt = 0;
      enemy.attackState = 'idle';
      enemy.dashUntil = 0;
      enemy.dashVx = 0;
      enemy.dashVy = 0;
    });
    if (!isNormalBattle() && state.boss && state.boss.hp > 0) {
      state.lastBossShotAt = now;
      removeBossDangerWarning();
      state.bossDangerExecuteAt = 0;
      state.nextBossDangerAt = Math.max(recoveryUntil, now + 1000);
    }
    prevTs = now;

    // build2056: 麻痺つき（ID113）。斬った敵を、盤面の再開後さらに arnoSlashParalyzeMs のあいだ行動不能にする
    const paralyzeMs = Math.max(0, Number(state.arnoSlashParalyzeMs || 0));
    if (paralyzeMs > 0 && Array.isArray(state.arnoSlashHitTargets)) {
      const paralyzeUntil = recoveryUntil + paralyzeMs;
      state.arnoSlashHitTargets.forEach(t => {
        if (t.kind === 'normal') {
          const enemy = t.ref; if (!enemy || enemy.hp <= 0) return;
          freezeNormalEnemyAction(enemy, paralyzeUntil, Math.max(0, (state.normalEnemies || []).indexOf(enemy)));
          createParalysisFx(enemy, paralyzeUntil);
        } else if (t.kind === 'boss' && state.boss && state.boss.hp > 0 && !isNormalBattle()) {
          state.bossStunUntil = Math.max(Number(state.bossStunUntil || 0), paralyzeUntil);
          deferBossAttackResume(paralyzeUntil);
          createParalysisFx(state.boss, paralyzeUntil, true);
        }
      });
    }
    // build2060: ディノヴァは麻痺の代わりに、斬った敵の左右へ放電コアを設置（壊すとダメージ＋麻痺）
    if (state.deinovaUltCoreCfg) placeDeinovaUltCores(now, recoveryUntil);
    state.deinovaUltCoreCfg = null;
    state.arnoSlashParalyzeMs = 0;
    state.arnoSlashHitTargets = [];

    if (overlay) {
      overlay.classList.add('hide');
      setTimeout(() => { if (overlay.isConnected) overlay.remove(); }, 160);
    }
    if (root) root.classList.remove('arno-slash-time-stop');
    renderHud();
  }

  function useArnoUlt(c) {
    if (!state || state.arnoSlashActive) return;
    const now = performance.now();
    const duration = Math.max(500, Number(c.arnoSlashDurationMs || 4000));
    const root = document.getElementById(ROOT_ID);
    const arena = document.getElementById('shooting-arena');
    if (!root || !arena) return;

    ensureArnoSlashStyle();
    clearEnemyBulletsOnly();

    state.arnoSlashActive = true;
    state.arnoSlashStartedAt = now;
    state.arnoSlashUntil = now + duration;
    state.arnoSlashOriginX = Number(state.player?.x || 0);
    state.arnoSlashOriginY = Number(state.player?.y || 0);
    state.arnoSlashLastTapAt = -9999;
    state.arnoSlashCount = 0;
    state.arnoSlashTargetKey = '';
    // build2056: 麻痺つき（ID113 ディノヴァ）。斬った敵を覚えておき、ULT終了後に行動不能にする
    state.arnoSlashParalyzeMs = Math.max(0, Number(c.arnoSlashParalyzeMs || 0));
    state.deinovaUltCoreCfg = getDeinovaUltCoreConfigFromCharacter(c); // build2060
    state.arnoSlashHitTargets = [];
    // ULT中は通常射撃を完全に封じる。
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + duration);
    state.playerShotLockUntil = Math.max(Number(state.playerShotLockUntil || 0), now + duration);

    const initialTarget = getArnoSlashTarget();
    if (initialTarget) {
      state.arnoSlashTargetKey = initialTarget.key;
      moveArnoInFrontOfTarget(initialTarget);
    }

    root.classList.add('arno-slash-time-stop');
    root.querySelectorAll('.shooting-arno-slash-overlay').forEach(el => el.remove());
    const overlay = document.createElement('div');
    overlay.className = 'shooting-arno-slash-overlay';
    // build1672: 1回のULTで出せる斬撃は最大 arnoSlashMaxHits 回（アルノ13回＝ATK×4.55／アリス14回＝ATK×3.5）。残り回数を表示。
    const maxHits = Math.max(1, Math.floor(Number(c.arnoSlashMaxHits || 13)));
    overlay.innerHTML = `<div class="shooting-arno-slash-prompt"><b>連打！</b><small>残り <span class="arno-slash-left">${maxHits}</span></small></div>`;
    const leftEl = overlay.querySelector('.arno-slash-left');
    arena.appendChild(overlay);

    overlay.addEventListener('pointerdown', event => {
      event.preventDefault();
      event.stopPropagation();
      if (!state || !state.arnoSlashActive || state.ended || state.finishing) return;
      const tapNow = performance.now();
      if (tapNow >= Number(state.arnoSlashUntil || 0)) {
        finishArnoUlt();
        return;
      }
      const minInterval = Math.max(0, Number(c.arnoSlashMinTapIntervalMs || 80));
      if (tapNow - Number(state.arnoSlashLastTapAt || -9999) < minInterval) return;
      state.arnoSlashLastTapAt = tapNow;

      let target = getArnoSlashTarget();
      if (!target) return;
      if (target.key !== state.arnoSlashTargetKey) {
        state.arnoSlashTargetKey = target.key;
        moveArnoInFrontOfTarget(target);
      }

      if (Number(state.arnoSlashCount || 0) >= maxHits) return;
      state.arnoSlashCount = Math.max(0, Number(state.arnoSlashCount || 0)) + 1;
      createArnoSlashFx(target, state.arnoSlashCount);
      damageArnoSlashTarget(c, target, tapNow);
      if ((state.arnoSlashParalyzeMs > 0 || state.deinovaUltCoreCfg) && Array.isArray(state.arnoSlashHitTargets)) {
        const known = state.arnoSlashHitTargets.find(t => t.key === target.key);
        if (known) known.hits = Number(known.hits || 1) + 1;
        else state.arnoSlashHitTargets.push({ key: target.key, kind: target.kind, ref: target.ref, hits: 1 });
      }
      if (leftEl) leftEl.textContent = String(Math.max(0, maxHits - state.arnoSlashCount));
      // 上限に達したら、最後の斬撃の演出を見せてから少し早めに終了する（待ち時間を作らない）
      if (state.arnoSlashCount >= maxHits && state.arnoSlashActive) {
        const endAt = Math.min(Number(state.arnoSlashUntil || tapNow), tapNow + 260);
        clearTimeout(state.arnoSlashTimerId);
        state.arnoSlashTimerId = setTimeout(() => {
          if (state && state.arnoSlashActive) finishArnoUlt();
        }, Math.max(0, endAt - tapNow));
      }
    }, { passive:false });

    // 停止中に敵側の次回攻撃時刻をULT終了時刻へ送り、内部蓄積を作らない。
    // 終了後の1秒硬直はfinishArnoUlt()側で一律管理する。
    deferAllEnemyAttackResume(now + duration);
    prevTs = now;
    renderHud();

    const timerId = setTimeout(() => {
      if (!state || !state.arnoSlashActive) return;
      finishArnoUlt();
    }, duration);
    state.arnoSlashTimerId = timerId;
  }


  // ============================================================
  // SIGMA-IX：ブラックシップ
  // 正面へ5秒間の極太レーザー。敵弾消去・スタン等の追加効果なし。
  // ============================================================
  function applyTestChanBeamTick(c, now) {
    if (!state || state.ended || state.finishing) return;
    const beamWidth = Math.max(30, Number(c.ultBeamWidth || 62));
    const half = beamWidth * 0.5;
    const px = Number(state.player.x || 0);
    const py = Number(state.player.y || 0);
    const damage = Number(c.atk || 0) * Number(c.ultBeamTickAtkMultiplier || 0.35);

    if (isNormalBattle()) {
      const targets = (state.normalEnemies || []).filter(enemy =>
        enemy && enemy.el && enemy.hp > 0 &&
        Number(enemy.y || 0) < py &&
        Math.abs(Number(enemy.x || 0) - px) <= half + 28
      );
      targets.forEach(enemy => {
        const targetElement = getCombatTargetElement(enemy);
        const finalDamage = applyElementDamage(damage, getUltAttackElement(c), targetElement);
        damageNormalEnemy(enemy, finalDamage, now, false, getElementDamageReaction(getUltAttackElement(c), targetElement));
      });
      state.normalEnemies = (state.normalEnemies || []).filter(enemy => enemy && enemy.hp > 0);
      addLegacyCombatScore(Math.round(damage * 30 * Math.max(1, targets.length)));
      evaluateNormalMission(now);
      renderHud();
      return;
    }

    // build1740: BOSS戦の随伴敵（鳥居など）も、レーザー正面にいれば攻撃。
    damageBossAddsByUlt(getBossAddUltTargets().filter(enemy =>
      Number(enemy.y || 0) < py && Math.abs(Number(enemy.x || 0) - px) <= half + 28
    ), damage, c, now, false);

    // SPECIAL EVENTのHP付きオブジェクトも、レーザー正面にいれば攻撃。
    if (isFacelessStage()) {
      (state.facelessObjects || []).forEach(obj => {
        if (!obj || !obj.el || obj.hp <= 0) return;
        if (Number(obj.y || 0) >= py) return;
        if (Math.abs(Number(obj.x || 0) - px) > half + 30) return;
        const targetElement = getCombatTargetElement(obj, state.boss?.element);
        const finalDamage = applyElementDamage(damage, getUltAttackElement(c), targetElement);
        damageFacelessObject(obj, finalDamage, now, getElementDamageReaction(getUltAttackElement(c), targetElement));
      });
    }

    if (!state.boss || state.boss.hp <= 0) return;
    if (Number(state.boss.y || 0) >= py) return;
    if (Math.abs(Number(state.boss.x || 0) - px) > half + 48) return;

    const targetElement = getCombatTargetElement(state.boss);
    const finalDamage = applyElementDamage(damage, getUltAttackElement(c), targetElement);
    const applied = Math.min(state.boss.hp, Math.max(0, finalDamage));
    state.boss.hp = Math.max(0, state.boss.hp - applied);
    updateBossPhase();
    if (!addScoreAttackDamageScore(applied)) {
      addLegacyCombatScore(Math.round(applied * 100));
    }

    // 5秒持続ULTなので数字・HIT演出は毎tick出さず軽量化。
    if (!isRaidStage() || shouldRenderRaidBossHitVisual(now, 'hit')) {
      createHit(state.boss.x, state.boss.y, false);
      flashBossHit(false);
    }
    if (!isRaidStage() || shouldRenderRaidBossHitVisual(now, 'number')) {
      showBossDamageNumber(applied, false, getElementDamageReaction(getUltAttackElement(c), targetElement));
    }

    renderHud();
    if (state.boss.hp <= 0) beginBossDefeat();
  }


  function pointSegmentDistance(px, py, ax, ay, bx, by) {
    const abx = bx - ax;
    const aby = by - ay;
    const lenSq = abx * abx + aby * aby;
    if (lenSq <= 0.0001) return Math.hypot(px - ax, py - ay);
    const t = clamp(((px - ax) * abx + (py - ay) * aby) / lenSq, 0, 1);
    const qx = ax + abx * t;
    const qy = ay + aby * t;
    return Math.hypot(px - qx, py - qy);
  }

  function randomJigBounceAngle(side, previousAngle) {
    // 壁沿いに張り付く極端な浅角度を避けつつ、反射のたびに十分ランダム化する。
    const minNormal = 0.34; // 壁法線方向の最低成分。約20度相当。
    let vx = 0;
    let vy = 0;
    for (let i = 0; i < 10; i++) {
      let a = Math.random() * Math.PI * 2;
      vx = Math.cos(a);
      vy = Math.sin(a);
      const valid =
        (side === 'left'   && vx >  minNormal) ||
        (side === 'right'  && vx < -minNormal) ||
        (side === 'top'    && vy >  minNormal) ||
        (side === 'bottom' && vy < -minNormal);
      if (!valid) continue;
      // 直前とほぼ同じ向きだけは避け、スクランブル感を保つ。
      const delta = Math.abs(Math.atan2(Math.sin(a - previousAngle), Math.cos(a - previousAngle)));
      if (delta < 0.22) continue;
      return a;
    }
    // フォールバック：通常反射に少しだけランダム角を足す。
    if (side === 'left' || side === 'right') return Math.PI - previousAngle + (Math.random() - .5) * .8;
    return -previousAngle + (Math.random() - .5) * .8;
  }

  function damageJigScrambleTargets(beam, c, now) {
    if (!state || !beam) return;
    const len = Math.max(48, Number(c.jigUltBeamLength || 280));
    const angle = Number(beam.angle || 0);
    const hx = Number(beam.x || 0);
    const hy = Number(beam.y || 0);
    const tx = hx - Math.cos(angle) * len;
    const ty = hy - Math.sin(angle) * len;
    const hitInterval = Math.max(80, Number(c.jigUltHitIntervalMs || 200));
    const baseDamage = Number(c.atk || 0) * Math.max(0, Number(c.jigUltDamageAtkRate || 0.12));
    const beamRadius = Math.max(10, Number(c.jigUltBeamWidth || 2) * 1.8);

    if (isNormalBattle() || hasBossAdds()) {
      (state.normalEnemies || []).slice().forEach(enemy => {
        if (!enemy || !enemy.el || enemy.hp <= 0) return;
        const key = enemy;
        const last = Number(beam.hitCooldown.get(key) || -Infinity);
        if (now - last < hitInterval) return;
        const hitRadius = beamRadius + 22;
        if (pointSegmentDistance(Number(enemy.x || 0), Number(enemy.y || 0), tx, ty, hx, hy) > hitRadius) return;
        beam.hitCooldown.set(key, now);
        const targetElement = getCombatTargetElement(enemy);
        const finalDamage = applyElementDamage(baseDamage, getUltAttackElement(c), targetElement);
        damageNormalEnemy(enemy, finalDamage, now, false, getElementDamageReaction(getUltAttackElement(c), targetElement));
      });
      state.normalEnemies = (state.normalEnemies || []).filter(enemy => enemy && enemy.hp > 0);
    }

    if (!isNormalBattle() && state.boss && state.boss.hp > 0) {
      const key = state.boss;
      const last = Number(beam.hitCooldown.get(key) || -Infinity);
      if (now - last >= hitInterval) {
        const bossHitRadius = beamRadius + 44;
        if (pointSegmentDistance(Number(state.boss.x || 0), Number(state.boss.y || 0), tx, ty, hx, hy) <= bossHitRadius) {
          beam.hitCooldown.set(key, now);
          const targetElement = getCombatTargetElement(state.boss);
          const finalDamage = applyElementDamage(baseDamage, getUltAttackElement(c), targetElement);
          const appliedDamage = Math.min(state.boss.hp, Math.max(0, Number(finalDamage || 0)));
          state.boss.hp = Math.max(0, state.boss.hp - appliedDamage);
          updateBossPhase();
          if (shouldRenderRaidBossHitVisual(now, 'hit')) {
            createHit(Number(state.boss.x || hx), Number(state.boss.y || hy), false);
            flashBossHit(false, true);
          }
          if (shouldRenderRaidBossHitVisual(now, 'number')) showBossDamageNumber(appliedDamage, false, getElementDamageReaction(getUltAttackElement(c), targetElement));
          if (!addScoreAttackDamageScore(appliedDamage)) addLegacyCombatScore(Math.round(appliedDamage * 70));
          if (state.boss.hp <= 0) beginBossDefeat();
        }
      }
    }
  }

  function useJigScrambleUlt(c) {
    const arena = document.getElementById('shooting-arena');
    const root = document.getElementById(ROOT_ID);
    if (!arena || !state) return;

    showUltCut(c.ultName || 'SCRAMBLE RAY', c.effectKey);
    clearEnemyBulletsOnly();

    const duration = Math.max(1000, Number(c.jigUltDurationMs || 5000));
    const count = Math.max(1, Math.round(Number(c.jigUltBeamCount || 6)));
    const speed = Math.max(180, Number(c.jigUltBeamSpeed || 520));
    const len = Math.max(48, Number(c.jigUltBeamLength || 280));
    const width = Math.max(2, Number(c.jigUltBeamWidth || 2));
    const startX = Number(state.player.x || arena.clientWidth * .5);
    const startY = Number(state.player.y || arena.clientHeight * .78);
    const margin = 3;
    const token = (Number(state.jigScrambleToken || 0) + 1);
    state.jigScrambleToken = token;
    state.ultActiveUntil = performance.now() + duration;
    state.ultLockUntil = performance.now() + 260;

    arena.querySelectorAll('.shooting-jig-scramble-ray').forEach(el => el.remove());
    if (root) {
      root.classList.remove('jig-scramble-active');
      void root.offsetWidth;
      root.classList.add('jig-scramble-active');
    }

    const beams = [];
    for (let i = 0; i < count; i++) {
      // 均等放射を基準に少し乱し、6本が最初から同方向へ固まらないようにする。
      const base = -Math.PI * 0.92 + (Math.PI * 1.84) * (i / Math.max(1, count - 1));
      const angle = base + (Math.random() - .5) * 0.34;
      const el = document.createElement('i');
      el.className = 'shooting-jig-scramble-ray';
      el.style.setProperty('--jig-ray-length', len + 'px');
      el.style.setProperty('--jig-ray-width', width + 'px');
      arena.appendChild(el);
      beams.push({
        el,
        x: startX,
        y: startY,
        angle,
        speed: speed * (0.92 + Math.random() * 0.16),
        hitCooldown: new Map(),
      });
    }

    const startedAt = performance.now();
    let lastFrame = startedAt;
    let ended = false;

    function finish() {
      if (ended) return;
      ended = true;
      beams.forEach(beam => beam.el && beam.el.remove());
      if (root) root.classList.remove('jig-scramble-active');
      if (state && state.jigScrambleToken === token) state.ultActiveUntil = 0;
      renderHud();
    }

    function frame(now) {
      if (!state || state.jigScrambleToken !== token || state.ended || state.finishing || now - startedAt >= duration) {
        finish();
        return;
      }
      const dt = Math.min(0.035, Math.max(0.001, (now - lastFrame) / 1000));
      lastFrame = now;
      const w = Math.max(1, arena.clientWidth);
      const h = Math.max(1, arena.clientHeight);

      beams.forEach(beam => {
        let vx = Math.cos(beam.angle) * beam.speed;
        let vy = Math.sin(beam.angle) * beam.speed;
        beam.x += vx * dt;
        beam.y += vy * dt;

        let side = '';
        if (beam.x <= margin) { beam.x = margin; side = 'left'; }
        else if (beam.x >= w - margin) { beam.x = w - margin; side = 'right'; }
        if (beam.y <= margin) { beam.y = margin; side = side || 'top'; }
        else if (beam.y >= h - margin) { beam.y = h - margin; side = side || 'bottom'; }

        if (side) beam.angle = randomJigBounceAngle(side, beam.angle);

        beam.el.style.left = (beam.x - len) + 'px';
        beam.el.style.top = (beam.y - width * .5) + 'px';
        beam.el.style.transform = 'rotate(' + beam.angle + 'rad)';
        damageJigScrambleTargets(beam, c, now);
      });

      renderHud();
      requestAnimationFrame(frame);
    }

    requestAnimationFrame(frame);
    renderHud();
  }

  function useTestChanUlt(c) {
    if (!state || state.ended || state.finishing) return;

    showUltCut(c.ultName, c.effectKey);
    const root = document.getElementById(ROOT_ID);
    const arena = document.getElementById('shooting-arena');
    if (!root || !arena) return;

    root.classList.remove('testchan-blackship-active');
    void root.offsetWidth;
    root.classList.add('testchan-blackship-active');

    const old = arena.querySelector('.shooting-testchan-blackship-beam');
    if (old) old.remove();

    const beam = document.createElement('div');
    beam.className = 'shooting-testchan-blackship-beam';
    beam.innerHTML = '<i></i>';
    arena.appendChild(beam);

    const duration = Math.max(1000, Number(c.ultBeamDurationMs || 5000));
    const tickMs = Math.max(100, Number(c.ultBeamTickMs || 250));
    const started = performance.now();
    const until = started + duration;
    const token = (state.testchanUltToken || 0) + 1;
    state.testchanUltToken = token;
    // build566: 5秒レーザー中に敵弾生成だけが止まっていた副作用を修正。
    // 敵は移動・攻撃とも通常継続。使用者の通常射撃だけレーザー終了まで止める。
    state.ultLockUntil = started + 260;
    state.playerShotLockUntil = until;

    let nextDamageAt = started;

    const frame = (now) => {
      if (!state || state.testchanUltToken !== token || state.ended || state.finishing || now >= until) {
        beam.classList.add('ending');
        root.classList.remove('testchan-blackship-active');
        setTimeout(() => beam.isConnected && beam.remove(), 180);
        renderHud();
        return;
      }

      const x = Number(state.player.x || 0);
      const y = Math.max(0, Number(state.player.y || 0));
      const width = Math.max(30, Number(c.ultBeamWidth || 62));
      beam.style.width = `${width}px`;
      beam.style.height = `${Math.max(24, y)}px`;
      beam.style.transform = `translate3d(${x - width / 2}px,0,0)`;

      if (now >= nextDamageAt) {
        applyTestChanBeamTick(c, now);
        nextDamageAt += tickMs;
        if (nextDamageAt < now - tickMs) nextDamageAt = now + tickMs;
      }

      requestAnimationFrame(frame);
    };

    requestAnimationFrame(frame);
    renderHud();
  }


  // ============================================================

  // ============================================================
  // build907: ニーナ ULT「出力最大！」
  // 7秒間 PLASMA威力×1.5 / 射程×2.0。
  // 連鎖数・発射速度は通常時のまま。旧LIGHTNING STORMの落雷は発動しない。
  // ============================================================
  function useNinaOutputMax(c) {
    if (!state || state.ended || state.finishing) return;

    showUltCut(c.ultName || '出力最大！', c.effectKey);

    const now = performance.now();
    const duration = Math.max(1000, Number(c.ninaOutputMaxDurationMs || 7000));
    state.ninaOutputMaxUntil = now + duration;

    // ULT直前のロック状態を一度切り、拡張された射程で再探索させる。
    state.ninaLightningLockedTarget = null;
    state.ninaLightningPendingTarget = null;
    state.ninaLightningLastFireAt = 0;
    state.ninaLightningAttackToken = Number(state.ninaLightningAttackToken || 0) + 1;

    // カットイン後は移動・射撃をすぐ再開。7秒間の強化時間を射撃停止で消費しない。
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + 180);
    renderHud();
  }


  // ============================================================
  // ニーナ旧ULT：LIGHTNING STORM（build907以降は未使用）
  // 8秒 / 16発 / 各ATK×4.0。
  // 毎回、その時点で生存している敵からランダム選択。
  // 命中した敵だけ3秒麻痺（移動・射撃停止）。全体停止はしない。
  // ============================================================
  function getNinaParalyzeElement(target) {
    if (!target) return null;
    if ((target.kind === 'normal' || target.kind === 'faceless') && target.ref && target.ref.el) {
      return target.ref.el;
    }
    if (target.kind === 'boss') return document.getElementById(BOSS_ID);
    return null;
  }

  function showNinaParalyzeVfx(target, element, until) {
    const host = getNinaParalyzeElement(target);
    if (!host) return;

    const visual = ULT_ELEMENT_VISUAL[normalizeCombatElement(element) || 'neutral'] || ULT_ELEMENT_VISUAL.neutral;
    let fx = Array.from(host.children || []).find(child => child && child.classList && child.classList.contains('shooting-nina-paralyze-vfx'));
    if (!fx) {
      fx = document.createElement('span');
      fx.className = 'shooting-nina-paralyze-vfx';
      fx.setAttribute('aria-hidden', 'true');
      fx.innerHTML = `
        <svg viewBox="0 0 100 100" preserveAspectRatio="none">
          <path d="M4 24 L18 11 L29 30 L43 17 L57 35 L74 14 L96 28"/>
          <path d="M8 66 L23 50 L36 70 L50 48 L64 72 L81 54 L95 67"/>
          <path d="M26 4 L39 22 L31 40 L55 55 L45 76 L67 96"/>
        </svg>`;
      host.appendChild(fx);
    }

    fx.style.setProperty('--nina-paralyze-rgb', visual.rgb);
    fx.style.setProperty('--nina-paralyze-color', visual.color);
    const nextUntil = Math.max(Number(fx.dataset.ninaParalyzeUntil || 0), Number(until || 0));
    fx.dataset.ninaParalyzeUntil = String(nextUntil);

    const wait = Math.max(80, nextUntil - performance.now() + 60);
    // build811: 同じ敵へ再命中するたびにremove用Timerを積まない。常に1本だけ更新する。
    if (fx._ninaParalyzeRemoveTimer) clearTimeout(fx._ninaParalyzeRemoveTimer);
    fx._ninaParalyzeRemoveTimer = setTimeout(() => {
      if (!fx || !fx.isConnected) return;
      const activeUntil = Number(fx.dataset.ninaParalyzeUntil || 0);
      if (performance.now() + 8 < activeUntil) return;
      fx._ninaParalyzeRemoveTimer = null;
      try { fx.remove(); } catch (_) {}
    }, wait);
  }

  function applyNinaParalyze(target, durationMs, element) {
    if (!state || !target || !target.ref) return;
    const now = performance.now();
    const duration = Math.max(300, Number(durationMs || 3000));
    const until = now + duration;

    if (target.kind === 'normal') {
      target.ref.noahStunUntil = Math.max(Number(target.ref.noahStunUntil || 0), until);
      showNinaParalyzeVfx(target, element, target.ref.noahStunUntil);
      freezeNormalEnemyAction(target.ref, target.ref.noahStunUntil);
      return;
    }

    if (target.kind === 'faceless') {
      target.ref.noahStunUntil = Math.max(Number(target.ref.noahStunUntil || 0), until);
      showNinaParalyzeVfx(target, element, target.ref.noahStunUntil);
      deferFacelessObjectAttackResume(target.ref, target.ref.noahStunUntil);
      return;
    }

    if (target.kind === 'boss') {
      applyBossStun(duration, 'nina_lightning_storm');
      showNinaParalyzeVfx(target, element, Math.max(until, Number(state.bossStunUntil || 0)));
    }
  }

  function applyNinaUltHit(c, target, now) {
    if (!state || state.ended || state.finishing || !target) return 0;

    const baseDamage = Math.max(
      0,
      Number(c.atk || 0) * Math.max(0, Number(c.ninaUltHitAtkMultiplier || 4.0))
    );
    const attackElement = getUltAttackElement(c);
    let appliedDamage = 0;

    if (target.kind === 'normal' && target.ref && target.ref.hp > 0) {
      const targetElement = getCombatTargetElement(target.ref);
      const finalDamage = applyElementDamage(baseDamage, attackElement, targetElement);
      appliedDamage = damageNormalEnemy(
        target.ref,
        finalDamage,
        now,
        false,
        getElementDamageReaction(attackElement, targetElement)
      );
      state.normalEnemies = (state.normalEnemies || []).filter(enemy => enemy && enemy.hp > 0);
      if (isNormalBattle()) evaluateNormalMission(now);
    } else if (target.kind === 'faceless' && target.ref && target.ref.hp > 0) {
      const targetElement = getCombatTargetElement(target.ref, state.boss?.element);
      const finalDamage = applyElementDamage(baseDamage, attackElement, targetElement);
      appliedDamage = damageFacelessObject(
        target.ref,
        finalDamage,
        now,
        getElementDamageReaction(attackElement, targetElement)
      );
    } else if (target.kind === 'boss' && state.boss && state.boss.hp > 0) {
      const targetElement = getCombatTargetElement(state.boss);
      const finalDamage = applyElementDamage(baseDamage, attackElement, targetElement);
      appliedDamage = Math.min(state.boss.hp, Math.max(0, finalDamage));

      if (appliedDamage > 0) {
        state.boss.hp = Math.max(0, state.boss.hp - appliedDamage);
        createHit(state.boss.x, state.boss.y, true);
        showBossDamageNumber(
          appliedDamage,
          false,
          getElementDamageReaction(attackElement, targetElement)
        );
        flashBossHit(false);
        if (!addScoreAttackDamageScore(appliedDamage)) {
          addLegacyCombatScore(Math.round(appliedDamage * 100));
        }
        updateBossPhase();
        if (state.boss.hp <= 0) beginBossDefeat();
      }
    }

    if (appliedDamage > 0) {
      state.shotsHit = Number(state.shotsHit || 0) + 1;
      registerComboHit(c.id, now, appliedDamage);
      applyNinaParalyze(target, Number(c.ninaUltParalyzeMs || 3000), attackElement);
    }

    renderHud();
    return appliedDamage;
  }

  function getNinaUltZoneRect(c, zoneIndex, arena) {
    if (!arena) return null;

    const width = Math.max(1, Number(arena.clientWidth || 0));
    const height = Math.max(1, Number(arena.clientHeight || 0));
    const fieldRatio = Math.max(.2, Math.min(.8, Number(c.ninaUltEnemyFieldRatio || .5)));
    const cols = Math.max(1, Math.floor(Number(c.ninaUltZoneColumns || 4)));
    const rows = Math.max(1, Math.floor(Number(c.ninaUltZoneRows || 2)));
    const zoneCount = cols * rows;
    const safeIndex = ((Math.floor(Number(zoneIndex || 0)) % zoneCount) + zoneCount) % zoneCount;

    // 敵側フィールド = 画面上半分。
    // その領域だけを4列×2段（計8エリア）へ等分する。
    const enemyFieldHeight = height * fieldRatio;
    const cellWidth = width / cols;
    const cellHeight = enemyFieldHeight / rows;
    const col = safeIndex % cols;
    const row = Math.floor(safeIndex / cols);

    return {
      index: safeIndex,
      left: col * cellWidth,
      right: (col + 1) * cellWidth,
      top: row * cellHeight,
      bottom: (row + 1) * cellHeight,
      width: cellWidth,
      height: cellHeight,
      centerX: (col + .5) * cellWidth,
      centerY: (row + .5) * cellHeight
    };
  }

  function showNinaUltZoneWarning(rect, telegraphMs) {
    // build1674: 区画の予告枠（四角い枠＋十字線）は、落雷の区画分け（4列×2段）が透けて見えるため表示しない。
    //  予告の待ち時間（telegraphMs）と命中判定は従来どおり。
    if (rect) return null;
    const arena = document.getElementById('shooting-arena');
    if (!arena || !rect) return null;

    const warning = document.createElement('div');
    warning.className = 'shooting-nina-ult-zone-warning';
    warning.setAttribute('aria-hidden', 'true');
    warning.style.left = `${rect.left}px`;
    warning.style.top = `${rect.top}px`;
    warning.style.width = `${rect.width}px`;
    warning.style.height = `${rect.height}px`;
    warning.style.animationDuration = `${Math.max(80, Number(telegraphMs || 180))}ms`;
    arena.appendChild(warning);
    return warning;
  }

  function getNinaTargetsInZone(rect) {
    if (!state || !rect) return [];
    const targets = getNoahUltTargets();

    return targets.filter(target => {
      if (!target || !target.ref) return false;
      const x = Number(target.x || 0);
      const y = Number(target.y || 0);

      // 敵の中心座標が選択エリア内にある場合のみ命中。
      // 右端・下端は隣接エリアとの二重判定を避けるため非包含。
      return (
        x >= rect.left &&
        x < rect.right &&
        y >= rect.top &&
        y < rect.bottom
      );
    });
  }

  // build811: ニーナULTの見た目はそのまま、落雷SVGと塵DOMを使い回してGC負荷を抑える。
  // 16発ごとに要素を生成・破棄せず、1セットだけ再利用してアニメーションを再始動する。
  function createNinaUltLightningBolt(c, x, y) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return null;

    const width = Math.max(1, Number(arena.clientWidth || 0));
    const height = Math.max(1, Number(arena.clientHeight || 0));
    const tx = clamp(Number(x || width * .5), 8, Math.max(8, width - 8));
    const ty = clamp(Number(y || height * .35), 24, Math.max(24, height - 8));
    const element = getUltAttackElement(c);
    const visual = ULT_ELEMENT_VISUAL[element] || ULT_ELEMENT_VISUAL.neutral;
    const svgNs = 'http://www.w3.org/2000/svg';

    let svg = arena.querySelector('.shooting-nina-ult-lightning');
    if (!svg) {
      svg = document.createElementNS(svgNs, 'svg');
      svg.setAttribute('class', 'shooting-nina-ult-lightning');
      svg.setAttribute('preserveAspectRatio', 'none');
      svg.setAttribute('aria-hidden', 'true');
      const classes = [
        'shooting-nina-ult-bolt-glow',
        'shooting-nina-ult-bolt-color',
        'shooting-nina-ult-bolt-core',
        'shooting-nina-ult-bolt-branch',
        'shooting-nina-ult-bolt-branch'
      ];
      classes.forEach(cls => {
        const path = document.createElementNS(svgNs, 'path');
        path.setAttribute('class', cls);
        path.setAttribute('d', 'M0 0 L0 0');
        path.setAttribute('pathLength', '100');
        svg.appendChild(path);
      });
      arena.appendChild(svg);
    }

    svg.style.display = 'block';
    svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
    svg.style.setProperty('--nina-ult-rgb', visual.rgb);
    svg.style.setProperty('--nina-ult-color', visual.color);

    const points = [];
    const segments = 10;
    const topDrift = (Math.random() - .5) * 18;
    for (let i = 0; i <= segments; i++) {
      const t = i / segments;
      const py = ty * t;
      let px;
      if (i === 0) px = tx + topDrift;
      else if (i === segments) px = tx;
      else {
        const envelope = .52 + Math.sin(Math.PI * t) * .58;
        const jag = (Math.random() - .5) * 34 * envelope;
        const alternating = (i % 2 ? -1 : 1) * (5 + Math.random() * 7);
        px = tx + jag + alternating;
      }
      points.push([clamp(px, 4, width - 4), py]);
    }
    const d = points.map((pt, i) => `${i ? 'L' : 'M'}${pt[0].toFixed(1)} ${pt[1].toFixed(1)}`).join(' ');
    const paths = Array.from(svg.querySelectorAll('path'));
    if (paths[0]) paths[0].setAttribute('d', d);
    if (paths[1]) paths[1].setAttribute('d', d);
    if (paths[2]) paths[2].setAttribute('d', d);

    // 稲光の短い枝。主線より細く、着弾地点までは伸ばさない。
    [3, 6].forEach((idx, branchIndex) => {
      const base = points[idx];
      const path = paths[3 + branchIndex];
      if (!base || !path) return;
      const dir = branchIndex % 2 ? 1 : -1;
      const bx1 = clamp(base[0] + dir * (10 + Math.random() * 10), 4, width - 4);
      const by1 = Math.min(ty, base[1] + 10 + Math.random() * 12);
      const bx2 = clamp(bx1 + dir * (7 + Math.random() * 8), 4, width - 4);
      const by2 = Math.min(ty, by1 + 10 + Math.random() * 14);
      path.setAttribute('d', `M${base[0].toFixed(1)} ${base[1].toFixed(1)} L${bx1.toFixed(1)} ${by1.toFixed(1)} L${bx2.toFixed(1)} ${by2.toFixed(1)}`);
    });

    // CSSアニメーションだけを再始動。SVGそのものは破棄しない。
    paths.forEach(path => { path.style.animation = 'none'; });
    void svg.getBoundingClientRect();
    paths.forEach(path => { path.style.animation = ''; });

    if (svg._ninaUltHideTimer) clearTimeout(svg._ninaUltHideTimer);
    svg._ninaUltHideTimer = setTimeout(() => {
      if (svg && svg.isConnected) svg.style.display = 'none';
    }, 320);
    return svg;
  }

  function createNinaUltDust(x, y) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;

    let dust = arena.querySelector('.shooting-nina-ult-dust');
    if (!dust) {
      dust = document.createElement('span');
      dust.className = 'shooting-nina-ult-dust';
      dust.setAttribute('aria-hidden', 'true');
      const offsets = [
        [-14,-10,4,0], [12,-12,5,12], [-7,-17,3,22], [18,-7,4,34], [3,-20,3,46]
      ];
      offsets.forEach(([dx,dy,size,delay]) => {
        const p = document.createElement('i');
        p.style.setProperty('--dust-x', `${dx}px`);
        p.style.setProperty('--dust-y', `${dy}px`);
        p.style.setProperty('--dust-size', `${size}px`);
        p.style.setProperty('--dust-delay', `${delay}ms`);
        dust.appendChild(p);
      });
      arena.appendChild(dust);
    }

    dust.style.display = 'block';
    dust.style.transform = `translate3d(${Number(x || 0)}px,${Number(y || 0)}px,0)`;
    const particles = Array.from(dust.children || []);
    particles.forEach(p => { p.style.animation = 'none'; });
    void dust.offsetWidth;
    particles.forEach(p => { p.style.animation = ''; });

    if (dust._ninaUltHideTimer) clearTimeout(dust._ninaUltHideTimer);
    dust._ninaUltHideTimer = setTimeout(() => {
      if (dust && dust.isConnected) dust.style.display = 'none';
    }, 460);
  }

  function strikeNinaUltZone(c, rect, warning) {
    if (!state || state.ended || state.finishing || !rect) {
      try { warning && warning.remove(); } catch (_) {}
      return false;
    }

    const arena = document.getElementById('shooting-arena');
    const targets = getNinaTargetsInZone(rect);
    const now = performance.now();

    if (arena) {
      // 性能・判定は従来のエリア方式をそのまま維持。
      // 見た目だけ、命中時はエリア内の敵へ寄せ、空振り時はエリア中央へ落とす。
      let tx = rect.centerX;
      let ty = rect.centerY;
      if (targets.length > 0) {
        const visualTarget = targets[Math.floor(Math.random() * targets.length)];
        tx = Number(visualTarget && visualTarget.x || rect.centerX);
        ty = Number(visualTarget && visualTarget.y || rect.centerY);
      } else {
        tx += (Math.random() - .5) * Math.min(32, rect.width * .2);
      }
      tx = clamp(tx, 8, Math.max(8, arena.clientWidth - 8));
      ty = clamp(ty, 18, Math.max(18, arena.clientHeight * .5 - 8));

      // build1674: チャチャ（forbidden_shock）の落雷もノアULTと同じ稲妻演出に
      //  （上から走る稲妻・枝分かれ・瞬き・着弾の閃光と衝撃輪・画面の白閃）。
      const bolt = createNoahLightningBolt(tx, ty);
      // build1752: テストのULT（木属性版）は緑の稲妻
      const woodBolt = String(c && c.ultLightningTheme || '') === 'wood';
      if (woodBolt) bolt.classList.add('nl-wood');
      arena.appendChild(bolt);
      spawnNoahLightningFlash(arena, tx);
      if (woodBolt) arena.lastElementChild?.classList?.contains('shooting-noah-lightning-flash') && arena.lastElementChild.classList.add('nl-wood');
      setTimeout(() => bolt.remove(), 480);
    }

    // その瞬間、エリア内にいる敵全員へ同時命中。
    // ダメージ・麻痺時間・16回という性能値は変更しない。
    targets.forEach(target => {
      applyNinaUltHit(c, target, now);
    });

    try { warning && warning.remove(); } catch (_) {}
    // 画面シェイクは「敵に当たった時だけ」。空振り落雷では揺らさない。
    if (targets.length > 0) shakeNoahLightning();
    return targets.length > 0;
  }

  function queueNinaLightningZone(c, token) {
    if (!state || state.ended || state.finishing) return false;

    const arena = document.getElementById('shooting-arena');
    if (!arena) return false;

    const cols = Math.max(1, Math.floor(Number(c.ninaUltZoneColumns || 4)));
    const rows = Math.max(1, Math.floor(Number(c.ninaUltZoneRows || 2)));
    const zoneCount = Math.max(1, cols * rows);
    const zoneIndex = Math.floor(Math.random() * zoneCount);
    const rect = getNinaUltZoneRect(c, zoneIndex, arena);
    if (!rect) return false;

    const telegraphMs = Math.max(80, Number(c.ninaUltTelegraphMs || 180));
    const warning = showNinaUltZoneWarning(rect, telegraphMs);

    pushUltTimer(() => {
      if (
        !state ||
        state.ended ||
        state.finishing ||
        Number(state.ninaUltToken || 0) !== Number(token)
      ) {
        try { warning && warning.remove(); } catch (_) {}
        return;
      }
      strikeNinaUltZone(c, rect, warning);
    }, telegraphMs);

    return true;
  }

  function useNinaUlt(c) {
    if (!state || state.ended || state.finishing) return;

    showUltCut(c.ultName || 'LIGHTNING STORM', c.effectKey);

    const duration = Math.max(1000, Number(c.ninaUltDurationMs || 8000));
    const hitCount = Math.max(1, Math.floor(Number(c.ninaUltHitCount || 16)));
    const interval = duration / hitCount;
    const token = Number(state.ninaUltToken || 0) + 1;
    state.ninaUltToken = token;

    // カットイン後は通常移動・通常射撃を継続可能。
    // 8秒間の落雷は独立した継続ULTとして処理する。
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), performance.now() + 260);

    for (let i = 0; i < hitCount; i++) {
      // 0.5秒間隔で16回。
      // 各回、画面上半分の8エリアから1エリアをランダム選択して予兆→落雷。
      const delay = interval * i + 70;
      pushUltTimer(() => {
        if (
          !state ||
          state.ended ||
          state.finishing ||
          Number(state.ninaUltToken || 0) !== token
        ) return;
        queueNinaLightningZone(c, token);
      }, delay);
    }

    renderHud();
  }


    // ノア ULT：理想郷の静止
  // 発動直後に盤面の敵弾を完全削除。
  // 8拍×2セットの16落雷 -> 終了後に敵を感電停止。
  // ============================================================
  function getNoahUltTargets() {
    if (!state) return [];
    const list = [];

    if (isNormalBattle()) {
      (state.normalEnemies || []).forEach(enemy => {
        if (!enemy || !enemy.el || enemy.hp <= 0) return;
        list.push({ kind:'normal', ref:enemy, x:Number(enemy.x || 0), y:Number(enemy.y || 0) });
      });
      return list;
    }

    if (isFacelessStage()) {
      (state.facelessObjects || []).forEach(obj => {
        if (!obj || !obj.el || obj.hp <= 0) return;
        list.push({ kind:'faceless', ref:obj, x:Number(obj.x || 0), y:Number(obj.y || 0) });
      });
    }

    // build1740: BOSS戦の随伴敵（鳥居など）
    getBossAddUltTargets().forEach(enemy => {
      list.push({ kind:'normal', ref:enemy, x:Number(enemy.x || 0), y:Number(enemy.y || 0) });
    });

    if (state.boss && state.boss.hp > 0) {
      list.push({ kind:'boss', ref:state.boss, x:Number(state.boss.x || 0), y:Number(state.boss.y || 0) });
    }
    return list;
  }

  function clearNoahUltEnemyBarrage() {
    if (!state) return;

    // state配列を例外なく空にする。乱入用persistent弾もノアULTでは消す。
    (state.enemyBullets || []).forEach(p => {
      try { p && p.el && p.el.remove(); } catch (_) {}
    });
    state.enemyBullets = [];

    // Canvas描画弾も即時クリア。
    clearEnemyBulletCanvas();

    // state管理外の警告弾・レーザー等もその場で除去する。
    const arena = document.getElementById('shooting-arena');
    if (arena) {
      arena.querySelectorAll(
        '.shooting-enemy-bullet,' +
        '.shooting-raid-green-laser,' +
        '.shooting-boss-danger-warning,' +
        '.shooting-ambush-warning-bullet,' +
        '.shooting-ch04-curtain-bullet'
      ).forEach(el => el.remove());
    }

    removeBossDangerWarning();
    state.bossDangerExecuteAt = 0;
    state.lastBossShotAt = performance.now();
  }

  function clearNoahUltPlayerShots() {
    if (!state) return;

    // 発動時点で画面上に存在する自機弾を全部消す。
    (state.bullets || []).forEach(p => {
      try { p && p.el && p.el.remove(); } catch (_) {}
    });
    state.bullets = [];

    // ノアの中心レーザーも即座に消す。
    hideIgnisLaser();

    // 次にショット再開した瞬間、待ち時間なしで撃てるようにする。
    state.lastShotAt = -Infinity;
  }

  function applyNoahUltHit(c, target, now) {
    if (!state || state.ended || state.finishing || !target) return;

    let comboDamage = 0;
    const damage = Math.max(0, Number(c.atk || 0) * Number(c.noahUltHitAtkMultiplier || 0.35));

    if (target.kind === 'normal' && target.ref && target.ref.hp > 0) {
      const targetElement = getCombatTargetElement(target.ref);
      const finalDamage = applyElementDamage(damage, getUltAttackElement(c), targetElement);
      comboDamage = damageNormalEnemy(target.ref, finalDamage, now, false, getElementDamageReaction(getUltAttackElement(c), targetElement));
      state.normalEnemies = (state.normalEnemies || []).filter(enemy => enemy && enemy.hp > 0);
      evaluateNormalMission(now);
    } else if (target.kind === 'faceless' && target.ref && target.ref.hp > 0) {
      const targetElement = getCombatTargetElement(target.ref, state.boss?.element);
      const finalDamage = applyElementDamage(damage, getUltAttackElement(c), targetElement);
      comboDamage = damageFacelessObject(target.ref, finalDamage, now, getElementDamageReaction(getUltAttackElement(c), targetElement));
    } else if (target.kind === 'boss' && state.boss && state.boss.hp > 0) {
      const targetElement = getCombatTargetElement(state.boss);
      const finalDamage = applyElementDamage(damage, getUltAttackElement(c), targetElement);
      const applied = Math.min(state.boss.hp, finalDamage);
      if (applied <= 0) return;
      comboDamage = applied;
      state.boss.hp = Math.max(0, state.boss.hp - applied);
      createHit(state.boss.x, state.boss.y, true);
      showBossDamageNumber(applied, false, getElementDamageReaction(getUltAttackElement(c), targetElement));
      flashBossHit(false);
      if (!addScoreAttackDamageScore(applied)) addLegacyCombatScore(Math.round(applied * 100));
      updateBossPhase();
      if (state.boss.hp <= 0) beginBossDefeat();
    }

    if (comboDamage > 0) state.shotsHit = Number(state.shotsHit || 0) + 1;
    registerComboHit(c.id, now, comboDamage);
    renderHud();
  }

  function shakeNoahLightning() {
    const root = document.getElementById(ROOT_ID);
    if (!root) return;

    if (typeof root.animate === 'function') {
      // build1673: 落雷の「ドン」を縦方向の突き上げ中心に
      root.animate([
        { transform:'translate3d(0,0,0)' },
        { transform:'translate3d(-3px,7px,0)' },
        { transform:'translate3d(4px,-5px,0)' },
        { transform:'translate3d(-3px,4px,0)' },
        { transform:'translate3d(2px,-2px,0)' },
        { transform:'translate3d(0,0,0)' }
      ], { duration:180, easing:'ease-out' });
      return;
    }

    root.classList.remove('ayane-rampage-shake');
    void root.offsetWidth;
    root.classList.add('ayane-rampage-shake');
    setTimeout(() => root.classList.remove('ayane-rampage-shake'), 150);
  }

  // build1673: 落雷1本分の要素。上端→着弾点へギザギザの稲妻（主幹＋枝2本）をSVGで毎回生成する。
  //  親は left/top で配置（幅160px・高さ＝着弾点まで）。描画は stroke-dashoffset で上から一気に走らせる。
  function buildNoahBoltPoints(x0, y0, x1, y1, segments, amp) {
    const pts = [[x0, y0]];
    for (let i = 1; i < segments; i++) {
      const f = i / segments;
      const fall = 1 - Math.pow(f, 1.6) * .55; // 着弾点に近いほど揺れを小さく
      const x = x0 + (x1 - x0) * f + (Math.random() * 2 - 1) * amp * fall;
      const y = y0 + (y1 - y0) * (f + (Math.random() - .5) * (.5 / segments));
      pts.push([x, y]);
    }
    pts.push([x1, y1]);
    return pts;
  }
  function noahBoltPathD(pts) {
    return 'M' + pts.map(p => p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' L');
  }
  // build1851: 透き通る稲光。太い塗りをやめ、細い白熱の芯＋薄い光の層（加算合成）で描く。
  //  枝は本数を増やして細く・薄く・長さもまちまちに。背後に淡い光の柱（稲光の残光）を置く。
  let noahBoltSeq = 0;
  function createNoahLightningBolt(x, targetY) {
    const W = 180, cx = W / 2;
    const H = Math.max(54, Math.round(targetY));
    const fid = 'nlb' + (++noahBoltSeq);
    const el = document.createElement('div');
    el.className = 'shooting-noah-lightning strike nl-v2';
    el.style.left = `${Math.round(x - cx)}px`;
    el.style.top = '0px';
    el.style.height = `${H}px`;

    const segs = Math.max(7, Math.min(18, Math.round(H / 26)));
    const main = buildNoahBoltPoints(cx + (Math.random() * 2 - 1) * 30, -6, cx, H, segs, 20);
    const mainD = noahBoltPathD(main);
    let branches = '';
    let branchGlows = '';
    const branchCount = H > 220 ? 4 : (H > 120 ? 3 : 2);
    for (let b = 0; b < branchCount; b++) {
      const at = Math.floor(segs * (.15 + Math.random() * .6));
      const start = main[Math.min(main.length - 2, Math.max(1, at))];
      const side = Math.random() < .5 ? -1 : 1;
      const len = H * (.12 + Math.random() * .2);
      const end = [start[0] + side * (16 + Math.random() * 40), start[1] + len];
      const pts = buildNoahBoltPoints(start[0], start[1], end[0], end[1], 5, 8);
      const d = noahBoltPathD(pts);
      const op = (.45 + Math.random() * .45).toFixed(2);
      branchGlows += `<path class="nl-branch-glow" pathLength="1" style="opacity:${op}" d="${d}"/>`;
      branches += `<path class="nl-branch" pathLength="1" style="opacity:${op}" d="${d}"/>`;
      // 小枝（さらに細かく分かれる）
      if (Math.random() < .7) {
        const s2 = pts[Math.min(pts.length - 2, 2)];
        const e2 = [s2[0] + side * (8 + Math.random() * 18), s2[1] + len * (.35 + Math.random() * .3)];
        const d2 = noahBoltPathD(buildNoahBoltPoints(s2[0], s2[1], e2[0], e2[1], 3, 5));
        branches += `<path class="nl-twig" pathLength="1" style="opacity:${(op * .8).toFixed(2)}" d="${d2}"/>`;
      }
    }
    let sparks = '';
    for (let i = 0; i < 6; i++) {
      const a = -Math.PI * (.08 + Math.random() * .84);
      const d = 22 + Math.random() * 30;
      sparks += `<u style="--dx:${Math.round(Math.cos(a) * d)}px;--dy:${Math.round(Math.sin(a) * d)}px"></u>`;
    }
    el.innerHTML =
      `<span class="nl-sheath"></span>` +
      `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true" focusable="false">` +
      `<defs><filter id="${fid}" x="-60%" y="-10%" width="220%" height="120%"><feGaussianBlur stdDeviation="3.2"/></filter></defs><g class="nl-bolt">` +
      `<g class="nl-soft" filter="url(#${fid})"><path class="nl-halo" pathLength="1" d="${mainD}"/><path class="nl-glow" pathLength="1" d="${mainD}"/>${branchGlows}</g>${branches}` +
      `<path class="nl-mid" pathLength="1" d="${mainD}"/><path class="nl-core" pathLength="1" d="${mainD}"/>` +
      `</g></svg><span class="nl-impact"><i></i><b></b>${sparks}</span>`;
    return el;
  }
  // 落雷の瞬間に盤面全体を一瞬だけ白く光らせる（落ちた位置側を少し明るく）。
  function spawnNoahLightningFlash(arena, x) {
    const w = Math.max(1, Number(arena.clientWidth || 1));
    const flash = document.createElement('div');
    flash.className = 'shooting-noah-lightning-flash';
    flash.style.setProperty('--fx', `${Math.round(clamp(x / w, 0, 1) * 100)}%`);
    arena.appendChild(flash);
    setTimeout(() => flash.remove(), 200);
  }

  function spawnNoahLightning(c) {
    if (!state || state.ended || state.finishing) return false;

    // 毎落雷ごとに最新の盤面からランダム選択。
    // 途中でスポーンした敵も次の落雷から対象になる。
    const targets = getNoahUltTargets();
    if (!targets.length) return false;
    const target = targets.length === 1
      ? targets[0]
      : targets[Math.floor(Math.random() * targets.length)];

    const arena = document.getElementById('shooting-arena');
    if (!arena) {
      applyNoahUltHit(c, target, performance.now());
      shakeNoahLightning();
      return true;
    }

    const tx = clamp(Number(target.x || arena.clientWidth * .5), 10, Math.max(10, arena.clientWidth - 10));
    const ty = clamp(Number(target.y || arena.clientHeight * .35), 20, Math.max(20, arena.clientHeight - 20));
    const jitterX = (Math.random() - .5) * 34;

    const bolt = createNoahLightningBolt(tx + jitterX, ty);
    arena.appendChild(bolt);
    spawnNoahLightningFlash(arena, tx + jitterX);

    // 落雷を受けた敵を記録。ULT終了後、この敵だけ1.5秒スタン。
    state.noahUltHitTargets = Array.isArray(state.noahUltHitTargets) ? state.noahUltHitTargets : [];
    if (!state.noahUltHitTargets.some(t => t && t.kind === target.kind && t.ref === target.ref)) {
      state.noahUltHitTargets.push(target);
    }

    // 落雷の瞬間にダメージ + シェイク。
    applyNoahUltHit(c, target, performance.now());
    shakeNoahLightning();

    setTimeout(() => bolt.remove(), 480);
    return true;
  }

  function applyNoahTargetStuns(c) {
    if (!state || state.ended || state.finishing) return;

    const duration = Math.max(300, Number(c.noahUltParalyzeMs || 1500));
    const now = performance.now();
    const until = now + duration;
    const refs = Array.isArray(state.noahUltHitTargets) ? state.noahUltHitTargets : [];

    refs.forEach(target => {
      if (!target || !target.ref) return;
      // 敵オブジェクト単位のスタンだけを付与。
      // player / party / movement state には一切触れない。
      target.ref.noahStunUntil = Math.max(Number(target.ref.noahStunUntil || 0), until);
      if (target.kind === 'normal') {
        freezeNormalEnemyAction(target.ref, target.ref.noahStunUntil);
      } else if (target.kind === 'faceless') {
        deferFacelessObjectAttackResume(target.ref, target.ref.noahStunUntil);
      }
    });

    if (refs.some(t => t && t.kind === 'boss')) {
      applyBossStun(duration, 'noah_ult');
    }

    renderHud();
  }


  function finishNoahUlt() {
    if (!state) return;

    // 16発目の落雷が終わった瞬間に、ULT中の全体停止を完全解除。
    // この後の1.5秒スタンは「落雷を受けた敵だけ」に残し、
    // プレイヤー（ノア）は通常どおり移動・射撃できる。
    state.noahMovementFreezeUntil = 0;
    state.noahUltActive = false;
    // 全体停止解除フレームを射撃再開の起点にする。
    // 個別1.5秒スタン対象は、すでにより後ろのresumeAtが入っているため維持される。
    deferAllEnemyAttackResume(performance.now());

    // ここからは「敵だけスタン」のフェーズ。
    // ULTロックを解除し、ノアは即座に移動・通常射撃へ復帰する。
    state.ultLockUntil = 0;
    state.lastShotAt = -Infinity;

    state.noahUltToken = Number(state.noahUltToken || 0) + 1;
    renderHud();
  }

  function useNoahUlt(c) {
    if (!state || state.ended || state.finishing) return;

    showUltCut(c.ultName, c.effectKey);

    // ULT発動フレームで盤面をリセット。
    // 敵弾だけでなく、ノア自身が発射済みの弾・レーザーも全部消す。
    clearNoahUltEnemyBarrage();
    clearNoahUltPlayerShots();

    const beatMs = c.id === CHARACTER_ID.NOAH
      ? 540
      : Math.max(70, Number(c.noahUltBeatMs || 135));
    const hitCount = 16;
    const token = Number(state.noahUltToken || 0) + 1;
    state.noahUltToken = token;
    state.noahUltActive = true;
    state.noahUltHitTargets = [];

    // 8拍子を間を置かず2周 = 合計16発。
    const times = Array.from({ length: hitCount }, (_, i) => i * beatMs);

    // 16発を撃ち切るまで盤面上の敵全体の移動・攻撃を停止。
    // 新規スポーン判定は止めない。
    state.noahMovementFreezeUntil = performance.now() + (hitCount - 1) * beatMs + 220;
    deferAllEnemyAttackResume(state.noahMovementFreezeUntil);

    times.forEach((delay, i) => {
      pushUltTimer(() => {
        if (!state || state.ended || state.finishing || Number(state.noahUltToken || 0) !== token) return;
        spawnNoahLightning(c);

        if (i === hitCount - 1) {
          // 最後の一撃後、実際に落雷を受けた敵だけ1.5秒スタン。
          applyNoahTargetStuns(c);
          finishNoahUlt();
        }
      }, delay);
    });

    // プレイヤー側のULTロックは「16発目が落ちるまで」だけ。
    // その後の1.5秒スタン中はノアが通常射撃できる。
    const lightningMs = (hitCount - 1) * beatMs + 220;
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), performance.now() + lightningMs);
    renderHud();
  }


  // ============================================================
  // シイナ ULT：術式・光の円環
  // 自機追従の大きな光円。円内の敵弾だけ移動速度を低下させる。
  // 弾そのものの vx/vy は書き換えず、更新時の dt を縮めるため、
  // 円外へ出た瞬間に元の速度へ自然に復帰する。
  // ============================================================
  function isShiinaLightRingActive(now = performance.now()) {
    return !!state && now < Number(state.shiinaLightRingUntil || 0);
  }

  function getShiinaEnemyBulletSpeedMultiplier(p, now = performance.now()) {
    if (!p || !state) return 1;
    const shiinaActive = isShiinaLightRingActive(now);
    const suiActive = isSuiTimeDomainActive(now);
    if (!shiinaActive && !suiActive) return 1;
    const dx = Number(p.x || 0) - Number(state.player?.x || 0);
    const dy = Number(p.y || 0) - Number(state.player?.y || 0);
    const dist2 = dx * dx + dy * dy;
    let multiplier = 1;
    if (shiinaActive && dist2 <= Number(state.shiinaLightRingRadius || 190) ** 2) {
      multiplier = Math.min(multiplier, Math.max(0.05, Number(state.shiinaLightRingSlowMultiplier || 0.2)));
    }
    if (suiActive && dist2 <= Number(state.suiTimeDomainRadius || 275) ** 2) {
      multiplier = Math.min(multiplier, Math.max(0.05, Number(state.suiTimeDomainBulletSpeedMultiplier || 0.2)));
    }
    return multiplier;
  }

  function syncShiinaLightRingVisual(now = performance.now()) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;

    let ring = arena.querySelector('.shooting-shiina-light-ring');
    if (!isShiinaLightRingActive(now)) {
      if (ring) ring.remove();
      return;
    }

    if (!ring) {
      ring = document.createElement('div');
      ring.className = 'shooting-shiina-light-ring';
      Object.assign(ring.style, {
        position: 'absolute',
        left: '0px',
        top: '0px',
        borderRadius: '50%',
        pointerEvents: 'none',
        zIndex: '6',
        boxSizing: 'border-box',
        border: '2px solid rgba(255,248,205,.88)',
        background: 'radial-gradient(circle, rgba(255,250,220,.035) 0%, rgba(245,255,220,.05) 55%, rgba(255,248,200,.13) 78%, rgba(255,255,235,.025) 100%)',
        boxShadow: '0 0 14px rgba(255,250,205,.62), inset 0 0 18px rgba(255,255,225,.30)',
        transform: 'translate3d(-50%,-50%,0)',
        opacity: '.92'
      });
      arena.appendChild(ring);
      if (typeof ring.animate === 'function') {
        ring.animate([
          { opacity:.48, filter:'brightness(.88)' },
          { opacity:.96, filter:'brightness(1.22)' },
          { opacity:.58, filter:'brightness(.96)' }
        ], { duration:1350, iterations:Infinity, easing:'ease-in-out' });
      }
    }

    const radius = Math.max(1, Number(state.shiinaLightRingRadius || 190));
    ring.style.width = `${radius * 2}px`;
    ring.style.height = `${radius * 2}px`;
    ring.style.left = `${Number(state.player?.x || 0)}px`;
    ring.style.top = `${Number(state.player?.y || 0)}px`;
  }

  function useShiinaLightRingUlt(c) {
    if (!state || state.ended || state.finishing) return;
    const now = performance.now();
    const duration = Math.max(1000, Number(c.lightRingDurationMs || 7000));

    showUltCut(c.ultName || '術式・光の円環', c.effectKey);
    state.shiinaLightRingUntil = now + duration;
    state.shiinaLightRingRadius = Math.max(80, Number(c.lightRingRadius || 190));
    state.shiinaLightRingSlowMultiplier = Math.max(0.05, Math.min(1, Number(c.lightRingBulletSpeedMultiplier || 0.2)));
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + 260);
    syncShiinaLightRingVisual(now);
    renderHud();
  }


  // build1801: 弱体化（被ダメ軽減）中は、刻印された敵に小さな「呪」の印を付けて追従させる
  function syncShionCurseTags(now) {
    if (!state) return;
    const active = now < Number(state.shionEnemyDebuffUntil || 0) && !state.ended;
    let tags = state.shionCurseTags || (state.shionCurseTags = new Map());
    if (!active) {
      if (tags.size) { tags.forEach(el => el.remove()); tags.clear(); }
      return;
    }
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const targets = [];
    if (!isNormalBattle() && state.boss && state.boss.hp > 0) targets.push(state.boss);
    (state.normalEnemies || []).forEach(e => { if (e && e.hp > 0 && e.el && targets.length < 8) targets.push(e); });
    const keep = new Set(targets);
    tags.forEach((el, t) => { if (!keep.has(t)) { el.remove(); tags.delete(t); } });
    targets.forEach(t => {
      let el = tags.get(t);
      if (!el) { el = document.createElement('i'); el.className = 'shooting-shion-curse-tag'; el.setAttribute('aria-hidden', 'true'); arena.appendChild(el); tags.set(t, el); }
      const off = t === state.boss ? -Math.max(30, getBossHalfWidthFast(now) * 1.2) : -24;
      el.style.transform = `translate(${Number(t.x || 0).toFixed(1)}px,${(Number(t.y || 0) + off).toFixed(1)}px)`;
    });
  }

  function spawnShionCurseMarks(points) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return [];
    return (Array.isArray(points) ? points : []).map(point => {
      const el = document.createElement('i');
      el.className = 'shooting-shion-curse-mark arm';
      el.setAttribute('aria-hidden', 'true');
      arena.appendChild(el);
      positionUnit(el, Number(point.x || 0), Number(point.y || 0));
      return el;
    });
  }

  function useShionUlt(c) {
    if (!state || state.ended || state.finishing) return;

    const now = performance.now();
    const delayMs = Math.max(300, Number(c.ultDelayMs || 1200));
    const debuffMs = Math.max(1000, Number(c.ultDebuffDurationMs || 6000));
    const damageMultiplier = Math.max(0, Number(c.ultDamageAtkMultiplier || 2.8));
    const enemyDamageMultiplier = Math.max(0.05, Math.min(1, Number(c.ultEnemyDamageMultiplier || 0.70)));
    const root = document.getElementById(ROOT_ID);

    showUltCut(c.ultName || '黒羽葬鐘', c.effectKey);
    ultScreenFlash('ult-flash-ayane');

    // 発動時点の敵位置へ呪印を置く。ダメージ自体は時間差で、その時点で生存している敵全体へ適用。
    const points = getEriUltTargetPoints();
    const marks = spawnShionCurseMarks(points);

    // build566: 呪印の待機時間中も敵は移動・攻撃を継続する。
    // シオン本人の通常射撃だけ、時間差発動までロックする。
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + 260);
    state.playerShotLockUntil = Math.max(Number(state.playerShotLockUntil || 0), now + delayMs + 180);
    renderHud();

    pushUltTimer(() => {
      if (!state || state.ended || state.finishing) return;

      marks.forEach(el => {
        if (!el || !el.isConnected) return;
        el.classList.remove('arm');
        void el.offsetWidth;
        el.classList.add('detonate');
        setTimeout(() => el.remove(), 440);
      });

      const damage = Number(c.atk || 0) * damageMultiplier;
      applyUltDamage(damage, true, c);

      state.shionEnemyDebuffUntil = performance.now() + debuffMs;
      state.shionEnemyDamageMultiplier = enemyDamageMultiplier;

      if (root) {
        root.classList.remove('shion-curse-active');
        void root.offsetWidth;
        root.classList.add('shion-curse-active');
      }

      state.ultLockUntil = performance.now() + 120;
      state.playerShotLockUntil = performance.now() + 120;
      renderHud();

      pushUltTimer(() => {
        if (!state) return;
        state.shionEnemyDebuffUntil = 0;
        state.shionEnemyDamageMultiplier = 1;
        if (root) root.classList.remove('shion-curse-active');
        renderHud();
      }, debuffMs);
    }, delayMs);
  }

  function shakeVeronicaPunchImpact() {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;

    // Hit時だけ短く強めに揺らす。MISSでは呼ばない。
    // Web Animationsを使い、ゲームループ側の座標/transform処理とは分離する。
    if (typeof arena.animate === 'function') {
      arena.animate([
        { transform:'translate3d(0,0,0)' },
        { transform:'translate3d(-5px,2px,0)' },
        { transform:'translate3d(5px,-3px,0)' },
        { transform:'translate3d(-4px,-2px,0)' },
        { transform:'translate3d(3px,2px,0)' },
        { transform:'translate3d(-2px,1px,0)' },
        { transform:'translate3d(0,0,0)' }
      ], {
        duration: 260,
        easing: 'cubic-bezier(.2,.8,.2,1)'
      });
    }
  }

  function useVeronicaBrassPunchUlt(c) {
    if (!state || state.ended || state.finishing) return;
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;

    const now = performance.now();
    const px = Number(state.player?.x || 0);
    const py = Number(state.player?.y || 0);
    const range = Math.max(56, Number(c.ultPunchRange || 118));
    const width = Math.max(36, Number(c.ultPunchWidth || 68));
    const halfWidth = width * .5;
    const damage = Math.max(0, Number(c.atk || 0) * Number(c.ultDamageAtkMultiplier || 7));
    const attackElement = getUltAttackElement(c);
    const arenaRect = arena.getBoundingClientRect();

    showUltCut(c.ultName || 'キョーレツな一発をあげる♡', c.effectKey);
    ultScreenFlash('ult-flash-ayane', c);

    // ベロニカの真正面だけ。通常Strikeより狭く、追尾・自動補正はしない。
    const punchRect = {
      left: arenaRect.left + px - halfWidth,
      right: arenaRect.left + px + halfWidth,
      top: arenaRect.top + py - range,
      bottom: arenaRect.top + py + 6
    };

    const candidates = [];
    const pushCandidate = (kind, ref, rect, x, y) => {
      if (!rect || !rectsHit(punchRect, rect, 0, 0)) return;
      const dx = Number(x || 0) - px;
      const dy = Number(y || 0) - py;
      candidates.push({ kind, ref, x:Number(x || 0), y:Number(y || 0), dist2:dx*dx + dy*dy });
    };

    // CH06/デイリー上級の壁はStrike系を遮る。壁が一番手前なら拳はそこで止まる。
    (state.chapter6Barriers || []).forEach(barrier => {
      if (!barrier || !barrier.el) return;
      pushCandidate('barrier', barrier, getChapter6BarrierRect(barrier, arenaRect), barrier.x, barrier.y);
    });

    (state.normalEnemies || []).forEach(enemy => {
      if (!enemy || !enemy.el || enemy.hp <= 0) return;
      let rect = null;
      let hw = Number(enemy._hw || 0);
      let hh = Number(enemy._hh || 0);
      if (hw <= 0 || hh <= 0) {
        measureUnitSize(enemy);
        hw = Number(enemy._hw || 0);
        hh = Number(enemy._hh || 0);
      }
      if (hw > 0 && hh > 0) rect = getUnitRect(enemy, arenaRect);
      if (!rect) rect = enemy.el.getBoundingClientRect();
      pushCandidate('enemy', enemy, rect, enemy.x, enemy.y);
    });

    (state.facelessObjects || []).forEach(obj => {
      if (!obj || !obj.el || obj.hp <= 0) return;
      pushCandidate('faceless', obj, obj.el.getBoundingClientRect(), obj.x, obj.y);
    });

    if (state.boss && state.boss.hp > 0) {
      const bossEl = document.getElementById(BOSS_ID);
      const bossRect = bossEl ? bossEl.getBoundingClientRect() : {
        left:arenaRect.left + Number(state.boss.x || 0) - 48,
        right:arenaRect.left + Number(state.boss.x || 0) + 48,
        top:arenaRect.top + Number(state.boss.y || 0) - 48,
        bottom:arenaRect.top + Number(state.boss.y || 0) + 48
      };
      pushCandidate('boss', state.boss, bossRect, state.boss.x, state.boss.y);
    }

    candidates.sort((a,b) => a.dist2 - b.dist2);
    const target = candidates[0] || null;

    // 外したらそのまま終了。バフ・追撃・再判定は一切ない。
    if (!target) {
      state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + 180);
      renderHud();
      return;
    }

    if (target.kind === 'barrier') {
      pulseChapter6Barrier(target.ref, target.x, target.y);
      createHit(target.x, target.y, true);
      shakeVeronicaPunchImpact();
      state.shotsHit = Number(state.shotsHit || 0) + 1;
      state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + 220);
      renderHud();
      return;
    }

    let appliedDamage = 0;
    let reaction = '';

    if (target.kind === 'enemy') {
      const targetElement = getCombatTargetElement(target.ref);
      reaction = getElementDamageReaction(attackElement, targetElement);
      const finalDamage = applyElementDamage(damage, attackElement, targetElement);
      appliedDamage = damageNormalEnemy(target.ref, finalDamage, now, true, reaction);
      state.normalEnemies = (state.normalEnemies || []).filter(enemy => enemy && enemy.hp > 0);
      evaluateNormalMission(now);
    } else if (target.kind === 'faceless') {
      const targetElement = getCombatTargetElement(target.ref);
      reaction = getElementDamageReaction(attackElement, targetElement);
      const finalDamage = applyElementDamage(damage, attackElement, targetElement);
      appliedDamage = damageFacelessObject(target.ref, finalDamage, now, reaction);
    } else if (target.kind === 'boss') {
      const targetElement = getCombatTargetElement(state.boss);
      reaction = getElementDamageReaction(attackElement, targetElement);
      const finalDamage = applyElementDamage(damage, attackElement, targetElement);
      appliedDamage = Math.min(state.boss.hp, Math.max(0, Number(finalDamage || 0)));
      state.boss.hp = Math.max(0, state.boss.hp - appliedDamage);
      updateBossPhase();
      createHit(target.x, target.y, true);
      showBossDamageNumber(appliedDamage, true, reaction);
      flashBossHit(true);
      if (state.boss.hp <= 0) beginBossDefeat();
    }

    // 1回のULTにつきHit判定も1回。IMMUNE(0 damage)はHit COMBOに加算しない。
    state.shotsHit = Number(state.shotsHit || 0) + 1;
    registerComboHit(c.id, now, appliedDamage > 0 ? appliedDamage : 0);
    shakeVeronicaPunchImpact();
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + 260);
    renderHud();
  }


  // ============================================================
  // build941: ID38 クロエ ULT — 虹のかかる世界
  //
  // 旧「親弾が着弾 → 6方向へ分裂」は完全廃止。
  // プレイヤー前方へ、筆でペンキを払うように6本の属性変化弾を同時発射する。
  // 左から NEUTRAL / FIRE / AQUA / WOOD / DARK / LIGHT。
  // 全弾貫通。同じ弾は同一対象へ1回だけ命中する。
  // 複数属性弾が同じ対象へ命中した場合は、命中順に属性を書き換え、最後の属性が残る。
  // ============================================================
  function setCombatTargetElement(target, element) {
    if (!target) return false;
    const nextElement = normalizeCombatElement(element) || 'neutral';
    target.element = nextElement;
    if (target.el) target.el.dataset.element = nextElement;

    if (Object.prototype.hasOwnProperty.call(target, 'elementEl')) {
      const src = getCombatElementIcon(nextElement);
      if (target.elementEl && src) {
        target.elementEl.src = src;
        target.elementEl.style.display = '';
      }
      if (target.weaknessBarrierEl) {
        ['neutral','aqua','fire','wood','dark','light'].forEach(key => {
          target.weaknessBarrierEl.classList.remove(`element-${key}`);
        });
        target.weaknessBarrierEl.classList.add(`element-${nextElement}`);
        target.weaknessBarrierEl.dataset.element = nextElement;
      }
      positionMiniEnemyHp(target);
    }

    if (target === state?.boss) renderBossElementIcon();

    if (target.el) {
      const visual = getBombElementVisual(nextElement);
      target.el.style.setProperty('--painter-shift-rgb', visual.rgb);
      target.el.classList.remove('painter-element-shift-hit');
      void target.el.offsetWidth;
      target.el.classList.add('painter-element-shift-hit');
      setTimeout(() => target.el && target.el.classList.remove('painter-element-shift-hit'), 420);
    }
    return true;
  }

  function ensurePainterUltStyle() {
    const styleId = 'shooting-painter-element-spread-style-v5';
    if (document.getElementById(styleId)) return;
    const style = document.createElement('style');
    style.id = styleId;
    style.textContent = `
      .painter-element-shift-hit{
        filter:
          brightness(1.18)
          saturate(1.04)
          drop-shadow(0 0 10px rgba(var(--painter-shift-rgb,231,200,90),.78))!important;
      }
      .shooting-painter-spread-bullet{
        position:absolute;
        z-index:48;
        width:17px;
        height:38px;
        margin:-19px 0 0 -8.5px;
        border:0!important;
        outline:0!important;
        border-radius:52% 52% 62% 62% / 35% 35% 70% 70%;
        pointer-events:none;
        box-sizing:border-box;
        transform-origin:50% 50%;
        background:
          radial-gradient(ellipse at 50% 22%,
            rgba(255,255,255,.95) 0 8%,
            rgba(var(--painter-rgb,244,239,227),.96) 18%,
            rgba(var(--painter-rgb,244,239,227),.78) 48%,
            rgba(var(--painter-rgb,244,239,227),.28) 72%,
            transparent 88%);
        box-shadow:
          0 0 6px rgba(255,255,255,.40),
          0 0 12px rgba(var(--painter-rgb,244,239,227),.42),
          0 0 22px rgba(var(--painter-rgb,244,239,227),.16)!important;
        filter:saturate(1.08) blur(.18px);
      }
      .shooting-painter-spread-bullet::before{
        content:"";
        position:absolute;
        left:50%;
        top:62%;
        width:7px;
        height:32px;
        transform:translateX(-50%);
        border-radius:50%;
        background:linear-gradient(180deg,
          rgba(var(--painter-rgb,244,239,227),.52),
          rgba(var(--painter-rgb,244,239,227),.20) 48%,
          transparent 100%);
        filter:blur(2.7px);
        opacity:.80;
      }
      .shooting-painter-spread-bullet::after{
        content:"";
        position:absolute;
        left:50%;
        top:78%;
        width:4px;
        height:4px;
        border-radius:50%;
        background:rgba(var(--painter-rgb,244,239,227),.75);
        box-shadow:
          -7px 7px 0 -1px rgba(var(--painter-rgb,244,239,227),.55),
           6px 11px 0 -1px rgba(var(--painter-rgb,244,239,227),.46),
          -3px 17px 0 -1.5px rgba(var(--painter-rgb,244,239,227),.34);
        opacity:.84;
      }
      .shooting-painter-spread-launch{
        position:absolute;
        z-index:47;
        width:64px;
        height:22px;
        margin:-11px 0 0 -32px;
        pointer-events:none;
        border-radius:50%;
        background:linear-gradient(90deg,
          rgba(238,235,225,.70),
          rgba(245,92,70,.65),
          rgba(68,164,255,.65),
          rgba(100,196,102,.65),
          rgba(112,73,164,.65),
          rgba(244,224,113,.70));
        filter:blur(5px);
        animation:painterSpreadLaunch .30s ease-out both;
      }
      @keyframes painterSpreadLaunch{
        0%{transform:scale(.35,.55);opacity:.95}
        100%{transform:scale(1.65,.25);opacity:0}
      }
    `;
    document.head.appendChild(style);
  }

  function getPainterUltCandidates() {
    const list = [];
    (state?.normalEnemies || []).forEach(enemy => {
      if (enemy && enemy.el && enemy.hp > 0) list.push(enemy);
    });
    (state?.facelessObjects || []).forEach(obj => {
      if (obj && obj.el && obj.hp > 0) list.push(obj);
    });
    if (!isNormalBattle() && state?.boss && state.boss.hp > 0) list.push(state.boss);
    return list;
  }

  function findPainterSpreadCollisionsSwept(x0, y0, x1, y1, arenaRect, alreadyHit, radius = 10) {
    const r = Math.max(4, Number(radius || 10));
    const hits = [];
    for (const target of getPainterUltCandidates()) {
      if (!target || target.hp <= 0 || (alreadyHit && alreadyHit.has(target))) continue;
      const viewportRect = getUnitRect(target, arenaRect);
      if (!viewportRect) continue;

      const inset = target === state?.boss ? 5 : 2;
      const minX = viewportRect.left - arenaRect.left + inset - r;
      const maxX = viewportRect.right - arenaRect.left - inset + r;
      const minY = viewportRect.top - arenaRect.top + inset - r;
      const maxY = viewportRect.bottom - arenaRect.top - inset + r;
      if (minX > maxX || minY > maxY) continue;

      const t = segmentAabbEntryT(x0, y0, x1, y1, minX, maxX, minY, maxY);
      if (t == null) continue;
      hits.push({
        target,
        t,
        x:x0 + (x1 - x0) * t,
        y:y0 + (y1 - y0) * t,
      });
    }
    hits.sort((a,b) => a.t - b.t);
    return hits;
  }

  function applyPainterSpreadDamage(target, rawDamage, attackElement, now, c) {
    if (!target || target.hp <= 0) return 0;

    // ダメージは命中直前の属性で計算し、その後に属性を書き換える。
    const targetElementBeforeHit = getCombatTargetElement(target, state?.boss?.element);
    const reaction = getElementDamageReaction(attackElement, targetElementBeforeHit);
    const finalDamage = applyElementDamage(rawDamage, attackElement, targetElementBeforeHit);
    let appliedDamage = 0;

    if ((state.normalEnemies || []).includes(target)) {
      appliedDamage = damageNormalEnemy(target, finalDamage, now, false, reaction);
    } else if ((state.facelessObjects || []).includes(target)) {
      appliedDamage = damageFacelessObject(target, finalDamage, now, reaction);
    } else if (target === state.boss && state.boss && state.boss.hp > 0) {
      appliedDamage = Math.min(state.boss.hp, Math.max(0, Number(finalDamage || 0)));
      state.boss.hp = Math.max(0, state.boss.hp - appliedDamage);
      updateBossPhase();
      createHit(Number(target.x || 0), Number(target.y || 0), false);
      showBossDamageNumber(appliedDamage, false, reaction);
      flashBossHit(false);
      if (!addScoreAttackDamageScore(appliedDamage)) {
        addLegacyCombatScore(Math.round(appliedDamage * 80));
      }
    }

    if (appliedDamage > 0) {
      state.shotsHit = Number(state.shotsHit || 0) + 1;
      registerComboHit(c.id, now, appliedDamage);
    }

    // 生存していれば、命中したペンキの属性へ即時書き換え。
    if (target.hp > 0) {
      // build1871: 結界を持つ敵を塗ると、結界は消えずに「塗った色の結界」へ張り替わる。
      // 例）闇の結界のボスを火で塗る → 火の結界（水か無属性でしか通らない）
      if (hasAnyWeaknessBarrier(target)) {
        target.paintBarrierElement = normalizeCombatElement(attackElement) || 'neutral';
        target.lyuneBarrierRemoved = false;
      }
      setCombatTargetElement(target, attackElement);
    }
    return appliedDamage;
  }

  function finalizePainterSpreadHit(now) {
    state.normalEnemies = (state.normalEnemies || []).filter(enemy => enemy && enemy.hp > 0);
    state.facelessObjects = (state.facelessObjects || []).filter(obj => obj && obj.hp > 0);
    if (isNormalBattle()) {
      evaluateNormalMission(now);
    } else if (state.boss && state.boss.hp <= 0) {
      beginBossDefeat();
    }
    renderHud();
  }

  function createPainterSpreadLaunch(x, y) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const burst = document.createElement('i');
    burst.className = 'shooting-painter-spread-launch';
    burst.style.left = `${x}px`;
    burst.style.top = `${y}px`;
    arena.appendChild(burst);
    setTimeout(() => burst.remove(), 340);
  }

  function usePainterElementSpreadUlt(c) {
    if (!state || state.ended || state.finishing) return;
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;

    ensureBombVisualStyles();
    ensurePainterUltStyle();
    showUltCut(c.ultName || '虹のかかる世界', c.effectKey, c);
    ultScreenFlash('ult-flash-element', c);

    const startX = Number(state.player?.x || arena.clientWidth * .5);
    const startY = Math.max(42, Number(state.player?.y || arena.clientHeight * .80) - 30);
    createPainterSpreadLaunch(startX, startY);

    // 左 → 右の順序を固定。画面上でもこの並びになる。
    const specs = [
      { element:'neutral', spread:-0.48 },
      { element:'fire',    spread:-0.29 },
      { element:'aqua',    spread:-0.10 },
      { element:'wood',    spread: 0.10 },
      { element:'dark',    spread: 0.29 },
      { element:'light',   spread: 0.48 },
    ];

    const speed = Math.max(360, Number(c.paintSpreadSpeed || c.paintRainbowChildSpeed || 560));
    const damage = Math.max(
      0,
      Number(c.atk || 0) * Math.max(0, Number(c.paintSpreadDamageAtkMultiplier ?? c.paintRainbowChildDamageAtkMultiplier ?? 1.75))
    );

    const bullets = specs.map((spec, index) => {
      const visual = getBombElementVisual(spec.element);
      const dx = Math.sin(spec.spread);
      const dy = -Math.cos(spec.spread);
      const angleDeg = spec.spread * 180 / Math.PI;
      const el = document.createElement('i');
      el.className = `shooting-painter-spread-bullet element-${spec.element}`;
      el.dataset.element = spec.element;
      el.dataset.order = String(index);
      el.style.setProperty('--painter-rgb', visual.rgb);
      arena.appendChild(el);
      return {
        ...spec,
        dx,
        dy,
        angleDeg,
        x:startX,
        y:startY,
        el,
        alive:true,
        hitTargets:new Set(),
      };
    });

    let lastTs = performance.now();
    let raf = 0;

    const cleanup = () => {
      if (raf) cancelAnimationFrame(raf);
      bullets.forEach(b => b.el && b.el.remove());
    };

    const animate = ts => {
      if (!state || state.ended || state.finishing) {
        cleanup();
        return;
      }

      const dt = Math.min(.035, Math.max(0, (ts - lastTs) / 1000));
      lastTs = ts;
      const arenaRect = arena.getBoundingClientRect();
      const width = Math.max(1, Number(arena.clientWidth || 0));
      const height = Math.max(1, Number(arena.clientHeight || 0));
      let aliveCount = 0;

      // 配列順＝左から neutral → fire → aqua → wood → dark → light。
      // 同一frameで同じ敵へ複数色が入った場合も、後ろの弾ほど後から上書きされる。
      for (const bullet of bullets) {
        if (!bullet.alive) continue;

        const prevX = bullet.x;
        const prevY = bullet.y;
        bullet.x += bullet.dx * speed * dt;
        bullet.y += bullet.dy * speed * dt;
        bullet.el.style.transform = `translate3d(${bullet.x}px,${bullet.y}px,0) rotate(${bullet.angleDeg}deg)`;

        const hits = findPainterSpreadCollisionsSwept(
          prevX,
          prevY,
          bullet.x,
          bullet.y,
          arenaRect,
          bullet.hitTargets,
          9
        );

        for (const hit of hits) {
          if (!hit.target || hit.target.hp <= 0) continue;
          bullet.hitTargets.add(hit.target);
          createBombSplashVictimHitEffect(hit.x, hit.y, bullet.element);
          applyPainterSpreadDamage(hit.target, damage, bullet.element, ts, c);
        }

        if (hits.length) finalizePainterSpreadHit(ts);

        if (
          bullet.x < -48 || bullet.x > width + 48 ||
          bullet.y < -54 || bullet.y > height + 54
        ) {
          bullet.alive = false;
          bullet.el.remove();
          continue;
        }

        aliveCount++;
      }

      if (aliveCount > 0) raf = requestAnimationFrame(animate);
      else cleanup();
    };

    bullets.forEach(b => {
      b.el.style.transform = `translate3d(${b.x}px,${b.y}px,0) rotate(${b.angleDeg}deg)`;
    });
    raf = requestAnimationFrame(animate);
    renderHud();
  }


  function isUltReady() {
    if (!state || state.ended || state.phaseTransition || state.finishing || state.countdown) return false;
    // build1255: CH04でも通常どおりULTを使用可能。
    // CH04-3の演出上の攻撃封印中だけULTを止める。
    if (isChapter43BossStage() && state.chapter43AttackSealed) return false;
    if (performance.now() < (state.ultLockUntil || 0)) return false;
    const c = getCurrentCharacter();
    const member = getActiveMember();
    return !!member && member.burst >= c.burstNeed;
  }

  // リュネ ULT「アブソリュート・レーテー」: 盤面全体へATK×2.0を1回適用し、全属性バリアを解除。
  function useLyuneAbsoluteLetheUlt(c) {
    if (!state || state.ended || state.finishing) return;
    showUltCut(c.ultName || 'アブソリュート・レーテー', c.effectKey);
    const targets = isNormalBattle()
      ? (state.normalEnemies || []).filter(e => e && e.hp > 0)
      : [...getBossAddUltTargets(), ...(state.boss && state.boss.hp > 0 ? [state.boss] : [])]; // build1740
    // バリアを先に消すことで、今回の全体攻撃にもIMMUNEが適用されない。
    targets.forEach(enemy => {
      if (!enemy.weaknessBarrierEl && !enemy.weaknessBarrier) return;
      enemy.lyuneBarrierRemoved = true;
      if (enemy.weaknessBarrierEl) { enemy.weaknessBarrierEl.remove(); enemy.weaknessBarrierEl = null; }
      if (enemy.el) enemy.el.classList.remove('has-weakness-barrier');
    });
    // Boss shields use a separate DOM node; retain the cleared state on this boss only.
    const bossShield = document.getElementById('shooting-boss-weakness-barrier');
    if (bossShield && state.boss && state.boss.hp > 0) {
      state.boss.lyuneBarrierRemoved = true;
      bossShield.remove();
    }
    applyUltDamage(Math.max(0, Number(c.atk || 0)) * Math.max(0, Number(c.ultDamageAtkMultiplier ?? 2.0)), true, c);
  }

  // ============================================================
  // build1613: スマイル ULT「びっくり箱」
  // ハオと同じ arena(x,y) / positionUnit の座標系を描画・弾遮蔽・爆発・ドロップで共有。
  // CSSのアニメーションは子要素だけで行い、positionUnitのtranslateを上書きしない。
  // ============================================================
  const SMILE_BOX_HALF_WIDTH = 44; // 遮蔽は箱の中央88×76px。飾りリボンを判定から除く。
  const SMILE_BOX_HALF_HEIGHT = 38;
  function clearSmileBoxes() {
    if (!state) return;
    (state.smileBoxes || []).forEach(box => box?.el?.remove());
    state.smileBoxes = [];
  }

  // build1875: 「前から飛んでくるもの」はびっくり箱で防げる（弾以外のレーザー・柱・衝撃波も）。
  //  発射元(x0,y0)→自機(x1,y1) の線分が設置中の箱を通れば遮られる。戻り値は箱と接触点、なければ null。
  function findSmileBoxShield(x0, y0, x1, y1, pad = 0) {
    if (!state || !Array.isArray(state.smileBoxes) || !state.smileBoxes.length) return null;
    const now = performance.now();
    let best = null;
    for (const box of state.smileBoxes) {
      if (!box || !box.el?.isConnected || now >= box.explodeAt) continue;
      const t = segmentAabbEntryT(x0, y0, x1, y1,
        box.x - SMILE_BOX_HALF_WIDTH - pad, box.x + SMILE_BOX_HALF_WIDTH + pad,
        box.y - SMILE_BOX_HALF_HEIGHT - pad, box.y + SMILE_BOX_HALF_HEIGHT + pad);
      if (t === null) continue;
      if (!best || t < best.t) best = { box, t, x: x0 + (x1 - x0) * t, y: y0 + (y1 - y0) * t };
    }
    return best;
  }
  // 遮った演出（火花＋箱が揺れる）。big で「BLOCK!」
  function showSmileBoxShield(hit, now, big) {
    if (!hit || !hit.box) return;
    const box = hit.box;
    if (now - Number(box.lastShieldFxAt || 0) < (big ? 0 : 120)) return;
    box.lastShieldFxAt = now;
    if (box.el) {
      box.el.classList.remove('smile-box-hit');
      void box.el.offsetWidth;
      box.el.classList.add('smile-box-hit');
    }
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const fx = document.createElement('div');
    fx.className = 'haze-block-spark' + (big ? ' is-big' : '');
    fx.setAttribute('aria-hidden', 'true');
    fx.innerHTML = '<i></i><b></b><u></u><u></u><u></u><u></u><u></u>' + (big ? '<em>BLOCK!</em>' : '');
    fx.style.transform = `translate3d(${hit.x.toFixed(1)}px,${hit.y.toFixed(1)}px,0)`;
    arena.appendChild(fx);
    setTimeout(() => fx.remove(), big ? 760 : 360);
  }
  // 自機の真上（列の上端 topY）から降ってくる縦の攻撃用
  function findSmileBoxShieldAbove(topY) {
    if (!state || !state.player) return null;
    const px = Number(state.player.x || 0), py = Number(state.player.y || 0);
    if (py <= topY) return null;
    return findSmileBoxShield(px, topY, px, py, 0);
  }
  function tryBlockEnemyBulletWithSmileBox(bullet, fromX, fromY, now) {
    if (!state || !Array.isArray(state.smileBoxes) || !state.smileBoxes.length) return false;
    const toX = Number(bullet.x || 0);
    const toY = Number(bullet.y || 0);
    // getUnitRect と同じく弾サイズは既存の半径キャッシュを使う。
    const hw = Math.max(0, Number(bullet._hw || bullet.canvasHalfWidth || 0));
    const hh = Math.max(0, Number(bullet._hh || bullet.canvasHalfHeight || 0));
    for (const box of state.smileBoxes) {
      if (!box || !box.el?.isConnected || now >= box.explodeAt) continue;
      const t = segmentAabbEntryT(
        fromX, fromY, toX, toY,
        box.x - SMILE_BOX_HALF_WIDTH - hw, box.x + SMILE_BOX_HALF_WIDTH + hw,
        box.y - SMILE_BOX_HALF_HEIGHT - hh, box.y + SMILE_BOX_HALF_HEIGHT + hh
      );
      if (t === null) continue;
      if (now - Number(box.lastHitFxAt || 0) >= 110) {
        box.lastHitFxAt = now;
        box.el.classList.remove('smile-box-hit');
        void box.el.offsetWidth;
        box.el.classList.add('smile-box-hit');
      }
      return true;
    }
    return false;
  }

  // build1615: 爆風演出を広範囲・多層に。閃光→衝撃波2重→煙→紙吹雪（星・菱形カード・鈴）＋画面揺れ。
  // DOMは約30個・900msで破棄（軽量化のため画像は使わずCSSのみ）。
  function spawnSmileExplosionFx(x, y, radius) {
    if (state && state.nerisa) nerisaBlastAt(Number(x), Number(y), Number(radius || 90)); // build2121
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const fx = document.createElement('div');
    fx.className = 'shooting-smile-box-explosion';
    fx.style.setProperty('--smile-blast-size', `${Math.round(radius * 2)}px`);
    const parts = [
      '<span class="smile-blast-flash"></span>',
      '<span class="smile-blast-core"></span>',
      '<span class="smile-blast-ring"></span>',
      '<span class="smile-blast-ring smile-blast-ring2"></span>',
      '<span class="smile-blast-wave"></span>',
      '<span class="smile-blast-star">✦</span>',
    ];
    const smokeCount = 10;
    for (let i = 0; i < smokeCount; i++) {
      const a = (i / smokeCount) * Math.PI * 2 + Math.random() * .4;
      const d = radius * (.55 + Math.random() * .35);
      const sz = Math.round(radius * (.32 + Math.random() * .18));
      parts.push(`<span class="smile-blast-smoke" style="--dx:${Math.round(Math.cos(a) * d)}px;--dy:${Math.round(Math.sin(a) * d)}px;--sz:${sz}px;--dl:${Math.round(Math.random() * 80)}ms"></span>`);
    }
    const confetti = ['star', 'star', 'card', 'card', 'diamond', 'bell'];
    const confettiCount = 16;
    for (let i = 0; i < confettiCount; i++) {
      const a = (i / confettiCount) * Math.PI * 2 + (Math.random() - .5) * .5;
      const d = radius * (.75 + Math.random() * .45);
      const kind = confetti[i % confetti.length];
      const rot = Math.round((Math.random() < .5 ? -1 : 1) * (240 + Math.random() * 360));
      const glyph = kind === 'star' ? '★' : kind === 'diamond' ? '✦' : '';
      parts.push(`<span class="smile-blast-bit is-${kind}" style="--dx:${Math.round(Math.cos(a) * d)}px;--dy:${Math.round(Math.sin(a) * d - radius * .12)}px;--rot:${rot}deg;--dl:${Math.round(Math.random() * 60)}ms">${glyph}</span>`);
    }
    fx.innerHTML = parts.join('');
    arena.appendChild(fx);
    positionUnit(fx, x, y);
    const root = document.getElementById(ROOT_ID);
    if (root) {
      root.classList.remove('smile-blast-shake');
      void root.offsetWidth;
      root.classList.add('smile-blast-shake');
      setTimeout(() => root.classList.remove('smile-blast-shake'), 420);
    }
    setTimeout(() => fx.remove(), 950);
  }

  // build1615: 爆発時は箱を「開いた箱」の画像に差し替えて一瞬弾ませてから消す（弾の遮蔽はこの時点で終了）。
  function openSmileBox(box) {
    const el = box && box.el;
    if (!el || !el.isConnected) return;
    el.classList.add('smile-box-open');
    el.querySelector('.smile-box-timer')?.remove();
    el.querySelector('.smile-box-halo')?.remove();
    const img = el.querySelector('img');
    if (img) img.src = 'images/chara_56_box_open.webp';
    setTimeout(() => el.remove(), 820);
  }

  function spawnSmileRandomItem(box, now) {
    const layer = document.getElementById('shooting-collectible-layer');
    if (!layer || !state) return;
    // 4種類は均等抽選。箱の中心（爆発の中心）に出し、拾うまでは残す。
    const kinds = ['atk', 'invincible', 'heal', 'ult'];
    const kind = kinds[Math.floor(Math.random() * kinds.length)];
    const owner = box.owner;
    const el = document.createElement('div');
    el.className = `shooting-mimosa-item mimosa-item-${kind}`;
    applySummonItemLook(el, kind);
    layer.appendChild(el);
    const item = {
      uid: `smile_${kind}_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
      sourceType:'smile_surprise_box', el, x:box.x, y:box.y, kind,
      label: kind === 'atk' ? 'ATK UP' : kind === 'invincible' ? 'INVINCIBLE'
        : kind === 'heal' ? 'HP HEAL' : 'ULT MAX',
      detail: kind === 'atk' ? 'ATK ×1.5 / 5秒' : kind === 'invincible' ? '3秒無敵'
        : kind === 'heal' ? '最大HP 33%回復' : 'ULTゲージ全回復',
      atkBuffMultiplier: Number(owner.smileItemAtkMultiplier ?? 1.5),
      atkBuffDurationMs: Number(owner.smileItemAtkDurationMs ?? 5000),
      invincibleDurationMs: Number(owner.smileItemInvincibleDurationMs ?? 3000),
      healPercent: Number(owner.smileItemHealPercent ?? 0.33),
      spawnedAt: now,
    };
    state.mimosaItems.push(item);
    positionUnit(el, box.x, box.y);
  }

  function explodeSmileBox(box, now) {
    if (!state || state.ended || state.finishing) return;
    const damage = Math.max(0, Number(box.owner.atk || 0)) * Math.max(0, Number(box.damageMultiplier || 3));
    const radius = Math.max(30, Number(box.blastRadius || 230));
    const element = getUltAttackElement(box.owner);
    openSmileBox(box);
    spawnSmileExplosionFx(box.x, box.y, radius);

    // BOSSの増援も含め、座標が爆風内の敵に1回だけ命中させる。
    for (const enemy of (state.normalEnemies || []).slice()) {
      if (!enemy || enemy.hp <= 0 || !enemy.el) continue;
      const hitPadding = Math.max(18, Math.min(48, Number(enemy._hw || 27)));
      if (Math.hypot(Number(enemy.x || 0) - box.x, Number(enemy.y || 0) - box.y) > radius + hitPadding) continue;
      const targetElement = getCombatTargetElement(enemy);
      damageNormalEnemy(enemy, applyElementDamage(damage, element, targetElement), now, true,
        getElementDamageReaction(element, targetElement));
    }
    state.normalEnemies = (state.normalEnemies || []).filter(enemy => enemy && enemy.hp > 0);
    if (!isNormalBattle() && state.boss && state.boss.hp > 0) {
      const boss = state.boss;
      const bossSize = document.getElementById(BOSS_ID)?.getBoundingClientRect();
      const bossPadding = Math.min(75, Math.max(28, Number(bossSize?.width || 0) * .3));
      if (Math.hypot(Number(boss.x || 0) - box.x, Number(boss.y || 0) - box.y) <= radius + bossPadding) {
        // build2081: ボス本体にだけ1回。applyUltDamage は全体攻撃用（配下全員・呪核にも当たる）なので使わない。
        //  配下は上のループで「爆風の範囲内だけ1回」当てている。
        const targetElement = getCombatTargetElement(boss);
        const finalDamage = applyElementDamage(damage, element, targetElement);
        const appliedDamage = Math.min(boss.hp, Math.max(0, Number(finalDamage || 0)));
        boss.hp = Math.max(0, boss.hp - appliedDamage);
        updateBossPhase();
        createHit(boss.x, boss.y, true);
        showBossDamageNumber(appliedDamage, true, getElementDamageReaction(element, targetElement));
        flashBossHit(true);
        if (!addScoreAttackDamageScore(appliedDamage)) addLegacyCombatScore(Math.round(appliedDamage * 100));
        if (boss.hp <= 0) beginBossDefeat();
      }
    }
    // build2081: イノリの呪核も、爆風の範囲内にある時だけ1回
    const execField = state.inoriExecutionField;
    if (execField && execField.mode === 'active' && execField.hp > 0 &&
        Math.hypot(Number(execField.coreX || 0) - box.x, Number(execField.coreY || 0) - box.y) <= radius + 38) {
      damageInoriExecutionCore(damage, now);
    }
    spawnSmileRandomItem(box, now);
    if (isNormalBattle()) evaluateNormalMission(now);
    renderHud();
  }

  function updateSmileBoxes(now) {
    if (!state || !Array.isArray(state.smileBoxes) || !state.smileBoxes.length) return;
    if (state.ended || state.finishing) { clearSmileBoxes(); return; }
    // 配列を先に更新。爆発から次のULT発動が起きても旧要素は残らない。
    const expired = [];
    state.smileBoxes = state.smileBoxes.filter(box => {
      if (!box?.el?.isConnected) return false;
      if (now < box.explodeAt) return true;
      expired.push(box);
      return false;
    });
    expired.forEach(box => explodeSmileBox(box, now));
  }

  function useSmileSurpriseBoxUlt(c) {
    if (!state || state.ended || state.finishing) return;
    showUltCut(c.ultName || 'びっくり箱', c.effectKey, c);
    ultScreenFlash('ult-flash-eri', c);
    placeSmileSurpriseBox(c);
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), performance.now() + 250);
  }

  // build2074: びっくり箱の設置だけ（ULTとお助けフレンドの「びっくり箱」で共用）
  function placeSmileSurpriseBox(c) {
    if (!state || state.ended || state.finishing) return;
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const width = Math.max(120, Number(arena.clientWidth || 0));
    const height = Math.max(120, Number(arena.clientHeight || 0));
    const x = clamp(Number(state.player.x ?? width * .5), 60, Math.max(60, width - 60));
    const y = clamp(Number(state.player.y ?? height * .75) - Number(c.smileBoxOffsetY ?? 90),
      60, Math.max(60, height - 60));
    const el = document.createElement('div');
    el.className = 'shooting-smile-box';
    el.setAttribute('aria-label', 'スマイル ULT びっくり箱');
    el.innerHTML = '<span class="smile-box-halo"></span><img src="images/chara_56_box.webp" alt="" draggable="false"><span class="smile-box-timer"></span>';
    // 爆発時に差し替える画像を先読み（切り替えの一瞬の空白を防ぐ）
    try { const pre = new Image(); pre.src = 'images/chara_56_box_open.webp'; } catch (_) {}
    el.style.left = '0px';
    el.style.top = '0px';
    arena.appendChild(el);
    positionUnit(el, x, y);
    const now = performance.now();
    state.smileBoxes.push({
      el, x, y, owner:c, explodeAt:now + Math.max(100, Number(c.smileBoxDurationMs ?? 3000)),
      blastRadius:Math.max(30, Number(c.smileBoxBlastRadius ?? 230)),
      damageMultiplier:Math.max(0, Number(c.smileBoxDamageMultiplier ?? 3)),
      lastHitFxAt:0,
    });
  }


  // ============================================================
  // build1817: イノリ ULT「双鳥居・祈りの帳」
  //  ・自機の左右に鳥居（chara_111_object）を2基設置（設置位置は固定）。
  //  ・鳥居は敵弾を受け止める（1基あたり inoriToriiHits 発で崩れる）。
  //  ・2基とも崩れるか inoriToriiDurationMs 経つまで、発動したキャラは無敵。
  //  ・鳥居から真上へ光属性レーザーを照射し続ける（inoriToriiLaserTickMs ごとに ATK×inoriToriiLaserAtkRate）。
  //  ・build1818: 鳥居の耐久は被弾HIT数（1基 inoriToriiHits=30）、最長 inoriToriiDurationMs=7秒。
  //    鳥居が建っている間に達成したコンボ数 × inoriJudgmentPerCombo(10) のダメージで、
  //    鳥居が消えた瞬間に「神罰」が盤面の敵1体（ボス優先・いなければHPが最も高い敵）へ降り注ぐ。
  //  ※ボスのイノリ（state.inori）とは別物。状態は state.inoriGuard に持つ。
  // ============================================================
  const INORI_TORII_HALF_W = 30;
  const INORI_TORII_HALF_H = 32;
  function ensureInoriGuardStyle() {
    if (document.getElementById('shooting-inori-guard-style-v1817')) return;
    const st = document.createElement('style');
    st.id = 'shooting-inori-guard-style-v1817';
    st.textContent = `
      #shooting-event-root .shooting-inori-guard-torii{position:absolute;left:0;top:0;width:72px;height:72px;z-index:11;pointer-events:none;
        transform-origin:50% 50%;animation:inoriToriiIn .34s cubic-bezier(.2,.9,.3,1.25) both}
      #shooting-event-root .shooting-inori-guard-torii > img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;
        filter:drop-shadow(0 0 6px rgba(255,236,170,.85)) drop-shadow(0 2px 3px rgba(80,60,40,.35))}
      #shooting-event-root .shooting-inori-guard-torii > i{position:absolute;left:50%;bottom:-6px;width:88px;height:18px;margin-left:-44px;border-radius:50%;
        background:radial-gradient(ellipse at center,rgba(255,244,196,.75),rgba(255,226,140,.25) 55%,transparent 72%)}
      #shooting-event-root .shooting-inori-guard-torii > b{position:absolute;left:8px;right:8px;bottom:-10px;height:4px;border-radius:3px;background:rgba(60,48,30,.35);overflow:hidden}
      #shooting-event-root .shooting-inori-guard-torii > b > u{display:block;height:100%;width:var(--hp,100%);background:linear-gradient(90deg,#fff3c4,#ffd35e);transition:width .12s ease}
      #shooting-event-root .shooting-inori-guard-torii.is-hit > img{animation:inoriToriiHit .16s ease}
      #shooting-event-root .shooting-inori-guard-torii.is-break{animation:inoriToriiBreak .42s ease forwards}
      @keyframes inoriToriiIn{from{opacity:0;transform:var(--pos) translateY(-26px) scale(.7)}to{opacity:1;transform:var(--pos) translateY(0) scale(1)}}
      @keyframes inoriToriiHit{0%{filter:brightness(2.2) drop-shadow(0 0 10px #fff)}100%{filter:drop-shadow(0 0 6px rgba(255,236,170,.85))}}
      @keyframes inoriToriiBreak{to{opacity:0;transform:var(--pos) translateY(10px) scale(.86) rotate(-6deg);filter:blur(1px)}}
      #shooting-event-root .shooting-inori-guard-beam{position:absolute;left:0;top:0;width:var(--w,14px);margin-left:calc(var(--w,14px) / -2);z-index:8;pointer-events:none;
        transform-origin:50% 100%;border-radius:999px;
        background:linear-gradient(90deg,rgba(255,236,160,0),rgba(255,246,206,.9) 30%,#fff 50%,rgba(255,246,206,.9) 70%,rgba(255,236,160,0));
        box-shadow:0 0 10px rgba(255,226,120,.85),0 0 22px rgba(255,210,80,.45);opacity:.92;animation:inoriBeamPulse .22s ease-in-out infinite alternate}
      @keyframes inoriBeamPulse{from{opacity:.78}to{opacity:1}}
      #shooting-event-root .shooting-inori-guard-veil{position:absolute;left:0;top:0;width:96px;height:96px;margin:-48px 0 0 -48px;z-index:12;pointer-events:none;border-radius:50%;
        border:2px solid rgba(255,238,170,.85);box-shadow:0 0 14px rgba(255,226,120,.7),inset 0 0 18px rgba(255,240,190,.45);
        background:radial-gradient(circle,rgba(255,250,224,.18),rgba(255,236,170,.08) 60%,transparent 72%);animation:inoriVeil 1.1s ease-in-out infinite alternate}
      @keyframes inoriVeil{from{opacity:.65}to{opacity:1}}
      #shooting-event-root .shooting-inori-judgment-count{position:absolute;left:0;top:0;z-index:13;pointer-events:none;white-space:nowrap;
        font:700 12px/1 "Noto Serif JP",serif;letter-spacing:.06em;color:#7a5410;
        padding:3px 9px;border-radius:999px;background:rgba(255,250,232,.9);border:1px solid rgba(214,170,70,.85);
        box-shadow:0 0 8px rgba(255,214,110,.6)}
      #shooting-event-root .shooting-inori-judgment-count b{font-family:Cinzel,serif;font-size:14px;color:#a36d0c;margin-left:4px}
      #shooting-event-root .shooting-inori-judgment-count.is-pulse{animation:inoriJcPulse .18s ease}
      @keyframes inoriJcPulse{50%{transform:var(--pos) scale(1.12)}}
      #shooting-event-root .shooting-inori-judgment{position:absolute;left:0;top:0;width:var(--jw,120px);z-index:21;pointer-events:none;
        transform-origin:50% 100%;animation:inoriJudgment .9s ease-out forwards}
      #shooting-event-root .shooting-inori-judgment > i{position:absolute;left:0;right:0;top:0;bottom:0;border-radius:0 0 50% 50%/0 0 30px 30px;
        background:linear-gradient(180deg,rgba(255,255,255,0),rgba(255,248,214,.92) 40%,#fff 75%,rgba(255,236,160,.95));
        box-shadow:0 0 26px rgba(255,226,120,.95),0 0 60px rgba(255,200,70,.6)}
      #shooting-event-root .shooting-inori-judgment > u{position:absolute;left:50%;bottom:-40px;width:200px;height:80px;margin-left:-100px;border-radius:50%;
        background:radial-gradient(ellipse,rgba(255,255,255,.95),rgba(255,226,130,.6) 40%,transparent 70%);animation:inoriJudgmentBurst .9s ease-out forwards}
      #shooting-event-root .shooting-inori-judgment > em{position:absolute;left:50%;bottom:30px;transform:translateX(-50%);white-space:nowrap;
        font:900 26px/1 "Noto Serif JP",serif;letter-spacing:.2em;color:#fff;text-shadow:0 0 6px #e8a520,0 0 16px rgba(255,200,60,.9),0 2px 0 #8a5a10}
      @keyframes inoriJudgment{0%{opacity:0;transform:var(--pos) scaleY(.1)}12%{opacity:1;transform:var(--pos) scaleY(1)}70%{opacity:1}100%{opacity:0;transform:var(--pos) scaleY(1) scaleX(.4)}}
      @keyframes inoriJudgmentBurst{0%{transform:scale(.2);opacity:0}20%{opacity:1}100%{transform:scale(1.6);opacity:0}}
      @media (prefers-reduced-motion:reduce){#shooting-event-root .shooting-inori-guard-beam,#shooting-event-root .shooting-inori-guard-veil{animation:none}}
    `;
    document.head.appendChild(st);
  }
  function clearInoriGuard() {
    if (!state || !state.inoriGuard) return;
    const g = state.inoriGuard;
    (g.torii || []).forEach(t => { t.el?.remove(); t.beam?.remove(); });
    g.veil?.remove();
    g.counter?.remove();
    // この鳥居で付けた無敵だけを解除（他の無敵は残す）
    const member = (state.party || []).find(m => m && Number(m.id) === Number(g.memberId));
    if (member && Number(member.invincibleUntil || 0) === Number(g.invincibleUntil || -1)) member.invincibleUntil = performance.now();
    state.inoriGuard = null;
  }
  function useInoriToriiGuardUlt(c) {
    if (!state || state.ended || state.finishing) return;
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    ensureInoriGuardStyle();
    if (state.inoriGuard) clearInoriGuard();
    // build1825: イノリの凸段階別ULT（0～4凸）。キャラ所有情報から読み取る。
    // ガチャ試遊は最大育成（4凸）として扱い、通常戦では所持中の限界突破に従う。
    const inoriLb = Math.max(0, Math.min(4, Math.floor(
      isGachaTrialStage() ? 4 : getShootingResonanceLevel(111)
    )));
    c = Object.assign({}, c, {
      inoriToriiDurationMs: [3000, 4000, 5000, 6000, 7000][inoriLb],
      inoriToriiHits: [20, 25, 30, 35, 40][inoriLb],
      inoriJudgmentPerCombo: [6, 7, 8, 9, 10][inoriLb],
    });
    showUltCut(c.ultName || '双鳥居・祈りの帳', c.effectKey, c);
    ultScreenFlash('ult-flash-eri', c);
    const now = performance.now();
    const width = Math.max(120, Number(arena.clientWidth || 0));
    const height = Math.max(120, Number(arena.clientHeight || 0));
    const px = Number(state.player.x ?? width * .5);
    const py = Number(state.player.y ?? height * .75);
    const off = Math.max(40, Number(c.inoriToriiOffsetX || 64));
    const y = clamp(py + Number(c.inoriToriiOffsetY || -6), 60, Math.max(60, height - 40));
    const hits = Math.max(1, Math.floor(Number(c.inoriToriiHits || 30)));
    const duration = Math.max(500, Number(c.inoriToriiDurationMs || 7000));
    const torii = [-1, 1].map(side => {
      const x = clamp(px + side * off, 30, Math.max(30, width - 30));
      const el = document.createElement('div');
      el.className = 'shooting-inori-guard-torii';
      el.innerHTML = '<i></i><img src="images/chara_111_object.webp" alt="" draggable="false"><b><u></u></b>';
      const pos = `translate3d(${x}px,${y}px,0) translate(-50%,-50%)`;
      el.style.setProperty('--pos', pos);
      el.style.transform = pos;
      arena.appendChild(el);
      const beam = document.createElement('div');
      beam.className = 'shooting-inori-guard-beam';
      const topY = y - INORI_TORII_HALF_H;
      beam.style.setProperty('--w', `${Math.max(6, Number(c.inoriToriiLaserWidth || 14))}px`);
      beam.style.height = `${Math.max(10, topY - 6)}px`;
      beam.style.transform = `translate3d(${x}px,6px,0)`;
      arena.appendChild(beam);
      return { el, beam, x, y, topY, hp: hits, maxHp: hits, alive: true, lastHitFxAt: 0 };
    });
    const member = getActiveMember();
    const invincibleUntil = now + duration;
    if (member) member.invincibleUntil = Math.max(Number(member.invincibleUntil || 0), invincibleUntil);
    const veil = document.createElement('div');
    veil.className = 'shooting-inori-guard-veil';
    arena.appendChild(veil);
    // 神罰の威力表示（2基の鳥居の間・上）
    const counter = document.createElement('div');
    counter.className = 'shooting-inori-judgment-count';
    const cpos = `translate3d(${px}px,${Math.max(20, y - 70)}px,0) translate(-50%,-50%)`;
    counter.style.setProperty('--pos', cpos);
    counter.style.transform = cpos;
    counter.innerHTML = '神罰<b>0</b>';
    arena.appendChild(counter);
    state.inoriGuard = {
      owner: c, torii, veil, counter, memberId: member ? Number(member.id) : 0,
      invincibleUntil: member ? Number(member.invincibleUntil) : 0,
      endAt: now + duration, nextTickAt: now + 120, comboHits: 0, comboDirty: false,
    };
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + 300);
    renderHud();
  }
  // 敵弾が鳥居に当たったら受け止める（スマイルの箱と同じ線分判定）。true＝弾を消す
  function tryBlockEnemyBulletWithInoriTorii(bullet, fromX, fromY, now) {
    const g = state && state.inoriGuard;
    if (!g) return false;
    const toX = Number(bullet.x || 0), toY = Number(bullet.y || 0);
    const hw = Math.max(0, Number(bullet._hw || bullet.canvasHalfWidth || 0));
    const hh = Math.max(0, Number(bullet._hh || bullet.canvasHalfHeight || 0));
    for (const t of g.torii) {
      if (!t.alive) continue;
      const hit = segmentAabbEntryT(fromX, fromY, toX, toY,
        t.x - INORI_TORII_HALF_W - hw, t.x + INORI_TORII_HALF_W + hw,
        t.y - INORI_TORII_HALF_H - hh, t.y + INORI_TORII_HALF_H + hh);
      if (hit === null) continue;
      t.hp -= 1;
      const bar = t.el.querySelector('u');
      if (bar) bar.style.setProperty('--hp', `${Math.max(0, t.hp / t.maxHp * 100)}%`);
      if (now - t.lastHitFxAt >= 110) {
        t.lastHitFxAt = now;
        t.el.classList.remove('is-hit'); void t.el.offsetWidth; t.el.classList.add('is-hit');
      }
      if (t.hp <= 0) breakInoriTorii(t);
      return true;
    }
    return false;
  }
  function breakInoriTorii(t) {
    if (!t.alive) return;
    t.alive = false;
    t.beam?.remove();
    t.el.classList.add('is-break');
    const el = t.el;
    setTimeout(() => el.remove(), 450);
  }
  // build1818: 神罰。鳥居が建っていた間のコンボ数 × 10 の固定ダメージを、盤面の敵1体へ。
  function pickInoriJudgmentTarget() {
    if (!isNormalBattle() && !isBossPassThrough() && state.boss && state.boss.hp > 0) {
      return { kind: 'boss', target: state.boss, x: state.boss.x, y: state.boss.y };
    }
    let best = null;
    (state.normalEnemies || []).forEach(e => {
      if (!e || !e.el || e.hp <= 0) return;
      if (!best || Number(e.hp) > Number(best.hp)) best = e;
    });
    if (best) return { kind: 'normal', target: best, x: best.x, y: best.y };
    if (isFacelessStage() || isAmbushStage()) {
      const obj = (state.facelessObjects || []).filter(o => o && o.hp > 0).sort((a, b) => Number(b.hp) - Number(a.hp))[0];
      if (obj) return { kind: 'object', target: obj, x: obj.x, y: obj.y };
    }
    return null;
  }
  function castInoriJudgment(g, now) {
    if (!state || state.ended || state.finishing || !g) return;
    const per = Math.max(0, Number(g.owner.inoriJudgmentPerCombo ?? 10));
    const damage = Math.max(0, Math.floor(Number(g.comboHits || 0))) * per;
    if (damage <= 0) return;
    const target = pickInoriJudgmentTarget();
    if (!target) return;
    const arena = document.getElementById('shooting-arena');
    if (arena) {
      const fx = document.createElement('div');
      fx.className = 'shooting-inori-judgment';
      const h = Math.max(80, Number(target.y || 0) + 20);
      const pos = `translate3d(${Number(target.x || 0)}px,0px,0) translateX(-50%)`;
      fx.style.setProperty('--pos', pos);
      fx.style.transform = pos;
      fx.style.height = `${h}px`;
      fx.style.setProperty('--jw', `${Math.min(170, 90 + damage / 40)}px`);
      fx.innerHTML = '<i></i><u></u><em>神罰</em>';
      arena.appendChild(fx);
      setTimeout(() => fx.remove(), 950);
      ultScreenFlash('ult-flash-eri', g.owner);
    }
    // 固定ダメージ（無属性扱い：属性の有利不利で増減しない）
    const hits = applyLaserDamageToEntries(g.owner, [target], damage, 'neutral', now, false);
    state.normalEnemies = (state.normalEnemies || []).filter(enemy => enemy && enemy.hp > 0);
    if (hits > 0 && isNormalBattle()) evaluateNormalMission(now);
    renderHud();
  }
  function updateInoriGuard(now) {
    const g = state && state.inoriGuard;
    if (!g) return;
    if (state.ended || state.finishing) { clearInoriGuard(); return; }
    const alive = g.torii.filter(t => t.alive);
    if (!alive.length || now >= g.endAt) {
      g.torii.forEach(breakInoriTorii);
      g.veil?.remove();
      g.counter?.remove();
      const member = (state.party || []).find(m => m && Number(m.id) === Number(g.memberId));
      if (member && Number(member.invincibleUntil || 0) === Number(g.invincibleUntil || -1)) member.invincibleUntil = now;
      state.inoriGuard = null;
      castInoriJudgment(g, now);
      return;
    }
    if (g.comboDirty && g.counter) {
      g.comboDirty = false;
      const per = Math.max(0, Number(g.owner.inoriJudgmentPerCombo ?? 10));
      const b = g.counter.querySelector('b');
      if (b) b.textContent = (Math.max(0, g.comboHits) * per).toLocaleString('ja-JP');
      g.counter.classList.remove('is-pulse'); void g.counter.offsetWidth; g.counter.classList.add('is-pulse');
    }
    // 無敵の膜は発動キャラが出場中の時だけ自機に重ねる
    if (g.veil) {
      const show = Number(state.activeCharacterId) === Number(g.memberId);
      g.veil.style.display = show ? '' : 'none';
      if (show) g.veil.style.transform = `translate3d(${Number(state.player.x || 0)}px,${Number(state.player.y || 0)}px,0)`;
    }
    if (now < g.nextTickAt) return;
    g.nextTickAt = now + Math.max(60, Number(g.owner.inoriToriiLaserTickMs || 150));
    const c = g.owner;
    const damage = Math.max(0, Number(c.atk || 0)) * Math.max(0, Number(g.owner.inoriToriiLaserAtkRate || 0.08));
    if (damage <= 0) return;
    const element = getUltAttackElement(g.owner);
    const hitWidth = Math.max(8, Number(g.owner.inoriToriiLaserHitWidth || 30));
    let hits = 0;
    alive.forEach(t => { hits += applyLaserDamageToEntries(c, getIgnisLaserTargets(t.x, t.topY, hitWidth), damage, element, now, false); });
    state.normalEnemies = (state.normalEnemies || []).filter(enemy => enemy && enemy.hp > 0);
    if (hits > 0) {
      state.shotsHit += hits;
      for (let i = 0; i < hits; i++) registerComboHit(g.owner.id, now);
    }
    if (isNormalBattle() && hits > 0) evaluateNormalMission(now);
  }

  // build1312: ハオULT『天機・五刻の雷』。盤面固定の成長トリガーを自キャラが回収すると全体落雷。
  const HAO_TRIGGER_DEFAULT_MULTIPLIERS = Object.freeze([1.0, 1.8, 3.0, 4.0, 5.0]);

  // build1497: 紋章を全面刷新。LVごとに「図形が増える／色が変わる／大きくなる／5つの刻印が灯る」。
  // ・LV1 淡翠：外環＋目盛り＋刻印1灯
  // ・LV2 翠  ：五角形が刻まれる（刻印2灯）
  // ・LV3 碧  ：五芒星＋内環（刻印3灯）
  // ・LV4 金翠：外側に八卦の回転環（刻印4灯）
  // ・LV5 黄金：中央に日輪の紋＋光輪・高速回転（刻印5灯）
  // LVが上がる瞬間は衝撃リング＋LV表示の跳ねで知らせる。回転は独立したSVG要素の transform のみ。
  const HAO_TRIGGER_SCALES = Object.freeze([1.0, 1.08, 1.16, 1.25, 1.36]);
  const HAO_TRIGGER_BASE_HIT_RADIUS = 36;

  function buildHaoSigilSvg() {
    const pt = (r, deg) => {
      const a = (deg - 90) * Math.PI / 180;
      return [+(Math.cos(a) * r).toFixed(2), +(Math.sin(a) * r).toFixed(2)];
    };
    const five = [0, 1, 2, 3, 4].map(i => pt(36, i * 72));
    const pentagon = 'M' + five.map(p => p.join(' ')).join(' L') + 'Z';
    const star = 'M' + [0, 2, 4, 1, 3].map(i => five[i].join(' ')).join(' L') + 'Z';
    const pips = [0, 1, 2, 3, 4].map(i => {
      const [x, y] = pt(44, i * 72);
      return `<circle class="hao-pip p${i + 1}" cx="${x}" cy="${y}" r="3.6"/>`;
    }).join('');
    const rays = Array.from({ length: 12 }, (_, i) => {
      const [x1, y1] = pt(9, i * 30);
      const [x2, y2] = pt(i % 2 ? 16 : 21, i * 30);
      return `M${x1} ${y1}L${x2} ${y2}`;
    }).join(' ');
    return `
      <svg class="hao-mark" viewBox="-50 -50 100 100" aria-hidden="true" focusable="false">
        <circle class="hao-engrave" r="44"/>
        <circle class="hao-line hao-strong" r="44"/>
        <circle class="hao-ticks" r="41.6"/>
        <circle class="hao-line" r="39"/>
        <g class="hao-lv1">
          <circle class="hao-line" r="10"/>
          <path class="hao-accent" d="M0 -8 L5 0 L0 8 L-5 0Z"/>
        </g>
        <g class="hao-lv2"><path class="hao-engrave thin" d="${pentagon}"/><path class="hao-accent" d="${pentagon}"/></g>
        <g class="hao-lv3"><path class="hao-engrave thin" d="${star}"/><path class="hao-accent" d="${star}"/><circle class="hao-line" r="22"/></g>
        <g class="hao-lv5"><circle class="hao-sun" r="8"/><path class="hao-accent" d="${rays}"/></g>
        ${pips}
      </svg>`;
  }

  function buildHaoTrigramBandSvg() {
    // 八卦（3本の爻）。陽＝一本線、陰＝中央が切れた線。
    const trigrams = ['111', '011', '101', '001', '110', '010', '100', '000'];
    const bars = trigrams.map((code, i) => {
      const lines = code.split('').map((bit, j) => {
        const r = 50 + j * 3.4;
        return bit === '1'
          ? `M-4.6 ${-r}H4.6`
          : `M-4.6 ${-r}H-1.1M1.1 ${-r}H4.6`;
      }).join('');
      return `<path transform="rotate(${i * 45})" d="${lines}"/>`;
    }).join('');
    return `
      <svg class="hao-band-svg" viewBox="-62 -62 124 124" aria-hidden="true" focusable="false">
        <circle class="hao-band-ring" r="47.5"/>
        <circle class="hao-band-ring" r="59.5"/>
        <g class="hao-trigram">${bars}</g>
      </svg>`;
  }

  function ensureHaoTriggerStyle() {
    if (document.getElementById('shooting-hao-trigger-style-1497')) return;
    const old = document.getElementById('shooting-hao-trigger-style');
    if (old) old.remove();
    const lit = [];
    for (let lv = 1; lv <= 5; lv++) {
      for (let n = 1; n <= lv; n++) lit.push(`.shooting-hao-trigger[data-level="${lv}"] .hao-pip.p${n}`);
    }
    const show = (n) => {
      const sel = [];
      for (let lv = n; lv <= 5; lv++) sel.push(`.shooting-hao-trigger[data-level="${lv}"] .hao-lv${n}`);
      return sel.join(',');
    };
    const style = document.createElement('style');
    style.id = 'shooting-hao-trigger-style-1497';
    style.textContent = `
      .shooting-hao-trigger{
        position:absolute;left:0;top:0;width:88px;height:88px;z-index:8;pointer-events:none;
        border:0;background:transparent;box-shadow:none;overflow:visible;
        font-family:'Noto Serif JP',serif;
        --hc:rgba(186,236,196,.92);      /* 線 */
        --hc2:rgba(226,252,224,1);       /* 強調線 */
        --hglow:rgba(130,214,160,.55);   /* 発光 */
        --hfill:rgba(12,40,24,.50);      /* 地 */
        --hpip:rgba(232,255,214,1);
        --hscale:1;
      }
      .shooting-hao-trigger[data-level="2"]{--hc:rgba(150,232,130,.9);--hc2:rgba(206,255,170,.98);--hglow:rgba(110,220,100,.55);--hscale:${HAO_TRIGGER_SCALES[1]}}
      .shooting-hao-trigger[data-level="3"]{--hc:rgba(110,236,200,.92);--hc2:rgba(200,255,238,1);--hglow:rgba(70,220,190,.62);--hfill:rgba(8,44,40,.55);--hpip:rgba(220,255,248,1);--hscale:${HAO_TRIGGER_SCALES[2]}}
      .shooting-hao-trigger[data-level="4"]{--hc:rgba(214,236,120,.94);--hc2:rgba(250,255,190,1);--hglow:rgba(206,226,90,.66);--hfill:rgba(36,46,12,.56);--hpip:rgba(255,252,206,1);--hscale:${HAO_TRIGGER_SCALES[3]}}
      .shooting-hao-trigger[data-level="5"]{--hc:rgba(255,212,110,.96);--hc2:rgba(255,246,200,1);--hglow:rgba(255,196,80,.80);--hfill:rgba(60,38,8,.58);--hpip:rgba(255,255,236,1);--hscale:${HAO_TRIGGER_SCALES[4]}}

      .shooting-hao-trigger .hao-body{
        position:absolute;inset:0;transform:scale(var(--hscale));transform-origin:50% 50%;
        transition:transform .32s cubic-bezier(.2,1.6,.4,1);
      }
      .shooting-hao-trigger .hao-ground{
        position:absolute;inset:-6%;border-radius:50%;
        background:radial-gradient(circle,var(--hfill) 0%,var(--hfill) 52%,rgba(0,0,0,0) 72%);
        box-shadow:0 0 18px var(--hglow),inset 0 0 14px var(--hglow);
      }
      .shooting-hao-trigger .hao-aura{
        position:absolute;inset:-26%;border-radius:50%;
        background:radial-gradient(circle,rgba(0,0,0,0) 40%,var(--hglow) 58%,rgba(0,0,0,0) 74%);
        opacity:.0;animation:haoAuraBreathe 1.8s ease-in-out infinite;
      }
      .shooting-hao-trigger[data-level="1"] .hao-aura{opacity:.32}
      .shooting-hao-trigger[data-level="2"] .hao-aura{opacity:.42}
      .shooting-hao-trigger[data-level="3"] .hao-aura{opacity:.6}
      .shooting-hao-trigger[data-level="4"] .hao-aura{opacity:.75}
      .shooting-hao-trigger[data-level="5"] .hao-aura{opacity:1;animation-duration:1.1s}
      .shooting-hao-trigger .hao-mark,
      .shooting-hao-trigger .hao-band{position:absolute;overflow:visible}
      .shooting-hao-trigger .hao-mark{inset:0;width:100%;height:100%;
        filter:drop-shadow(0 0 3px var(--hglow));}
      .shooting-hao-trigger .hao-engrave{fill:none;stroke:rgba(6,22,14,.9);stroke-width:3.4;stroke-linejoin:round}
      .shooting-hao-trigger .hao-engrave.thin{stroke-width:3}
      .shooting-hao-trigger .hao-line{fill:none;stroke:var(--hc);stroke-width:1}
      .shooting-hao-trigger .hao-strong{stroke-width:1.8}
      .shooting-hao-trigger .hao-ticks{fill:none;stroke:var(--hc);stroke-width:3.2;stroke-dasharray:.7 3.66;opacity:.9}
      .shooting-hao-trigger .hao-accent{fill:none;stroke:var(--hc2);stroke-width:1.5;stroke-linejoin:round;stroke-linecap:round}
      .shooting-hao-trigger .hao-sun{fill:var(--hc2);stroke:rgba(90,56,10,.6);stroke-width:1}
      .shooting-hao-trigger .hao-pip{fill:rgba(6,22,14,.95);stroke:rgba(120,140,128,.7);stroke-width:1;transform-box:fill-box;transform-origin:center;transform:scale(.8);transition:fill .25s ease,transform .3s cubic-bezier(.2,1.8,.4,1)}
      ${lit.join(',')}{fill:var(--hpip);stroke:var(--hc2);stroke-width:1.4;transform:scale(1.25);filter:drop-shadow(0 0 3px var(--hglow)) drop-shadow(0 0 1px #fff)}
      .shooting-hao-trigger .hao-lv2,
      .shooting-hao-trigger .hao-lv3,
      .shooting-hao-trigger .hao-lv5{opacity:0;transition:opacity .3s ease}
      ${show(2)},${show(3)},${show(5)}{opacity:1}
      .shooting-hao-trigger[data-level="5"] .hao-lv1{opacity:0}

      /* LV4〜：外側の八卦環。要素ごと回転（SVG内部はアニメーションしない） */
      .shooting-hao-trigger .hao-band{left:-20%;top:-20%;width:140%;height:140%;opacity:0;
        transform:scale(.7);transition:opacity .3s ease,transform .35s cubic-bezier(.2,1.5,.4,1)}
      .shooting-hao-trigger[data-level="4"] .hao-band,
      .shooting-hao-trigger[data-level="5"] .hao-band{opacity:1;transform:scale(1)}
      .shooting-hao-trigger .hao-band-spin{position:absolute;inset:0;animation:haoBandSpin 14s linear infinite}
      .shooting-hao-trigger[data-level="5"] .hao-band-spin{animation-duration:6s}
      .shooting-hao-trigger .hao-band-ring{fill:none;stroke:var(--hc);stroke-width:.9;opacity:.85}
      .shooting-hao-trigger .hao-trigram path{fill:none;stroke:var(--hc2);stroke-width:2;stroke-linecap:round}
      .shooting-hao-trigger .hao-band-svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible;filter:drop-shadow(0 0 2px var(--hglow))}

      /* LVアップの衝撃リング */
      .shooting-hao-trigger .hao-levelup{position:absolute;inset:0;border-radius:50%;
        border:3px solid var(--hc2);box-shadow:0 0 16px var(--hglow);opacity:0}
      .shooting-hao-trigger .hao-levelup.go{animation:haoLevelUp .5s ease-out forwards}

      /* LV表示：バッジ */
      .shooting-hao-trigger .hao-caption{
        position:absolute;top:100%;left:50%;margin-top:calc((var(--hscale) - 1) * 44px + 4px);
        transform:translateX(-50%);
        display:flex;gap:5px;align-items:baseline;white-space:nowrap;
        padding:2px 8px 3px;border-radius:999px;
        background:linear-gradient(180deg,rgba(10,30,20,.82),rgba(6,20,14,.82));
        border:1px solid var(--hc);box-shadow:0 0 8px var(--hglow);
        color:var(--hc2);line-height:1;letter-spacing:.04em;
        text-shadow:0 1px 2px rgba(0,0,0,.8);
      }
      .shooting-hao-trigger[data-level="5"] .hao-caption{background:linear-gradient(180deg,rgba(70,44,8,.9),rgba(40,24,4,.9))}
      .shooting-hao-trigger .hao-level{font-size:12px;font-weight:700}
      .shooting-hao-trigger .hao-power{font-size:10px;opacity:.9}
      .shooting-hao-trigger .hao-caption.pop{animation:haoCaptionPop .38s cubic-bezier(.2,1.8,.4,1)}

      .shooting-hao-trigger.is-arming{opacity:.6}

      /* 起爆：紋章が光って弾ける */
      .shooting-hao-trigger-burst{position:absolute;left:0;top:0;width:var(--hb-size,120px);height:var(--hb-size,120px);
        z-index:8;pointer-events:none;border-radius:50%}
      .shooting-hao-trigger-burst::before,
      .shooting-hao-trigger-burst::after{content:'';position:absolute;inset:0;border-radius:50%;opacity:0}
      .shooting-hao-trigger-burst::before{background:radial-gradient(circle,rgba(255,255,240,1) 0 12%,var(--hb-c2) 32%,var(--hb-c) 52%,rgba(0,0,0,0) 72%);
        animation:haoTrigFlash .45s ease-out forwards}
      .shooting-hao-trigger-burst::after{border:4px solid var(--hb-c2);box-shadow:0 0 18px var(--hb-c);
        animation:haoTrigRing .55s cubic-bezier(.15,.7,.3,1) forwards}

      .shooting-hao-lightning{position:absolute;z-index:49;width:16px;pointer-events:none;opacity:0;animation:haoLightningStrike .4s ease-out both;
        --hl1:rgba(237,255,217,.98);--hl2:rgba(184,236,141,.88);--hlg:#daf6a7}
      .shooting-hao-lightning.lv3{--hl1:rgba(220,255,246,.98);--hl2:rgba(110,236,200,.9);--hlg:#9ff5df}
      .shooting-hao-lightning.lv4{--hl1:rgba(252,255,214,.98);--hl2:rgba(214,236,120,.9);--hlg:#eef59a}
      .shooting-hao-lightning.lv5{--hl1:rgba(255,250,224,1);--hl2:rgba(255,206,96,.95);--hlg:#ffd66e;width:24px}
      .shooting-hao-lightning::before{content:'';position:absolute;left:2px;right:2px;top:0;bottom:0;
        background:linear-gradient(180deg,transparent,var(--hl1) 15%,#fff 48%,var(--hl2) 78%,transparent);
        filter:drop-shadow(0 0 7px var(--hlg));clip-path:polygon(48% 0%,75% 0%,48% 27%,92% 31%,37% 61%,72% 67%,24% 100%,40% 66%,4% 60%,58% 35%,20% 29%)}
      .shooting-hao-lightning::after{content:'';position:absolute;left:50%;bottom:-9px;width:54px;height:18px;transform:translateX(-50%);border:2px solid var(--hl2);border-radius:50%;box-shadow:0 0 12px var(--hlg);background:radial-gradient(ellipse,rgba(255,254,218,.6),transparent 70%)}
      .shooting-hao-lightning.lv5::after{width:78px;height:24px;border-width:3px}

      @keyframes haoLightningStrike{0%{opacity:0}15%{opacity:1}48%{opacity:1}100%{opacity:0}}
      @keyframes haoAuraBreathe{0%,100%{transform:scale(.94)}50%{transform:scale(1.04)}}
      @keyframes haoBandSpin{to{transform:rotate(360deg)}}
      @keyframes haoLevelUp{0%{transform:scale(.6);opacity:1}100%{transform:scale(1.7);opacity:0}}
      @keyframes haoCaptionPop{0%{transform:translateX(-50%) scale(1.6)}100%{transform:translateX(-50%) scale(1)}}
      @keyframes haoTrigFlash{0%{transform:scale(.3);opacity:1}100%{transform:scale(1.1);opacity:0}}
      @keyframes haoTrigRing{0%{transform:scale(.25);opacity:1}100%{transform:scale(1.2);opacity:0}}
      @media(prefers-reduced-motion:reduce){
        .shooting-hao-trigger .hao-band-spin,.shooting-hao-trigger .hao-aura{animation:none}
      }
    `;
    document.head.appendChild(style);
  }

  function clearHaoTrigger() {
    if (!state || !state.haoTrigger) return;
    if (state.haoTrigger.el) state.haoTrigger.el.remove();
    state.haoTrigger = null;
  }

  function getHaoTriggerLevel(trigger, now) {
    const step = Math.max(250, Number(trigger.upgradeMs || 2000));
    return Math.min(5, 1 + Math.floor(Math.max(0, now - trigger.startedAt) / step));
  }

  function spawnHaoLightningOnBoard(points, level) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const lv = Math.max(1, Math.min(5, Number(level || 1)));
    for (const point of points) {
      const el = document.createElement('i');
      el.className = 'shooting-hao-lightning lv' + lv;
      const targetY = Math.max(25, Number(point.y || 0));
      const targetX = Number(point.x || 0);
      const w = lv >= 5 ? 24 : 16;
      el.style.left = `${targetX - w / 2}px`;
      el.style.top = '0px';
      el.style.height = `${targetY}px`;
      arena.appendChild(el);
      setTimeout(() => el.remove(), 470);
    }
  }

  function spawnHaoTriggerBurst(trigger, level) {
    if (state && state.nerisa) nerisaBlastAll(.8 + Number(level || 1) * .12, { collapse: true }); // build2126: 落雷は一撃でヴェール崩壊
    const arena = document.getElementById('shooting-arena');
    if (!arena || !trigger) return;
    const el = document.createElement('i');
    el.className = 'shooting-hao-trigger-burst';
    const colors = [
      ['rgba(120,200,140,.6)', 'rgba(214,246,200,.95)'],
      ['rgba(110,220,100,.65)', 'rgba(206,255,170,.95)'],
      ['rgba(70,220,190,.7)', 'rgba(200,255,238,.95)'],
      ['rgba(206,226,90,.7)', 'rgba(250,255,190,.95)'],
      ['rgba(255,196,80,.8)', 'rgba(255,246,200,1)'],
    ][Math.max(0, Math.min(4, level - 1))];
    el.style.setProperty('--hb-c', colors[0]);
    el.style.setProperty('--hb-c2', colors[1]);
    el.style.setProperty('--hb-size', `${Math.round(110 + level * 26)}px`);
    arena.appendChild(el);
    positionUnit(el, trigger.x, trigger.y);
    setTimeout(() => el.remove(), 600);
  }

  function useHaoUlt(c) {
    if (!state || state.ended || state.finishing) return;
    showUltCut(c.ultName, c.effectKey, c);
    ultScreenFlash('ult-flash-eri', c);
    clearEnemyBulletsOnly();
    clearHaoTrigger(); // 同一キャラの再発動は前のトリガーと置換
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    ensureHaoTriggerStyle();
    const bounds = arena.getBoundingClientRect();
    const width = Math.max(80, bounds.width || arena.clientWidth);
    const height = Math.max(80, bounds.height || arena.clientHeight);
    const playerX = Number(state.player.x || width * .5);
    const playerY = Number(state.player.y || height * .75);
    const x = Math.max(44, Math.min(width - 44, playerX));
    // Front of player is the UPWARD direction (negative arena Y).
    const y = Math.max(44, Math.min(height - 44, playerY - 90));
    const el = document.createElement('div');
    el.className = 'shooting-hao-trigger is-arming';
    el.setAttribute('aria-label', 'ハオ ULT 起動紋様');
    el.dataset.level = '1';
    el.innerHTML = `
      <span class="hao-body" aria-hidden="true">
        <span class="hao-aura"></span>
        <span class="hao-ground"></span>
        <span class="hao-band"><span class="hao-band-spin">${buildHaoTrigramBandSvg()}</span></span>
        ${buildHaoSigilSvg()}
        <span class="hao-levelup"></span>
      </span>
      <span class="hao-caption"><span class="hao-level">LV1</span><span class="hao-power">×1.0</span></span>`;
    // positionUnit uses translate(x,y) from the ARENA origin.
    el.style.left = '0px';
    el.style.top = '0px';
    arena.appendChild(el);
    positionUnit(el, x, y);
    state.haoTrigger = {
      el, x, y, startedAt: performance.now(), owner: c,
      upgradeMs: Number(c.haoTriggerUpgradeMs || 2000),
      safetyMs: Number(c.haoTriggerSafetyMs || 500),
      multipliers: Array.isArray(c.haoTriggerMultipliers) ? c.haoTriggerMultipliers : HAO_TRIGGER_DEFAULT_MULTIPLIERS,
      level: 1
    };
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), performance.now() + 220);
  }

  function updateHaoTrigger(now) {
    if (!state || !state.haoTrigger) return;
    if (state.ended || state.finishing) { clearHaoTrigger(); return; }
    const trigger = state.haoTrigger;
    if (!trigger.el || !trigger.el.isConnected) { clearHaoTrigger(); return; }
    const level = getHaoTriggerLevel(trigger, now);
    if (level !== trigger.level) {
      trigger.level = level;
      trigger.el.dataset.level = String(level);
      const label = trigger.el.querySelector('.hao-level');
      const power = trigger.el.querySelector('.hao-power');
      if (label) label.textContent = `LV${level}`;
      if (power) power.textContent = `×${Number(trigger.multipliers[level - 1] || 1).toFixed(1)}`;
      // LVアップ演出：衝撃リングとバッジの跳ね（要素を差し替えてアニメーションを再始動）
      const ring = trigger.el.querySelector('.hao-levelup');
      if (ring) {
        const fresh = ring.cloneNode(false);
        fresh.className = 'hao-levelup go';
        ring.replaceWith(fresh);
      }
      const caption = trigger.el.querySelector('.hao-caption');
      if (caption) {
        caption.classList.remove('pop');
        requestAnimationFrame(() => caption.classList.add('pop'));
      }
    }
    if (now - trigger.startedAt < trigger.safetyMs) return;
    trigger.el.classList.remove('is-arming');
    // プレイヤー自身が紋様へ接触した時だけ起爆。敵弾との接触は無視する。
    const dx = Number(state.player.x || 0) - trigger.x;
    const dy = Number(state.player.y || 0) - trigger.y;
    // 紋章はLVごとに大きくなるため、接触半径も見た目に合わせて広げる。
    const hitRadius = HAO_TRIGGER_BASE_HIT_RADIUS * (HAO_TRIGGER_SCALES[level - 1] || 1);
    if (dx * dx + dy * dy > hitRadius * hitRadius) return;

    // 消す→演出→攻撃の順。複数フレームで再発動しない。
    const owner = trigger.owner;
    const multiplier = Number(trigger.multipliers[level - 1] || 1);
    const damage = Math.max(0, Number(owner.atk || 0)) * multiplier;
    const targets = getEriUltTargetPoints();
    if (!isNormalBattle() && Array.isArray(state.normalEnemies)) {
      for (const enemy of state.normalEnemies) {
        if (enemy && enemy.el && enemy.hp > 0) targets.push({x: enemy.x,y: enemy.y});
      }
    }
    const firedTrigger = { x: trigger.x, y: trigger.y };
    clearHaoTrigger();
    spawnHaoTriggerBurst(firedTrigger, level);
    spawnHaoLightningOnBoard(targets, level);
    // ボス戦における増援も盤面の全敵に含む。通常戦と同じ属性相性処理を適用。
    if (!isNormalBattle() && Array.isArray(state.normalEnemies)) {
      for (const enemy of state.normalEnemies) {
        if (!enemy || !enemy.el || enemy.hp <= 0) continue;
        const element = getUltAttackElement(owner);
        const targetElement = getCombatTargetElement(enemy);
        damageNormalEnemy(enemy, applyElementDamage(damage, element, targetElement), now, true,
          getElementDamageReaction(element, targetElement));
      }
      state.normalEnemies = state.normalEnemies.filter(e => e && e.hp > 0);
    }
    applyUltDamage(damage, true, owner);
    renderHud();
  }

  // build1539: トワULT「常闇」／暗転は背景レイヤーだけ。
  // 背景切替はULTの開始と終了の2回だけ。敵・自機・弾・HUDは触らない。
  function updateTowaDarkness(now = performance.now()) {
    if (!state || !Number(state.towaDarkUntil || 0)) return;
    if (now < Number(state.towaDarkUntil)) return;
    state.towaDarkUntil = 0;
    // 暗転解除から敵の攻撃タイマーを再開。停止中の射撃は溜めない。
    deferAllEnemyAttackResume(now);
    document.getElementById(ROOT_ID)?.classList.remove('towa-dark-background', 'towa-light-background');
  }

  function useTowaEternalDarkUlt(c) {
    if (!state || state.ended || state.finishing) return;
    showUltCut(c.ultName || '常闇', c.effectKey, c);
    const now = performance.now();
    const duration = Math.max(500, Number(c.towaDarkDurationMs ?? 5000));
    state.towaDarkUntil = Math.max(Number(state.towaDarkUntil || 0), now + duration);
    // 効果中は敵弾生成を抑止し、既存弾は全消去する。戦闘の時計・敵位置は変えない。
    deferAllEnemyAttackResume(state.towaDarkUntil);
    clearAllEnemyBulletsForTowa();
    // 旧ビルドの黒い全面オーバーレイが残っていても除去する。
    document.getElementById('shooting-towa-darkness')?.remove();
    // CSSは戦闘背景の2要素だけを隠し、ステージ背景色を黒くする。光トワ（夜明けの刻）は白く飛ばす。
    const towaRoot = document.getElementById(ROOT_ID);
    if (c.ultType === 'towa_dawn_moment') { towaRoot?.classList.remove('towa-dark-background'); towaRoot?.classList.add('towa-light-background'); }
    else { towaRoot?.classList.remove('towa-light-background'); towaRoot?.classList.add('towa-dark-background'); }
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + 250);
    renderHud();
  }

  // build1657 カミラULT: 移動拘束のみ、敵弾や射撃処理は停止させない。
  function absorbCamillaWebDamage(damage, now) {
    if(!state || !state.camillaWebUlt || Number(now||performance.now())>=Number(state.camillaWebUlt.until||0)) return;
    const rate=Number(state.camillaWebUlt.absorbRate||0);
    if(rate<=0)return;
    const member=getActiveMember();
    if(!member || Number(member.hp||0)<=0)return;
    const heal=Math.max(0,Number(damage||0)*rate);
    const maxHp=Math.max(1,Number(member.hpMax||0));
    const before=Number(member.hp||0);
    member.hp=Math.min(maxHp,before+heal);
    if(member.hp>before)showHealNumber(member.hp-before,member);
  }

  function useCamillaCrimsonWebUlt(c) {
    if(!state||state.ended||state.finishing)return;
    const lb=Math.max(0,Math.min(4,Math.floor(Number(getShootingResonanceLevel(102)||0))));
    const duration=[3,4,5,6,7][lb]*1000;
    const rate=[.02,.03,.04,.05,.06][lb];
    const now=performance.now();
    const until=now+duration;
    showUltCut(c.ultName||'血界・緋糸万華',c.effectKey,c);
    ensureConjureVisualStyles();
    const arena=document.getElementById('shooting-arena');
    state.camillaWebUlt?.overlay?.remove();
    const overlay=document.createElement('div');overlay.className='shooting-camilla-web-overlay';
    // build1659: 画面全体に張り巡らされる本物の蜘蛛の巣（中心から一気に広がる）
    overlay.innerHTML=getCamillaWebSvg(18,10,true)+'<i class="cw-core"></i>';
    arena?.prepend(overlay); // 背面：アリーナの最初の子として置き、他の要素がすべて上に描かれるようにする
    state.camillaWebUlt={until,absorbRate:rate,overlay};
    (state.normalEnemies||[]).forEach(e=>{if(e&&e.hp>0)e.camillaWebRootUntil=Math.max(Number(e.camillaWebRootUntil||0),until);});
    if(state.boss&&state.boss.hp>0)state.boss.camillaWebRootUntil=Math.max(Number(state.boss.camillaWebRootUntil||0),until);
    state.ultLockUntil=Math.max(Number(state.ultLockUntil||0),now+250);
    renderHud();
  }

  function updateCamillaCrimsonWeb(now) {
    const ult=state?.camillaWebUlt;
    if(!ult)return;
    if(now>=ult.until){ult.overlay?.remove();state.camillaWebUlt=null;}
    else if(ult.until-now<=400) ult.overlay?.classList.add('is-ending');
    else {
      (state.normalEnemies||[]).forEach(e=>{if(e&&e.hp>0)e.camillaWebRootUntil=Math.max(Number(e.camillaWebRootUntil||0),ult.until);});
      if(state.boss&&state.boss.hp>0)state.boss.camillaWebRootUntil=Math.max(Number(state.boss.camillaWebRootUntil||0),ult.until);
    }
  }

  // build1324: スズULT「静寂の森」：既存の敵弾を消去し、3.5秒間だけ弾生成を封印。
  // 敵の移動・HP・照準AIには手を触れない。全弾生成の共通ゲートで抑止する。
  function useSuzuBulletSilenceUlt(c) {
    if (!state || state.ended || state.finishing) return;
    showUltCut(c.ultName, c.effectKey, c);
    ultScreenFlash('ult-flash-eri', c);
    clearEnemyBulletsOnly();
    const now = performance.now();
    state.suzuBulletSilenceUntil = Math.max(Number(state.suzuBulletSilenceUntil || 0),
      now + Math.max(0, Number(c.suzuBulletSilenceMs ?? 3500)));
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + 250);
    renderHud();
  }

  // build1324: メロリアULT「冥府の宣告」。全敵5秒停止＋敵1体ずつ20%で最大HP50%。
  // 既存弾は消さず、割合ダメージはULT由来なのでULTゲージやコンボ加算なし。
  // ============================================================
  // build1731: ナイトシェード ULT「ナイトシェード・スナイプ」
  //  BOSSがいればBOSS、いなければ一番近い敵へ向けて直線の狙撃弾。射線上の敵すべてに：
  //   ① 属性バリアを剥がす（リュネULTと同じ lyuneBarrierRemoved を使う＝以後も弱点以外が通る）
  //   ② 5秒スタン（ニーナ／チャチャと同じ「命中した敵だけ」の麻痺。BOSSはBOSS単体スタン）
  //   ③ ATK×2.5 のダメージ（バリアを先に剥がすので IMMUNE にならない）
  // ============================================================
  function stripNightshadeBarrier(target) {
    if (!target || !target.ref) return;
    if (target.kind === 'boss') {
      const shield = document.getElementById('shooting-boss-weakness-barrier');
      if (state.boss) state.boss.lyuneBarrierRemoved = true;
      if (shield) shield.remove();
      return;
    }
    const enemy = target.ref;
    if (!enemy.weaknessBarrierEl && !enemy.weaknessBarrier) return;
    enemy.lyuneBarrierRemoved = true;
    if (enemy.weaknessBarrierEl) { enemy.weaknessBarrierEl.remove(); enemy.weaknessBarrierEl = null; }
    if (enemy.el) enemy.el.classList.remove('has-weakness-barrier');
  }

  function getNightshadeSnipeCandidates() {
    const list = [];
    (state.normalEnemies || []).forEach(e => {
      if (e && e.el && e.hp > 0) list.push({ kind: 'normal', ref: e, x: Number(e.x || 0), y: Number(e.y || 0), r: 26 });
    });
    (state.facelessObjects || []).forEach(o => {
      if (o && o.el && o.hp > 0) list.push({ kind: 'faceless', ref: o, x: Number(o.x || 0), y: Number(o.y || 0), r: 26 });
    });
    if (!isNormalBattle() && state.boss && state.boss.hp > 0) {
      const bossEl = document.getElementById(BOSS_ID);
      const half = bossEl ? Math.max(30, Math.min(bossEl.offsetWidth, bossEl.offsetHeight) * .32) : 48;
      list.push({ kind: 'boss', ref: state.boss, x: Number(state.boss.x || 0), y: Number(state.boss.y || 0), r: half });
    }
    return list;
  }

  function useNightshadeSnipeUlt(c) {
    if (!state || state.ended || state.finishing) return;
    showUltCut(c.ultName, c.effectKey, c);
    ultScreenFlash('ult-flash-nem', c);
    const arena = document.getElementById('shooting-arena');
    const now = performance.now();
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + 420);
    if (!arena) return;
    const sx = Number(state.player.x || arena.clientWidth / 2);
    const sy = Math.max(20, Number(state.player.y || arena.clientHeight * .8) - 30);
    const candidates = getNightshadeSnipeCandidates();
    // 狙い：BOSSがいればBOSS（増援より優先）、いなければ一番近い敵。どちらもいなければ真上へ撃つ（空振り）。
    const primary = candidates.find(t => t.kind === 'boss')
      || candidates.slice().sort((a, b) => Math.hypot(a.x - sx, a.y - sy) - Math.hypot(b.x - sx, b.y - sy))[0];
    let ux = 0, uy = -1;
    if (primary) {
      const dx = primary.x - sx, dy = primary.y - sy, len = Math.max(1, Math.hypot(dx, dy));
      ux = dx / len; uy = dy / len;
    }
    const rayLength = Math.hypot(arena.clientWidth, arena.clientHeight) * 1.2;
    const halfWidth = Math.max(8, Number(c.nightshadeHitHalfWidth || 30));
    const hits = candidates
      .map(t => {
        const ex = t.x - sx, ey = t.y - sy;
        const along = ex * ux + ey * uy;
        const side = Math.abs(ex * uy - ey * ux);
        return { t, along, side };
      })
      .filter(v => v.along >= 0 && v.along <= rayLength && v.side <= halfWidth + v.t.r)
      .sort((a, b) => a.along - b.along)
      .map(v => v.t);
    if (primary && !hits.includes(primary)) hits.unshift(primary);

    spawnNightshadeTracer(sx, sy, ux, uy, rayLength);

    const stunMs = Math.max(300, Number(c.nightshadeStunMs || 5000));
    const hitProfile = { ...c, ninaUltHitAtkMultiplier: Math.max(0, Number(c.nightshadeDamageAtkMultiplier ?? 2.5)), ninaUltParalyzeMs: stunMs };
    const attackElement = getUltAttackElement(c);
    // 弾が届く時間だけ遅らせて命中させる（射線の手前から順に）
    hits.forEach((target, index) => {
      const delay = 90 + index * 40;
      setTimeout(() => {
        if (!state || state.ended || state.finishing) return;
        if (target.kind === 'boss' ? !(state.boss && state.boss.hp > 0) : !(target.ref && target.ref.hp > 0)) return;
        stripNightshadeBarrier(target);
        const t = performance.now();
        const applied = applyNinaUltHit(hitProfile, target, t);
        // ダメージが通らない相手（無敵中など）にもスタンだけは入れる
        if (!(applied > 0)) applyNinaParalyze(target, stunMs, attackElement);
        createNightshadeImpact(target.kind === 'boss' ? Number(state.boss?.x || target.x) : Number(target.ref.x || target.x),
          target.kind === 'boss' ? Number(state.boss?.y || target.y) : Number(target.ref.y || target.y));
      }, delay);
    });
    renderHud();
  }

  // ============================================================
  // build1733: ナイトシェード ULT「乱射」— アルノ「千ノ刻」の銃乱射版。
  //  敵弾を全消去して時間停止（アルノと同じ arnoSlash* の仕組みを流用＝時計の補正・終了処理も共通）。
  //  制限時間中、タップするたびに散弾 nightshadePelletsPerTap 発を、生きている敵（通常敵＋BOSS）へ
  //  ランダムにばら撒く。1発 ATK×nightshadePelletAtkRate。タップ回数は nightshadeMaxTaps 回まで。
  //  ナイトシェードは移動しない（その場で撃つ）。
  // ============================================================
  function getNightshadeBarrageTargets() {
    const list = [];
    (state.normalEnemies || []).forEach(enemy => {
      if (enemy && enemy.el && enemy.hp > 0) list.push({ kind:'normal', key:`normal:${enemy.uid || ''}`, ref:enemy, x:Number(enemy.x || 0), y:Number(enemy.y || 0) });
    });
    if (!isNormalBattle() && state.boss && state.boss.hp > 0) {
      list.push({ kind:'boss', key:'boss', ref:state.boss, x:Number(state.boss.x || 0), y:Number(state.boss.y || 0) });
    }
    return list;
  }

  // ============================================================
  // build1853: クロエULT「虹のかかる世界」→ パレット選択式
  //  時間停止 → 6色パレットから1色タップ（5秒で自動＝おすすめ色）
  //  → build1854: 敵を指でなぞって塗る。触れた敵へダメージ＋属性をその色に塗り替え。
  // ============================================================
  const PALETTE_ELEMENTS = ['fire', 'aqua', 'wood', 'dark', 'light']; // build1873: 無色は選べない
  const PALETTE_LABEL = { neutral:'無', fire:'火', aqua:'水', wood:'木', dark:'闇', light:'光' };
  const PALETTE_EN = { neutral:'NEUTRAL', fire:'FIRE', aqua:'AQUA', wood:'WOOD', dark:'DARK', light:'LIGHT' };

  // パーティ全員の属性で殴ったとき、一番WEAKを取りやすい色＝おすすめ
  function getPaletteRecommendedElement() {
    const members = (state && Array.isArray(state.party) ? state.party : []).filter(Boolean);
    let best = 'neutral', bestScore = -Infinity;
    const used = getPaletteUsedSet();
    PALETTE_ELEMENTS.forEach(el => {
      if (el === 'neutral' || used.has(el)) return;
      let score = 0;
      members.forEach(m => {
        const ch = getBattleCharacter(m.id) || {};
        const atkEl = normalizeCombatElement(ch.shotElement || ch.element) || 'neutral';
        score += getElementDamageMultiplier(atkEl, el) * (Number(m.hp || 0) > 0 ? 1 : .25);
      });
      if (score > bestScore + 1e-6) { bestScore = score; best = el; }
    });
    if (used.has(best)) best = PALETTE_ELEMENTS.find(el => !used.has(el)) || best;
    return best;
  }
  // build1872: クロエのインクは1色につき1ステージ1回（ゲージが変わっても戻らない）。
  //  5色すべて使い切ったら、パレットを補充（全色リセット）する。
  function getPaletteUsedSet() {
    if (!state) return new Set();
    if (!Array.isArray(state.paletteUsedElements)) state.paletteUsedElements = [];
    if (PALETTE_ELEMENTS.every(el => state.paletteUsedElements.includes(el))) state.paletteUsedElements = [];
    return new Set(state.paletteUsedElements);
  }
  function markPaletteUsed(el) {
    if (!state) return;
    if (!Array.isArray(state.paletteUsedElements)) state.paletteUsedElements = [];
    if (!state.paletteUsedElements.includes(el)) state.paletteUsedElements.push(el);
  }

  function getPalettePaintTargets() {
    const list = [];
    (state.normalEnemies || []).forEach(e => { if (e && e.el && e.hp > 0) list.push({ ref:e, x:Number(e.x || 0), y:Number(e.y || 0) }); });
    (state.facelessObjects || []).forEach(o => { if (o && o.el && o.hp > 0) list.push({ ref:o, x:Number(o.x || 0), y:Number(o.y || 0) }); });
    if (!isNormalBattle() && state.boss && state.boss.hp > 0) list.push({ ref:state.boss, x:Number(state.boss.x || 0), y:Number(state.boss.y || 0), boss:true });
    return list;
  }

  function usePainterPaletteUlt(c) {
    if (!state || state.arnoSlashActive) return;
    const now = performance.now();
    const pickMs = Math.max(1500, Number(c.paletteChooseMs || 5000));
    const root = document.getElementById(ROOT_ID);
    const arena = document.getElementById('shooting-arena');
    if (!root || !arena) return;

    ensureArnoSlashStyle();
    ensureBombVisualStyles();
    clearEnemyBulletsOnly();
    showUltCut(c.ultName || '虹のかかる世界', c.effectKey, c);

    state.arnoSlashActive = true;
    state.arnoSlashStartedAt = now;
    state.arnoSlashUntil = now + pickMs + 1200; // 色決定後、なぞり時間ぶん延長する
    state.arnoSlashOriginX = Number(state.player?.x || 0);
    state.arnoSlashOriginY = Number(state.player?.y || 0);
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + pickMs + 1200);
    state.playerShotLockUntil = Math.max(Number(state.playerShotLockUntil || 0), now + pickMs + 1200);

    root.classList.add('arno-slash-time-stop');
    root.querySelectorAll('.shooting-arno-slash-overlay').forEach(el => el.remove());
    const usedSet = getPaletteUsedSet();
    const recommended = getPaletteRecommendedElement();
    const overlay = document.createElement('div');
    overlay.className = 'shooting-arno-slash-overlay shooting-palette-overlay';
    overlay.style.setProperty('--pal-ms', `${pickMs}ms`);
    overlay.innerHTML =
      '<div class="pal-panel">' +
        '<i class="pal-corner tl"></i><i class="pal-corner tr"></i><i class="pal-corner bl"></i><i class="pal-corner br"></i>' +
        '<div class="pal-head"><small>SELECT ELEMENT</small><b>属性を選択してください</b><i class="pal-rule"></i></div>' +
        '<div class="pal-grid">' +
        PALETTE_ELEMENTS.map(el => {
          const v = getBombElementVisual(el);
          const icon = getCombatElementIcon(el);
          const isUsed = usedSet.has(el);
          return `<button type="button" class="pal-btn element-${el}${isUsed ? ' is-used' : ''}" data-el="${el}" style="--pal-rgb:${v.rgb}"${isUsed ? ' disabled aria-disabled="true"' : ''}>` +
            `<span class="pal-blob">${(!isUsed && icon) ? `<img src="${icon}" alt="">` : ''}</span>` +
            `<span class="pal-name">${isUsed ? '空' : PALETTE_LABEL[el]}<small>${isUsed ? 'EMPTY' : PALETTE_EN[el]}</small></span>` +
            '</button>';
        }).join('') +
        '</div>' +
        `<div class="pal-time">残り <em>${Math.ceil(pickMs / 1000)}</em> 秒</div>` +
        '<div class="pal-timer"><i></i></div>' +
      '</div>';
    arena.appendChild(overlay);
    // build1859: 下部UI（フッター・交代レール）に被せない
    try {
      const ar = arena.getBoundingClientRect();
      const scaleY = ar.height / Math.max(1, arena.clientHeight);
      let topOfBottomUi = ar.bottom;
      root.querySelectorAll('.shooting-footer, .shooting-switch-rail, .shooting-switch-rail *').forEach(el => {
        const r = el.getBoundingClientRect();
        if (r.height > 0 && r.width > 0 && r.top < topOfBottomUi && r.top > ar.top + ar.height * .5) topOfBottomUi = r.top;
      });
      const panel = overlay.querySelector('.pal-panel');
      if (panel) panel.style.bottom = `${Math.round(Math.max(0, ar.bottom - topOfBottomUi) / scaleY + 8)}px`;
    } catch (_) {}

    let chosen = false;
    const choose = el => {
      if (chosen || !state || !state.arnoSlashActive) return;
      if (usedSet.has(el)) return; // 使用済みの色は選べない
      chosen = true;
      markPaletteUsed(el);
      clearTimeout(state.arnoSlashTimerId);
      overlay.classList.add('is-chosen');
      overlay.querySelectorAll('.pal-btn').forEach(b => b.classList.toggle('is-picked', b.dataset.el === el));
      setTimeout(() => startPaletteFingerPaint(c, el), 260); // build1854: なぞって塗る
    };
    overlay.querySelectorAll('.pal-btn').forEach(btn => {
      btn.addEventListener('pointerdown', ev => {
        ev.preventDefault(); ev.stopPropagation();
        if (btn.classList.contains('is-used')) { btn.classList.remove('is-denied'); void btn.offsetWidth; btn.classList.add('is-denied'); return; }
        choose(btn.dataset.el);
      }, { passive:false });
    });
    overlay.addEventListener('pointerdown', ev => { ev.preventDefault(); ev.stopPropagation(); }, { passive:false });

    deferAllEnemyAttackResume(now + pickMs + 1200);
    prevTs = now;
    renderHud();
    state.arnoSlashTimerId = setTimeout(() => choose(recommended), pickMs);
    const palTimeEl = overlay.querySelector('.pal-time em');
    const palTick = () => {
      if (chosen || !overlay.isConnected) return;
      const left = Math.max(0, pickMs - (performance.now() - now));
      if (palTimeEl) palTimeEl.textContent = String(Math.ceil(left / 1000));
      requestAnimationFrame(palTick);
    };
    requestAnimationFrame(palTick);
  }

  // build1854: 選んだ色で、敵を指でなぞって塗る。
  //  ・インク量（なぞれる長さ）と制限時間のどちらかが尽きたら終了
  //  ・筆に触れた敵は1回だけ：ダメージ（塗る前の属性で計算）→ 属性をその色に塗り替え
  function startPaletteFingerPaint(c, element) {
    if (!state || !state.arnoSlashActive) return;
    const arena = document.getElementById('shooting-arena');
    const old = arena && arena.querySelector('.shooting-palette-overlay');
    if (old) { old.classList.add('hide'); setTimeout(() => old.isConnected && old.remove(), 200); }
    if (!arena) { finishArnoUlt(); return; }

    const paintMs = Math.max(1500, Number(c.palettePaintMs || 4000));
    const inkMax = Math.max(200, Number(c.paletteInkPx || 1100));
    const brush = Math.max(8, Number(c.paletteBrushRadius || 22));
    const damage = Math.max(0, Number(c.atk || 0) * Math.max(0, Number(c.palettePaintAtkMultiplier ?? 3.0)));
    const visual = getBombElementVisual(element);
    const icon = getCombatElementIcon(element);
    const W = arena.clientWidth, H = arena.clientHeight;

    // 時間停止の終わりを、なぞり時間ぶん延長
    const now0 = performance.now();
    state.arnoSlashUntil = now0 + paintMs + 900;
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now0 + paintMs + 900);
    state.playerShotLockUntil = Math.max(Number(state.playerShotLockUntil || 0), now0 + paintMs + 900);
    deferAllEnemyAttackResume(now0 + paintMs + 900);

    const ov = document.createElement('div');
    ov.className = `shooting-arno-slash-overlay shooting-paint-overlay element-${element}`;
    ov.style.setProperty('--pal-rgb', visual.rgb);
    ov.style.setProperty('--pal-ms', `${paintMs}ms`);
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    ov.innerHTML =
      `<canvas class="paint-canvas" width="${Math.round(W * dpr)}" height="${Math.round(H * dpr)}"></canvas>` +
      `<div class="paint-hud"><div class="paint-plaque"><span class="paint-chip">${icon ? `<img src="${icon}" alt="">` : ''}</span>` +
      `<span class="paint-plaque-text"><small>${PALETTE_EN[element]} PAINT</small><b>敵をなぞるとダメージ&amp;属性変化</b></span></div>` +
      `<div class="paint-meter"><span class="paint-time"><small>残り</small><em>${(paintMs / 1000).toFixed(1)}</em><small>秒</small></span>` +
      `<span class="paint-ink-label">INK</span><div class="paint-ink"><i></i></div></div></div>` +
      `<img class="paint-brush is-idle" src="images/chloe_ult_brush.webp" alt="" draggable="false">`;
    arena.appendChild(ov);
    // build1855: 筆（画像の穂先＝上端の右寄り 75%,0% を指先に合わせる）
    const brushEl = ov.querySelector('.paint-brush');
    let brushX = W * .5, brushY = H * .45, brushTilt = 0;
    const placeBrush = (x, y, tilt) => {
      if (!brushEl) return;
      brushEl.style.transform = `translate3d(${x}px,${y}px,0) rotate(${tilt}deg)`;
    };
    placeBrush(brushX, brushY, 0);
    const canvas = ov.querySelector('canvas');
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);
    ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    const inkBar = ov.querySelector('.paint-ink i');

    let ink = inkMax;
    let last = null;
    let ended = false;
    const painted = new Set();

    const toLocal = ev => {
      const r = arena.getBoundingClientRect();
      const sx = r.width / Math.max(1, W), sy = r.height / Math.max(1, H);
      return { x: (ev.clientX - r.left) / sx, y: (ev.clientY - r.top) / sy };
    };
    const segDist = (px, py, ax, ay, bx, by) => {
      const dx = bx - ax, dy = by - ay, l2 = dx * dx + dy * dy;
      const t = l2 > 0 ? Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / l2)) : 0;
      return Math.hypot(px - (ax + dx * t), py - (ay + dy * t));
    };
    const paintTargetsAlong = (a, b) => {
      const t = performance.now();
      getPalettePaintTargets().forEach(tg => {
        if (painted.has(tg.ref)) return;
        const rad = tg.boss ? 46 : Math.max(18, Number(tg.ref._hw || 22));
        if (segDist(tg.x, tg.y, a.x, a.y, b.x, b.y) > brush + rad) return;
        painted.add(tg.ref);
        applyPainterSpreadDamage(tg.ref, damage, element, t, c);
        // しぶき＋目印
        const mark = document.createElement('div');
        mark.className = `shooting-palette-mark element-${element}`;
        mark.style.setProperty('--pal-rgb', visual.rgb);
        let drops = '';
        for (let i = 0; i < 6; i++) {
          const ang = Math.random() * Math.PI * 2, d = 26 + Math.random() * 22;
          drops += `<u style="--dx:${Math.round(Math.cos(ang) * d)}px;--dy:${Math.round(Math.sin(ang) * d)}px;--sz:${Math.round(7 + Math.random() * 8)}px"></u>`;
        }
        mark.innerHTML = `<i></i>${drops}${icon ? `<img src="${icon}" alt="">` : ''}`;
        arena.appendChild(mark);
        positionUnit(mark, tg.x, tg.y);
        setTimeout(() => mark.remove(), 1000);
        finalizePainterSpreadHit(t);
        if (navigator.vibrate) { try { navigator.vibrate(12); } catch (_) {} }
      });
    };
    const drawSeg = (a, b) => {
      // 下地（にじみ）→ 本体 → ハイライト
      ctx.strokeStyle = `rgba(${visual.rgb},.28)`; ctx.lineWidth = brush * 2 + 10;
      ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
      ctx.strokeStyle = `rgba(${visual.rgb},.82)`; ctx.lineWidth = brush * 2;
      ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
      ctx.strokeStyle = 'rgba(255,255,255,.35)'; ctx.lineWidth = Math.max(2, brush * .35);
      ctx.beginPath(); ctx.moveTo(a.x - 2, a.y - 3); ctx.lineTo(b.x - 2, b.y - 3); ctx.stroke();
    };
    const stroke = p => {
      if (ended) return;
      // 筆を指先へ。横の動きに合わせて少し傾ける
      const vx = p.x - brushX;
      brushTilt = brushTilt * .7 + Math.max(-18, Math.min(18, vx * .9)) * .3;
      brushX = p.x; brushY = p.y;
      if (brushEl) brushEl.classList.remove('is-idle');
      placeBrush(brushX, brushY, brushTilt);
      const a = last || p;
      let b = p;
      let len = Math.hypot(b.x - a.x, b.y - a.y);
      if (last && len < 2) return;
      if (len > ink) { // インクが足りない分は手前で止める
        const f = ink / Math.max(1e-6, len);
        b = { x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f };
        len = ink;
      }
      drawSeg(a, b);
      paintTargetsAlong(a, b);
      ink -= len;
      last = b;
      if (inkBar) inkBar.style.transform = `scaleX(${Math.max(0, ink / inkMax)})`;
      if (ink <= 0) end();
    };

    const end = () => {
      if (ended) return;
      ended = true;
      clearTimeout(state && state.arnoSlashTimerId);
      ov.classList.add('is-done');
      if (brushEl) brushEl.classList.add('is-gone');
      setTimeout(() => {
        ov.classList.add('hide');
        setTimeout(() => ov.isConnected && ov.remove(), 260);
        if (state && state.arnoSlashActive) finishArnoUlt();
      }, 420);
    };

    ov.addEventListener('pointerdown', ev => {
      ev.preventDefault(); ev.stopPropagation();
      try { ov.setPointerCapture(ev.pointerId); } catch (_) {}
      last = null;
      stroke(toLocal(ev));
    }, { passive:false });
    ov.addEventListener('pointermove', ev => {
      if (!(ev.buttons & 1) && ev.pointerType === 'mouse') return;
      ev.preventDefault();
      if (last === null) return;
      stroke(toLocal(ev));
    }, { passive:false });
    ['pointerup', 'pointercancel'].forEach(type => ov.addEventListener(type, () => { last = null; }));

    state.arnoSlashTimerId = setTimeout(end, paintMs);
    // build1856: 残り時間の数字表示
    const timeEl = ov.querySelector('.paint-time em');
    const paintStart = performance.now();
    const tick = () => {
      if (ended || !ov.isConnected) return;
      const left = Math.max(0, paintMs - (performance.now() - paintStart));
      if (timeEl) timeEl.textContent = (left / 1000).toFixed(1);
      ov.classList.toggle('is-hurry', left <= 1000);
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }

  function useNightshadeBarrageUlt(c) {
    if (!state || state.arnoSlashActive) return;
    const now = performance.now();
    const duration = Math.max(500, Number(c.nightshadeBarrageDurationMs || 4000));
    const root = document.getElementById(ROOT_ID);
    const arena = document.getElementById('shooting-arena');
    if (!root || !arena) return;

    ensureArnoSlashStyle();
    clearEnemyBulletsOnly();

    state.arnoSlashActive = true;
    state.arnoSlashStartedAt = now;
    state.arnoSlashUntil = now + duration;
    state.arnoSlashOriginX = Number(state.player?.x || 0);
    state.arnoSlashOriginY = Number(state.player?.y || 0);
    state.arnoSlashLastTapAt = -9999;
    state.arnoSlashCount = 0;
    state.arnoSlashTargetKey = '';
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + duration);
    state.playerShotLockUntil = Math.max(Number(state.playerShotLockUntil || 0), now + duration);

    root.classList.add('arno-slash-time-stop');
    root.querySelectorAll('.shooting-arno-slash-overlay').forEach(el => el.remove());
    const overlay = document.createElement('div');
    overlay.className = 'shooting-arno-slash-overlay shooting-nightshade-barrage-overlay';
    const maxTaps = Math.max(1, Math.floor(Number(c.nightshadeMaxTaps || 12)));
    overlay.innerHTML = `<div class="shooting-arno-slash-prompt"><b>連打！</b><small>残り <span class="arno-slash-left">${maxTaps}</span></small></div>`;
    const leftEl = overlay.querySelector('.arno-slash-left');
    arena.appendChild(overlay);

    // build1755: 敵がいなくなったら「連打！」を待たずに終了する（最後の弾が届くまで少しだけ待つ）
    const scheduleEmptyFinish = () => {
      if (!state || !state.arnoSlashActive || state.nightshadeEmptyFinishing) return;
      state.nightshadeEmptyFinishing = true;
      clearTimeout(state.arnoSlashTimerId);
      state.arnoSlashTimerId = setTimeout(() => {
        if (state) state.nightshadeEmptyFinishing = false;
        if (state && state.arnoSlashActive) finishArnoUlt();
      }, 320);
    };
    state.nightshadeEmptyFinishing = false;
    const emptyCheck = setInterval(() => {
      if (!state || !state.arnoSlashActive) { clearInterval(emptyCheck); return; }
      if (!getNightshadeBarrageTargets().length) { clearInterval(emptyCheck); scheduleEmptyFinish(); }
    }, 120);

    const pelletsPerTap = Math.max(1, Math.floor(Number(c.nightshadePelletsPerTap || 4)));
    const pelletProfile = { ...c, arnoSlashDamageAtkRate: Math.max(0, Number(c.nightshadePelletAtkRate ?? 0.095)) };

    overlay.addEventListener('pointerdown', event => {
      event.preventDefault();
      event.stopPropagation();
      if (!state || !state.arnoSlashActive || state.ended || state.finishing) return;
      const tapNow = performance.now();
      if (tapNow >= Number(state.arnoSlashUntil || 0)) { finishArnoUlt(); return; }
      const minInterval = Math.max(0, Number(c.nightshadeMinTapIntervalMs || 80));
      if (tapNow - Number(state.arnoSlashLastTapAt || -9999) < minInterval) return;
      if (Number(state.arnoSlashCount || 0) >= maxTaps) return;
      const targets = getNightshadeBarrageTargets();
      if (!targets.length) { scheduleEmptyFinish(); return; }
      state.arnoSlashLastTapAt = tapNow;
      state.arnoSlashCount = Math.max(0, Number(state.arnoSlashCount || 0)) + 1;

      const sx = Number(state.player?.x || 0);
      const sy = Number(state.player?.y || 0) - 34;
      createNightshadeMuzzle(sx, sy);
      for (let i = 0; i < pelletsPerTap; i++) {
        // 1発ごとに対象をランダムに選び、着弾点も少し散らす（バラバラ感）
        const target = targets[Math.floor(Math.random() * targets.length)];
        const jx = (Math.random() - .5) * 34, jy = (Math.random() - .5) * 26;
        const delay = i * 28 + Math.random() * 18;
        setTimeout(() => {
          if (!state || !state.arnoSlashActive || state.ended || state.finishing) return;
          const alive = target.kind === 'boss' ? (state.boss && state.boss.hp > 0) : (target.ref && target.ref.hp > 0);
          const tx = (target.kind === 'boss' ? Number(state.boss?.x || target.x) : Number(target.ref.x || target.x)) + jx;
          const ty = (target.kind === 'boss' ? Number(state.boss?.y || target.y) : Number(target.ref.y || target.y)) + jy;
          spawnNightshadePellet(sx, sy, tx, ty);
          if (alive) damageArnoSlashTarget(pelletProfile, target, performance.now());
        }, delay);
      }
      if (leftEl) leftEl.textContent = String(Math.max(0, maxTaps - state.arnoSlashCount));
      // 上限に達したら最後の弾が届くのを待って少し早めに終了
      if (state.arnoSlashCount >= maxTaps && state.arnoSlashActive) {
        const endAt = Math.min(Number(state.arnoSlashUntil || tapNow), tapNow + 360);
        clearTimeout(state.arnoSlashTimerId);
        state.arnoSlashTimerId = setTimeout(() => { if (state && state.arnoSlashActive) finishArnoUlt(); }, Math.max(0, endAt - tapNow));
      }
    }, { passive:false });

    deferAllEnemyAttackResume(now + duration);
    prevTs = now;
    renderHud();
    state.arnoSlashTimerId = setTimeout(() => {
      if (!state || !state.arnoSlashActive) return;
      finishArnoUlt();
    }, duration);
  }

  function createNightshadeMuzzle(x, y) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const el = document.createElement('div');
    el.className = 'shooting-nightshade-muzzle';
    el.innerHTML = '<i></i>';
    arena.appendChild(el);
    positionUnit(el, x, y);
    setTimeout(() => el.remove(), 260);
  }

  function spawnNightshadePellet(sx, sy, tx, ty) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const dx = tx - sx, dy = ty - sy;
    const el = document.createElement('div');
    el.className = 'shooting-nightshade-tracer is-pellet';
    el.style.setProperty('--ns-len', `${Math.round(Math.hypot(dx, dy))}px`);
    el.style.setProperty('--ns-angle', `${Math.atan2(dy, dx) * 180 / Math.PI}deg`);
    el.style.left = `${sx}px`;
    el.style.top = `${sy}px`;
    el.innerHTML = '<i class="ns-trail"></i><i class="ns-core"></i>';
    arena.appendChild(el);
    setTimeout(() => el.remove(), 360);
    const hit = document.createElement('div');
    hit.className = 'shooting-nightshade-impact is-pellet';
    hit.innerHTML = '<i class="ns-burst"></i>';
    arena.appendChild(hit);
    positionUnit(hit, tx, ty);
    setTimeout(() => hit.remove(), 420);
  }

  function spawnNightshadeTracer(sx, sy, ux, uy, length) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const el = document.createElement('div');
    el.className = 'shooting-nightshade-tracer';
    el.style.setProperty('--ns-len', `${Math.round(length)}px`);
    el.style.setProperty('--ns-angle', `${Math.atan2(uy, ux) * 180 / Math.PI}deg`);
    el.style.left = `${sx}px`;
    el.style.top = `${sy}px`;
    el.innerHTML = '<i class="ns-trail"></i><i class="ns-core"></i><i class="ns-muzzle"></i>';
    arena.appendChild(el);
    setTimeout(() => el.remove(), 720);
  }

  function createNightshadeImpact(x, y) {
    const arena = document.getElementById('shooting-arena');
    if (!arena) return;
    const el = document.createElement('div');
    el.className = 'shooting-nightshade-impact';
    el.innerHTML = '<i class="ns-reticle"></i><i class="ns-burst"></i>';
    arena.appendChild(el);
    positionUnit(el, x, y);
    setTimeout(() => el.remove(), 760);
  }

  function useMeloriaStunUlt(c) {
    if (!state || state.ended || state.finishing) return;
    showUltCut(c.ultName, c.effectKey, c);
    ultScreenFlash('ult-flash-nem', c);
    const now = performance.now();
    applyAngeEnemyFreeze(Math.max(0, Number(c.ultStunMs ?? 5000)));
    const chance = Math.max(0, Math.min(1, Number(c.meloriaPercentChance ?? 0.2)));
    const hpRatio = Math.max(0, Number(c.meloriaMaxHpDamageRate ?? 0.5));

    // 通常敵はBOSS戦の増援も含む。各対象が独立して20%抽選する。
    (state.normalEnemies || []).slice().forEach(enemy => {
      if (!enemy || !enemy.el || enemy.hp <= 0 || Math.random() >= chance) return;
      const maxHp = Math.max(1, Number(enemy.hpMax || enemy.hp || 1));
      damageNormalEnemy(enemy, maxHp * hpRatio, now, true);
    });
    state.normalEnemies = (state.normalEnemies || []).filter(enemy => enemy && enemy.hp > 0);

    if (!isNormalBattle() && !isEclipseBattle() && state.boss && state.boss.hp > 0 && Math.random() < chance) { // build1681: エクリプス本体には割合ダメージも通らない
      const boss = state.boss;
      const damage = Math.min(Number(boss.hp || 0), Math.max(0, Number(boss.hpMax || boss.hp || 1)) * hpRatio);
      boss.hp = Math.max(0, Number(boss.hp || 0) - damage);
      if (!addScoreAttackDamageScore(damage)) addLegacyCombatScore(Math.round(damage * 100));
      showBossDamageNumber(damage, true);
      createHit(Number(boss.x || 0), Number(boss.y || 0), true);
      updateBossPhase();
      if (boss.hp <= 0) beginBossDefeat();
    }
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + 250);
    renderHud();
  }

  // build1324: アイレナULT「光の祝福」：前方に拾えるATK×1.5・5秒アイテムを1個。
  // ミモザの既存ATK UP取得システムを再利用し、拾ったキャラだけ強化する。
  function useAirenaAtkItemUlt(c) {
    if (!state || state.ended || state.finishing) return;
    showUltCut(c.ultName, c.effectKey, c);
    ultScreenFlash('ult-flash-mimosa', c);
    const arena = document.getElementById('shooting-arena');
    const layer = document.getElementById('shooting-collectible-layer');
    if (!arena || !layer) return;
    const now = performance.now();
    const multiplier = Math.max(1, Number(c.itemAtkMultiplier || 1.5));
    const duration = Math.max(100, Number(c.itemAtkDurationMs || 5000));
    const x = clamp(Number(state.player.x || arena.clientWidth * 0.5), 35, Math.max(35, arena.clientWidth - 35));
    const y = clamp(Number(state.player.y || arena.clientHeight * 0.75) - 86, 65,
      Math.max(65, arena.clientHeight - 65));
    const el = document.createElement('div');
    el.className = 'shooting-mimosa-item mimosa-item-atk';
    applySummonItemLook(el, 'atk');
    layer.appendChild(el);
    const item = {
      uid: `airena_atk_${Date.now()}_${Math.random().toString(36).slice(2,6)}`,
      sourceType: 'airena_atk_item', el, x, y,
      kind: 'atk', label: 'ATK UP',
      detail: `ATK ×${multiplier.toFixed(1)} / ${Math.round(duration / 1000)}秒`,
      atkBuffMultiplier: multiplier,
      atkBuffDurationMs: duration
    };
    state.mimosaItems.push(item);
    positionUnit(el, x, y);
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + 250);
    renderHud();
  }

  // build1922: アライン「SYNC」7秒間の本人限定CHARGE加速・被ダメ半減。
  function useAlignSyncUlt(c) {
    if (!state || state.ended || state.finishing) return;
    const member = getActiveMember();
    if (!member || Number(member.id) !== 46) return;
    const now = performance.now();
    const duration = Math.max(100, Number(c.alignSyncDurationMs || 7000));
    member.alignSyncUntil = now + duration;
    showUltCut(c.ultName, c.effectKey, c);
    ultScreenFlash('ult-flash-mimosa', c);
    state.ultLockUntil = Math.max(Number(state.ultLockUntil || 0), now + 250);
    renderHud();
  }

  function executeCharacterUlt(c) {
    if (!state || state.ended || state.finishing) return;

    // ULTの内部属性と、画像を使わない演出の基調色を同じ属性へ同期。
    applyUltElementVisualContext(c);

    if (c.ultType === 'ryune_absolute_lethe' || Number(c.id) === 25) useLyuneAbsoluteLetheUlt(c);
    else if (c.ultType === 'sui_time_domain') useSuiTimeDomainUlt(c);
    else if (c.ultType === 'towa_eternal_darkness' || c.ultType === 'towa_dawn_moment') useTowaEternalDarkUlt(c); // build1877: 光トワは白
    else if (c.ultType === 'rose_fortress') useRoseUlt(c);
    else if (c.ultType === 'suzu_bullet_silence') useSuzuBulletSilenceUlt(c);
    else if (c.ultType === 'meloria_stun') useMeloriaStunUlt(c);
    else if (c.ultType === 'nightshade_snipe') useNightshadeSnipeUlt(c); // build1731（旧仕様・現在は未使用）
    else if (c.ultType === 'nightshade_barrage') useNightshadeBarrageUlt(c);
    else if (c.ultType === 'align_sync') useAlignSyncUlt(c);
    else if (c.ultType === 'airena_atk_item') useAirenaAtkItemUlt(c);
    else if (c.ultType === 'ignis_fire_wheel') useIgnisUlt(c);
    else if (c.ultType === 'clarine_decoy') useClarineUlt(c);
    else if (c.ultType === 'gresha_burn_field') useGreshaUlt(c);
    else if (c.ultType === 'arno_thousand_slash' || c.ultType === 'arno_aura') useArnoUlt(c);
    else if (c.ultType === 'speed_storm') useHayateUlt(c);
    else if (c.ultType === 'precision_beam') useAyaneUlt(c);
    else if (c.ultType === 'gojo_purple') useGojoUlt(c);
    else if (c.ultType === 'eltena_black_hole') useEltenaUlt(c);
    else if (c.ultType === 'kureha_fire_black_hole') useKurehaUlt(c);
    else if (c.ultType === 'deinova_raptoplasm') useDeinovaRaptoplasmUlt(c);
    else if (c.ultType === 'nem_stun') useNemUlt(c);
  // build1327: shared healing ULT dispatcher includes アンジェ・リンリン・ノエル.
    else if (c.ultType === 'ange_healing_hearts') useAngeUlt(c);
    else if (c.ultType === 'mimosa_item_spawn') useMimosaUlt(c);
    else if (c.ultType === 'mito_summon_double') useMitoUlt(c);
    else if (c.ultType === 'wolf_atk_field') useWolfUlt(c);
    else if (c.ultType === 'wolf_berserk') useWolfBerserkUlt(c); // build1860
    else if (c.ultType === 'toyfel_double_black_hole') useToyfelUlt(c);
    else if (c.ultType === 'painter_palette') usePainterPaletteUlt(c); // build1853: クロエ
    else if (
      c.ultType === 'painter_element_spread' ||
      c.ultType === 'painter_rainbow_world' ||
      c.ultType === 'painter_light_paint_bomb' ||
      c.ultType === 'painter_dark_paint_bomb'
    ) usePainterElementSpreadUlt(c);
    else if (c.ultType === 'hao_fivefold_trigger') useHaoUlt(c);
    else if (c.ultType === 'smile_surprise_box') useSmileSurpriseBoxUlt(c);
    else if (c.ultType === 'inori_torii_guard') useInoriToriiGuardUlt(c); // build1817
    else if (c.ultType === 'aina_stealth') useAinaStealthUlt(c);
    else if (c.ultType === 'forbidden_shock') useNinaUlt(c); // 旧ニーナ落雷演出を70%威力で再利用
    else if (c.ultType === 'nina_output_max' || c.ultType === 'nina_lightning_storm') useNinaOutputMax(c);
    else if (c.ultType === 'noah_time_homing') useNoahUlt(c);
    else if (c.ultType === 'jig_scramble_ray') useJigScrambleUlt(c);
    else if (c.ultType === 'testchan_black_ship') useTestChanUlt(c);
    else if (c.ultType === 'camilla_crimson_web') useCamillaCrimsonWebUlt(c);
    else if (c.ultType === 'conjure_homing_battery') useConjureUlt(c);
    else if (c.ultType === 'veronica_brass_punch') useVeronicaBrassPunchUlt(c);
    else if (c.ultType === 'shiina_light_ring') useShiinaLightRingUlt(c);
    else if (c.ultType === 'shion_delayed_curse') useShionUlt(c);
    else if (c.ultType === 'liz_giant_bomb') useLizGiantBombUlt(c);
    else if (c.ultType === 'prototype_generic') useEriUlt(c);
    else useEriUlt(c);

    renderHud();
  }

  window.useShootingBurst = function () {
    if (!isUltReady()) return;
    const c = getCurrentCharacter();
    const member = getActiveMember();
    if (!member) return;

    // 二重発動防止のため、カットイン開始時点でゲージを消費。
    member.burst = 0;

    // 神聖樹 ULT SLOT：ULT発動直後に必要ゲージ量の一定割合を還元する。
    // Stage1→5 = 4 / 8 / 12 / 16 / 20%。
    try {
      const blessing = window.ShinjuProgress && typeof window.ShinjuProgress.getBlessingForCharacter === 'function'
        ? window.ShinjuProgress.getBlessingForCharacter(c.id)
        : null;
      const refundRate = Math.max(0, Math.min(1, Number(blessing && blessing.ultRefundRate || 0)));
      if (refundRate > 0) {
        member.burst = Math.min(Number(c.burstNeed || 0), Number(c.burstNeed || 0) * refundRate);
      }
    } catch (err) {
      console.warn('[shooting] shinju ULT refund skipped:', err);
    }

    member.ultReadyNotified = false;
    member.ultUseCount = (member.ultUseCount || 0) + 1;
    clearUltTimers();

    const chapter101TutorialUlt =
      isChapter101TutorialStage() && state.ch101TutorialPhase === 'ult_ready';
    if (chapter101TutorialUlt) {
      state.ch101TutorialUltTriggered = true;
      state.ch101TutorialPhase = 'ult_resolving';
      const root = document.getElementById(ROOT_ID);
      if (root) root.classList.remove('ch101-ult-prompt');
    }

    // 約1秒のカットイン → その後にULT効果を発動。
    playUltCutin(c, () => {
      executeCharacterUlt(c);
      if (chapter101TutorialUlt) {
        setTimeout(() => defeatChapter101TutorialUltWave(), 520);
      }
    });
    renderHud();
  };

  window.addEventListener('keydown', e => {
    keys[e.key] = true;
    if (document.getElementById(ROOT_ID)?.classList.contains('open') && ['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(e.key)) e.preventDefault();
  }, { passive: false });
  window.addEventListener('keyup', e => { keys[e.key] = false; });
  window.addEventListener('resize', () => {
    invalidateArenaInputRect();
    if (state && state.running && !state.ended) placeInitialUnits();
    else requestAnimationFrame(() => refreshArenaInputRect(true));
  });
  window.addEventListener('orientationchange', () => {
    invalidateArenaInputRect();
    // iOSはorientationchange直後にviewportサイズが確定していない場合があるため、
    // 次フレームで再取得する。
    requestAnimationFrame(() => {
      refreshArenaInputRect(true);
      refreshResponsiveCombatUnitScales();
    });
  });
  // 復元チェックは所持キャラ判定(collected)に依存する。
  // window._dbLoadPromiseは、index.html側のinit()がスプラッシュタップ後の
  // Step2に到達して初めて代入される。ページ読み込み直後(スプラッシュ表示中)は
  // まだこの変数自体が存在しないため、「あれば待つ」だけでは不十分で、
  // 存在するようになるまでポーリングして待つ必要がある。
  function waitForShootingDbLoad(timeoutMs = 20000) {
    return new Promise(resolve => {
      const startedAt = performance.now();
      (function poll() {
        if (window._dbLoadPromise && typeof window._dbLoadPromise.then === 'function') {
          window._dbLoadPromise.then(resolve, resolve);
          return;
        }
        if (performance.now() - startedAt > timeoutMs) {
          // タイムアウトしても復元チェック自体は諦めず、ベストエフォートで進む。
          resolve();
          return;
        }
        setTimeout(poll, 120);
      })();
    });
  }

  async function tryRestoreShootingBattleWhenReady() {
    try {
      await waitForShootingDbLoad();
    } catch (_) {
      // DB読み込みが失敗した場合でも、復元チェック自体はベストエフォートで試みる。
    }
    tryRestoreShootingBattle();
  }
  setTimeout(() => { tryRestoreShootingBattleWhenReady(); }, 0);

